local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "비밀 지키는 사람, 제가 언제 아카데미의 묘지를 참관할 수 있을까요? 그곳에 묻힌 위대한 영혼들은 분명 제가 비범한 영감을 받을 수 있게 해줄 것입니다! 걱정하지 마세요, 제가 다시는 그 시체들을 파내어 가까이 관찰하지 않을 것을 보장합니다……"
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "잡담·모델에 대해"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "번뜩였다. 이건 새로운 표현법이야! 분명 그림계에 큰 충격을 줄 거야!"
  },
  Voice_100336_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_100337_AwakerVoiceContent = {
