  },
  Voice_100339_AwakerVoiceContent = {
    Text = "얼마나 멋진 검은 색 물감인가! 나는 과거에 많은 부식액을 모아 그림을 그렸지만, 결국 그 그림들은 사라졌습니다. 원주율 우주의 색깔, 모든 화면은 삼키고 아무도 기억하지 못한 그림……더 멋지지 않나요?!"
