  Voice_100340_AwakerVoiceContent = {
    Text = "조금 더 가까이 다가오게 해줘… 좀 더 많이 보고 싶어! 이 강렬한 빛과 그림자, 이 색채, 이 자세… 그것들과 비교하면, 내가 예전 그린 것들은 모두 쓸모없는 종이 같다…"
  },
  Voice_100340_AwakerVoiceTitle = {
