  },
  Voice_100341_AwakerVoiceContent = {
    Text = "두레사인은 계속해서 그의 요리가 얼마나 예술적인지 말하곤 했고, 그걸 보라고 했어요. 먹는 것과 예술은 전혀 관계가 없어요! 소중한 창작 시간을 낭비하여 복잡한 시체 처리 작업을 해야 하고, 힘들게 모양과 색을 갖춘 음식을 만들어 내놓고 나서는 그걸 씹고 삼켜야 하잖아요! 이건 예술에 대한 범죄에요!"
  },
  Voice_100341_AwakerVoiceTitle = {
