  Voice_100342_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_100343_AwakerVoiceContent = {
    Text = "나쁜 모델……"
  },
  Voice_100343_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_100344_AwakerVoiceContent = {
    Text = "큭... 또 졸작이네. 영감을 찾아야겠어. 묘지? 아니면 처형장으로 갈까?"
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "조각이라는 예술 형식이 다소 경직되고 고리타분하다고 생각하지만, 산이라는 조각가는 그녀의 조각칼이 이 예술 형식이 수용할 수 있는 표현력을 초월할 수 있음을 보여준다… 정말 드문 재능이다!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "잡담·산에 대해"
  },
  Voice_100345_UnlockDesc = {
    Text = "깨어남체「산」획득 후 개방"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "이 그림 보셨나요, 비밀 지키는 사람? 이것은 제가 당신을 위해 그린 초상화입니다. 당신이 시체를 먹는 모습은 얼마나 매력적인가요! 저는 모든 사람이 제 작품을 이해할 수 있는 것은 아닐지라도, 이 그림이 전하는 그 미친 아름다움은 당신이 분명히 느끼고 있을 것이라고 생각합니다, 그렇죠?! 저에게는 이게 충분히 만족스럽습니다, 완전히 충분합니다......"
  },
  Voice_100346_AwakerVoiceTitle = {
