  Voice_100346_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "당신이 방금 이 그림을 사겠다고 말했죠…… 진짜인가요?! 고마워요, 비밀 지키는 사람! 이런 것에 감상할 수 있는 인류는 정말 드뭅니다……"
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "동조율·2"
