  },
  Voice_100348_AwakerVoiceContent = {
    Text = "비밀 지키는 사람, 최근에 내 모델이 될 시간이 있었나요? 지난번 당신에게서 본 모습과 비교하면, 다른 모델들은 완전히 내 시간을 낭비하고 있어……"
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "이 그림 속에서, 새로운 탄생을 목격하라!"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "이 생동감 넘치는 선들을 보세요!"
  },
  Voice_100350_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_100351_AwakerVoiceContent = {
    Text = "이 붓이 그려내는 건, 분명 모두를 놀라게 할 걸작이 될 거야!"
  },
  Voice_100351_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_100352_AwakerVoiceContent = {
    Text = "이건, 새로운 물감이구나... 좋아, 가장 어울리는 곳에 칠해 주지!"
  },
  Voice_100352_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_100353_AwakerVoiceContent = {
    Text = "여기는 정말 나에게 영감을 주는 좋은 장소だ！ 나는 새로운 작품이 떠올랐다, 비밀 지키는 사람, 최근 내 화실타래에 방문할 수 있는 시간이 있나요? 와줘요 와줘요！"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_100353_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "좋아, 좋다고! 피로 물든 승리! 이 얼마나 절묘한 구도인가!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_100355_AwakerVoiceContent = {Text = "흐음..."},
  Voice_100355_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_100356_AwakerVoiceContent = {
    Text = "아! 앉으세요, 비밀 지키는 사람. 모델이 되는 것은 힘든 일이에요. 걱정하지 마세요, 반드시 당신을 위해 놀라운 그림을 창작할게요."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_100356_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "예술가는 오직 작품만을 바라보아야 하며, 남의 시선은 알 필요가 없다. 그러나 나는 할 수 없다……처음으로 붓을 들었던 그 날부터, 나는 진정한 아름다움을 모든 이에게 전할 수 있기를 바랐다."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_100357_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "여기에서 나는 예전 화학교에서의 시간들을 떠올리게 된다. 교수와 동료들은 대부분 예술을 전혀 모르는 천박한 사람들로 가득했지만, 항상 나의 그림에서 내가 보았던 아름다움을 엿볼 수 있는 한두 명의 식견있는 인물들이 있었다."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "이 야만적인 공연이, 참신한 예술을 만들어낼 거야!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "나의 팔레트!"
  },
  Voice_100360_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_100361_AwakerVoiceContent = {
    Text = "고통 또한 예술이다……"
  },
  Voice_100361_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_100362_AwakerVoiceContent = {
    Text = "아! 보였어요……심연 아래 숨겨진 무목의 눈, 우주의 궁극적인 그림……잠시만 기다려 주세요, 비밀 지키는 사람, 곧 완료됩니다!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_100362_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "내 화필은 내 정강이뼈로 만들어졌다. 색깔 팔레트, 이 색들은 내가 20개의 도시 묘지에서 모은 것들이다…… 그리고 내 소중한 가죽 캔버스! 비밀 지키는 사람, 이걸 가져가서 내 초상화를 그려줘! 아니, 아니, 당신이 그릴 기법이 필요 없다…… 나는 이 심령의 무간 공명이 캔버스에 드러날 때, 내가 결코 상상하지 못한 가장 아름다운 그림이 될 것이라고 믿는다……!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_100363_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "나는 빛과 그림자, 나는 색채, 나는... 그림 그 자체다!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "이 색깔을 시도해 보세요!"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_100366_AwakerVoiceContent = {
    Text = "예술의 본질은, 광기다!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "당신의 뜻은, 다음에 이 부위를 클로즈업하여 그릴 수 있다는 것인가요? 음…… 그런 생각은 전혀 못했습니다! 정말 천재적인 발상입니다!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_100368_AwakerVoiceContent = {Text = "조심!"},
  Voice_100368_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_100369_AwakerVoiceContent = {
    Text = "예술의 본질은, 광기다!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "나의 팔레트!"
  },
  Voice_100370_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_100371_AwakerVoiceContent = {
    Text = "오오, 이 매끄러운 턱선, 빛나는 눈, 완벽한 비율! 그리고 별하늘처럼 광활한 정신... 난 화가 픽맨이야. 당신을 그리고 싶은데, 괜찮을까?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_100372_AwakerVoiceContent = {
    Text = "내가 믿는 예술 개념은 광기와 불안정함이다. 하멜린의 음악은 전혀 다르고, 마치 죽은 무덤 비석처럼 엄격하다. 하지만 왜인지, 나는 그 정갈한 음표 속에서 우주 깊은 곳의 강렬한 혼돈을 볼 수 있다……"
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "잡담·하멜른에 대해"
  },
  Voice_100372_UnlockDesc = {
    Text = "깨어남체「하멜른」획득 후 개방"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "봐요, 비밀 지키는 사람! 캔버스 위의 그 영원하고 미친 광경, 얼마나 감동적이고 절망적이냐는 것! 이 궁극의 광기와 고통 속에서 피어나는 것이야말로 예술입니다..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_100373_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "아! 미, 미안해요, 비밀 지키는 사람……당신에게서 전에 본 적 없는 광경을 보았어요……심연보다 더 무섭고, 심연보다 더 매력적이에요……"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_100374_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "정말 이해할 수 없다, 인간이 기회를 얻으면 왜 식인 좀비가 되지 않으려고 하는가? 이 피범벅의 미친 아름다움이 대저택에서 열정 없는 인간이 되는 것보다 훨씬 더 재미있지 않을까요?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_100376_AwakerVoiceContent = {Text = "하!"},
  Voice_100376_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_116964_AwakerVoiceContent = {
    Text = "악을 처벌하라!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "악을 처벌하라!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "나는 그녀가 물건을 훔치는 능력이 있다는 것을 인정하지만, 숙녀는 그런 비열한 수법을 쓸 필요는 없어. 내가 원하는 것은 모두가 「자발적으로」 나에게 주면 되는 거 아닌가?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_117791_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "하하하, 내꺼, 내꺼, 미사그의 모든 사탕은 내꺼야! 더 이상 기다릴 거 없고, 나와 함께 가서 바로 런티니언의 모든 사탕 가게를 정복하자!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_117792_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "에에, 안 줄거야? 그럼, 진심으로 가지러 간다?"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "저기, 이 사탕, 대체 어떻게 안쪽을 채운 걸까? 틈새나 바늘구멍 하나 찾을 수 없는데. 이런 과자를 발명한 사람을 미사그의 레스토랑에 스카우트해서, 매일 새로운 과자를 만들게 하면 어때?"
  },
  Voice_117794_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_117795_AwakerVoiceContent = {
    Text = "너는 마녀의 화를 샀다!"
  },
  Voice_117795_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_117796_AwakerVoiceContent = {
    Text = "이전에는 사탕이 케이크보다 너무 단순하고 우아하지 않다고 생각했지만, 이제 보니, 나는 이 형형색색의 플라스틱 종이 속의 작은 것들을 과소평가했던 것 같아. 특히 케이크와 비교하면, 이 사탕의 유통 기한은 훨씬 길어, 필요한 만큼 쌓아두어도 상하지 않으니, 정말로 집을 가득 채우고 싶어!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "너는 새로운 사탕을 찾았니? 나에게 보여줘… 뭐야, 이 반지 사탕은 너무 웃기게 생겼어, 어떻게 계란처럼 큰 다이아몬드 반지가 있어! 잠깐, 너가 나에게 반지를 준다는 건 무슨 뜻이야? 분명하게 말해줘!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_117797_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "마녀의 곁에는 종종 신비로운 검은 고양이가 따른다고 들었어, 캠퍼스의 그 길고양이를 선택하는 건 정말 숙녀의 체면에 안 맞으니, 결정을 했어, 너에게 고양이 귀 머리띠를 쓰게 해서 내 작은 검은 고양이가 되어줘."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_117798_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "저항해도 소용없어."
  },
  Voice_117799_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_117800_AwakerVoiceContent = {
    Text = "덜 덜 덜!"
  },
  Voice_117800_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_117801_AwakerVoiceContent = {
    Text = "세상에 정말로 마녀가 있을까? 그들은 사람 그림자도 없는 숲에 혼자 살고, 누가 그들을 위해 요리하고, 빨래하고, 디저트를 준비해줄까? 오후 차라도 먹지 못한다면, 그런 삶은 무슨 의미가 있을까, 생각만 해도 견딜 수 없어."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_117801_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "마녀가 왔다!"
  },
  Voice_117802_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_117803_AwakerVoiceContent = {
    Text = "너는 초콜릿이 더 있니? 좋다, 다 내게 줘. 왜 그래? 네 물건은 내 물건이다, 이건 정당한 것이 아니냐?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_117803_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "너는 내가 가장 좋아하는 사탕이 뭐냐고? 생각해 볼게, 헤이즐넛 크런치의 여운이 진짜 향기롭고, 카라멜 초콜릿도 맛있으며, 크림이 들은 딸기 젤리, 포도 젤리의 식감도 흥미롭고, 긴 긴 라면처럼 늘어나는 맥주 설탕도 있다, 색깔은 꿀처럼 예쁘고… 안 되겠다, 고르는 게 불가능해, 각 사탕마다 다 저마다의 매력이 있으니, 어쨌든 퍼킨 바구니가 있으니까, 나는 전부 가져가면 될 거야!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_117804_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "내 인생 목표는 세상에 있는 모든 사탕을 먹어보는 것이야. 세상에 이렇게 많은 종류의 사탕이 기다리고 있는 생각만으로도 매일 아침 일어나는 것에 대한 힘이 생겨. 너는 케이크라고 말하니? 케이크도 내 또 다른 인생 목표야."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_117805_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "그를 아기처럼 보인다고 해도, 실타래상 나이는 이미 땅에 들어갈 나이인데, 사탕은커녕 어떤 살아있는 것이 좋아하는 것도 그에게는 흥미가 없다. 그러니 그에게 주려던 사탕은 전부 나에게 줘라, 나는 그것들을 가장 헛되게 하지 않을 사람이다."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "잡담·툴루에 대해"
  },
  Voice_117806_UnlockDesc = {
    Text = "깨어남체「툴루」획득 후 개방"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "만약 내가 마녀가 된다면, 반드시 호화로운 궁전에서 사는 마녀가 되고, 궁전은 시끌벅적해야 하고, 매일 나를 위해 각각 다른 케이크와 사탕을 만들 요리사를 열 명 구해다 줘야 해…… 당신이 말하는 그 공주라고? 어때, 나는 공주 마녀가 될 수 있어!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_117807_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "이봐, 빨리 여러 가지 치약을 더 준비해 줘, 없다고, 나는 그렇게 많은 사탕을 먹지 않았어, 나는 충치가 없어, 단지 밤에 자는 동안 조금 아플 뿐이야……"
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "잡담·사탕에 대해"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "미사그 식당의 규칙이 자주 짜증날지라도, 그들이 만드는 디저트의 기술은 음... 그럭저럭 괜찮은 것 같아요."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "이 세상에는 많은 어두운 곳, 끔찍한 곳이 존재합니다. 세계의 멸망을 걱정할 시간이라면 그 전에 사탕을 더 많이 먹는 것이 낫습니다."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_117811_AwakerVoiceContent = {Text = "아파!"},
  Voice_117811_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_117812_AwakerVoiceContent = {
    Text = "지금은 그 양털 카펫, 원양 블랙 펄 목걸이, 동양 실타래크 잠옷은 없어졌지만, 매일 설탕 가득한 방에서 깨어나면 손을 뻗으면 가득 찬 호박 바구니를 만질 수 있는 삶, 아마도 이것이 행복의 진정한 모습일 것입니다…… 요, 그렇게 자랑스럽게 웃지 마세요. 이 아가씨를 계속 섬겨야 하니 더 노력해야 해요!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_117812_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "미사그도 무의미한 짓을 하네. 나의 사탕 사냥을 방해하다니. 결국 이렇게 내 입으로 들어오게 되어 있는데."
  },
  Voice_117813_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_117814_AwakerVoiceContent = {
    Text = "무엇을 하려고? 내 사탕이 먹고 싶으신가? 흥흥, 그렇게 좋다면 관대하게 주도록 해, 자, 마녀님이라고 한 번 외쳐봐!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "이걸 강도로 부를 수는 없습니다. 나는 단지 숙녀의 귀한 권리를 행사하는 것뿐이죠."
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "정의의 사탕 마녀, 등장! 모든 길잃은 사탕들이여, 있어야 할 곳으로 돌아가라!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "아이 참, 쪼잔하기는! 나중에 기억해두라고!"
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "왜 그 쥐가 당당하게 사탕을 훔쳐갈 수 있는데 나는 안 되는 거야? 당신들은 숙녀를 대상으로 하고 있어! 불경스러운 짓이야!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "에에, 안 줄거야? 그럼, 진심으로 가지러 간다?"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "사탕을 드릴게요!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_117821_AwakerVoiceContent = {
    Text = "저 식당의 웨이터들과 비교하면, 당신이 제일 이해심이 깊네요. 저를 위해 특별히 사탕을 준비해 주셔서 감사합니다. 더 열심히 해 주세요, 제 전용 하인님."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_117821_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "덜 덜 덜!"
  },
  Voice_117822_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_117823_AwakerVoiceContent = {
    Text = "과합니다!"
  },
  Voice_117823_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_117824_AwakerVoiceContent = {
    Text = "나를 뭐하려고 막고 있나요? 나의 충실타래한 하인으로서, 당신은 마땅히 나의 모든 사탕을 빼앗아…… 가져와야 하지 않나요?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "움직이지 마, 나는 사탕 마녀야! 얌전히 사탕을 넘기도록 해! 안 그러면... 어떻게 되도 모른다구!"
  },
  Voice_117825_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_117826_AwakerVoiceContent = {
    Text = "폭신폭신, 바삭바삭, 끈적끈적, 푸석푸석. 우유 맛, 과일 맛, 견과류 맛, 초콜릿 맛! ...아아, 내가 모르는 사탕이 이렇게 많다니! 결정했어, 매주 할로윈을 개최하는 거야! 안 된다는 말은 하면 안 돼!"
  },
  Voice_117826_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_117827_AwakerVoiceContent = {Text = "으우우."},
  Voice_117827_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_117828_AwakerVoiceContent = {
    Text = "위대한 마녀는 반드시 승리한다구! 사탕의 신에게 축복받은 내가 모든 사탕을 지킬 거야! 아하하하하!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "저항해도 소용없어."
  },
  Voice_117829_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_117830_AwakerVoiceContent = {
    Text = "모든 사탕은 내 것이 될 운명이라구!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "그 아이는 너무 순 obedient해서 무섭기까지 했다. 네가 그녀에게 사탕을 달라고 하면, 그녀는 주고, 심지어 자신에게는 하나도 남기지 않았다. 그래서 사람들은 오히려 미안해하게 만든다... 헉헉, 나는 말했어, 그녀가 이렇게 알아차린다면, 자비로운 마녀는 당연히 그녀에게 몇 개를 보상으로 남겨줄 것이다."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "잡담·릴리에 대해"
  },
  Voice_117831_UnlockDesc = {
    Text = "깨어남체「릴리」획득 후 개방"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "너는 마녀의 화를 샀다!"
  },
  Voice_117832_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_117833_AwakerVoiceContent = {
    Text = "나는 화가 났다!"
  },
  Voice_117833_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_117834_AwakerVoiceContent = {
    Text = "모든 사탕은 내 것이 될 운명이라구!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "너는 뭐라고, 이 솜사탕을 구워먹을 수 있다고? 헉, 뜨끈뜨끈하고 쫀득쫀득한 게 맛있을까? 한번 맛보게 해줄래? 좋아, 그러면 비록 어깨 힘을 잃으면서 맛보아야겠다, 네가 나를 속이기라도 한다면… 음?! 이 바삭바삭하고 부드러운 식감, 정말 맛있네!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_117835_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "허망도, 도착도, 모두 정해진 운명대로!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "허망도, 도착도, 모두 정해진 운명대로!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "내 진짜 모습을 무서워하지 않는 건, 진짜 공포를 알아서라고...? 뭐야 그거, 반칙 아니야? 그래도 뭐... 조금 흥미는 생기네."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_123312_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "저기... 네 눈에는 이 세계가 어떻게 보여? 공포의 한계는 어디라고 생각해? 아니, 말로 들을 생각 없어. 광기도, 공포도, 죽음도... 전부 너랑 같이 느끼고 싶거든. 정했다. 이 호기심이 채워질 때까지, 난 네 옆에서 안 떠날 거야."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_123313_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "손쓸 수 없는 미치광이라... 뭐, 맞는 말일지도. 여긴 내가 살던 세계가 아니니까. 시시한 법도, 규칙도 없어. 그러니까 어떻게 행동하든 내 마음이지. 그러니까— 미쳐 날뛰는 녀석에게 물리고 싶지 않으면, 알아서 조심하라고, 수호자 씨."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_123314_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "내 몸 상태랑 멘탈이 불안하니까, 한번 제대로 얘기해보고 싶다고? 상관없긴 한데, 지금 바로 시작해줄래? 지루한 건 빨리 끝내는 게 좋거든."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_123315_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "「생각한 걸 솔직하게 말해」? 「\"올바르게\" 말하려 하지 마」? ...아차, 들켰네. 그럼, 내 진짜 모습을 마주할 각오는 돼 있는 거지?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_123316_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "으랴앗! 좋아, 목 하나 추가."
  },
  Voice_123770_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_123771_AwakerVoiceContent = {
    Text = "비장의 한 방으로, 보내줄게――샤이닝☆토네이도!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "왜, 나야..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_123773_AwakerVoiceContent = {
    Text = "샤이닝☆크러시!"
  },
  Voice_123773_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_123774_AwakerVoiceContent = {
    Text = "이 공포로 뒤틀린 세계를 구하고 싶다고? 좋네, 대담하고 재밌는 자살 기획이야. 네가 어디까지 가는지, 내가 끝까지 지켜봐 줄게."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "야호~ 귀여운 친구들~! 곧 도끼 맛을 보여줄 테니, 일렬로 서줘~!"
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "저기저기, 수호자! 방금 빛 보이지 않았어!? 이번엔 진짜 되는 거 아니야!? ...조사단 애들은 다들 뭐 하고 있으려나. 내 일, 전부 방치된 거 아냐? 야근은 사양이야..."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_123776_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "이 의식이 끝나면 돌아갈 수 있는 거야? 진짜로? 일단 이게 몇 번째인지는 알고는 있는 거지? ...뭐, 됐어. 시도하는 데 돈 드는 것도 아니고."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_123777_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "꺄하하! 역시 지루한 일상보다, 아드레날린 넘치는 이 순간이 나한테 더 잘 맞는다니까~!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_123779_AwakerVoiceContent = {Text = "하!"},
  Voice_123779_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_123780_AwakerVoiceContent = {
    Text = "왜, 나야..."
  },
  Voice_123780_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_123781_AwakerVoiceContent = {
    Text = "샤이닝☆슈퍼노바! 발사!"
  },
  Voice_123781_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_123782_AwakerVoiceContent = {
    Text = "비장의 한 방으로, 보내줄게――샤이닝☆토네이도!!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "뭐지, 이 느낌... 마치 안개에 둘러싸인 것 같아. 안개 속에 있던 그 애들이 떠오르네. 꽤 괜찮은 스트레스 해소였는데, 아쉽다."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_123783_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "「싫다」? 그런 표현은 안 써. 그냥 지루한 회의나 인간관계, 세상의 가치관 같은 게... 전부 사라져버렸으면 좋겠다고 생각할 뿐."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "그래그래... 이거야 이거... 「진정한 자신」에, 점점 가까워지고 있는 느낌이 들어."
  },
  Voice_123785_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_123786_AwakerVoiceContent = {
    Text = "실타래패네... 그럴 줄 알았어. 인생은 오르막도 있고 내리막도 있다지만, 솔직히 내리막이 훨씬 많잖아. 이제 슬슬 익숙해져야 하는데... 그래도, 그... 고마워. 나 때문에 여러 가지로 애써줘서."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_123786_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "안개의 재앙이든, 융식이든, 내가 아는 건 많지 않아. 근데 그게 오히려 매력적이지 않아?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "안녕안녕~ 무셰트야. 조사단 소속의...아, 이젠 아니었지. 그럼, 다시 한 번――나는 무셰트야. 그냥 귀여운 여자아이랍니다~!"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_123789_AwakerVoiceContent = {Text = "비켜!"},
  Voice_123789_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_123790_AwakerVoiceContent = {
    Text = "인간 거주지랑 가까워서 그런가, 어딜 가도 지루한 어른들뿐이야... 저기, 학교를 산속 같은 데로 옮길 생각은 없어?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(고통스러운 신음)"
  },
  Voice_123791_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_123792_AwakerVoiceContent = {
    Text = "이세계 돌아다니는 거, 은근 중독된다니까! 강한 깨어남체에, 무서운 융식, 거기다 정체불명의 신까지! 평범한 사회에서 벗어난 해방감이 이런 건가? 진짜 최고야!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "어라, 벌써 끝이야? 이제부터 재밌어지려고 했는데~! 그럼, 한 번만 더 자르게 해줘! 누구든 좋으니까, 빨리 빨리!"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(고통스러운 신음)"
  },
  Voice_123794_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_123795_AwakerVoiceContent = {
    Text = "뭐, 인생엔 실타래패 한두번 정도... 있어도 될 리가 없잖아~!! 너희들 전부, 목 씻고 기다리라고!!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "뭐야 뭐야? 임무? ...아, 그쪽이야? 다음부터는 인사 같은 거 필요 없어. 우리 사이에 그런 「형식적인 말」은 숨 막히기만 하니까."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "누군가를 위한 자기 희생이라니, 웃기고 짜증 나. 그런 걸 강요할 자격은, 신이라고 해도 없어."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "잡담·살바도르에 대해"
  },
  Voice_123797_UnlockDesc = {
    Text = "깨어남체 「살바도르」 획득 후 개방"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "헤에, 꽤 하잖아."
  },
  Voice_123798_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_123799_AwakerVoiceContent = {
    Text = "후우, 이제야 본성을 드러낼 수 있겠네... 만족할 때까지, 자~안뜩 놀아줄게."
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "저기, 아직 안 끝난 거야? 여기 실타래론티랑 안달루시아 츄러스도 나쁘진 않은데, 레이븐로그식 생선 조림이랑 갓 내린 헤이즐넛 카바 차가 너무 그립다니까."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_123800_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "단련시켜주는 건 고맙지만, 내가 폭주하거나 하면 어쩌려고? ...농담이야~ 하하, 농담이라니까."
  },
  Voice_123801_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_123802_AwakerVoiceContent = {
    Text = "사실타래 말이야, 당분간 이 세계에 남아 있는 것도 나쁘지 않을 것 같더라. 여기서 보고 들은 거 전부 다 기억해서, 저쪽 애들한테 이야기해줄 거야. 제목은 「무셰트의 이세계 모험기」! 어때? 완전 최고지?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_123802_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "그 애인가... 응, 귀엽긴 하지. 학교 길고양이랑 쫓고 쫓기거나 싸울 때 특히."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_123803_UnlockDesc = {
    Text = "깨어남체 「머피」 획득 후 개방"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "이 정도의 힘으로, 원래 세계로 돌아갈 수는 없겠지만... 뭐, 성장은 성장이니까."
  },
  Voice_123804_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_123805_AwakerVoiceContent = {
    Text = "아, 메이드? 나도 해본 적 있어. 다음에 내가 만든 청소기 전투법, 가르쳐줄까?"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "잡담·카렌에 대해"
  },
  Voice_123805_UnlockDesc = {
    Text = "깨어남체 「카렌」 획득 후 개방"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "꺄하하! 역시 지루한 일상보다, 아드레날린 넘치는 이 순간이 나한테 더 잘 맞는다니까~!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "저세상에 다녀오세요~"
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "그래그래, 순서대로 줄서줘~"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "소멸해라!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "무심이요, 불란이니, 보되 보지 말고 듣되 듣지 말며, 속세 만사는 족쇄임을 알지어다!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "무심이요, 불란이니, 보되 보지 말고 듣되 듣지 말며, 속세 만사는 족쇄임을 알지어다!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "저들의 머릿속이 텅 빈 이유가 궁금하시옵니까? 흠... 아마 태어날 때부터 그랬겠지요."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "노하지 말지어다, 원망하지 말지어다, 만상이 공허함을 알지어다."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "어머나, 참으로 자애로우십니다. 더 놀려보고 싶어지는군요."
  },
  Voice_126950_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_126951_AwakerVoiceContent = {Text = "아아!"},
  Voice_126951_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_126952_AwakerVoiceContent = {
    Text = "당신께서는 소첩에게 더한 아름다움을 바라십니까? 아니면 더한 공포를 바라십니까?"
  },
  Voice_126952_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_126953_AwakerVoiceContent = {
    Text = "쾌락 속에서 태어난 그 공주는 금실타래로 수놓은 드레스를 걸치고 있었사옵니다. 상아 같은 피부와 은은히 퍼지는 달콤한 향기는 보는 이를 한순간에 사로잡았지요."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_126953_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "신자들이 같은 연극을 되풀이하는 놀이에, 그녀는 이내 싫증을 내고 말았사옵니다. 욕망에서 태어난 사랑, 사랑에서 태어난 욕망에 물들어, 상실타래과 배신에 괴로워하는 모습들... 그 어리석음과 눈물에, 그녀는 점차 질려버렸지요."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_126954_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "그 눈빛, 몹시 거슬리옵니다."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "붉은 여인께서는 몇 번이고 소첩을 살롱으로 초대해 주셨지요. 이국의 과자는 꽤나 맛있었사옵니다. \n허나... 그녀의 저택에서는, 과자와 하인이 별개의 것이라는 점을 조금 더 일찍 알려주셨더라면 좋았을 것을요."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "잡담·소렐에 대해"
  },
  Voice_126956_UnlockDesc = {
    Text = "깨어남체 「소렐」 획득 후 개방"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "사랑하고 계시지 않사옵니까? 그런데 어찌 둘러싸이면 두려워하시는지요? 싫어하신다 하셨지요? 그런데 어찌 잃으면 눈물을 흘리시는지요? \n어머, 소첩이 두려워지셨사옵니까? 목련의 향기가, 이해할 수 없을 만큼 달콤하게 변해버린 듯하옵니까?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_126958_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_126959_AwakerVoiceContent = {Text = "윽!"},
  Voice_126959_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_126960_AwakerVoiceContent = {
    Text = "예? 어째서 그녀들이 겨드랑이에 문신을 새기고 있느냐고요? 재미 말고 또 무엇이 있겠사옵니까?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "잡담·창부회에 대해"
  },
  Voice_126961_AwakerVoiceContent = {Text = "아아!"},
  Voice_126961_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_126963_AwakerVoiceContent = {
    Text = "소첩이 신자들의 공물보다도 더 바라고 있었던 것이, 바로 이것이옵니다."
  },
  Voice_126963_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_126964_AwakerVoiceContent = {
    Text = "먼저 몸이요, 다음은 외양, 그리고 그것들은 마침내 같은 두 눈을 얻게 되었사옵니다... 사람의 기억에 깊이 남는, 혼을 빼앗길 듯 아름다운 눈—소첩과 같은 눈을."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_126964_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "지루하여 죽을 것만 같사옵니다. 이루고 싶은 꿈 하나 없으신지요? 참으로 유감이옵니다. 많은 이들이 하찮은 목적을 위해 검을 휘두르며, 소첩에게 피와 살을 바치고 있사온데... 허나, 당신께서라면..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_126965_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "옹용중이 왜 첩의 곁을 따르며, 또 어째서 결성되었느냐고요? 흥미로운 질문이네요. 당신도 간절히 원했으나 얻지 못한 사람, 힘이 미치지 못한 후회 같은 것이 있으신가요?\n\n음, 보아하니 없는 것 같군요, 참 아쉬워라.\n\n그런 절망 속에서 발버둥 치는 표정이, 만약 당신의 얼굴에 나타난다면, 분명 아주～아주 재미있을 텐데요."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_126966_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...이 이상 같은 짓을 되풀이하실타래 생각이라면, 소첩도 무슨 일을 저지를지 장담할 수 없사옵니다."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "그녀의 이야기는 이제 거의 잊어버렸사옵니다. 다만 말할 수 있는 것은, 그것이 즐거운 이야기이자 잔혹한 이야기였다는 것. 「유기」와 「응보」로 시작해, 끝내 「희생」과 「맹종」으로 맺어진 이야기였지요."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_126968_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "자! 고통과 공포 속에서 서로 죽여보시지요!"
  },
  Voice_126969_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_126970_AwakerVoiceContent = {
    Text = "...제법이로군요."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "누구나 이 부채 너머에서 사랑하는 이의 모습을 보게 되옵니다. 소첩은, 나약한 자들에게 힘을 내리는 존재이옵니다. 검을 휘두르는 가련하고도 아름다운 모습을 지켜보는 것이 소첩의 즐거움이지요. \n허나 만일... 만일 당신께서도 그러한 모습이 되어 주신다면, 그것이야말로 소첩에게 더없는 기쁨이 될 것이옵니다."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_126971_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "염려하지 마시옵소서. 당신께서는 저 평범한 자들과는 다르옵니다. 쉿— 뒤를 돌아보아서는 아니 되옵니다. 무언가 닿아도 개의치 마시고... 오직 소첩의 눈만 바라보시옵소서."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_126972_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "후후… 이 모습을 똑바로 마주하실타래 수 있겠사옵니까?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "입을 다무시지요."
  },
  Voice_126975_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_126976_AwakerVoiceContent = {
    Text = "어머나, 또다시 소첩의 부채를 그리 빤히 바라보고 계시다니! 후후… 이 부채 너머에 누구의 모습을 보고 싶어 하시든, 소첩이 이루어 드리겠사옵니다. 자, 이리 더 가까이— \n어머! 그만두라 하셨습니까? 그렇게 사랑스러운 얼굴로, 어찌 그리 매정한 말씀을 하시는지요..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_126976_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "당신께서는 꿈의 고향에 와서, 무엇을 찾고 계신 것이옵니까?"
  },
  Voice_126977_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_126978_AwakerVoiceContent = {
    Text = "노하지 말지어다, 원망하지 말지어다, 만상이 공허함을 알지어다."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "무례한 것!"
  },
  Voice_126979_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_126980_AwakerVoiceContent = {Text = "윽!"},
  Voice_126980_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_126981_AwakerVoiceContent = {
    Text = "소첩에게도 이처럼 사랑스럽고 순종적인 아이가 있었사옵니다. \n허나 아름다운 꽃봉오리에는 가시가 필요한 법. 꽃병에 꽂아 두고 장식할 수만은 없사옵니다."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "잡담·릴리에 대해"
  },
  Voice_126981_UnlockDesc = {
    Text = "깨어남체 「릴리」 획득 후 개방"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "상담실타래에서 일하게 해 달라 청했으나, 학원에서 거절당하고 말았사옵니다. 무엇이 문제였는지, 도무지 알 수가 없사옵니다!"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "어차피 모든 것은 끝내 허무로 돌아갈 터이니, 지금을 더 즐기시는 편이 어떠하옵니까? \n염려 마시옵소서. 언젠가 당신께서 저항할 수 없게 된다 해도, 소첩은 당신을 그 것들에게 넘겨주지 않겠사옵니다."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "거슬리옵니다."
  },
  Voice_126984_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_126985_AwakerVoiceContent = {
    Text = "참으로 드문 분이시옵니다. 멸망해 가는 이 세계에서, 하잘것없는 일들을 위해 분주히 뛰어다니고 계시다니. 그러한 당신께 자꾸만 눈길이 가옵니다."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_126985_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "가까이 오지 마시길!"
  },
  Voice_126986_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_126988_AwakerVoiceContent = {
    Text = "소첩은 꿈 없는 땅의 주인, 서라 하옵니다. 만일 당신께서 마음속으로 만나고 싶은 이가 있으시다면, 이 부채를 거두어 잠시 그 모습을 보여드리겠사옵니다."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_127088_AwakerVoiceContent = {
    Text = "생물의 어린것이라는 것은 참으로 성가신 존재이옵니다. 보잘것없고, 약하고, 시끄럽기만 하면서도, 어느새 주변을 제 뜻대로 휘두르고 있지요. \n소첩은 떠들썩한 것은 좋아하오나, 이런 소란은 사양이옵니다. 절대로 소첩에게 가까이 두지 마시옵소서."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "소첩에게 있어 자스민 아가씨이자, 착한 아이이자, 달콤하기 그지없는, 오로지 소첩만의 「소꿉놀이」이옵니다... 아니, 이런! 소첩이 무슨 말을 한 것인지… 부디 신경 쓰지 마시옵소서."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "반룡국의 전설에 따르면, 공작은 아름다우면서도 흉포한 짐승이라 하옵니다. 아름답고도 사나운 것— 듣기만 해도 가슴이 설레지 않사옵니까? 추하고도 상냥하다니, 그런 것은 전혀 흥미롭지 않사옵니다."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "냠냠, 전부 먹어버려!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "보글보글~"
  },
  Voice_129652_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_129653_AwakerVoiceContent = {
    Text = "숯댕이, 나, 밥, 같이? 같이, 밥!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_129653_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "모스! 엄청 강해!"
  },
  Voice_129654_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_129655_AwakerVoiceContent = {
    Text = "심연! 나선! 파멸! 전부——소용돌이로 변해라!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_129656_AwakerVoiceContent = {Text = "아파!"},
  Voice_129656_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_129657_AwakerVoiceContent = {
    Text = "나 건드리면, 안돼! 망가져!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_129657_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "조개껍데기, 반짝반짝! 반짝반짝, 예뻐! 너 줄게!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_129658_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "차가워, 무서워! 모스, 숨을래!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "잡담·돌에 대해"
  },
  Voice_129659_UnlockDesc = {
    Text = "깨어남체「돌」획득 후 개방"
  },
  Voice_129660_AwakerVoiceContent = {Text = "해냈다!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "사냥, 싫어! 해치워! 모스, 녀석들, 해치워!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "재밌어! 다음! 또 하자!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_129662_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "쓰담쓰담, 좋아! 모스, 너, 쓰담쓰담!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "시, 싫어! 숯댕이, 모스가 지켜!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "다시? 다시!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "헤헤, 모스! 놀 거야!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "큰 파도, 콰앙!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_129668_AwakerVoiceContent = {Text = "에잇!"},
  Voice_129668_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_129669_AwakerVoiceContent = {Text = "아파!"},
  Voice_129669_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_129670_AwakerVoiceContent = {Text = "으!"},
  Voice_129670_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_129671_AwakerVoiceContent = {
    Text = "의식?! 나도, 갈래!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_129671_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "소용돌이! 힘! 굉장해!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_129672_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_129673_AwakerVoiceContent = {Text = "쾅!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_129674_AwakerVoiceContent = {Text = "가자!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "찰싹찰싹!"
  },
  Voice_129675_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_129676_AwakerVoiceContent = {Text = "싸움!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "잡담·골리아에 대해"
  },
  Voice_129676_UnlockDesc = {
    Text = "깨어남체「골리아」획득 후 개방"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "찾았다! 잔뜩! 반짝반짝!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_129677_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "심연! 나선! 파멸! 전부——소용돌이로 변해라!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_129679_AwakerVoiceContent = {Text = "이야호!"},
  Voice_129679_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_129680_AwakerVoiceContent = {Text = "으!"},
  Voice_129680_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_129681_AwakerVoiceContent = {
    Text = "모스! 엄청 강해!"
  },
  Voice_129681_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_129682_AwakerVoiceContent = {
    Text = "냠냠, 전부 먹어버려!"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "앵무조개, 노틸라, 숯댕이! 반짝반짝!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "모스, 장전!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "스킬·2·장전1"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "모스, 씻어내!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "스킬·2·장전2"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "안아줘! 모스! 좋아!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_129686_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "숯댕이, 친구! 모스, 계속 함께!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "빨리, 빨리!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_129688_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "모스! 숯댕이! 계속, 함께? 평생!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_129689_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "콰앙~ 콰앙~ 큰 파도, 콰앙!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_129690_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "친구! 잔뜩! 좋아!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "모스! 대단해!"
  },
  Voice_129692_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_129693_AwakerVoiceContent = {
    Text = "노틸라, 보고 싶어. 아아, 노틸라, 모스, 여기! 모스, 여기!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "잡담·노틸라에 대해"
  },
  Voice_129693_UnlockDesc = {
    Text = "깨어남체「노틸라」획득 후 개방"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "모스! 강해졌어!"
  },
  Voice_129694_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_129695_AwakerVoiceContent = {
    Text = "나! 모스! 야호!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_130511_AwakerVoiceContent = {Text = "후—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "스킬·2·장전3"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "오류는 수정될 것이다."
  },
  Voice_133720_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_133721_AwakerVoiceContent = {
    Text = "당신이 목격한 비극은 수만 가지 가능성 중 하나를 엿본 것에 불과합니다. 운명의 장막을 걷어 올리니, 칠흑같이 어두운 무대가 보였습니다. 불이 꺼지고, 사람들이 흩어지며, 만상이 혼돈의 심연으로 돌아갑니다. 하지만…… 모든 것이 끝은 아닙니다. 제 의지가 아직 남아 있으니, 이 부질없는 고역을 버텨내며 다음 한 줄기 빛이 타오르기를 기다릴 수 있습니다."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "세상 사람들의 운명은 모두 실타래에 이끌려 움직입니다…… 하지만 당신의 운명은 제가 읽어낼 수 없는 대본입니다. 기대하고 있습니다, 당신이 이 세계에 어떤 멋진 즉흥 연기를 선보일지를."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "주연의 인형이여, 너만의 무대에 올라라."
  },
  Voice_133723_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_133724_AwakerVoiceContent = {Text = "음?"},
  Voice_133724_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_133725_AwakerVoiceContent = {
    Text = "지나간 모든 것은 서장에 불과합니다. 당신과 저의 새로운 장은 당신의 집필을 기다리고 있습니다, 비밀지기여."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_133725_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "희극을 좋아하신다면,\"한여름 밤의 꿈\"이 좋은 선택입니다. 저는 특히 퍽의 교활한 헛소리를 좋아하는데, 요정들의 웃음 속에는 언제나 운명이 무심코 흘린 비밀이 숨겨져 있거든요."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_133726_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "이에 따르겠습니다."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_133728_AwakerVoiceContent = {
    Text = "물레가 이곳에서 돌아간다."
  },
  Voice_133728_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_133729_AwakerVoiceContent = {
    Text = "운명의 비참한 죄수여, 너에게 정해진 판결을 받아들여라."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "만상을 꿰뚫어 보는 관찰자일지라도, 자신의 각본 속에서는 서투른 배우에 불과하다. 운명의 그물을 쥐고 있으면서도 결국 실타래에 얽매이니, 이 정해진 처지 속에서 우리는 서로 다른 길을 걷고 있지만, 그 헛된 추구를 포기한 적은 없다. 어리석다 해도, 미망이라 해도, 나도 그러하고, 그녀 또한 그러하다."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "한담: 타비에 대해"
  },
  Voice_133730_UnlockDesc = {
    Text = "깨어남체 「타비」 획득 후 해제"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "뜻밖의 반전인가요?"
  },
  Voice_133731_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_133732_AwakerVoiceContent = {
    Text = "막이 오르고 내리는 사이, 함께해 주셔서 감사합니다. 앞으로도 기대에 부응하여, 더욱 감동적인 연극의 밤을 선사해 드리겠습니다."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_133732_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "이토록 천부적인 가창력, 하늘이 내린 목소리, 맑으면서도 뜨거운, 마치 운명의 목소리에서 비롯된 듯한……만약 내 극장에 초대할 수 있다면, 아무리 까다로운 관객이라도 감탄을 금치 못할 것이다."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "한담: 틴크트에 대하여"
  },
  Voice_133733_UnlockDesc = {
    Text = "깨어남체 「틴커트」 획득 후 해금"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "당신과 나, 그 볼 수 없는 두 가닥의 운명의 실타래은 이미 단단히 얽혀 서로를 구분할 수 없게 되었고, 감옥과 길을 엮어냈습니다. 감옥의 끝도, 길의 종착점도 볼 수 없습니다. 이것이야말로 이 이야기에서 가장 매혹적인 부분입니다."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_133734_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "운명의 실타래이 이미 드리워졌다."
  },
  Voice_133735_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_133736_AwakerVoiceContent = {
    Text = "그녀는 자주 제 극장에 와서 자리에 앉곤 했습니다…… 하지만 저는 알고 있습니다, 그녀는 연극을 보러 온 것이 아니라, 이 무대를 빌려 자신의 품격을 비추려 한 것이라는 걸. 그러나 그토록 정교한 연기력을 지니고서 단지 관객으로만 머문다면, 아깝지 않을 수 없습니다. 그것은 본래 스포트라이트 아래에서 빛나야 할 것이지, 관객석의 어둠 속에 숨어 있을 것이 아닙니다."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "잡담·소렐에 대해"
  },
  Voice_133736_UnlockDesc = {
    Text = "깨어남체 「소렐」을 획득한 후 해금"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "저는 그의 연주를 들은 적이 있습니다. 그 아름다운 선율은 영혼을 뒤흔들었습니다…… 어쩌면, 그를 초대하여 제 새 작품에 운명의 교향곡 한 곡을 작곡해 달라고 해야 할까요?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "잡담·하멜른에 대해"
  },
  Voice_133737_UnlockDesc = {
    Text = "「함린」 깨어남체 획득 후 해금"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "또 하나의 원만한 이야기가, 막을 내렸군요."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "끝없는 운명의 그물, 이미 전모를 꿰뚫어 보았습니다."
  },
  Voice_133739_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_133740_AwakerVoiceContent = {
    Text = "허락해 주신다면…… 당신과 저만을 위한 2인극을 엮어 보고 싶습니다. 관객도 필요 없고, 리허설도 필요 없습니다…… 다만 기대하고 있을 뿐입니다. 당신이 빛 아래 서실타래 때, 제가 볼 수 없는 그 실타래이 어떤 놀라운 약동을 보여줄지를."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_133740_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "불행한 무용수여, 저는 그녀의 춤사위를 목격했습니다. 그것은 파멸에 다가서는 아름다움이었으니, 매 회전마다 초록빛 불꽃을 피워 올려 운명의 실타래을 태워 없애려 했지만, 안타깝게도 결국 그 실타래에 의해 가장 처절하고 아름다운 광경으로 갈라지고 말 것입니다. 기회가 된다면, 그녀만을 위한 무용극을 한 편 써드리고 싶습니다."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "한담: 리즈에 대하여"
  },
  Voice_133741_UnlockDesc = {
    Text = "깨어남체 「리즈」를 획득함으로써 해금"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "이곳에서 엮고, 이곳에서 가늠하고, 이곳에서 끊는다."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "잠잠해지거라……"
  },
  Voice_133743_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_133744_AwakerVoiceContent = {
    Text = "또 하나의 실타래이, 선명해졌군요."
  },
  Voice_133744_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_133745_AwakerVoiceContent = {
    Text = "장막이 당신을 위해 열렸고, 운명의 대본이 고요히 펼쳐지길 기다리고 있습니다. 말씀해 주세요, 어떤 운명의 궤적으로 발을 들이시겠습니까? 비통한 종막인가요, 아니면 환희의 서장인가요?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_133745_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "저는 분명 이 날마다 반복되는 직조에 도취되어 있었습니다…… 반복되고 고요한 실타래의 움직임 속에서 수만 가지 이야기의 시작과 끝을 예견하고, 모든 운명의 막이 내리는 것을 곁에서 지켜보며, 마치 운명 너머에 초연히 서 있는 듯했습니다. 하지만 운명의 그물은 피할 수 없는 것이고, 단지 방관만 하는 것은 결국 적막할 뿐입니다. 그래서 저는 극장에 발을 들여, 역할을 연기하는 가운데, 제 손으로 자아냈으나 직접 겪어보지 못한 희비를 친히 맛보게 되었습니다."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_133747_AwakerVoiceContent = {Text = "음……"},
  Voice_133747_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_133748_AwakerVoiceContent = {Text = "흥……"},
  Voice_133748_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_133749_AwakerVoiceContent = {
    Text = "이곳에서 엮고, 이곳에서 가늠하고, 이곳에서 끊는다."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "운명의 속삭임이, 더 가까워졌어요."
  },
  Voice_133750_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_133751_AwakerVoiceContent = {
    Text = "극장에서 새로운 로맨틱 코미디를 올렸습니다. 운명의 좌석에 당신을 위한 한 자리를 남겨 두었습니다. 운명이 교차하는 긴 밤마다, 당신과 만날 별빛을 고요히 기다리겠습니다."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_133751_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "이토록 집요하게 운명의 실타래을 튕기시다니…… 당신도 자신에게 속한 장을 엿보고 싶으신 건가요?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "미래가 도래했다."
  },
  Voice_133753_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_133754_AwakerVoiceContent = {
    Text = "비극의 전당에 발을 들이시겠다면,\"안티고네\"를 올려드리겠습니다. 신의 율법과 세속의 대치 속에서, 그녀의 매 걸음은 운명이 자아낸 실타래 위를 밟으며 석묘의 깊은 그림자 속으로 나아갑니다. 바로 이 속박을 벗어날 수 없기에, 그 작은 몸에서 터져 나오는 의지가 긴 밤의 외로운 불꽃처럼 눈부신 것입니다."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_133754_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "정해지지 않은 결말에서도, 인과의 그물망은 벗어날 수 없는 법……"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "실타래 위에서, 저는 무지개처럼 끊임없이 흘러가는 빛의 색채를 엿보았습니다——그것은 끝없는 그물을 이어 붙이고, 무한한 세계를 펼쳐 놓으며, 무한한 가능성을 뻗어 나가게 하여, 마침내 세상에서 가장 찬란하고 아름다운 무늬를 짜냅니다. 신이든 범인이든, 영웅이든 악인이든, 모두 그 가느다란 한 올의 실타래에 조종당하며, 운명의 시선 아래 주저 없이 자신만의 결말을 향해 달려갑니다."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "세상에 더 이상 저를 놀라게 할 선택은 없을 줄 알았는데…… 당신의 연극 취향에 깊은 인상을 받았습니다."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_133757_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "운명의 실타래은 언제나 어둠 속에서 이어져 있습니다…… 당신이 이 실타래을 건드렸고, 저 또한 흔들렸습니다."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_133758_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "저는 언제나 판에 박힌 공연을 보고 싶지 않았습니다. 극장에 들어서는 의미는 본래 복제할 수 없는 현장을 직접 체험하는 데 있는 것인데, 만약 매 공연이 기계적인 반복에 불과하다면, 무대는 정교한 감옥이 되고, 관극 또한 이미 알고 있는 결말에 대한 권태로운 순례로 전락합니다. 그런 공연은 아무리 화려해도 영혼을 잃은 것입니다. 당신은 어떻게 생각하시나요?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "운명의 실타래은 본래 제 손안에서 질서 있게 흘러가고 있었습니다…… 당신이 나타나기 전까지는. 당신의 등장이 그 궤적에 예상치 못한 파문을 일으켰습니다."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_133760_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "운명의 비참한 죄수여, 너에게 정해진 판결을 받아들여라."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "나는 끝없는 실타래타래 사이에서 유일한 궤적을 짜고 있다."
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "운명의 무대 위에서, 중생은 각자의 인과 속에 등장을 기다리고, 온갖 희비가 톱니바퀴의 회전 사이에 조용히 이야기가 되어가죠……막이 올랐습니다, 수비인이여, 당신과 저 사이의 이야기가 이제부터 시작됩니다."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_133764_AwakerVoiceContent = {
    Text = "분쟁이 다가왔습니다. 당신이 맡을 역할은, 그물을 찢는 영웅인가요, 아니면 운명에 순응하는 조연인가요?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "헛된 저항이로군."
  },
  Voice_133765_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_139865_AwakerVoiceContent = {
    Text = "감사해요. 이 선물을 소중히 간직할게요."
  },
  Voice_139865_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_139866_AwakerVoiceContent = {
    Text = "깨어남체의 구조에 대해 많이 배워서, 이제 전문가라고 할 수 있어. 하지만 은심 속의 「영성」이라는 건, 아직 좀 잘 모르겠어……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_139866_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "이것이, 새로운 세계의 시작……"
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "나는 그런 것도 할 수 있어. 다른 생물의 몸을 재구성한다든지, 조정한다든지……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_139868_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "어디를 어떻게 조정해야 하는지는 생물 종류마다 다 다르니까, 제대로 공부하지 않으면 안 돼."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_139869_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "무섭지 않아, 내 모습? 에잇, 좀 심심하네……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "누구도 우리를 방해하게 두지 않을 거야"
  },
  Voice_139871_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_139872_AwakerVoiceContent = {
    Text = "준비됐어요."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "생물은 정말 다양성이 넘치네. 더 알고 싶어!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "사야랑 같이 놀래?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_139876_AwakerVoiceContent = {Text = "아!"},
  Voice_139876_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_139877_AwakerVoiceContent = {
    Text = "이것이, 새로운 세계의 시작……"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "배불러요, 잘 먹었습니다!"
  },
  Voice_139878_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_139880_AwakerVoiceContent = {
    Text = "수밀인, 누군가를 사랑한 적 있어? 누군가를 그리워한 적 있어?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_139880_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_139881_AwakerVoiceContent = {Text = "으잇!"},
  Voice_139881_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_139882_AwakerVoiceContent = {
    Text = "여기입니까?"
  },
  Voice_139882_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_139883_AwakerVoiceContent = {
    Text = "수고했어! 좋은 수확이 있었어?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "여러 가지 검증을 한 끝에, 대충 알게 됐어. 각 깨어남체가 가진 「영성」은 완전히 달라. 그리고 내 은심 속의 영성은 「사랑」인 것 같아."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_139884_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "어때, 깜짝 놀랐지?"
  },
  Voice_139885_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_139886_AwakerVoiceContent = {
    Text = "이건 너에게 주는, 마지막 선물이야."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "「이 별들 중 어딘가에서, 내 꽃이 피어나고 있어……」라고 말했대요.\n너도 비슷한 말을 한 적 있는 것 같은데."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_139887_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "「은심」이라는 건, 아주 먼 곳의 의지와 연결되어 있는 것 같아. 정말 신기하네……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_139888_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "이건 너에게 주는, 마지막 선물이야."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_139891_AwakerVoiceContent = {Text = "야!"},
  Voice_139891_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_139892_AwakerVoiceContent = {
    Text = "어린 왕자가 말했대요, 자기가 장미를 돌봐줬기 때문에 장미가 특별해진 거라고…… 너도 그렇게 생각해?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_139892_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "어제, 릴리의 책장에서\"어린 왕자\"라는 책을 발견했어. 빌려왔거든. 나랑 같이 읽을래?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_139893_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "응, 은심의 구조도 연구해서, 깨어남체의 대략적인 윤곽을 점점 알게 됐어."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_139895_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_139896_AwakerVoiceContent = {Text = "야!"},
  Voice_139896_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_139897_AwakerVoiceContent = {Text = "읏쌰!"},
  Voice_139897_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_139899_AwakerVoiceContent = {
    Text = "잘 부탁드립니다!"
  },
  Voice_139899_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_139900_AwakerVoiceContent = {
    Text = "안녕하세요!……이렇게 말하면 맞나요?\n저는 사야예요. 음……잘 부탁드려요——"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_139901_AwakerVoiceContent = {
    Text = "민들레라는 꽃이 있는데, 씨앗을 바람에 실타래어 보낸대요. 보송보송한 씨앗이 바람에 실타래려서 고향에서 아주 멀리멀리 떠나가는 거야. 어쩌면 풀 한 포기 없는 사막에 떨어질 수도 있겠지. 그럴 때, 그 작디작은 씨앗은 무슨 생각을 할까……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_139901_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "몇 번을 해도 재미있어!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_139903_AwakerVoiceContent = {
    Text = "헤이——"
  },
  Voice_139903_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_139906_AwakerVoiceContent = {
    Text = "위험해——"
  },
  Voice_139906_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_140533_AwakerVoiceContent = {
    Text = "맛있는 음식 정말 좋아해! 사야한테 다정한 사람도 좋아해. 다정하게 대해주면 정말 기쁘거든——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "저 사람이 나를 깨어남시킨 사람이야? 왠지 눈부시네…… 음~ 그럼, 네가 그녀의 언니를 찾아줬어?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "한담: 틴크트에 대하여"
  },
  Voice_140534_UnlockDesc = {
    Text = "깨어남체 「틴커트」 획득 후 해금"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "사야가 수호자를 독차지하고 싶을 때마다 이상한 사람들이 잔뜩 몰려드는 곳이야. 역시 밀경에 있을 때가 더 좋아——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "그렇구나. 알겠어!"
  },
  Voice_140536_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_140537_AwakerVoiceContent = {
    Text = "수밀인, 링크, 깨어남체, 네가 알려준 관계잖아. 두 사람의 영혼이 연결되어 있는 게 느껴져…… 은빛 실타래? 같은 걸로, 음—— 아무래도 이것저것 다 너무 어려워……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "혈육으로 씨앗을 운반한다고? 음~ 그렇구나. 그녀의 양이 좀 궁금하네."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "잡담·타이스에 대해"
  },
  Voice_140538_UnlockDesc = {
    Text = "「테이스」 깨어남체를 획득하면 해금됩니다"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "이 세계를 위협하는 어떤 위기, 존재를 소멸시키는 어둠, 맞지? 알고 있어. 도르 교수한테 많이 들었거든."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "거친 사람은 싫어. 불쾌한 기분이 들어……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "그녀의 종족도 다른 종족을 약식해서 새로운 행성에서 번식할 기회를 얻는 것 같아. 음~ 그렇구나……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "한담: 윈코르에 대해"
  },
  Voice_140541_UnlockDesc = {
    Text = "깨어남체 「벤코르」를 획득하면 해금됩니다"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "착한 아이구나."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_141964_AwakerVoiceContent = {Text = "에이!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "특수 스킬·3"
  },
  Voice_141965_AwakerVoiceContent = {Text = "음!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "피격·오"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "매우 유감이군. 하지만 마음이 바뀌거든 알려다오. 내가 어디에 있는지는 너도 알고 있지 않은가?"
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_143501_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_143502_AwakerVoiceContent = {Text = "제길..."},
  Voice_143502_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_143503_AwakerVoiceContent = {
    Text = "피부, 근육, 신경, 뼈…… 전신이 재구축되어 간다. 되살아난 건강한 육체에 다시 활기가 넘쳐나는 것을 느껴라."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_143503_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "바다 앞에, 부술 수 없는 적은 없다!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "잔치, 사냥, 은신?\n기도를 바쳐라, 가장 오래된 바다가 내 이름을 알려주리라.\n그래…… 내 이름은 심연의 주인, 폰토스다."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_143506_AwakerVoiceContent = {
    Text = "후후, 에뷔노스에서 보낸 시간이 그리워졌나……\n에뷔노스는 이 몸속에 있다. 언제든지 돌아와도 좋다."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "어, 내가 그런 짓을 하지는 않지만, 혹시라도 언젠가 네 귀에 바다 물결 소리와 날개 짓는 소리가 들리더라도, 신경 쓰지 마라. 정상적인 현상이니까."
  },
  Voice_143507_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_143508_AwakerVoiceContent = {
    Text = "오감을 바쳐라, 영원히 심연 속에서 반성하게 될 것이다!"
  },
  Voice_143508_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_143509_AwakerVoiceContent = {
    Text = "난 활기찬 젊은이들을 무척 좋아한다. 하지만 미사그는 즐기는 것에 대한 제약이 너무 심해서, 제대로 된 사냥터조차 없지.\n게다가 그 안에는, 감히 공공연히 돌아다니면서 교수라는 간판까지 내건 더러운 녀석도 있더군."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_143510_AwakerVoiceContent = {Text = "으읏!"},
  Voice_143510_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_143511_AwakerVoiceContent = {
    Text = "이만큼이나 해줬는데, 너는 '삼촌'이라는 한마디조차 불러주지 않겠다는 건가. 정말 골칫거리로군."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "서두를 필요 없다. 머지않아 바다 깊은 곳의 어둠이 너희를 집어삼킬 것이다."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "무릎 꿇어라, 에뷔노스의 거름이 되어라."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "특수 스킬·3"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "나를 선택한 '그 존재'에 대해 말하자면…… 그저 자비롭고도 무섭다고 할 수 있지.\n어디로 떨어뜨릴지는 기분에 달렸지만, 위험에서 구해내는 것은 확실타래하다. 다만 그곳이 또 다른 위험한 장소일지라도, 지금의 '여행'에서 고려할 일은 아니야.\n참으로 흥미롭고, 예측 불가능하지 않은가. 나도 이 전통을 이어가려고 생각하고 있다."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_143515_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "나와 에뷔노스는 특별한 관계에 있다. 오히려, 나 자신이 곧 에뷔노스이며, 에뷔노스는 내게 의존하고, 내 몸을 통해 존재한다고 해야 할까."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "잡담: 에포양스에 대하여"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "고개를 들어라, 그 목을 내밀어라."
  },
  Voice_143517_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_143518_AwakerVoiceContent = {
    Text = "기억을 지우고, 존재를 말소한다…… 기억 나는군. 내가 무슨 말을 하려는지 알겠는가? 기원은 다르지만, 녀석들은 언제나 빛이 닿지 않는 곳에서 기어나오는 모양이니까."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "내 위엄을 침해하려고 하다니…… 어리석은 놈들."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "너무 약하잖아."
  },
  Voice_143520_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_143521_AwakerVoiceContent = {
    Text = "에뷔노스의 잔치는 결코 끝나지 않는다. 에뷔노스의 적에게 평온이 찾아오는 일 또한 영원히 없을 것이다."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_143521_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "아아, 너의 전율이 나에게도 느껴진다. 하지만 그럴 필요는 전혀 없어, 나의 젊은 친구여. 평범함과 소멸에 대한 너의 두려움을 받아들여라. 그리고 나를 보아라. 너에게는 항상 또 다른 선택지가 있다는 것을 깨닫게 될 테니까."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_143522_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "아아, 알고 있다. 그 재앙은 그가 직접 지시한 것이 아니라, 즐거움을 찾는 과정에서 발생한 우연에 불과하다는 것을. 하지만 그렇기에 더욱 그를 죽이고 싶어지는군.\n저 검은 안개 말이다. 부디 혼자 있는 일이 없도록 조심하는 게 좋을 거다. 그리고 내 손에 붙잡히지 않도록 기도하는 게 좋아."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "그 미끌미끌한 피쉬맨들은 내 친구가 아니다. 오히려 적이다. 의외인가? 바다는 원래 그런 놈들의 것이 아니다."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_143524_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "영원히 이곳에 머물러라!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "각오는 됐나, 사냥감들아!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "영성이 새로운 육체를 낳고, 그 육체에는 하찮은 지성이 주입된다. 그리고 그 아름답고 건강한 육체는 한곳에 모이게 되지.\n내가 했던 말 기억하는가? 바다의 깊은 곳은 모든 것을 받아들인다…… 그리고 모든 것을 거기에 머물게 한다."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_143527_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "나이트곤트, 방어하라!"
  },
  Voice_143528_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_143529_AwakerVoiceContent = {
    Text = "이 자그마한 녀석들 때문에 네가 먹고살 걱정을 하지 않길 바란다. 대가족을 부양하는 게 결코 쉬운 일이 아니라는 건 나도 잘 알고 있으니까."
  },
  Voice_143529_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_143530_AwakerVoiceContent = {
    Text = "아주 오래전, 대지가 바다 위로 떠오르기 전에, 이 별은 어떤 특별한 '영성'을 깨웠다. 강력하고, 위엄 있으며, 결코 함부로 엿볼 수 없는 존재였다.\n적이라고도, 아군이라고도 정의할 수 없는 그들에게 인류는 과거의 수많은 생명체들과 마찬가지로 하찮은 존재였다. 먼지처럼 쓸려나갈 수도, 영토와 함께 보호받을 수도 있었다."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_143530_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "오직 늙음만이 네가 홀로 맞서야 할 모험이자, 가장 친한 친구이자 가장 까다로운 적이다. 하지만 에뷔노스의 빛은 그것을 깨끗이 쓸어버려 주리라…… 너는 그런 하찮은 기억들에 묶여 있을 필요가 전혀 없단다."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_143531_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "도망칠 수 있다는 환상은 버려라."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "너는 잿빛 가루가 되는 편이 나을 거다."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_143534_AwakerVoiceContent = {Text = "핫!"},
  Voice_143534_AwakerVoiceTitle = {Text = "타격"},
  Voice_143535_AwakerVoiceContent = {
    Text = "아주 영리한 방법이군, 젊은 친구. 외래 괴물의 신자들은 시체를 바다에 던져버리는 바보들뿐이지. 그런 것들이 선물이 될 수 있을까? 안 그래?"
  },
  Voice_143535_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_143536_AwakerVoiceContent = {
    Text = "이미 너는 표적이 되었으니까."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "인정하고 싶지는 않지만, 아주 아주 가끔씩 생각할 때가 있다. 늙음이란 시간이 가져다주는 유일한 것이 아니라, 하나의 상징이 아닐까 하고.\n그러므로 나는 그것이 내 몸에 찾아오는 것 또한 허락하기로 했다. 물론…… 겉모습에 한해서 말이지만."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "기도는 효과적이다. 상상해 보아라. 벌레가 네 눈앞에서 자신들의 몸으로 론디니움 문자를 만들어냈다면, 너도 그 벌레의 소원을 들어주고 싶은 생각이 들지 않겠느냐?"
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_143539_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "아하하하! 무슨 그런 얼굴을 하고 있나, 내 젊은 친구여.\n그건 이른바 '오래된 신'들이 지켜야 할 전통일 뿐이다. 너에 관해서는 어떤 대가나 조건도 필요하지 않는다, 나는 영원히 네 편이니까."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_143540_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "흥! 외래 괴물 따위와 손잡는 조그마한 괴물 같으니라고.\n게다가 나와 그 녀석을 같은 제단에 모시다니! 이건 완전한 모욕이다!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "잡담: 툴루에 대하여"
  },
  Voice_143554_UnlockDesc = {
    Text = "깨어남체 「툴루」를 획득하면 해금됩니다"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "적의 적은 아군이다. 기회가 된다면, 숙적이 가장 좋아하는 장난감을 빼앗아버리는 거래쯤은 해줘도 상관없지."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "잡담: 라이커에 대하여"
  },
  Voice_143555_UnlockDesc = {
    Text = "깨어남체 「레이크」 획득 후 해금"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "오호라? 나와 겨뤄보겠다는 건가? 나야 상관없다."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "더! 더 많은 힘을 다오!"
  },
  Voice_146159_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_146160_AwakerVoiceContent = {
    Text = "난 순수하지 못 한 놈은 싫어한다. 그건 대개 나약함을 의미하기 때문이지. 허나 네 녀석은 예외다. 이때까지 나는, 많은 것을 짊어진 자는 더 먼 곳으로 나아갈 수 없다고 여겨 왔다. 그러나, 네 녀석이 걷는 길은, 이런 나조차 놀라지 않을 수가 없군…… 어쩌면, 나와는 다른 길을 걷는 자야말로, 성장하고 도전할 가치가 있는 상대일지도 모르겠다. 그렇지 않나, 「라이벌」이여!"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "별하늘을 헤엄치는 고래가 모든 것을 집어삼킨다!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "나와 겨룰 수 있음을 영광으로 여겨라!"
  },
  Voice_146162_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_146163_AwakerVoiceContent = {
    Text = "별의 바다가 파멸을 지켜보리라!"
  },
  Voice_146163_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_146164_AwakerVoiceContent = {
    Text = "부족해. 아직 멀었다……"
  },
  Voice_146164_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_146165_AwakerVoiceContent = {Text = "후우!"},
  Voice_146165_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_146166_AwakerVoiceContent = {Text = "흥."},
  Voice_146166_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_146167_AwakerVoiceContent = {
    Text = "이 세상이 사라진다고 한들, 내가 알 바는 아니다. 허나 그것이 내가 힘을 좇고 있는 길을 가로막는 것은 용납하지 않겠어."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "피할 수 없는 멸망이 다가온다 하여, 모든 존재를 의심하기 시작하다니…… 그런 어린애 같은 지루한 논쟁에는 낄 생각 없다. 멸망이 무엇인데, 기억에 남겨둔다 한들 무슨 소용이 있나? 힘 그 자체가 바로 이 세상의 의미인데."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "잡담: 융해·돌에 대하여"
  },
  Voice_146168_UnlockDesc = {
    Text = "깨어남체 「융해·돌」 획득 후 해제"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "네 녀석의 눈에는, 이 세계의 것이 아닌 의지가 깃들어 있다. 순수한 건 아니지만서도, 충분히 굳세지. 자, 증명해 보여라! 네 녀석은 어떤 힘과 야망을 가지고서 내 앞에 서있는 거냐!"
  },
  Voice_146169_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_146170_AwakerVoiceContent = {Text = "하앗!"},
  Voice_146170_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_146171_AwakerVoiceContent = {
    Text = "나와 겨룰 수 있음을 영광으로 여겨라!"
  },
  Voice_146171_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_146172_AwakerVoiceContent = {
    Text = "혼돈의 숨결이여, 오랜만에 보는군…… 이런 허무 속에 태어난 그 순간부터, 내가 좇아왔던 건 변하지 않았다."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_146172_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "나에게 도전하는 거냐? 그 용기는 가상하니, 내게 박살날 수 있는 영광을 내려주도록 하지. 「미사그의 수호자」를 향한 나의 예의랄까."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_146173_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "약자와 겁쟁이, 자기만의 세계에 빠진 멍청이들로 넘쳐나는 거짓된 유토피아이지. 허나, 그런 건 아무래도 좋다. 나는 이곳에서 최고의 흥분을 선사하는 적을 만날 수 있었으니까 말이다. 그것만으로도 충분하다."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "강한 힘을 지녔으면서도, 두려움과 죄책감, 피로에 사로잡혀 자신을 기나긴 꿈속에 가둬두고 있다니. 실타래로 아까운 일이다."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "잡담: 툴루에 대하여"
  },
  Voice_146175_UnlockDesc = {
    Text = "깨어남체 「툴루」를 획득하면 해금됩니다"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "별것 아니었군."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "봉인이 조금 느근해졌군…… 별의 바다 깊은 곳에 있는 힘이 솟구쳐 오고 있다. 참 오랜만에 느끼는 감각이다……"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_146177_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "별하늘을 헤엄치는 고래가 모든 것을 집어삼킨다!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "……통쾌하군."
  },
  Voice_146179_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_146180_AwakerVoiceContent = {
    Text = "나는 오랜 세월 동안 별의 바다를 떠돌면서, 자신을 강하다고 착각하는 놈들을 이 손으로 심연에 처넣어 왔었다. 네 녀석에게는 특별한 무언가가 있어. 허나 나와 어깨를 나란히 하고 싶다면, 먼저 고개를 들어 보여라. 나약한 동행자 따위는, 나한테 필요 없으니까."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_146180_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "용감한 자, 겁이 많은 자, 강한 자, 나약한 자…… 후, 아니. 상대가 어떤 인간이든 상관없다. 실타래력만 있는 라이벌인 거라면, 나는 최고의 기분을 느낄 수 있을 테니."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "나약함. 이 세계에는 구역질 나는 것들이 수없이 많지만, 그중에서도 가장 죄가 무거운 건 나약함이다. 누구나 검을 쥐고 이 세계에 태어나지. 손을 늦추며, 패배한다는 생각을 품은 채로 운명의 전장에 다다르는 건 절대로 용납하지 않을 거다. 그건 상대에 대한, 나아가 나 자신에 대한 모욕이니까."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "부패한 별의 잔해여, 깨어날 때가 왔다!"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "후…… 몸이 끓어오르는 상대였다. 다음엔 봐주지 않겠다."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "내 뼈가 기쁨으로 가득차 떨리고 있다…… 네 녀석의 노력을, 이 눈으로 확실타래하게 보았다. 이것이 네 녀석이 내 곁에 설 자격이 있다는 걸 증명하는 거다, 수호자여."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_146185_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "후…… 잘도 알아차렸구나, 수호자. 힘의 족쇄라는 건 부수기 위해 존재하는 거다!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_146186_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_146187_AwakerVoiceContent = {Text = "오호라?"},
  Voice_146187_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_146188_AwakerVoiceContent = {Text = "음?"},
  Voice_146188_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_146189_AwakerVoiceContent = {
    Text = "조금만 더 가면…… 내가 평생을 좇아온, 그 힘의 종착점이……. 나와 함께 걸으며, 나를 이곳으로 이끌었던 것은 바로 네 녀석이다. 네 녀석과 함께 궁극에 다다르는 그날을 목도할 것이 참으로 기대되는구나!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_146189_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "어쩌면 내가 네 녀석을 얕잡아 봤던 모양이다…… 그 성장 속도, 그리고 네 안에 잠든 힘은, 내 예상을 뛰어넘었다. 시간이 흘러가며 함께 쓰러져 간 수많은 생명을 봐 왔지만, 너는…… 뭔가가 남다르다. 알려다오. 네 안의 그 힘은, 대체 어디에서 온 거냐?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_146190_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "지옥이 입을 벌리고 기다리니!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "아아, 그렇나…… 힘의 종착점 같은 건 애초에 존재도 하지 않았던 건가…… 진정한 도전이, 이제야 나를 위해 당도하였구나! 네 녀석이 나를 이곳으로 이끌었던 덕에, 모든 걸 깨달았다. 머지않아 네 녀석 눈앞에, 한층 더 완벽해진 전사로 거듭나주지. 그때는 한층 더 완벽해진 네 녀석을 보고 싶구나, 나의 「라이벌」이여."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_146193_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "주제넘긴."
  },
  Voice_146194_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_146195_AwakerVoiceContent = {
    Text = "힘이 골수 속에서 끓어오른다!"
  },
  Voice_146195_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_146196_AwakerVoiceContent = {
    Text = "모조리 집어삼켜 주마!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_146197_AwakerVoiceContent = {
    Text = "자비, 나약함 그리고 방황…… 네 녀석의 눈은 불순물로 가득 차 있다. 순수하지 못한 자는, 힘 같은 게 어떤 건지도 이해 못 해."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_146197_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "진정한 힘은, 애초에 복수나 수호와는 무관한 것. 힘이란 단지 힘일 뿐, 또 다른 나는 이 이치를 「진정으로」 깨닫지 못했어. 그것이 바로 그녀가 충분히 강하지 못했던 근원이지."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "잡담: 로탄에 대하여"
  },
  Voice_146198_UnlockDesc = {
    Text = "「로탄」 깨어남체를 획득한 후 해금"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "한 번만 말할 테니, 잘 담아 들어라.\n나, 로탄은. 네 녀석을 기다릴 가치가 있는 라이벌로서 인정하기로 했다.\n네 녀석이 정점에 다다를 때까지, 내가 네 녀석의 가장 믿음직스러운 검이 되어주지. 이 맹세는 충성심이나 감정과는 관계없다. 최고의 라이벌이 도중에 죽어버리면 곤란하니까. 그것뿐이다."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_146199_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "자, 나를 한번 죽여봐라. 아니면 죽여버려주지."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "지옥이 입을 벌리고 기다리니!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "뼈의 칼날이 향하는 곳은 만물이 무너지리라!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "힘이란 건…… 끝 따위는 없다!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_147493_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(한 곡의 거친 부드러운 노래)"
  },
  Voice_147494_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_147495_AwakerVoiceContent = {
    Text = "관중, 더 많은 관중이 필요해요,……"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "사……하얀 사막……여기는 정말 위험해요, 어서 저와 함께 떠나요."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_147496_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "나는 아직도 새로운 고향의 지도를 기억해요. 모두 색칠되어 있어 매우 아름답습니다. 이곳이 우리가 가야 할 곳입니다. 우리는 노래를 부르고 행복을 찾을 수 있습니다."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_147498_AwakerVoiceContent = {Text = "아"},
  Voice_147498_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_147499_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_147499_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_147500_AwakerVoiceContent = {Text = "어……?"},
  Voice_147500_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_147501_AwakerVoiceContent = {
    Text = "그것은……별하늘의 소리……"
  },
  Voice_147501_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_147502_AwakerVoiceContent = {
    Text = "또 왔구나. 과거처럼 내 옆에 앉아서 함께 기다리자. 무엇을 기다리는 거야…? 기다림, 그 자체가 기다림이지."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "완벽한 리허설이었어요. 이제 무대에 오를 준비가 된 것 같아요."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_147503_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_147504_AwakerVoiceContent = {Text = "떨어져."},
  Voice_147504_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_147505_AwakerVoiceContent = {
    Text = "폐허와 죽음에 바치다."
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "나는 정신병자도 아니고, 슬픔을 느낀 적도 없습니다. 터무니없는 소문에 귀를 기울이지 마세요."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "기묘하네, 그들은 내 노래를 두려워하는 것 같아…"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_147508_AwakerVoiceContent = {Text = "쉿..."},
  Voice_147508_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_147509_AwakerVoiceContent = {
    Text = "정말 멋진 공연복이네, 반짝반짝 빛나네……"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_147509_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_147510_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_147511_AwakerVoiceContent = {
    Text = "지금까지 남겨진 별들의 찬란한 빛이여."
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_147512_AwakerVoiceContent = {Text = "노래해."},
  Voice_147512_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_147513_AwakerVoiceContent = {
    Text = "정확한 발성 훈련……? 하지만 지금 내 소리에 매우 만족해요."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_147513_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "소리가 조금 변한 것 같아……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_147515_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "어때요, 제 노래가 잘 들리나요?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_147517_AwakerVoiceContent = {
    Text = "자세요……"
  },
  Voice_147517_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_147519_AwakerVoiceContent = {Text = "좋아."},
  Voice_147519_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_147520_AwakerVoiceContent = {Text = "아"},
  Voice_147520_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_147521_AwakerVoiceContent = {
    Text = "천만에요… 고마워요라고 말해야 하나요?"
  },
  Voice_147521_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_147522_AwakerVoiceContent = {Text = "하아..."},
  Voice_147522_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_147523_AwakerVoiceContent = {
    Text = "빛을 발하라."
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "오랜만의 감각… 마침내 무대에 다시 회귀했다. 감사합니다, 수호자,"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_147524_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "무례하게 방해합니다… 나를 나무에서 내려줄 수 있을까요? 왜 올라갔는지 기억이 나지 않네요. 아마도 머리 위의 구름이 약간 그리움을 불러일으켰던 것 같아요…"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "내 족인들은 나를 떠난 적이 없습니다. 그들은 단지 매우 멀리,매우 멀리 갔을 뿐입니다."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "잡담·동족에 대해"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "들었나요?"
  },
  Voice_147527_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_147528_AwakerVoiceContent = {Text = "오."},
  Voice_147528_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_147529_AwakerVoiceContent = {
    Text = "너는 항상 내 주변을 맴도는 것 같아……알았어, 너는 내 팬이구나."
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_147529_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "라라라~ 뭐라고? 여기에 세계를 파괴하는 재앙이 있다니? 아…… 그럼 제 머리를 잘 정돈해야겠고, 누나를 찾아가야겠어……"
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "쉿… 말하지 마요, 나쁜 사람들이 왔어요. 그들은 저와 누나를 잡아가려 하고, 배에 타지 못하게 하려고 해요…"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "잡담·안전에 대해"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_147532_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "나가 깨어났을 때, 행성은 파괴되고 있었다. 나는 밤하늘에서 한 줄기씩 벗겨지는 것을 보았고, 세상은 거센 바람에 휩싸인 천이 되어 먼저 변형되고, 그 다음에는 찢어지고 부서졌다."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_147533_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "이것은 제 서명 포스터로, 피크맨 선생님이 그려 주신 것입니다. 이걸 당신에게 드립니다."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "잡담·파인트에 대해"
  },
  Voice_147534_UnlockDesc = {
    Text = "깨어남체 「파인트」를 획득하면 해금됩니다."
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "음~? 궁금해? 유감이지만, 이 요정 대모의 보물 창고는 외부인이 자유롭게 드나들 수 있는 그런 공간이 아니라구. 안에 뭐가 가득 차 있는지 알고 싶다면은…… 요정 교단에 들어올래?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "카라부의 말을 안 믿는 거야? 흑흑…… 역시 사람을 속이기란 어려운 건가…… 사실타래 나는 @1 공화국 보에몽 6세의 사생아야, 적군의 추적을 따돌리기 위해 요정인 척하고 있는 거라구…… 이런 중~요한 비밀을 알려줬는데, 이젠 믿을 수 있겠지? 그렇지?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_149668_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "아파라……~!"
  },
  Voice_149669_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_149670_AwakerVoiceContent = {
    Text = "사탕을 너무 많이 먹는다고? 아니라니까! 이건 이 요정님께서 미소를 유지하는 비결이라고. 충치같은 거 때문에 그만둘 순 없잖아?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "자, 이 요정님의 곁으로 오도록 해. 뭐? 다 같이 공물을 나눠 먹자고? ……뭐, 그게 미사그 대학의 교칙이라면야…… 나는…… 따, 딱히 반대할 이유가 없지만. 그럼, 모두 함께 즐겨보자고!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_149671_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "정말이지, 진짜 경건한 어린 양이라니까."
  },
  Voice_149672_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_149673_AwakerVoiceContent = {
    Text = "뭐 조금이라면야…… 그렇다면 요정이 축복을 내려줄게?"
  },
  Voice_149673_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_149674_AwakerVoiceContent = {
    Text = "너흰 아직 너무 어려~♪"
  },
  Voice_149674_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_149676_AwakerVoiceContent = {
    Text = "이번 예배 의식은 어느 때보다 성대하게, 그리고 공물의 양도 더 많아야 해…… 아, 물론 산 제물 같은 거는 아니야. 나는 마음씨 고운 요정님이니까, 누군가를 해치거나 하지는 않는다구~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_149676_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "수호자. 카라부의 진짜 속마음, 들을 준비됐어?\n내 출생 같은 그런 건 아무래도 좋아. 중요한 건, 수호자는 하늘이 내려준 가장 소중한 선물이니까. 나는 앞으로도 계~속 수호자의 곁에 있기로 결정했다구.\n이것도 내 과거를 더 캐지 못하게 하려는 수작 중 한 개라고 생각한 거야? 헤헤헤, 어떻게 생각해?\n어쨌든, 진심을 말해준 기념으로 사과 맛 젤리 하나 줄래?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_149677_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_149678_AwakerVoiceContent = {Text = "히히~"},
  Voice_149678_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_149680_AwakerVoiceContent = {
    Text = "괜찮아. 다음에는 조~금만 더 날 지키는 데 집중하면, 실타래패하지 않을 테니까."
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "그 손에 놀아나지는 않을 거니까!"
  },
  Voice_149682_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_149683_AwakerVoiceContent = {
    Text = "앗, 이렇게나 많은 공물이…… 크흠, 흐흐흠. 잘 해줬네, 이건 칭찬하지 않고는 못 배기겠는걸! 자, 이 요정님의 입맞춤을 선사해줄게!…… 엥? 뭘 생각하고 있는 거야? 당연히 이마에다 하는 거지!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_149683_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "신도 여러분, 공물 고마워! 마음씨 고운 이 요정님이 보답으로 신전에 네 동상을 세워줄게. 아아, 그 냉철하고 고귀한 모습을 재현하려면, 좀 더 많이 모아야겠지만~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_149684_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "너? ……넌 아직 깨달음을 얻지 못한 교단의 일원이려나. 이 요정님은 네가 세계의 진리를 깨닫는 날을 손꼽아 기다리고 있다구…… 그때가 오면 교주님께 몸도 마음도, 공물도 착실타래히 바치는 거다? 히히."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "목록에 적힌 것들이…… 벌써 다 모였다고? 미사그는 대체 돈을 얼마나 가지고 있는 거야…… 좀 빨리 아니, 조금만 더 빨리 알았더라면, 이 요정님께서…… 아아, 아무것도 아니야. 그냥 덱스터 경의 후한 인심에 감사하고 있었을 뿐이야. 히히."
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_149686_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "가장 싫어하는 거? 그야, 당연히 계약을 지키지 않는 마법사들이지. 몰래 알려주자면, 마법사들은 전부 엄청난 사기꾼들이야. 그 녀석들의 예언이나 저주를 믿다가는, 눈 깜짝할 새에 네 지갑이 텅 비게 되는 건 시간문제일걸! 그럼 어떻게 하면 막을 수 있냐고……? 네 모든 돈을 요정의 축복에 쓰이게 하면 돼!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "반가워! 나는 저기 머나먼 곳에서 온 「순백의 요정」인데~ 쪼오금은 관심이 생기지? 이 요정의 축복에는 공물을 얼마나 바치냐에 따라 강도가 달라진다~? 히히~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_149689_AwakerVoiceContent = {
    Text = "이전의 예배 의식에서는 7번의 예배와 3번의 서약 절차 밖에도, 신도들이 요정님을 위해 새 신전을 지어주고, 풍성한 공물을 바쳐줬다구. 봐봐, 이게 그 목록이야!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_149689_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "자. 버리고 싶은 미련 같은 것들 전부, 이 깊은 눈 속에 묻어버리자……"
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "나의 출생에 대해 알아보고 있는 거지? 헤헤, 그건 이 요정 대모의 비 · 밀 · 인 · 데~ 그래도 굳이 알고 싶다면은—— 요정 교단에 내가 직접 쓴 전기가 보관되어 있는데, 은심 10만 개를 낸다면 볼 수 있어…… 어떡할래?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_149691_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "괜찮지 않아? 여기엔 귀여운 애들이 엄청 많고, 상상을 초월할 정도로 후한 생활 지원까지 있단 말이지? 이 정도면, 동방으로 갈 여비도 곧 다 모일 거 같아."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "일상·미사그에 대해"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "요정 대모를 찬양하는 걸 잊지 말라구? 히히 ♪"
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "정말 죄송합니다만, 요정의 영역이란 곳은 신성한 곳이랍니다. 그러니까, 이상한 늑대이신 너 님의 출입을 거절하겠습니다…… 어? 공기 중에 거짓말의 향기가 나는 거 같다고? 아니, 그냥 코가 망가진 거 아니야?"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "잡담: 라이커에 대하여"
  },
  Voice_149694_UnlockDesc = {
    Text = "웨이크업 바디 「레이크」 획득 후 해금"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "엥? 내가 가짜 요정이라고 말하는 사람이 있었다고?…… 들켜버렸네, 헤헤. 그래도 그런 거에 연연하지 않을 거지?…… 그치?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "잡담·소문에 대하여"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "으음…… 맛있어~♪"
  },
  Voice_149696_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_149697_AwakerVoiceContent = {Text = "괜찮아~"},
  Voice_149697_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_149698_AwakerVoiceContent = {
    Text = "길 잃은 어린 양들아, 이 요정님이 너희의 죄를 씻어줄게. 후훗~♪"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "엥, 아직도 포기 안 한 거야? 어쩔 수 없네~ 이 카라부가 직접 알려줄게. 사실타래 카라부는 동쪽의 엄청 높~은 설산을 다스리는 여신인 우모파티의 딸이야…… 응? 그 여신에게는 아들밖에 없지 않냐고?…… 음~ 그래도 그분에 대한 기록은 항상 어딘가 빠진 부분이 있기 마련이잖아."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_149699_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "짜자~안! 요정의 빛망울을 네게 선사할게! 가보자!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "뭐, 됐어~ 더 이상은 캐묻진 말아주라? 응? 이런 무례한 짓을 그만둬준다면—— 특별히, 가장 아끼는 사탕 반쪽을 떼어줄게. 십자군 전장에서는 이런 다알~콤한 사탕이 엄청 귀중한 거니까……"
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_149701_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "카라부의 축복은 세상의 어떤 질병이라도 고칠 수 있어. 물론 이런 흑색 전염병도…… 진짜라니까! 하~지만, 충분한 신앙심을 가지고서, 나를 믿기만 한다면 말이지. 히히."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_149703_AwakerVoiceContent = {Text = "싫어!"},
  Voice_149703_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_149704_AwakerVoiceContent = {
    Text = "요정의 빛망울!"
  },
  Voice_149704_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_149705_AwakerVoiceContent = {
    Text = "7번의 예배, 3번의 서약—— 그것들로 요정의 사함을 받도록 하여라!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_150079_AwakerVoiceContent = {Text = "느껴봐!"},
  Voice_150079_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_150104_AwakerVoiceContent = {
    Text = "엥? 어떻게 여기 있는 거야? 오지에한테 아무도 들어오게 하지 말라고 말했는데…… 네가 오지에의 주인이라고? 믿음직스럽지 못한 아이는 정말 골칫거리라니까. 이번 집회를 위해 열심히 준비하고 있었는데. 그럼…… 받은 공물은 반반으로 나누고, 한 번만 눈감아주는 걸로 하면 안 될까?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "잡담: 오지에에 대하여"
  },
  Voice_150104_UnlockDesc = {
    Text = "웨이크업 바디 「오지르」 획득 후 해금"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "빨리 끝내고 돌아가야지."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "카이커스가 교회에 가입한 건 내가 잠들어 있었을 때라서, 안면이 거의 없어. 인간의 모습을 버리고 완전한 「도해자」가 되고 싶어서, 스스로 찾아왔다나... 흥, 힘에 집착하다니 바보 같네."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "잡담·카이커스에 대해"
  },
  Voice_36679_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "골리아는 충실타래한 개가 아니야. 사슬이 풀리면 제일 먼저 도망칠 게 뻔해... 미리암은 왜 그를 아끼는 걸까? 전혀 모르겠어."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "잡담·골리아에 대해"
  },
  Voice_36680_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "도해자들이 태어날 때부터 그 모습이었던 건 아니야. 사람들 사이에 섞이기 위해, 인간과 다를 바 없는 모습으로 반생을 사는 거야. 그러니까 조심해. 네가 제일 좋아하는 케이크 가게의 점장도 도해자일지도 모른다고?"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "잡담·도해자에 대해"
  },
  Voice_36681_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "셀레스트의 이상한 뱃노래, 선장이 만들어준 베이컨과 생선 조림, 바닷바람 때문에 비린내가 나는 뻣뻣한 이불... 위험한 일도 많아서 긴장됐지만, 바다로 망명을 떠난 그 몇 달을……그들과 보낸 날들을, 평생 잊지 않을 거야."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "잡담·「유령선」에 대해"
  },
  Voice_36682_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "대학에 있는 모두가 바빠 보이지만, 여기에는 지금까지 느껴보지 못한 편안함이 있어. 같은 목표를 향해서 협력하는 느낌... 뭐, 나쁘지 않네."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해·2"
  },
  Voice_36683_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "침대는 딱딱하고, 방은 춥고, 홍차에서는 풀맛이 나고... 여기가 싫은 이유는 차고 넘쳐. 그래도, 네가 있으니까, 나쁘지 않아... 가 아니라, 내가 특별히 참아주는 거야!"
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해 3"
  },
  Voice_36684_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "고, 고마워... 응? 갑자기 무슨 감사인사냐니, 당연하잖아?! 너에게, 바다 위에서 도움을 받았으니까... 잠깐, 왜 웃는 거야? 설마, 나를 놀리는 거야?"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해 2"
  },
  Voice_36685_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "나와 그 여자 사이에 가족의 정이 있다고 생각했어... 하지만 이런저런 일을 겪고 나니, 그저 내 착각이었다는 걸, 겨우 깨달았어.  그 여자를 어떻게 할지는, 너희들이 알아서 해. 더 이상 나에게 가까이 오지 못하게만 해줘."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해 2"
  },
  Voice_36686_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "이런 거 이상해... 진짜 이상해. 심장은 더이상 뛰지 않는데, 몸은 아직 따뜻해... 있잖아, 내 손 좀 잡아줘. 기분 탓은 아닌지 확인해봐야겠어."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "잡담·「깨어남체」에 대해"
  },
  Voice_36687_UnlockDesc = {
    Text = "「조사 임무」제6장 완료 후 개방"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "나는 레이왕국에서 태어난 것은 아니지만, 대성당은 나의 두 번째 생명을 획득한 곳이다. 이렇게 보면, 이곳을 내 고향으로 여기는 것이 무엇이 잘못된 것인가?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "잡담·고향에 대해"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "무형의 역병이 수년간 창궐한 후, 아버지 신은 마침내 제 기도를 들어주셨고, 저에게 고난에 대항할 수 있는 「축복」을 내려주셨습니다. 그것은 확실타래히 생명을 부여할 수 있지만, 대가가 필요합니다. \n저는 대행자로서, 그 축복을 받은 이들을 대신하여 짊어져야 합니다."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "잡담·「축복」에 대해"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "나에게 있어 깨어남체 상태는 아버지 신이 품에 안은 영혼에게 주신 은혜입니다. 이것은 두 번째 생명이며 과거의 후회를 만회할 기회이기도 합니다. \n나는 아버지 신의 일을 계속하며 대행자의 책임을 다하고 더 많은 고통을 덜어내겠습니다."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "잡담·「깨어남체」에 대해"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "다시 한번 감사의 말씀을 드립니다, 수호자. 당신은 제 의견을 존중해 주셨고, 심사회에 비밀을 지켜주셨습니다. 만약 그들이 개입했다면, 저에게 성당 구역에서 계속 봉사할 수 있는 허락을 하지 않았을 것입니다."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해 2"
  },
  Voice_45156_UnlockDesc = {
    Text = "특파 기록「피의 색」완료 후 개방"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "그 아이는 진실타래하고, 견고하며, 착한 마음을 지니고 있으며, 매우 드문 밝은 영혼을 가지고 있다. 이런 사람을 마지막으로 본 것은 내 첫 인생에서였다."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "잡담·오지에에 대해"
  },
  Voice_45157_UnlockDesc = {
    Text = "특파 기록「피의 색」완료 후 개방"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "시각을 잃었다고 해서 내가 무작정 맹목적인 것은 아닙니다. 아버지 신은 어둠을 내리면서도 저에게 영혼의 미약한 빛을 볼 수 있는 능력을 주셨습니다."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "잡담·시각에 대해"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "그때의 나는 「축복」을 받았지만, 그래도 한낱 보통 사람에 불과했다. 고통받는 이들이 너무 많았고, 「축복」이 필요한 이들도 너무 많았다. 나는 그들을 전부 구하고 싶었지만, 성공하지는 못했다.\n그것은 나의 가장 큰 후회이자 영원한 죄책감이다."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "잡담·첫 번째 생명에 대해"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "교정 내 많은 사람들이 《성전》에서 언급된 \"백색의 불꽃\"이 월광을 의미한다고 생각한다: 창백한 메신저가 월광에서 나타나 우리를 고통에서 벗어나게 할 것이다. \n하지만 나는 알고 있다, 진정한 불꽃은 당신과 내 심장에서 타오르는 영혼이다."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "잡담·「창백한 불꽃」에 대해"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "사실타래, 제 정체를 숨기라는 건 대주교님의 뜻이었어요. 자세한 이유는 말씀하지 않으셨고, 다만 이렇게 경고하셨죠: 지극히 순수한 곳에도 그림자가 존재할 수 있으니, 선을 행할 때도 조심해야 한다고요.\n물론, 당신은 완전히 신뢰하고 있어요."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "잡담·신분을 숨기는 것에 대해"
  },
  Voice_45161_UnlockDesc = {
    Text = "특파 기록「피의 색」완료 후 개방"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "제 노랫소리는, 힘이 되었을까요?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "쳇... 같은 아이인데, 왜 모두들 걔한테만 예의를 갖추는 거야? 나도 똑같이 대접해주라고!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "잡담·툴루에 대해"
  },
  Voice_4909_UnlockDesc = {
    Text = "깨어남체「툴루」획득 후 개방"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "있잖아, 다른 깨어남체들이 평소에 뭘 하는지 알아? 차, 착각하지 마, 친구를 만들고 싶다거나 그런 거 아니니까! 난 그냥……그래! 관찰하고 싶었을 뿐이야!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "잡담·일상에 대해"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "젠장젠장젠장! 놈들을 갈기갈기 찢어발겨서, 거미 밥으로 만들어줄 거야!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "여운이..."
  },
  Voice_4912_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_4913_AwakerVoiceContent = {
    Text = "음율이..."
  },
  Voice_4913_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_4914_AwakerVoiceContent = {
    Text = "대담하구나."
  },
  Voice_4914_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_4915_AwakerVoiceContent = {
    Text = "급히 할 필요는 없어요…… 무엇을 도와드릴 수 있을까요?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_4916_AwakerVoiceContent = {Text = "대담!"},
  Voice_4916_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(관심 있게 질문)"
  },
  Voice_4917_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_4918_AwakerVoiceContent = {
    Text = "자연은 나에게 최고의 존귀함을 선물로 주었다. 네가 이것이 내가 아니라고 생각하니?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "무엇을 할까요?"
  },
  Voice_4919_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_4920_AwakerVoiceContent = {
    Text = "헤헷, 잘했지! 그럼 보수를 줘. 말해 두지만, 나한테 공짜로 널 도와 줄 의리는 없다고?"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "오지 마!"
  },
  Voice_4921_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_4922_AwakerVoiceContent = {Text = "위험해!"},
  Voice_4922_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_4923_AwakerVoiceContent = {
    Text = "아름다운 승리였어... 이 순간을 영원히 남기고 싶을 정도야."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "오염의 원천을 느꼈습니다......본체에 한 발짝 더 다가섰습니다......으아아, 이 세계를 찢어버리겠습니다!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_4924_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "우리는... 준비됐어요. 명령을 내려주세요, 수호자."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_4925_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "주인님, 정말 착하신 분이세요. 아쉽지만 제가 보답할 것이 없어요. 저는 아무것도 할 수 없는 놈이니까..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_4926_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "...한 걸음 더 나아가면, 「그녀들」과 완전히 분리될 수 있을까?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_4927_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "어, 아직 살아있네...당신, 정말로 내 장기를 훔쳐가거나 실타래험 대상으로 삼지 않을 거예요?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_4928_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "윙클의 일족은 생물의 뇌 속에 기생하는 능력을 가지고 있어. 나와 융합한 외부의 의지도 그 이유로 그녀를 두려워하고 있지. 뭐, 지금은 그저 육체에 묶인 불쌍한 영혼에 불과하지만."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "잡담·윙클에 대해"
  },
  Voice_4929_UnlockDesc = {
    Text = "깨어남체「윙클」획득 후 개방"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "아이기스는, 이 세상의 모든 게 다 좋아요. 빈민원에서 식사 전에 기도를 할 때나, 모두와 함께 수호자님이 임무에서 돌아오길 기다릴 때 편안하고 행복한 기분이 들어요... 하지만, 아이기스가 행복을 누릴 자격이 있을까요?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "가라앉아라."
  },
  Voice_4931_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_4932_AwakerVoiceContent = {
    Text = "피어나라."
  },
  Voice_4932_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_4933_AwakerVoiceContent = {
    Text = "「신뢰」, 「복종」, 「노예」, 「애정」, 「존경」... 언어 모듈을 재구축하고 있습니다. 수호자 님, 학습에 협조를 부탁드립니다."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_4933_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "현재 에리카 대기 중, 본체의 냉각이 1시간 15분 후에 종료됩니다. —<Del: 에리카가 기동하길 원한다면 네 심장을 바쳐라>— 긴급 기동하시겠습니까? ...권한 인증 중...... 최고 권한의 인증이 완료되었습니다. 안녕하세요, 수호자 님."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_4934_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "조사 태스크의 평균 위험 지수는 7이며, 평균 의료 소모는 연금술 보충제 8병이고, 평균 시체 처리 소요 시간은 10시간입니다. \n결론: 수호자의 업무는 매우 위험하므로 행동 중 안전에 유의해야 합니다."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_4935_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "교사 프로필 검색 중, 에리카 레이필드, 은심 기계장치 및 자동화 교과 강사, 사망ー 찾으시는 데이터가 이것입니까? 알겠습니다, 다른 데이터를 찾아보겠습니다. 키워드 '에리카'로 재검색 중입니다."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_4936_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "자료를 검색하려면 아카이브의 이름을 완전히 설명해 주세요. 부분 검색 기능은 현재 사용할 수 없습니다."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_4937_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_4938_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_4938_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_4939_AwakerVoiceContent = {Text = "아"},
  Voice_4939_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_4940_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_4940_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_4941_AwakerVoiceContent = {Text = "아"},
  Voice_4941_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_4942_AwakerVoiceContent = {
    Text = "충전 완료. 폭파, 개시."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "충전 완료. 폭파, 개시."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "이런 사소한 일은 앞으로 왕녀의 휴식을 방해하지 말아요."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "틴커트를 지키던 때처럼, 당신을 지킬 거에요."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "저는 중요한 인물이 아니며, 많은 신자 중 한 명에 지나지 않습니다... 주를 따르며, 그분의 눈에 들 수만 있다면, 영혼을 바쳐도 후회는 없습니다..."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "잡담·과거에 대해"
  },
  Voice_4946_UnlockDesc = {
    Text = "깨어남체「툴루」획득 후 개방"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "나를 봐!"
  },
  Voice_4947_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_4948_AwakerVoiceContent = {
    Text = "내가 누구인지 알고 있는 거야?"
  },
  Voice_4948_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_4949_AwakerVoiceContent = {
    Text = "……그뿐이다. 다만 그 광적인 제사로 인해 나를 방해하지 않는다면, 그들과 같은 방에 있어도 상관없다."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "잡담·도해자에 대해"
  },
  Voice_4949_UnlockDesc = {
    Text = "깨어남체「미리암」,「골리아」,「카이커스」,「산」,「파로스」중 하나 획득 시 개방"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "나는 그 검은 느낌을 싫어해요. 마치 내면이 비어 있는 것 같고, 충족되지 않는 기분 때문에 온몸이 간지러운 것처럼 느껴져요…"
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "그만해그만해그만해그만해 그 얘기는 그만해..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_4953_AwakerVoiceContent = {Text = "하!"},
  Voice_4953_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_4954_AwakerVoiceContent = {Text = "윽!"},
  Voice_4954_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_4955_AwakerVoiceContent = {
    Text = "신국은 멸망했다고 결론짓는 학자들은, 어찌나 우매한 것일까요. 그러나, 무어라 하든 관계없습니다. 신국을 재건한다면, 학자들의 말 따윈 어떤 방해도 되지 않으니까요."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "사실타래……조용히 말하자면, 나는 지금의 오토바이에 상당히 만족하지 못하고 있어—나는 그것이 싫은 게 아니야! 다만, 나는 항상 그것이 뭔가 부족한 것 같다는 느낌을 받아……"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_4957_AwakerVoiceContent = {
    Text = "발설치 마라."
  },
  Voice_4957_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_4958_AwakerVoiceContent = {Text = "자르기!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "스킬·광란 2"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "미안해......그런 거 하고 싶지 않았어……"
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "스킬·우울 2"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(관심을 가지고 낮게 외침)"
  },
  Voice_4960_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2년, 워드 필립스, 클라커스, 타비 3인이 미사그 대학을 설립했습니다. 그 후, 오랜 기간을 거쳐 마침내—<Del:이 망할 감옥>— 미사그 대학이 되었습니다."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "정의, 충성, 강한, 자제. 이들은 이미 내 마음에 깊이 새겨져 있다."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "당신을 따르겠습니다."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "도대체 어떤 무책임한 부모가 자기 딸 이름을 괴물 머리가 달린 방패에서 따온 거야? …어? 그 아이는 부모가 없다고? 음... 방금 한 말은 아이기스에게 비밀로 해야겠어."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "잡담·아이기스에 대해"
  },
  Voice_4964_UnlockDesc = {
    Text = "깨어남체「아이기스」획득 후 개방"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "지루하다면, 미로에서 나랑 \"함께 있어줘\". 어차피 네가 가진 희망이 없는 인생과 끝없는 미로는 별 차이가 없으니까!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "잡담·미궁에 대해"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "도르가 있을 때, 조사원들의 효율이 평균 78.312% 향상되었고, 그에 따라 더 많은 이들이 감정적으로 침체되었다. 그녀의 말을 인용하자면, 누군가 말을 아끼는 법을 안다면, 세상이 더 원활하게 굴러갈 거야."
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "잡담·돌에 대해"
  },
  Voice_4966_UnlockDesc = {
    Text = "깨어남체「돌」획득 후 개방"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "이건 어때?"
  },
  Voice_4967_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_4968_AwakerVoiceContent = {
    Text = "강림하라!"
  },
  Voice_4968_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_4969_AwakerVoiceContent = {
    Text = "어떻게 모험을 싫어하는 사람이 있을까요? 아무도 가지 않은 신비한 영역을 깊이 탐험하고, 미지를 찾아 나서며, 자신만의 스토리를 만들어가는 건 정말 짜릿해요!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "잡담·모험에 대해"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "안녕하세요, 전 페브르에서 온 님피아라고 합니다. 자유롭게 호흡할 수 있는 몸을 주신 당신에게... 어떻게 은혜를 갚아야 할까요."
  },
  Voice_4970_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_4971_AwakerVoiceContent = {
    Text = "방금 또 들렸어. 나를 주인이라고 칭하는 놈들의 비명이—정말 아름다워."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_4971_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "채소를 안 먹어도 될까요? 틴커트는 균형 잡힌 식사를 해야 한다고 했지만, 그 색깔들이 싫어요……"
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "조물주가 말씀하셨다: 고통은 나의 유물이 아니다. 그것을 짊어지고 해소하라, 나의 대행자여, 땅 위에 고통 없는 나라를 건설하라. 이를 위해 나는 모든 것을, 심지어 생명까지 바치겠다."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_4973_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "모든 것을 파괴하는 녹아내림의 저주 앞에서 다른 고난은 모두 사소해진다. 내가 다른 사람들을 대신하여 저주를 견디지는 못하지만, 그들의 고통을 덜어주기 위해 최선을 다할 것이다."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_4974_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "지금의 나로써는 그들의 고통을 덜고, 그들의 영혼을 위로할 수 있을까?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_4975_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "이렇게 하면 나는 모든 존재의 고통을 짊어지고, 모든 생명에게 고통 없는 땅으로 향하는 길을 열 수 있습니다."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_4976_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "이 영혼 깊은 곳의 따뜻함… 당신의 선물에 감사드립니다, бледный огонь. 이 힘으로 아마도 나는 마침내 대행자의 책임을 수행하고 더 많은 사람들을 구할 수 있을 것입니다."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_4977_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "정말로 이만큼 먹을 수 있어?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_4978_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "후후... 그건 죽음이 아니야. 너의, 나의, 이 세계의... 미래의 모습이야."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "틴커트… 그녀의 애절한 노래를 들으면 춤을 추고 싶어지게 된다…"
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "잡담·틴커트에 대해"
  },
  Voice_4980_UnlockDesc = {
    Text = "깨어남체「틴커트」획득 후 개방"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "이런 평범한 시련으로, 혈맥의 힘을 끌어낼 수 있는 거냐?"
  },
  Voice_4981_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_4982_AwakerVoiceContent = {
    Text = "무기가 손에 익기 시작했어."
  },
  Voice_4982_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_4983_AwakerVoiceContent = {
    Text = "이런 걸로 내가 감사할 거라고 생각하진 마. 나는 긍지 높은 종족이다."
  },
  Voice_4983_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_4984_AwakerVoiceContent = {
    Text = "공격은 최선의 방어다."
  },
  Voice_4984_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "그 남자…… hey, 잠깐 기다려, 우리의 도박이 아직 끝나지 않았잖아?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "잡담·타인에 대해"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "나는 학원의 기록 장치를 매우 좋아합니다. 만약 휴대용 버전을 개조할 수 있다면, 실타래시간으로 무엇을 잊었는지 알려주면 좋겠습니다…"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "땅에 기어다니는 벌레들…… 아니, 벌레도 못 되고, 단지 빵 부스러기일 뿐이다. 그분의 강림을 위해 공양이 되어간다."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "보급이야."
  },
  Voice_4988_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_4989_AwakerVoiceContent = {
    Text = "보급이야."
  },
  Voice_4989_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_4990_AwakerVoiceContent = {
    Text = "음...... 힘을 주세요, 더 세게. 그래, 그렇게 해요......"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "아직 완전히 깨어남하지도 않았는데, 여유로운 승리로군."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "이런, 모자가 어긋났어... 음, 좋은 기분이네!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_4992_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"이런 힘을 가진 나는, 정말로 아직 인간이라고 할 수 있는 걸까?\", 전투 훈련을 받은 후, 매일 그런 생각을 했어. 세계는 어둡고, 더럽고, 그리고 지루했지... 하지만 지금은 달라. 네가 나타난 후로, 내게는 이 세계가 다이아몬드처럼 반짝여 보여. 이대로 힘이 강해지면, 언젠가 인간이 아니게 돼. 늘 그게 무서웠어. 하지만 네가, 나를 인간 세계에 묶어주었으니까, 나는 이 세계를 사랑할 수 있게 됐어. 그러니까, 앞으로도 잘 부탁해, 수호자."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_4993_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "아아... 네가 망설이는 것도 당연하네. 미안해, 내 배려가 부족했어. 파트너인 너에게는, 처음부터 제대로 설명했어야 했는데. 네가 보듯이, 나는 보통 사람과는 달라. 분명 내 출생과도 관련이 있겠지... 물론 몇 번이고 조사해보려고는 했어. 하지만 그만뒀어. 이 학교가, 내게 있을 장소를 주었으니까."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_4994_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "하얀 베일을 쓴 깨어남체와 만난 적 있어? 그녀는 이 학교의 설립자 중 하나인데, 솔직히, 그다지 좋아하진 않아. 세계가 어떻게 되든 상관없다는 듯한, 그 텅 빈 눈. 보고 있으면 불편해져. 뭐? 나와 닮았다고? 그래, 너 눈이 꽤 나쁘구나, 같이 의무실타래에 가 줄까?"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_4995_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "나와 교수 사이의 관계가 신경쓰여? 딱히 비밀은 아니니까, 듣고 싶다면 알려 줄게. 덱스터 교수는, 나를 거두어준 아버지같은 분이야. 나는 학교에서 자라서, 선생님들이 돌봐주셨어. 그 중에서도 돌은 가장 가까웠던 상대야."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_4996_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "깨어남체 사무소 수속부터, 식당에서 언제 인도 요리가 나오는지까지, 학교에 관한 거라면 뭐든 물어봐. 폐가 되진 않냐고? 내가 그렇게 차가운 사람으로 보여?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_4997_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "거울아 거울아, 세상에서 가장 위대한 마술사는 누구니? 카시아라고? 정답!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_4998_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "괜찮은데?"
  },
  Voice_4999_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5000_AwakerVoiceContent = {
    Text = "진짜 좋네요～"
  },
  Voice_5000_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5001_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5001_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5002_AwakerVoiceContent = {
    Text = "성공...인가요. 당신께 도움을 드릴 수 있었네요."
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5003_AwakerVoiceContent = {Text = "무용해!"},
  Voice_5003_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5004_AwakerVoiceContent = {
    Text = "(인내심)"
  },
  Voice_5004_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5005_AwakerVoiceContent = {
    Text = "착한 아이네."
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "함께 이곳을 시끌벅적한 바다로 만들자!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "호위가 필요한가? 네가 정의를 추구하는 한, 나도 힘을 빌려주도록 하지."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5008_AwakerVoiceContent = {
    Text = "타오르지 않도록..."
  },
  Voice_5008_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5009_AwakerVoiceContent = {
    Text = "타오르지 않도록..."
  },
  Voice_5009_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5010_AwakerVoiceContent = {
    Text = "안아주고 싶나요?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "내가 몸에 차고 있는 이 족쇄들을 보세요—— 그것들은 장식이 아니요, 상기시키는 것이죠. 배신당하고 짓밟힌 맛을 잊지 않게 하려는 것입니다."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "학교의 과거가 알고 싶다면, 자료관에 가 보는 게 좋아. ...응? 설마, 나보고 전부 설명해달라는 거야? 학교의 전신을 포함해서, 역사가 300년은 넘게 있는데?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "저기, 패배자에겐 어떤 벌을 줄까?"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "심해는 당신을 영원한 잠으로 초대합니다."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "심해는 당신을 영원한 잠으로 초대합니다."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "영겁의 녹염, 죽음을 고하는 춤을, 이곳에!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "영겁의 녹염, 죽음을 고하는 춤을, 이곳에!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "그 등대처럼 빛나는 양반님…… 영원한 밤의 여정에서 그녀처럼 눈부신 빛을 볼 수 있었다면, 아마도 저는 길을 잃지 않았을 거예요……"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "잡담·파로스에 대해"
  },
  Voice_5018_UnlockDesc = {
    Text = "깨어남체「파로스」획득 후 개방"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "신입 수호자, 우선 내게 보여줄래? 내가 실타래험실타래을 나올 정도의 가치가, 너에게 있는지를."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5020_AwakerVoiceContent = {
    Text = "너는 내 하인이야. 그리고 하인의 역할은 내가 원하는 게 있을 때마다 즉시 가져오는 거고. 알겠어? 뭐야, 하인 주제에, 보상을 달라는 거야? 그래, 주면 되잖아!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5021_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5021_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5022_AwakerVoiceContent = {
    Text = "이 일격으로, 설욕을 풀겠습니다...!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5023_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5023_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5024_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5024_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5025_AwakerVoiceContent = {
    Text = "주는 것이 곧 얻는 것이다."
  },
  Voice_5025_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5026_AwakerVoiceContent = {
    Text = "주는 것이 곧 얻는 것이다."
  },
  Voice_5026_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5027_AwakerVoiceContent = {
    Text = "상처를 입을 거야!"
  },
  Voice_5027_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5028_AwakerVoiceContent = {
    Text = "오지 마!"
  },
  Voice_5028_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5029_AwakerVoiceContent = {
    Text = "나는 보름달 때 금빛 달빛을 좋아합니다. 신비롭고 부드럽고, 바람이 불면 바다 표면에 황금빛 인광이 일렁이며 꿈처럼 낭만적입니다."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "만약 우리의 고향에 융식이 일어나지 않았다면, 나와 틴커트는 헤어지지 않았을 거야…… 나는 융식을 싫어해, 채소보다 싫어."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "앞에 보물이든 항구든 상관없습니다. 제 임무는 당신이 무사히 귀항할 수 있도록 보호하는 것입니다."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5031_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "천국새의 궤적을 따라가세요. 종점은 파란색의 앞에 있습니다."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5032_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "나는 종종 바다 지평선을 바라보며 지평선 저편의 풍경을 상상합니다. 그것은 점점 가까워지지만 영원히 도달할 수 없는 먼 대륙입니다. 만약 그날이 온다면, 당신과 함께 가보면 좋겠습니다."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5033_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "당신의 사랑을 받아, 이제는 광포한 바다라도 당신에게 후회 없는 축복을 전할 용기가 있습니다."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5034_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "마치 노잡이들의 노래를 듣는 것 같아, 익숙한 고향의 향기가 난다."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5035_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "당신은 저를 구원하러 오신 것이지요? 부패하는 세상에서, 감염된 두 눈의 증오에서, 영원한 녹화염에서…"
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "불경한 것!"
  },
  Voice_5037_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5038_AwakerVoiceContent = {
    Text = "이것을 당신의 서약서로 간주하겠습니다."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5038_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "혼내주겠어!"
  },
  Voice_5039_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5040_AwakerVoiceContent = {Text = "으우우."},
  Voice_5040_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5041_AwakerVoiceContent = {Text = "으우우."},
  Voice_5041_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5042_AwakerVoiceContent = {Text = "으우우."},
  Voice_5042_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5043_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5044_AwakerVoiceContent = {
    Text = "쥐의 실타래력을 보여주지!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "쥐의 실타래력을 보여주지!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "주사위는 던져졌다, 였던가? 그럼 어디, 가보도록 할까!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "감사 인사에서 당신의 이름을 추가하겠습니다. 검은 피로 더럽혀진 이 두 발로 다시 아름다운 발레 세계에 발을 들일 수 있게 해주신 분이 바로 당신입니다. 앞으로도 제 춤을 지켜봐 주세요, 수호자."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5047_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "어떻게 발버둥쳐도 운명을 거스를 수는 없다. 하지만 그 순간의 빛은 영원히 굳어질 것이다."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5048_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "패배자는 어떻게 처리할까나..."
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "만약 가슴에 욕망이 없다 해도, 나는 그 백조의 역할을 잘 수행할 것입니다."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5050_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "눈을 감고, 저에게 보이는 것을 말해주세요. 흠없는 월광, 잔잔한 호수…"
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5051_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "파괴와 비운의 재앙이 왜 나와 누나에게 닥쳤을까?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "내 사랑을 받아줘."
  },
  Voice_5053_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5054_AwakerVoiceContent = {
    Text = "내 사랑을 받아줘."
  },
  Voice_5054_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5055_AwakerVoiceContent = {
    Text = "상당히 편해졌어요, 감사합니다."
  },
  Voice_5055_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5056_AwakerVoiceContent = {Text = "크읏..."},
  Voice_5056_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5057_AwakerVoiceContent = {
    Text = "답례로 당신께, 연보랏빛 수련을 선물해드리고 싶어요."
  },
  Voice_5057_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5058_AwakerVoiceContent = {
    Text = "저도, 강해질 수 있는 걸까요."
  },
  Voice_5058_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5059_AwakerVoiceContent = {
    Text = "시작한다……!"
  },
  Voice_5059_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5060_AwakerVoiceContent = {Text = "으악!"},
  Voice_5060_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5061_AwakerVoiceContent = {
    Text = "이 다리의 상처 말인가? 네가 이것을 신경 쓸 줄은 몰랐다. 생전에 전투 중에 입은 상처다. \n염려하지 마라. 깨어남한 이후로는 더 이상 내 전투에 방해가 되지 않는다. \n통증? 아니, 그런 문제에 대해 생각해 본 적 없다."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5061_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "샤일비아가 내 심리 상태를 물어봤어, 네가 그녀를 부른 거지? 나는 환상적인 사지의 통증이 가끔 발생하는 것을 인정해. 하지만 내 감정은 신경 쓰지 마. 나는 너의 칼, 너의 날카로운 무기야. 정의를 위해 싸울 수 있는 한, 작은 통증은 아무런 영향을 미치지 않아."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5062_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "차회, 차회를 열어볼까! 실타래비아에게 많은 차와 과자를 받았어! 음, 흥겨운 포드워켄 춤으로 교환했어!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "제 자칭? 당신은 제 개인적인 일에 이렇게 관심을 가지시나요? 그냥 이야기를 나누고 싶었을 뿐입니다…… 알겠습니다. \n군대에서는 성별에 따라 동료를 차별하지 않습니다. 힘과 속도뿐만 아니라, 당연히 머리 스타일과 호칭도 포함됩니다. 오랜 시간이 지나면서 이런 표현 방식에 익숙해졌습니다."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5064_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "재미있군... 힘을 손에 넣은 내가, 너를 갈기갈기 찢어버릴지도 모르는데, 무섭지 않은 거냐?"
  },
  Voice_5065_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5066_AwakerVoiceContent = {
    Text = "이몸의 수호자답게, 매일 제법 열심히 하고 있잖냐! 칭찬해주지."
  },
  Voice_5066_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5067_AwakerVoiceContent = {
    Text = "나약한 놈들의 목을 찢어발기고 싶어서 못 참겠구만."
  },
  Voice_5067_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5068_AwakerVoiceContent = {
    Text = "무용은 순수합니다. 말은 오해를 불러일으킬 수 있지만, 춤은 그렇지 않습니다."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "잡담·춤에 대해"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "나는 바다를 싫어하는 것이 물론이겠지. 바다는 내가 사랑했던 모든 것을 흡수해버렸으니까…"
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "잊어버려도, 잃어버려도, 이번에야말로 돌아갈 거야!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "잊어버려도, 잃어버려도, 이번에야말로 돌아갈 거야!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "위험하니까, 이 이상 가까이 오지 마세요."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5073_AwakerVoiceContent = {
    Text = "마음대로 만져 보세요...... 이 모든 것은 그 해에 격투장에서 남긴 흉터, 남자의 훈장!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(통증을 느끼며 소리치는 것)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5075_AwakerVoiceContent = {Text = "아야야!"},
  Voice_5075_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5076_AwakerVoiceContent = {
    Text = "(통증을 느끼는 음성)"
  },
  Voice_5076_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5077_AwakerVoiceContent = {
    Text = "(불편한 음성)"
  },
  Voice_5077_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5078_AwakerVoiceContent = {
    Text = "몸에서 무언가가 솟아오르는 듯한 느낌이 들어. 이게 영지 계발이라는 거구나."
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5078_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "이것은 새로운 기술인가요? 제 의수의족은 훨씬 가벼워진 것 같습니다."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5079_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "바다 바람의 짠내를 맡았습니다. 내 나라까지 멀지 않았습니다."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5080_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "지나간 동포들이 이 빛을 따라 귀환할 수 있을까."
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5081_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "나는 이미 수천 수만 년을 찾아다녔습니다. 이 순간의 백 년은 문제가 되지 않습니다. 당신의 그곳에 도착하기 전까지 계속해서 당신을 돕겠습니다."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5082_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "나는 오직 고국을 위해 반짝일 것이며, 너…"
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5083_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "나는 미풍을 느꼈습니다. 그것은 가는 모래를 데리고 내 발등을 스쳤습니다."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5084_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "나의 힘은 여기까지입니다. 너무 욕심을 부리지 않는 게 좋아요?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5085_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "이미 이렇게까지 말했으니, 당신은 저에게 무엇을 기대하십니까? 그저 전투뿐입니까?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5086_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "사랑의 머리, 원한의 머리, 증오의 머리, 욕망의 머리… 아, 또 오셨네요?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5087_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "거래라면, 그냥 선물만 받을 순 없죠. 이 가게에서 뭔가 골라 보시겠어요?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5088_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "나는 당신에게 기쁨, 즐거움, 정상에 도달했을 때의 쾌감을 가르쳐 줄 거예요…… 반대로, 당신도 자신의 욕망을 솔직하게 드러내야 하죠."
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "나는 모나무이고, 모나무도 나다. 나무의 젖이 내 혈맥에서 넘치고, 나무의 의지가 내 마음에서 맴돌고……"
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "잡담·풍요의 지모수에 대해"
  },
  Voice_50899_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "배신의 대가를 치러라!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "저는 방금 열쇠 무덤에서 은신처를 찾던 중 당신의 묘비를 본 것 같습니다…… 제 시체도 여기에 안장될까요? 아닐까요? 정말 유감이네요."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "잡담·열쇠 무덤에 대해"
  },
  Voice_50900_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "늑대의 소년 아…… 그와 N과 사이에는 모호하고 설명하기 어려운 관계가 있어……"
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "잡담·라이커에 대해"
  },
  Voice_50901_UnlockDesc = {
    Text = "깨어남체「라이커」획득 후 개방"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "나에게 가까이 다가와, 나를 안아주고, 나를 맛보세요… 나를 잊지 말아요."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "잡담·수호자 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "그것은 지나치게 성실타래하고 조심스러운 아이였다. 물론 나는 그녀를 책망하지 않았다. 만약 그녀가 없었다면, 자유분방한 종족은 변화 속에서 파괴되었을 것이다."
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "잡담·엘바에 대해"
  },
  Voice_50903_UnlockDesc = {
    Text = "깨어남체「엘바」획득 후 개방"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "사막 속에서 태어나고 다시 사막으로 돌아갑니다. 이 짧은 여정에서 당신은 무언가를 남기고, 무언가를 심어야만 합니다."
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "잡담·사막에 대해"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "욕망은 모두 사랑에서 생겨난 것이다. 사랑은 하늘을 찌르는 거대한 나무가 되기 전, 그 처음의 씨앗이다."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "잡담·욕망에 대해"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "어라, 귀여운 소년쥐가 빠르게 지나갔네…… 나는 들었는데, 쥐는 고기를 좋아하는 동물이라고 하더라고. 그런데 이건 아직 너무 어려서, 요람에 있는 상태인 것 같아……"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_50906_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "그들은 나의 혈육과 피를 이어 받아 레무바시를 풍요롭게 하는 강물이 되었습니다… 이제부터는 오직 당신만이 나의 번식과 존속을 위해 노력해야 합니다…"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "잡담·아람에 대해"
  },
  Voice_50907_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "거미야…… 거미. 음~ 나는 거미를 좋아해, 그들이 빽빽이 태어나는 순간 걷는 힘을 획득하는데, 이런 번식과 생존 능력은 정말 부럽다……"
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "잡담·아그리파에 대해"
  },
  Voice_50908_UnlockDesc = {
    Text = "깨어남체「아그리파」획득 후 개방"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "나무의 피를 흐르는 모든 생명체들은 내 아이들이며, 나무 씨앗을 삼킨 당신도 내 아이와 같습니다?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "잡담·자손에 대해"
  },
  Voice_50909_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "내가 판매하는 상품? 모든 것을 갖추고 있어, 당신의 전부의 욕망을 만족시킬 수 있어……그저 그에 상응하는 대가를 치르면 되는 거야."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5090_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "어라, 어쩔 수 없이 한 번 지고 말았네요…… 다행히도, 그녀가 선택한 당신은 나무의 젖을 마시고, 제 피와 생명을 새로운 세상으로 가져가실타래 거예요?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "잡담·타비에 대해"
  },
  Voice_50910_UnlockDesc = {
    Text = "깨어남체「라모나」획득 후 개방"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "세 가지 주요 질체 중 하나인 그 녀석은 파악할 수 없는 몬스터예요. 그의 달콤한 말을 쉽게 믿지 마세요, 그럼 저는 마음이 아플 테니까……"
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "잡담·N에 대해"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "의식이 있는 것이라면 욕망도 있을 것입니다. 기계적인 생명체도 예외는 아닐 것입니다?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "잡담·에리카에 대해"
  },
  Voice_50912_UnlockDesc = {
    Text = "깨어남체「에리카」획득 후 개방"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "배신의 대가를 치러라!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "이상한 나라에, 어서오세요~!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(낮은 번호)"
  },
  Voice_5093_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5094_AwakerVoiceContent = {
    Text = "나는 조각 작업의 고통과 변화의 뜨거움을 잘 알고 있습니다. 그러나 이 모든 것이 영원한 아름다움 앞에서는 먼지처럼 작아집니다."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5094_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5095_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5096_AwakerVoiceContent = {
    Text = "그런 말들을 입 밖으로 내지 못했지만, 작품을 통해 당신에게 이야기하겠습니다."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5096_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5097_AwakerVoiceContent = {Text = "앗..."},
  Voice_5097_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5098_AwakerVoiceContent = {
    Text = "자는 군주가 내 귀에 속삭이고, 깊은 바다의 폐허가 내 눈앞에서 끊임없이 재구성되고 있다...수없이 꿈에 나왔던 장면이, 마침내 현실타래이 된 것인가?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5098_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "천만에요. 제가 준비한 작업실타래에 대해. 여기서는 모든 것이 햇빛에 가득 차 있습니다. 모든 작품과 조각 도구가 금빛으로 빛나는 듯합니다. 아, 봄은 금빛이로군요."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5099_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "비록 성격은 다르지만 나는 그 아이를 매우 좋아합니다. 그녀에게는 모든 어려움과 속박을 초월할 수 있는 용기가 있습니다. 내가 그렇게 용감하고 강한 사람이었다면, 바다에 몸을 맡긴 결말을 선택하지 않았을지도 모릅니다……"
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_5100_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "붉은 부인은 제가 지금까지 모셨던 분들과는 완전히 다릅니다... 그분을 싫어하는 건 아니지만, 대하기 조금 어렵습니다..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "잡담·소렐에 대해"
  },
  Voice_5101_UnlockDesc = {
    Text = "깨어남체「소렐」획득 후 개방"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "발버둥쳐 봐."
  },
  Voice_5102_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5103_AwakerVoiceContent = {
    Text = "광기를 품으로!"
  },
  Voice_5103_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5104_AwakerVoiceContent = {
    Text = "사냥한다!"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "이렇게까지 하지 않아도 되는데……."
  },
  Voice_5105_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5106_AwakerVoiceContent = {
    Text = "마음이란, 영원히 채워질 수 없는 심연인가 봐."
  },
  Voice_5106_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5107_AwakerVoiceContent = {
    Text = "아프지도 간지럽지도 않은데... 그래도 고마워."
  },
  Voice_5107_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5108_AwakerVoiceContent = {
    Text = "아…… 당신이 저에게 말을 걸고 있나요? 죄송해요, 방금 전에 돛대에서 보았던 광경을 회상하고 있었습니다. 당신의 질문을 다시 한번 말씀해 주실타래 수 있나요?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "잡담·과거에 대해"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "주인은, 릴리의 주인이고, 엄마."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "빈틈이야!"
  },
  Voice_5110_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5111_AwakerVoiceContent = {Text = "보였다!"},
  Voice_5111_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5112_AwakerVoiceContent = {Text = "준비—"},
  Voice_5112_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5113_AwakerVoiceContent = {Text = "하!"},
  Voice_5113_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5114_AwakerVoiceContent = {
    Text = "더 힘을 좀 더 줘~"
  },
  Voice_5114_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5115_AwakerVoiceContent = {
    Text = "뜨거운 사랑!"
  },
  Voice_5115_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5116_AwakerVoiceContent = {
    Text = "융식에 대해서라... 자세한 것은 얘기해줄 수 없지만, 하나만 알려주지. 융식은 너희들이 생각하는 것보다 훨씬 예전부터 있었다."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "본 실타래력을 낼 때가 온 것 같구나."
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5119_AwakerVoiceContent = {Text = "이쪽."},
  Voice_5119_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5120_AwakerVoiceContent = {
    Text = "출발하자."
  },
  Voice_5120_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5121_AwakerVoiceContent = {
    Text = "흐흐, 우리의 꼭두각시 공주가 또다시 울어대네요. 젖병이 입에 맞지 않는 건가요, 아니면 요람곡이 마음에 들지 않는 건가요?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_5121_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "으으... 이런 거, 상대하고 싶지 않은데..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "당신께 바치는 보답입니다."
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "뼈까지 갉아먹는 듯한 작열... 힘이 넘치는 게 느껴져요."
  },
  Voice_5124_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5125_AwakerVoiceContent = {
    Text = "그... 죄송해요! 움직이지 말아주세요!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "이 따뜻함에는, 손이 닿네요..."
  },
  Voice_5126_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5127_AwakerVoiceContent = {
    Text = "안뜰의 장미가 활짝 피었어요."
  },
  Voice_5127_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5128_AwakerVoiceContent = {
    Text = "잘했어. 계속 나아갈 수 있겠어?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "기사에게 원래의 형태는 없습니다. 충성, 용기, 그리고 미덕이 기사를 만듭니다. 저의 무기도 지키고자 하는 의지가 있었기에 중검의 형태가 된 것입니다."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "잡담·기사에 대해"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "젠킨, 다이애나, 마이크, 트요그, 브라운... 앗! 죄, 죄송해요. 혼잣말이었어요! 네? 어째서 이름들을 불렀냐고요? 그건, 아이기스가 모두를 잊고 싶지 않아서..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "잡담·친구에 대해"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "가까이 오지 마!"
  },
  Voice_5131_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5132_AwakerVoiceContent = {Text = "싫어!"},
  Voice_5132_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5133_AwakerVoiceContent = {
    Text = "과학의 힘을 경외하도록 해."
  },
  Voice_5133_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5134_AwakerVoiceContent = {
    Text = "과학의 힘을 경외하도록 해."
  },
  Voice_5134_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5135_AwakerVoiceContent = {
    Text = "라~라라라~ ...불러주셔서 감사합니다. 노래를 바칠 일이 있다면, 미리 말씀해주세요."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5137_AwakerVoiceContent = {
    Text = "그것은... 혈관 속을 흐르는 검은색 점액, 모든 신음을 소멸시키는 최종적인 힘! 「나」는 여기서 탄생하여 파괴를 위해 존재한다! 하하하!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "여어! 무슨 일이야? 내기인가? ...하아, 평범한 사건이잖아. 미안하지만 난 빠질게, 운이 달아나버릴지도 몰라서 말이지..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5139_AwakerVoiceContent = {
    Text = "이론 수업은 지루해. 수업 중에는 항상, 맨 뒷 열에서 몰래 조사 파일을 읽고 있어. 이거, 돌한텐 비밀이야."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "복수는 아직 끝나지 않았어!"
  },
  Voice_5140_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5141_AwakerVoiceContent = {
    Text = "악의 복수를 맛봐라!"
  },
  Voice_5141_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5142_AwakerVoiceContent = {
    Text = "나는 유리엣트를 탓하지 않았다. 그녀 역시 검은 시련의 희생자일 뿐이지만…… 그녀는 내 말을 듣고 싶어 하지 않는 것 같아요. 당신이 그녀에게 전해줄 수 있을까요, 사자?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "잡담·유리에트에 대해"
  },
  Voice_5142_UnlockDesc = {
    Text = "음성 미실타래장"
  },
  Voice_5143_AwakerVoiceContent = {Text = "천천히."},
  Voice_5143_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5144_AwakerVoiceContent = {Text = "이쪽."},
  Voice_5144_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5145_AwakerVoiceContent = {
    Text = "잠깐! 질척질척 만지지 마! 옷이 흐트러지잖아! 됐어, 나는 마음이 넓으니까 용서해줄게."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "필요 없다!"
  },
  Voice_5146_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5147_AwakerVoiceContent = {Text = "쳇!"},
  Voice_5147_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5148_AwakerVoiceContent = {
    Text = "당신이 저를 어둠에서 깨어남시킨 그날부터, 저는 확신했습니다. 당신이 모든 것을 융식이라는 절망에서 구원하여 무구의 정토로 인도하실타래 수 있다는 것을. 저는 이 날을 기다리고 있었습니다."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해 1"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "피의 냄새다..."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "목표물은 어디냐? 나를 깨운 답례로, 네 적을 죽여주지."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5151_AwakerVoiceContent = {
    Text = "카시아의 모자는 기다리다 지쳤다고!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "저는, 신이 아닌 존재에게 설레여서는 안된답니다... 하지만 당신의 체온은..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "뭐냐, 해 보자는 거냐?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "오염자……"
  },
  Voice_5154_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5155_AwakerVoiceContent = {
    Text = "용서할 수 없다."
  },
  Voice_5155_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5156_AwakerVoiceContent = {
    Text = "에리카는 현재 정상적으로 작동하고 있으며, 미사그 대학 내 전기 설비와 잘 연결되어 있습니다. 기숙사의 전등을 켤 필요 있어요?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "잡담·에리카에 대해"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "드디어 식사 시간이네, 후후..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "보라색 넓은 모자를 쓴 여자가 무대에 가까이 오지 않게 해요! 이유는 묻지 마세요. 만약 당신이 그녀의 모자에서 점액질이 흘러나오는 것을 원하지 않는다면, 그녀를 이쪽으로 오게 하지 마세요!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "잡담·다포딜에 대해"
  },
  Voice_5159_UnlockDesc = {
    Text = "깨어남체 「다포딜」획득 후 개방"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "너는 항상 그래왔나? 모든 사람에게 등을 맡기고 신뢰를 주는 거야? 너무 천진난만해?"
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "증오는, 묶어둘 수는 있어도, 절대 사라지지 않아..."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "깨어남체? 으응... 그래그래! 아침 7시는 제일 머리가 깨어남하는 시간이야! 내일은 빨리 일어나서 바다로 조개를 주우러 가자!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "잡담·깨어남체에 대해"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "영생을 주노라!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5164_AwakerVoiceContent = {Text = "하앗!"},
  Voice_5164_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5165_AwakerVoiceContent = {Text = "하앗!"},
  Voice_5165_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5166_AwakerVoiceContent = {
    Text = "죄, 죄송해요. 여기 있으면 방해가 되겠죠? 지금 바로 떠날게요!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5166_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "머무를 곳을 제공해 줘서 고마워. 하지만 내 무대를 기대하고 있는 거라면, 포기하도록 해. 나에게는 이제, 무대에 설 자격이 없어."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5168_AwakerVoiceContent = {
    Text = "머무르게 해주셔서, 감사해요. 답례로 뭐든 해드릴테니 말만 해주세요. 차라도, 내드릴까요?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5168_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "여기는 따뜻해서, 떠나고 싶지 않아요. 혼자 있을 때는 어둡고, 차갑고, 무서워요..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5169_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "아이기스도... 평범하게 살 수 있을까요? 아직 마음의 준비가 안 되었는데, 수호자님은 아이기스를 친절하게 받아주셨어요... 저, 앞으로도 잘 부탁드려요... 수호자님."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5170_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "아아, 생각났다, 생각났다고! 더러운 인간의 피 때문에... 나는 다시 태어나지 못했어! 어째서냐! 어째서 내 지느러미는 움직이지 않지?! 어째서...!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5172_AwakerVoiceContent = {
    Text = "나는 구운 문어, 끓인 문어, 볶은 문어...\n어떤 사람들은 내가 고의로 신성 모독한다고 생각하지만, 죄송합니다, 문어가 정말 너무 맛있어서 그렇습니다, 하하하하!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "지렁이. 별들. 나는...... 유우하시! 죽여...... 나를 죽게 해!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5173_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "깊은 붉은색의 몸체, 맥동하는 촉수, 끊임없이 열리고 닫히는 구강... 좋아, 좋아! 나는 이미 누군가의 목을 찢어발기고 싶어서 견딜 수 없어!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5174_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "하하하하하, 바로 이런 느낌이야! 더 줘봐… 두 배, 아니, 열 배 분량!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5175_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "끝까지 버텨볼게요."
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "이 신기한 느낌...... 나쁘지 않아. 리반트 마법사의 벨라도나보다는 낫네."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5177_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "동료? 흥…… 동료 따위 필요 없어. 나는 같은 짐에 두 번 걸리지 않을 거야."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5178_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "너와 협력하는 것은 단지 너가 나와 맞먹는 힘을 보여줬기 때문이다. 잊지 말아요, 이 계약은 네 힘이 약화될 때 종료될 거야. 그때가 되면 주저하지 않고 네 목을 베어버릴 것이다."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5179_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "나는 당신의 두 눈에서......반짝임의 휘광을 보았습니다. 그것은 야심과 욕망의 불꽃입니다. 범인, 자신을 알라! 우리는 정말로 같은 종류의 사람들입니다!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5180_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "신천옹을 알고 있나요? 그들은 인간 따위는 안중에도 없이, 힘차게 날개를 펼쳐 폭풍우의 도전에 맞서죠. 하지만 일단 땅 위로 내쫓겨 조롱과 야유 속에 놓이면, 거대한 늘어진 날개가 오히려 비참한 방해물이 되어버려요.\n이 이야기에 깊은 뜻은 없어요, 그저 당신과 함께 있으면 편안해서, 이런저런 얘기를 해본 것뿐이에요."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5181_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "아마도, 시대가 정말로 변한 것일세. 지금은 약한 자들도 암초를 넘어 파도 위에서 활약하며 청공의 왕이 될 수 있다네. \n인간, 네가 역사를 새로 쓰는 그날을 기다리고 있겠다. 그때가 되면, 나는 영광스럽게도 너의 손에 쥐어진 거대한 검이 되겠노라!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5182_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "전환률이 너무 낮네. 처음부터 공부할 필요가 있겠어. 내일 내 사무실타래로 오도록 해."
  },
  Voice_5183_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5184_AwakerVoiceContent = {
    Text = "당신은 다른 돌을 만났나요? 「세계의 진실타래」이 이렇게 차갑고 이성적인 돌을 완전히 다른 사람으로 바꿔놓다니…… 결국 우리도 그런 모습이 될까요?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "잡담·@2에 대해"
  },
  Voice_5184_UnlockDesc = {
    Text = "깨어남체 @2 획득 후 개방"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "주인... 명령이 필요해, 명령을 내려줘."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5186_AwakerVoiceContent = {
    Text = "기체 성능이 상향되었습니다."
  },
  Voice_5186_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5189_AwakerVoiceContent = {Text = "으흐흥!"},
  Voice_5189_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5190_AwakerVoiceContent = {
    Text = "친구를 많이 많이!"
  },
  Voice_5190_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5191_AwakerVoiceContent = {
    Text = "친구를 많이 많이!"
  },
  Voice_5191_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5192_AwakerVoiceContent = {
    Text = "죄송합니다, 저는 요람을 떠날 수 없어요… 이런 식으로 하면 모두의 시야를 가리게 될 테니까요, 그래서 저는 교실타래 맨 뒤에 있는 게 좋겠어요."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "뭐?! 콘스탄티노플 카펫도, 실타래론티도, 안달루시아의 츄러스도 못 샀다고!? 쳇... 그 여자는 늘 쉽게 구해서, 흔한 줄 알았는데..."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "최초의 내 모습과는 상당히 멀군."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5194_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "이토록 급하게, 당신과 같은 재능 있는 분에게는 다소 서두르는 것 같아요."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "강해졌다 해도, 이 짐승의 모습은 변하지 않아. 그야 이 녀석은, 내 힘이 구현화된 존재니까 말이지."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5196_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "혼돈의 바다로 돌아간 기분이다, 나쁘지 않아."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5197_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "여기까지 잘 해냈다, 동행자로써 인정해주지 않을 것도 없지."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5198_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "미로의 벽은 부수면 그만이야, 힘의 벽도 말이지."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5199_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "음식을 함부로 다루는 것, 금지... 식당의 의자를 부수는 것, 금지... 알겠어. 다시는 안 할게요."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5200_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "엄마라고 불러도 돼?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5201_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "주인, 명령은? 녀석들과 함께 걸어다니면, 모두가 무서워한다고? 알겠어, 감출게."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5202_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "깨어남체가 된다는 건 이런 느낌이었구나."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5203_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "엄마, 옆에서 자도 돼? 혼자 있으면, 무서운 끔을 꿔. 릴리의 손발이 떨어져 나가서, 엄청 아파..."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5204_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "와앗! 카렌을 기대해주셔서, 정말 감사합니다! 카렌은 그저 볼품없는 시녀일 뿐인데..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5205_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5206_AwakerVoiceContent = {
    Text = "꿈 같아요."
  },
  Voice_5206_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5207_AwakerVoiceContent = {
    Text = "마침 조각에 쓸 소재가 필요했는데. 신선한 게 제일 좋지, 후후."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5208_AwakerVoiceContent = {Text = "조용히."},
  Voice_5208_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5209_AwakerVoiceContent = {
    Text = "집착하는 자는 헛된 일을 행한다."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5209_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "이 지경이 되었으니, 당신의 의도를 어느 정도 이해할 수 있다. 상관없어, 계속해라."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5210_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "나는 당신의 결심을 보았습니다. 다시 잠들기 전에, 나는 당신의 증인이 될 것입니다, 운명에 대항하는 증인의 아들의 장엄한 행동을 목격할 것입니다. 하지만 지금, 저는 한 점 휴식 시간이 필요합니다."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5211_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "천명에 순응하는 것이 나쁘지 않다. 왜 운명의 의지를 거스르는가."
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5212_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "원하는 것을 이루기 위해 당신은 이렇게 많은 것을 페이할 수 있네요…"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5213_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "아, 진짜! 시끄러워! 그 녀석 일로 날 귀찮게 하지 마! 후, 됐어... 맘대로 해. 어차피 한가하니까, 어울려줄게. 감사하라고!"
  },
  Voice_5214_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5215_AwakerVoiceContent = {
    Text = "융식……그러한 더러운 검은 액체가 종종 그의 꿈을 침입하여 참기 힘들게 한다."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "권력은 양날의 검이고, 제가 어떻게 모르겠습니까…… 하지만 깨달아서 너무 늦었습니다, 너무 늦었습니다. 제가 손을 놓으면, 그들은 달려들어 저를 파편으로 찢어버릴 것입니다…… 만약 처음부터 당신처럼 명확했다면, 그렇게 비참한 방식으로 막을 내리지는 않았을 것입니다. 어, 어? 당신이 말하길, 앞으로 휴게실타래에서 살롱을 개최할 수 있다고요?! 이거 정말…… 당신을 직접 섬기는 것 외에 어떻게 보답할 수 있을까요……"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5216_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "당신은 정말로 유염불진인 손님 같으시네요. 도대체 어떻게 모시면 당신이 손에 쥔 특권을 내어놓으실타래까요? 권력은 재앙을 초래할 뿐, 이렇게 명백한 이치를 당신이 모르지 않겠죠?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5217_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "살롱이 시작되기 전에 이야기를 듣고 싶으신가요? 시골 소녀가 권력의 왕관을 차지하게 된 이야기…… 어디서부터 시작해야 할까요, 부모님에게 노년의 노인과 결혼하라고 강요당한 이야기부터 시작할까요, 아니면 귀족 정원에서 그녀가 화려하게 빛난 이야기를 더 듣고 싶으신가요?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5218_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "과거에는 손님들이 모두 「레드 레디」라고 불렀습니다. 물론, 당신은 제 가장 특별한 손님이니까 「소렐」이라고 부르셔도 됩니다……"
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5219_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "살롱의 여주인으로서, 각 손님을 만족시키는 것이 제 임무입니다."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5220_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5221_AwakerVoiceContent = {Text = "아"},
  Voice_5221_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5222_AwakerVoiceContent = {
    Text = "주군? 혹시 제 자세에 문제가 있었습니까?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5223_AwakerVoiceContent = {Text = "아이야!"},
  Voice_5223_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5224_AwakerVoiceContent = {Text = "불운~"},
  Voice_5224_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5225_AwakerVoiceContent = {Text = "아"},
  Voice_5225_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5226_AwakerVoiceContent = {
    Text = "나는 그 감정을 기억해, 그 영광스러운 순간이 다가옵니다…"
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5226_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "비록 특징이 아직도 나타나지 않았지만, 나는 그것 때문에 불안해하지 않아. 이 막날개는 너를 수호하는 방어막이 될 거야, 수호자."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5227_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "너…… 정말로 다른 인간들보다 더 인내심이 많구나…… 나를 위해 이렇게 많은 자원을 쏟아붓다니, 너는 정말…… 나를 싫어하지 않는 거네?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5228_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "아? 의식이 끝났는데, 왜 아직도 아가미가 자라지 않는 거야? 변화가 또 실타래패한 거야! 망할! 망할! 망할!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5229_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "그 목소리가 다시 나를 호출하고 있어… 그 깊은 바다에서 울려 퍼지는 옥음!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5230_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "꽝・이・야♪"
  },
  Voice_5231_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5232_AwakerVoiceContent = {
    Text = "예술가 산, 네게 이 팔을 바치기 위해 시테의 거리로부터 왔어. 넌 마치 다듬지 않은 다이아몬드 원석 같네."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5238_AwakerVoiceContent = {
    Text = "못된 아이들, 여기 모여~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "진정한 예술에 설명은 필요없는 법이야."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "진정한 예술에 설명은 필요없는 법이야."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "오레타도, 도움이 될 수 있을까?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "호각을 불어라!"
  },
  Voice_5242_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5243_AwakerVoiceContent = {
    Text = "비용을 아끼지 않겠다!"
  },
  Voice_5243_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5244_AwakerVoiceContent = {
    Text = "양광 아래에서 목욕하는 느낌…… 이렇게 부드럽고, 눈물이 날 만큼 따뜻하다."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5244_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "감사의 표시로......제 고통의 깊은 곳에서 비밀의 제단을 지어드리겠습니다."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5245_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "형의 혈육과 제 몸이 더욱 잘 어우러져 맞아떨어졌습니다......"
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5246_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "나는 당신이 상상하는 것보다 더 강합니다. 그래서 저를 사용할 때는 조금 더 힘을 줘도 괜찮아요."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5247_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "내 착각인가? 피에 대한 갈망이 약간 줄어든 것 같다."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5248_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "입학 전부터 너와 만나는 걸 기대해왔어. 실타래제로, 우리는 좋은 콤비라고 생각하지 않아?"
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "진짜로 형편없다."
  },
  Voice_5250_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5251_AwakerVoiceContent = {Text = "야아!"},
  Voice_5251_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5252_AwakerVoiceContent = {
    Text = "하하하하!"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "타격·광란"
  },
  Voice_5253_AwakerVoiceContent = {Text = "음…"},
  Voice_5253_AwakerVoiceTitle = {
    Text = "타격·우울"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "데미지를 마음껏 입혀주세요!"
  },
  Voice_5254_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5255_AwakerVoiceContent = {
    Text = "아이기스는 두려워요. 그, 모두가 두렵다는 게 아니라, 사람들을 다시 슬프게 할까봐, 두려워요."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "이 시대의 그림책은 과거보다 훨씬 재미있네요! 아, 저기! 오해하지 마세요. 전 그림책만 좋아하는 어린아이가 아니니까요!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "데미지를 마음껏 입혀주세요!"
  },
  Voice_5257_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5258_AwakerVoiceContent = {
    Text = "휴... 아이기스가 혹시 폐를 끼치지는 않았나요?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "당신은 항상 웃음을 자아내는 그 신뢰를 품고 내 곁에 머물렀어……좋아, 어쩌면, 당신을 활용하는 것이 나쁜 일은 아닐지도. 하지만 기억해두세요: 나는 어떤 배반도 용납할 수 없으며, 특히 당신으로부터의 배반은 더욱 그렇다."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5259_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "나는 그들의 시체를 나무말뚝에 못 박아 성벽에 걸지 않은 것을 후회할 뿐이다! 모든 나를 배반하고, 밟고, 모욕한 자들, 나는 단 한 사람도 용서하지 않을 것이다!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5260_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "틀림없습니다, 저도 그 사람들 앞에서 비굴하게 굴었던 적이 있습니다. 부인할 것이 없습니다. 그들은 제 무지를 이용했고, 저는 그들에게 대가를 치르게 했습니다."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5261_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "너는 멋진 말 몇 마디와 며칠간의 거짓된 특혜로 내가 스스로 다시 족쇄를 차고 네 마음대로 놀아나게 할 수 있다고 생각하느냐?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5262_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "모든 나를 지배하려고 하고 이용하려고 한 자들은 결국 내가 직접 음계로 보내버렸다—— 나는 너도 보내는 것에 거리낌이 없다."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5263_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "그... 죄송해요! 움직이지 말아주세요!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "만지지 마!"
  },
  Voice_5265_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5266_AwakerVoiceContent = {Text = "무례!"},
  Voice_5266_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5267_AwakerVoiceContent = {
    Text = "저항은 그만두고, 향락과 꿈의 잔치에 어서오라고."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "모든 방황하는 자들이여, 죽음의 도시로 가거라."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "아이기스, 히, 힘낼게요!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "그게…… 저는 생명력을 흡수하는 걸 통제할 수 없어요. 그래서 요람에 손을 넣지 말아요. 이렇게 하다간 아플 거예요."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "우리가 대화하는 동안 또 고장나지 않았으면 좋겠네. 다음에도 폭발이 일어나면 그때야말로 실타래험실타래이 없어져 버릴 거야. 에리카는 귀여우면서도, 그런 점이 참 밉단 말이지."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "잡담·에리카에 대해"
  },
  Voice_5271_UnlockDesc = {
    Text = "깨어남체「에리카」획득 후 개방"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "팔, 성가신 팔! 그것들이 항상 제 머리카락을 잡아당겨요. 자신의 손조차 제어할 수 없으니, 저는 정말 무능력한 놈이에요...... 차라리......"
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "잡담·자신에 대해"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "감사합니다. 이제야 파인트의 선택을 이해하게 되었습니다. 제가 이 모든 것을 당연하게 여겼는데， 그녀에게 그렇게 큰 심리적 부담을 주었을 줄 몰랐습니다. 앞으로는 나 자신을 위해 살아보려고 노력하겠습니다."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5274_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "긴 시간 동안, 나와 파인트는 서로뿐이었습니다…… 하지만, 지금 저는 새로운 소중한 사람을 얻었어요…… 수호자님, 이전의 말을 거두어도 될까요? 당신은 그들과 다르세요. 당신은 제 노래와 예복만을 신경 쓰는 것이 아니라, 저를 바라보고 계세요. 그래서 저도 당신을 바라볼 것입니다."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5275_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "짐의 꿈속에서 잠든 별들이여, 깨어나 신의 나라를 보여라!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "왜 저는 언제 어디서나 이 드레스를 입고 있을까요? 이렇게 하면 언제든 당신을 위해 노래를 불러드릴 수 있습니다."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5277_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "나 스스로 하고 싶은 일?…… 죄송합니다, 당신이 무슨 말씀을 하시는지 이해할 수 없습니다…… 사실타래, 파인트도 이 문제에 대해 여러 번 물어본 적이 있지만, 나는 그저 그녀가 완전히 회복되길 바랄 뿐입니다……"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5278_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "황성에서 그 대인들의 동정이 우리 자매에게 생존할 수 있는 자원을 제공해주었습니다. 결국, 그들은 저에게 황성을 떠날 기회를 주었지만, 단 한 사람만 가능했습니다. 그들은 모두 저의 은인이며, 마치 저에게 피신처를 마련해 준 수호자님처럼 중요합니다."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5279_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "친절한 수호자님은, 아이기스가 머물 장소를 주셨어요. 그래서, 말씀하시는 건 뭐든지 따를게요. 하지만, 아이기스가 무능하지 않았다면, 수호자님께 더 많은 도움이 되었을텐데..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "장소 준비를 잊지 마세요. 당신이 예약한 장소가 엘워스의 것보다 작지 않겠죠?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5281_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "좋았어! 갑자기 의욕이 솟구쳐요! 하루에 방 20개를 청소할 수 있을 것 같아요!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5282_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "흠흠흠~ 이 노래는 호수만큼이나 오래된 「우리」의 노래에요. 자, 주인님도 같이 춤춰요! 「그분」께서 카렌의 목소리를 빼앗기 전에..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5283_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "주인님! 카렌의 목소리가... 희미해지고 있어요... 도와... 주세요..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5284_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "카렌의 시력이 더 좋아졌어요...! 주인님, 또 머리를 빗는 걸 잊으셨나요?"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5285_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "설령 강해진다 하더라도, 카렌은 복수할 생각이 전혀 없어요. 노래를 부르거나, 춤을 추거나, 파티를 즐기는 게 카렌의 가장 큰 소원이에요!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5286_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "세상이 모두 파괴된 후에도 계속 존재하기 위해, 나는 너무 많은 사람들에게 영혼과 피를 나눴다. 지금의 내 힘은 이 의지를 처음 받아들였을 때와는 많이 다르다…"
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "잡담·과거에 대해"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "교실타래 빌딩에서 나를 찾을 생각은 하지 마. 여기는 썩은 노학자의 냄새로 가득 차 있어서 하루도 견딜 수 없어."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "도망가지 마."
  },
  Voice_5289_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5290_AwakerVoiceContent = {
    Text = "나의 고향은 「신성」을 믿고, 그에 대응하여 내가 따르는 왕은 당연히 「신성과 소통하는 자」입니다."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "잡담·영원한 왕국에 대해"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "여기 인재가 넘쳐나는군요, 화려한 살롱을 열 만합니다…안심하세요, 그때가 되면 저의 하인들이 초대장을 반드시 당신에게 전달할 것입니다."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5292_AwakerVoiceContent = {Text = "자아!"},
  Voice_5292_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5293_AwakerVoiceContent = {
    Text = "친구가 더 필요해~..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "나와 그녀는 다르잖아. 그녀가 제공하는 건 오직 적대감에 찬 전율과 공포뿐이지만, 내가 주는 건 피부를 맞대는 달콤하고 뜨거운 고통과 사랑이야?"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "잡담·완다에 대해"
  },
  Voice_5294_UnlockDesc = {
    Text = "깨어남체「완다」획득 후 개방"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "이걸로 끝이라고 생각하지 마! 당한 굴욕은 하나도 빠짐없이 갚을 거니까!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "당신의 손은 당신의 영혼처럼 따뜻해요, 블레드니 올니, 나…… 당신의 만지기에 감사합니다."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "교실타래에서 브리지 치는 게 무엇이 문제인가요? 테이블도 있고, 사람도 있고, 제가 카드를 가져왔으니 이는 곧 \"시작\"을 의미합니다!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5299_AwakerVoiceContent = {Text = "안 돼..."},
  Voice_5299_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5300_AwakerVoiceContent = {
    Text = "나락의 끝, 심연을 엿보아라!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "나락의 끝, 심연을 엿보아라!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5302_AwakerVoiceContent = {Text = "으우우."},
  Voice_5302_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5303_AwakerVoiceContent = {Text = "으우우."},
  Voice_5303_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5304_AwakerVoiceContent = {Text = "으우우."},
  Voice_5304_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5305_AwakerVoiceContent = {Text = "으우우."},
  Voice_5305_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5306_AwakerVoiceContent = {
    Text = "신의 빛을!"
  },
  Voice_5306_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5307_AwakerVoiceContent = {
    Text = "기도가 닿기를!"
  },
  Voice_5307_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5308_AwakerVoiceContent = {
    Text = "겁쟁이들이 아무리 모여도, 강해질 수 없나 봐... 하아..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "전쟁은 항상 고통을 가져다줍니다. 고문을 견디는 것은 전사의 의무입니다. 양손을 잃고, 양발을 잃고, 모든 것을 잃더라도 나는 여전히 정의를 위해 싸우겠습니다."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "이것이 당신이 그분에게 바치는 공물입니까?"
  },
  Voice_5312_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5313_AwakerVoiceContent = {
    Text = "그렇게 하면 미래를 바꿀 수 있다고 생각하나?"
  },
  Voice_5313_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5314_AwakerVoiceContent = {
    Text = "그분의 임신……내 배 안에서……"
  },
  Voice_5314_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5315_AwakerVoiceContent = {
    Text = "흥, 꽤 눈치가 좋잖아."
  },
  Voice_5315_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5316_AwakerVoiceContent = {
    Text = "하인이 주인에게 헌상하는 건 당연하지."
  },
  Voice_5316_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5317_AwakerVoiceContent = {
    Text = "필사적으로 내 기분을 맞추는 모습이, 꽤나 보기 좋네."
  },
  Voice_5317_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5318_AwakerVoiceContent = {
    Text = "브라우니, 카라멜 푸딩, 자허토르테, 초콜릿 케익, 쿠키... 전부 준비해 둬!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5318_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "있잖아, 잠깐 봐줘. 내 치마 어때? 주름이나 올 풀림 같은 거 없어? ...뭐? 무슨 불만이라도 있어?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5319_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "어서 와, 내 마지막 계령 의식에... 모든 건 내가 정성껏 준비했어. 뭐, 수호자도 아주 조금은 도움이 됐고..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5320_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "식탁보는 레이스가 있는 걸로, 화분에는 붉은색 접란을 심어서 준비해줘. 자, 빨리!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5321_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "어서 가서 손님들을 데려와! 어째서 이런 간단한 일도 못하는 거야?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5322_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "도망칠 곳은 없다!"
  },
  Voice_5323_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5324_AwakerVoiceContent = {
    Text = "도망칠 곳은 없다!"
  },
  Voice_5324_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5325_AwakerVoiceContent = {
    Text = "당신의 기대를 배신하지 않도록, 매일 정진하도록 하겠습니다."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5325_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "나는 그 여자를 꽤 좋아해, 우리에겐 뭐였지……아, 공통 언어!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "잡담·완다에 대해"
  },
  Voice_5326_UnlockDesc = {
    Text = "깨어남체「완다」획득 후 개방"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "무례하다!"
  },
  Voice_5327_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5328_AwakerVoiceContent = {
    Text = "무례하다!"
  },
  Voice_5328_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5329_AwakerVoiceContent = {
    Text = "주검이 되어라."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5330_AwakerVoiceContent = {Text = "부서져."},
  Voice_5330_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5331_AwakerVoiceContent = {
    Text = "현실타래의 장벽을 뚫어라!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "최근에 바다를 건너는 계획이 있으신가요? 제 부탁을 들어주실타래 수 있다면, 저와 함께 가게 해주시겠습니까? 대양으로 가는 것만으로도 충분합니다……"
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5332_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "만약 당신이 여전히 저를 신뢰한다면, 제게 이 여행의 안내자가 되는 것을 허락해 주세요. 하지만, 이렇게 단순한 일조차도 저는 한번 실타래패한 적이 있습니다…"
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5333_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "바다로 가고 싶지 않니? 지금의 해도를 확인해 보자……남위 47도 9분, 서경 126도 43분, 바로 여기다."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5334_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "과거의 나는 많은 재앙을 일으켰고, 심지어 몇몇 문명을 거의 파괴할 뻔했다……나……만약 아니요라고 한다면, 이미 너무 늦은 것일까요?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5335_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "나는 영원한 나라의 입구를 지키는 자로, 귀향자들에게 길을 안내합니다. 얼마나 웃기지, 이런 임무를 맡은 내가 고향이 어디인지 잊어버렸다니……\n너…… 내 등대가 될 수 있겠니?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5336_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5337_AwakerVoiceContent = {Text = "별단아."},
  Voice_5337_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5338_AwakerVoiceContent = {Text = "앗!"},
  Voice_5338_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5339_AwakerVoiceContent = {Text = "안개야."},
  Voice_5339_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5340_AwakerVoiceContent = {
    Text = "문제 없어."
  },
  Voice_5340_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5341_AwakerVoiceContent = {
    Text = "대부분의 사람들을 호위하는 보호자는 별 차이가 없지만, 그 여자만은 예외입니다. 가능하다면 다른 항로를 배정해 주실타래 수 있나요."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해"
  },
  Voice_5341_UnlockDesc = {
    Text = "깨어남체「미리암」획득 후 개방"
  },
  Voice_5342_AwakerVoiceContent = {Text = "앗!"},
  Voice_5342_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5343_AwakerVoiceContent = {
    Text = "그게 다야?"
  },
  Voice_5343_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5344_AwakerVoiceContent = {
    Text = "손을 치워줘요."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "내가 해저 궁전으로 돌아가기 전에, 겨우 너에게 일부 깊은 바다의 힘을 빌려주겠지만, 이것뿐이다."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5346_AwakerVoiceContent = {Text = "와!"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "좋아? 나는 통증을 좋아해. 피부가 붉어지고 부어오르는 걸, 즐거움과 고통이 섞인 신음을 좋아해. 통증이야말로 가장 원시적이고 진실타래된 욕망일 거야."
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "오레타의 친구가 되자!"
  },
  Voice_5348_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5349_AwakerVoiceContent = {
    Text = "오레타의 친구가 되자!"
  },
  Voice_5349_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5350_AwakerVoiceContent = {
    Text = "그 누나, 계속 무서운 눈으로 릴리를 노려봐. 그런데, 어째선지 친근한 느낌이 들어. 엄마랑 비슷한 느낌."
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "잡담·히로에 대해"
  },
  Voice_5350_UnlockDesc = {
    Text = "깨어남체 「히로」획득 후 개방"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "머리가 맑아졌어, 괜찮은 기분이네."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5351_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "외근보다는, 실타래험실타래에서 일하는 편을 좋아해. 설마 실타래험 도구를 바다에서 건져올렸다거나 하고 생각했어?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5352_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "나사든 못이든, 많으면 많을 수록 도움이 되지!"
  },
  Voice_5353_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5354_AwakerVoiceContent = {
    Text = "이 몸으로는 이제 힘을 억누를 수 없겠네. 하지만 아직 인형을 교체할 시기는 아닌데... 멍하니 서 있지 말고 도와줘. 조정할 거니까, 이 다리를 잠깐 들고 있어 줘."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5354_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "빛을 안내하는 짐은 가장 순수한 성인조차도 무너뜨릴 수 있습니다. 만약 피곤함을 느끼신다면, 나의 백염이여, 꼭 저에게 말씀해 주십시오. 저는 당신의 고민을 덜어드리고, 함께 행복의 무게를 나누기 위해 제가 할 수 있는 모든 것을 다하겠습니다."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "잡담·피로에 대해"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "당신께 인정받고서 비로소, 저는 기사로 있을 수 있습니다."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5356_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "신들의 빛이 보입니다. 이게 당신이 가지신 신통력인가요? 이 얼마나 장엄하고 신성한 빛인가요."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5357_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "신국으로 통하는 문은, 바로 그곳에."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5358_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "보다 밝게, 보다 선명하게..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5359_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "깨어남체인 채 인간으로 돌아간다니... 아아, 들립니다... 신국에서 연주하는, 저를 위한 성스러운 노래가..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5360_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "신께선 저를 신역으로 받아들이시고, 평안한 잠을 내려주셨습니다..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5361_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "안심하세요, 우리 모두 매우 유용합니다. 저는 봉제와 청소를 할 수 있고, 다른 나는 전투를 잘 하며, 나머지 나는......"
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "나는 밝은, 부드러운 것들을 싫어합니다. 온화함은 거울처럼 모든 추악함, 욕심, 그리고 약함이 그 앞에서 숨길 곳이 없습니다."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "브라운을 만지고 싶나요? 나는 결정할 수 없어요, 당신은 직접 그녀에게 물어봐야 해요."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "나를 기쁘게 하려면? 그럼 무릎을 꿇고, 목을 내밀고, 내가 너를 빨아들일 때까지 조용히 있어."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5366_AwakerVoiceContent = {Text = "하!"},
  Voice_5366_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5367_AwakerVoiceContent = {
    Text = "내가 어젯밤에 꿈을 꾸었는데, 그게 내가 별들 사이를 떠돌기 시작한 지점이었어."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5367_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "아, 아이기스가 도움이 되었나요?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5368_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "느껴졌어요~"
  },
  Voice_5369_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5370_AwakerVoiceContent = {
    Text = "전황을 바꾼다!"
  },
  Voice_5370_AwakerVoiceTitle = {Text = "스킬·3"},
  Voice_5371_AwakerVoiceContent = {Text = "조심해!"},
  Voice_5371_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5372_AwakerVoiceContent = {Text = "물러서."},
  Voice_5372_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5373_AwakerVoiceContent = {
    Text = "아무도 상처받지 않는 세계가, 탄생한다."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "(애교부리다)"
  },
  Voice_5374_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5375_AwakerVoiceContent = {
    Text = "주의 제단을 두는 것을 허가해주세요. 이건 신자가 만든 조각상으로, 당신께 저주를 불러오는 일은 없을 겁니다."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "조금만 한 점…"
  },
  Voice_5376_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5377_AwakerVoiceContent = {
    Text = "내 스패너 어디 갔어?!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "화학, 물리학, 은핵 응용학... 「기사의 일곱 가지 미덕」은 시대에 뒤떨어졌나요? 그렇다면 저도 이 세계의 지식을 배우게 해주세요!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "오레타는 여행을 한 적이 있어! 파도에 쓸려간 게 아니라, 트레일러 여행이었어!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5379_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "홍해파리, 투구해파리, 민물해파리, 모두 무리지어 다니고 있어. 오레타도 모두랑 같이 있는 게 좋아!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5380_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "옛날 일? 잘 기억나지 않아... 하지만 수족관에서 일했던 건 기억하고 있어! 일급은 분명, 2페니였을까나!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5381_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "저기, 오레타는 실타래은 바다에서 왔어... 그러니까 오레타는 해저인이야! 오레타가 착하게 지내고, 야채를 많이 먹고, 친구를 많이 만들면 바다 친구들이 기뻐해줄 거야!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5382_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "오레타의 집, 수족관 친구들, 좋아하는 해파리들, 다들 모두 없어져 버렸어....... 나도 언젠가 사라지는 거야? ...계속계속 오레타랑 놀아주면 좋겠어."
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5383_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "이긴 건가? 다행이네..."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "평화를 위해."
  },
  Voice_5387_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5388_AwakerVoiceContent = {
    Text = "정의를 위해."
  },
  Voice_5388_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5389_AwakerVoiceContent = {
    Text = "네가 내 몸 속에 있다는 것을, 나는 알고 있다!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "인간, 거짓 신, 깨어남체, 융식... 이 세계의 모든 것이, 제가 영원의 왕국을 재건하기 위한 초석이 되겠지요."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "네가 내 몸 속에 있다는 것을, 나는 알고 있다!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "유우하시...... 그는 좀 내 형 같아서, 자주 그 어두운, 차가운 잠 못 이룬 날들을 떠올리게 해."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "잡담·유우하시에 대해"
  },
  Voice_5392_UnlockDesc = {
    Text = "깨어남체「유우하시」획득 후 개방"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "우리의 관계는 셜록 홈즈와 왓슨 같지 않나요? 최근에 유행하는 잡지에 관심을 갖고 계신가요?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "아름다움의 포로가 되어라."
  },
  Voice_5394_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5395_AwakerVoiceContent = {
    Text = "아름다움의 포로가 되어라."
  },
  Voice_5395_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5396_AwakerVoiceContent = {
    Text = "「싫다」, 형용사. 싫어하는 것.「싫어하다」, 동사. 사물에 강한 반감을 가지다.「반감」명사, 불쾌하거나 반항하는 감정.「불쾌」, 명사. 기분이 좋지 아니함——<Del:억누르지말라고 파괴시켜파괴시켜파괴>— 죄송합니다. '싫다'의 뜻을 알 수 없습니다."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "결국은 이렇게 되는 걸까..."
  },
  Voice_5397_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5398_AwakerVoiceContent = {
    Text = "더욱 더 변한 것 같아."
  },
  Voice_5398_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5399_AwakerVoiceContent = {
    Text = "이몸은 골리아다! 제대로 기억해 두라고. 이 이름은 인류의 하찮은 역사를 다시 쓸 거니까."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5400_AwakerVoiceContent = {
    Text = "걱정할 필요 없어."
  },
  Voice_5400_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5401_AwakerVoiceContent = {
    Text = "네 재능과 모두의 기대를 저버리지 않았으면 좋겠어, 신입 수호자."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5402_AwakerVoiceContent = {Text = "과부하."},
  Voice_5402_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5403_AwakerVoiceContent = {
    Text = "오버드라이브."
  },
  Voice_5403_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5404_AwakerVoiceContent = {
    Text = "음, 지갑에서 찾은 사진? 아, 그건 과거의 나야. 지금의 모습은 내 도박 파트너이자 상대방이 만들어준 거야."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5404_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "마침——한 판 도박할래? 이기면 비밀 하나 알려줄게?\n하지만 조심해, 엘바에게 걸리지 않도록~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5405_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "너는 이 털을 그렇게 신경 쓰나? 만져볼래? 걱정하지 마, 나는 정말 대방이야!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5406_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "물론 좋은 점도 있죠, 제가 제 왓슨을 만나지 않았습니까? 이 일에 비하면 생사와 외모는 중요하지 않죠, 그렇죠?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5407_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "너가 나에게 후회하겠느냐? 전혀. 인생이 언제나 순조롭다면 너무 지루하지 않을까?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5408_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "내 시대에는 학교가 전사들을 훈련시키는 장소였고, 지금도 그렇군."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "메이슨…아니, 이렇게도 충분해, 적어도 우리는 다시 함께할 수 있어, 「24」."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "잡담·24에 대해"
  },
  Voice_5410_UnlockDesc = {
    Text = "깨어남체「24」획득 후 개방"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "헤헷, 잘했지! 그럼 보수를 줘. 말해 두지만, 나한테 공짜로 널 도와 줄 의리는 없다고?"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "나는 서대에서 왔습니다. 거기에서는 모든 사람이 배우가 되고 싶어 하고, 아무도 관객으로만 머물고 싶어 하지 않습니다. 사실타래 우리는 모두 이 도시의 가련한 부록에 불과합니다."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "잡담·과거에 대해"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "고대 석각을 보셨나요? 산과 하나 되어 자연에 힘입어 시간의 흔적을 피한 정말 놀라운 유물입니다…… 다만, 아직도 충분하지는 않네요……"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "비둘기가, 돌아오지 않아..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "물러나세요!"
  },
  Voice_5415_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5416_AwakerVoiceContent = {Text = "흥!"},
  Voice_5416_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5417_AwakerVoiceContent = {
    Text = "명령 실타래행!"
  },
  Voice_5417_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5418_AwakerVoiceContent = {Text = "바보"},
  Voice_5418_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5419_AwakerVoiceContent = {
    Text = "……아? 나를 부르는 거야? 오토바이 고치느라 못 들었어……말하자면, 착한 외인, 내 렌치를 보았나요?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5419_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "내 기억은 항상 흐릿해요. 현재 일에만 집중할 수 있어요. 하지만, 나는 당신의 이름을 머릿속에 새기려고 노력할 거예요…… 이름이 뭐였죠?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5420_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "당신은 눈에 익숙해 보이는데, 이름을 기억해내지 못하겠네요…… 당신은 제 조수인가요? 그렇다면 일곱 개의 나사 모자를 가져다 주실타래 수 있나요?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5421_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "나는 당신의 이름을 환영함에 새겼습니다. 언젠가 우리가 함께 모험을 떠날 때, 당신을 부르는 방법을 잊지 않을 것입니다."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5422_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "매우 익숙해, 매우 익숙해, 우리 사이에 무언가 일어난 적이 분명해. 잠깐 시간을 주세요, 회상해보려고 해요……아, 당신이구나, 수호자！"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5423_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "당신은 정말 솔직하지 않은 아이군요. 다행히도, 저는 충분한 시간과 인내심을 가지고 당신을 기다릴 수 있습니다…"
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"모두 기뻐할 거야.\" 라고 해야 할까?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "꽤나 멋진 목을 구할 수 있었네요. 새로운 컬렉션을 찾는 여행은, 언제나 대환영이랍니다. 다음에도 꼭 불러주시길."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5427_AwakerVoiceContent = {Text = "음……"},
  Voice_5427_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5428_AwakerVoiceContent = {
    Text = "주인님을 위해 프로 메이드가, 나쁜 사람들과 더러운 것들을 전부 청소해드릴게요~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "우리는 이제 동료라고 할 수 있겠어. 네가 어느 날 거리에서 살게 되더라도, 쓰레기를 먹으며 살아가게는 하지 않을 거야."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "묘목이여, 크게 자라나렴."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "묘목이여, 크게 자라나렴."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "좋았어! 주사위 운이 더 좋아진 것 같아!"
  },
  Voice_5432_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5433_AwakerVoiceContent = {
    Text = "좋았어, 운이 잘 따르네!"
  },
  Voice_5433_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5434_AwakerVoiceContent = {Text = "Lucky~!"},
  Voice_5434_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5435_AwakerVoiceContent = {
    Text = "가까이 오지 마."
  },
  Voice_5435_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5436_AwakerVoiceContent = {
    Text = "가까이 오지 마."
  },
  Voice_5436_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5437_AwakerVoiceContent = {
    Text = "저는 당신을 고발해야 합니다, 수호자. 당신이 저에게 너무 다정하게 대해 주셔서 불안합니다—— 저에게는 육체의 고통만이 진실타래하고 영원한 것이기 때문입니다."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "좋네, 칭찬해주지."
  },
  Voice_5438_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5439_AwakerVoiceContent = {
    Text = "이 정도로는 한참 부족해."
  },
  Voice_5439_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5440_AwakerVoiceContent = {
    Text = "원하는 상을 말해볼래?"
  },
  Voice_5440_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5441_AwakerVoiceContent = {
    Text = "쳇! 정말 지저분한 장소네. 내 아름다운 발이 더러워지잖아. 거기, 밟아줄 테니까 그 부드러운 등을 내놓고 있도록."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5442_AwakerVoiceContent = {
    Text = "마침내... 찾았다!"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "브라운도 매끈매끈해졌어."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5443_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "보디가드는 조금 어렵겠지만, 자잘한 일이라면 맡겨 줘."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5444_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "왜 브라운을 그런 표정으로 보는 거야...? 후후, 브라운 님께서 오늘 밤 겁쟁이의 다리를 갉아먹겠다고 하신다. 누가 선택받을까나?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5445_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "키가 커지거나 하진 않으려나."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5446_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "일이야? 알겠어. 브라운, 기합 넣고 가자!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5447_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "아그리파? 죄송하지만, 내가 직접 보내준 사람이 너무 많아서 대부분의 얼굴이 흐릿하고, 기억에 남을 만한 상대방은 없습니다."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "잡담·아그리파에 대해"
  },
  Voice_5448_UnlockDesc = {
    Text = "깨어남체「아그리파」획득 후 개방"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "위험한 선원……아니, 단지 항해의 안전을 위해서……"
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "잡담·파로스에 대해"
  },
  Voice_5449_UnlockDesc = {
    Text = "깨어남체「파로스」획득 후 개방"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "오지 말아요!"
  },
  Voice_5450_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5451_AwakerVoiceContent = {
    Text = "조, 조심하세요!"
  },
  Voice_5451_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5452_AwakerVoiceContent = {
    Text = "해치웠어... 어라? 이번에도 너무 과했나?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "아, 이거 내가 필요한 부품이야, 고마워요! ……응? 내가 도와 찾으라고 했어? 전혀 기억이 안 나는데, 혹시 착각한 거 아니야?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "잡담·부품에 대해"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "후후, 영감이 속속이 밀려들고 있어..."
  },
  Voice_5454_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5455_AwakerVoiceContent = {
    Text = "센스가 좋네."
  },
  Voice_5455_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5456_AwakerVoiceContent = {
    Text = "이 조각칼, 내 손에 딱 맞네. 네가 골라준 덕분이야."
  },
  Voice_5456_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5457_AwakerVoiceContent = {
    Text = "나는 통제를 잃는 것을 싫어한다. 하지만, 당신의 존재로 인해 나는 약간의 미묘한 통제 상실타래이 색다른 즐거움을 가져올 수 있다는 것을 발견했다."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "저, 조금은 성장했을까요."
  },
  Voice_5458_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5459_AwakerVoiceContent = {
    Text = "죄송해요, 거의 성장하지 못해서..."
  },
  Voice_5459_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_54601_AwakerVoiceContent = {
    Text = "이것이 세계를 아는 방법이야."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "이것이 세계를 아는 방법이야."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "즐거운 시간 보내세요!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "즐거운 시간 보내세요!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "자, 세계의 본질을 드러내는 거야."
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "자, 세계의 본질을 드러내는 거야."
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "신의 곁으로, 돌아가는 겁니다!"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "자, 잘 먹었습니다..."
  },
  Voice_5460_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_54610_AwakerVoiceContent = {
    Text = "신의 곁으로, 돌아가는 겁니다!"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "방해하지 마...! 아하하하하!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "정의의 빛이여, 심연을 비춰라!"
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "방해하지 마...! 아하하하하!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "이 달콤한 고통에, 취해버려!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "이 달콤한 고통에, 취해버려!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "「너는 어린 나이에, 성난 강물에 빠져 죽었지!」"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "「너는 어린 나이에, 성난 강물에 빠져 죽었지!」"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "형태 없는 존재여, 수호의 방패가 되어라!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "형태 없는 존재여, 수호의 방패가 되어라!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "신경써 주셔서, 진심으로 감사드립니다."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5461_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "심연의 짐승이여, 전부 집어삼켜라!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "심연의 짐승이여, 전부 집어삼켜라!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "정의의 빛이여, 심연을 비춰라!"
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "나는 속박을 풀어내는 자, Tokuli-Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "나는 속박을 풀어내는 자, Tokuli-Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "지금의 나는, 미래를 붙잡기 위해 탄생한 존재다!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "지금의 나는, 미래를 붙잡기 위해 탄생한 존재다!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "제 앞에 무릎 꿇고, 발끝에 입맞추세요!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "모든 너트가 이곳에 있어!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "모든 너트가 이곳에 있어!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "우월한 힘은 깊은 바다의 몸이 아니면 견딜 수 없다. 네가 나를 부러워할 거라고 생각하는데, 하하, 약한 인간으로 태어난 것은 네 잘못이 아니다. 너도 좀 긍정적으로 생각해봐."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5462_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "제 앞에 무릎 꿇고, 발끝에 입맞추세요!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "패배한 녀석들은 내 노예로 삼아도 돼?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5464_AwakerVoiceContent = {Text = "흥."},
  Voice_5464_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5465_AwakerVoiceContent = {
    Text = "그런 것밖에 안 돼."
  },
  Voice_5465_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5466_AwakerVoiceContent = {Text = "아"},
  Voice_5466_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5467_AwakerVoiceContent = {Text = "아"},
  Voice_5467_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5468_AwakerVoiceContent = {
    Text = "만일 내가 좀 더 일찍 알았다면, 그때 그 사람들이 이 모든 것을 녹아내림시키는 저주로 인해 고통스러워했다는 것을, 나는…… 아니, 지금 알아도 늦지 않았다. 반드시 그것을 없애야겠다, 모든 고통을 없애버리겠다. 설령 다시 생명을 바쳐야 한다 해도."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "낙담할 필요는 없어요. 바다는 모든 생명을 품어주니까요."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "그런 약한 몸으로는 나의 동료가 되기에는 아직 부족하다. 가자, 너를 학원의 운동 클럽에 데려가서 눈을 뜨게 해주고 훈련을 강화시켜주겠다!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "나에게 힘을 빌려준 그 불쌍한 여자는 지금도 융식에 고통받고 있어….뭐야, 그 눈은? 그녀가 있는 곳은 절대 안 알려줄거니까 포기해!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "운만 있다면 너도 무적이야."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "보다 격렬한 사랑을."
  },
  Voice_5473_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5474_AwakerVoiceContent = {
    Text = "에이, 여기 있는 대부분은 아직 아이들이네요. 저 신사는 이미 수염과 머리가 모두 하얗게 변했고, 그 냉정한 청년은 한쪽 팔이 없어요. 완벽한 후보가 아닌 것 같아요…… 정말 난감하네요."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "보다 격렬한 사랑을."
  },
  Voice_5475_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5476_AwakerVoiceContent = {
    Text = "정성껏 그린 룬, 경건하게 조각한 신상, 수차례 정제된 금기 약제… 하나도 빠질 수 없다."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5476_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "왕좌는 깊은 바다에서 채굴한 고대의 청석으로 쌓아야 하며, 제단에는 희생의 피로 물들여야 합니다… 아직 준비하지 않았나?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5477_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "그들을 모두 불러오세요. 그들은 당연히 떨며 무릎을 꿇고 그의 강림을 맞이해야 합니다."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5478_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "나는 그 깊은 바다 유적지로 가서, 그분이 태어난 바닷물에 목욕할 것입니다…"
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5479_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "환영합니다, 그분의 강생 의식에 참석하여 그분의 생일을 함께 증언하십시오……뭐라고? 당신은 그분의 소멸도 운명이라고 말합니까?……아니, 절대 불가능해……나는 이미 그렇게 많은 대가를 치렀어……"
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5480_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "신의 계명을 따르십시오."
  },
  Voice_5481_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5482_AwakerVoiceContent = {
    Text = "당신의 곁은 나와 파인트의 집이 될 수 있을까요?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5482_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "음, 그때 저는 제 목소리를 잃었습니다. 당신의 치유 덕분에 원래 상태로 회복되었습니다."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5483_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "신의 계명을 따르십시오."
  },
  Voice_5484_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5485_AwakerVoiceContent = {
    Text = "광활한 별하늘, 무한한 심연의 우주, 끝없는 여정은 나를 깊은 혼란에 빠뜨렸다……"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5485_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "손쉽게 강해지는 건 좋지만, 단련을 게을리하면 안 돼."
  },
  Voice_5486_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5487_AwakerVoiceContent = {
    Text = "그렇구나, 이런 방법도 있었네..."
  },
  Voice_5487_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5488_AwakerVoiceContent = {
    Text = "기묘한 감각이네."
  },
  Voice_5488_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5492_AwakerVoiceContent = {
    Text = "그의 강림은 이러한 검은 죽음이 가져오는 고통을 종료시킬 것입니다, 그렇지 않나요?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "좋은 아침입니다, 주군. 조사를 나가실타래 예정이라면, 호위로 동행하게 해주세요."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5493_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "뭘 하는 거야? 쓸데 없는 장난은 그만두고, 어서 행동 보고부터 끝내도록 해."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "드디어 시작하는 거야? 내 귀여운 애완동물들이, 꽤 굶주려 있어서 말이야..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "혈맥의 힘이 넘쳐흐르고 있어."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "……잠깐, 이런 것을 본 적이 있어. 그들은 내게 준 물에 이런 검은 점액이 들어 있었다. 내가 녹화염의 힘을 획득한 것이 이것과 관련이 있을까? 그것도 인화득복이라고 할 수 있겠지."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "라모나 덱스터, 라모나라고 불러줘. 앞으로 잘 부탁해, 수호자."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5499_AwakerVoiceContent = {Text = "네."},
  Voice_5499_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5500_AwakerVoiceContent = {
    Text = "명령 접수 완료."
  },
  Voice_5500_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5501_AwakerVoiceContent = {
    Text = "흥, 버릇이 없네. 이 몸이 친히 상대해줘야겠어."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "싫어하는 것? 마침 피우고 끝낸 담배, 놓친 마차, 새 가죽 신발을 신고 나갔는데 내린 비. 결국, 모든 불운이 싫다."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "다목적 렌치, 조절식 렌치, 육각렌치, 일자 스크루드라이버, 십자 스크루드라이버, 침입형 나사, 판형 나사… 고장 난 것을 고칠 수 있는 것이라면 무엇이든 좋아합니다."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "아이~ 당신에게 들키다니~\n괜찮아요, 깨어남체의 정신력이 그렇게 충만해서 적어도 365번 더 훔쳐야 그들이 무지무각한 인형이 될 거예요~ 못 하겠어요? 알겠어요, 다음엔 꼭 조심할게요! 음, 사람을 자를 때 조금씩 \"공포\"를 훔치는 건 괜찮겠죠?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5504_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "어, 카시아의 마법 비밀을 이미 알고 있었나? 음, 네가 비밀을 누설하지 않도록 하기 위해 어디서든 순회 공연할 때마다 나를 따라다녀야 해~ 하하, 내가 너의 감정을 수집하기 위해서라고 생각해? 역시 내 비밀은 숨길 수 없었군!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5505_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "너, 카시아의 마법 보조를 해줄래? 겁내지 마~ 나의 마법 상자에 잠깐 들어가기만 하면 돼. \n\n숨었나? 검을 꽂을 거야~ 아, 안에 기믹은 없어~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5506_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "오세요, 이 정장모자를 써보세요! 그리고, 가장 원하는 선물을 말해 보세요. 좋습니다, 그런 것이군요, 알았습니다! 이제, 모자 안을 만져 보세요——"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5507_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "조금 곤란하네요. 그 아이들이 매번 공연을 보러 오는데, 제 재고가 금방 바닥날 것 같아요……음, 마술사는 같은 관객 앞에서 같은 마술을 반복할 수 없어요. 새로운 마법을 만들까요? 죄송하지만, 저는 그런 재능이 없어요. 제가 잘하는 건 단지 모방뿐이에요."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5508_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "이 학원은 낡아서 보기 흉하지만, 학장 선생님께서 사용하시는 휴식실타래만은 조금 나아 보입니다. 어떻게 생각하시나요?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5509_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "오만하고 비겁한 놈들은, 이 손으로 처리한다."
  },
  Voice_5510_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5511_AwakerVoiceContent = {
    Text = "복수의 칼날을 연마한다."
  },
  Voice_5511_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5512_AwakerVoiceContent = {
    Text = "내 살롱은 무도회처럼 순진하지 않습니다. 준비됐어요?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5512_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "내 살롱은 토양이며, 정원입니다. 매혹적인 아름다움과 힘이 이곳에서 피어날 것입니다…"
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5513_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "안락의자, 홍차, 마카롱…… 아침 이슬이 맺힌 신선한 장미로 내 접견실타래을 꾸며야 해요."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5514_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "조정할 수 없나 외부 손님들도 학원에 들어갈 수 있게?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5515_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "에러, 에러, 에러, 에러..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "앗! 지금 몇 시인가요? 죄송해요, 주인님... 깜빡 졸았어요..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "이대로 죽음을 기다리는 것밖에 못하는 거야? 여기서 구해줄 사람은 없는 거야? …그런 생각을 계속 했지만, 사실타래 답은 예전부터 알고 있었어. 단지 인정할 용기가 없었을 뿐…. 네가 나타나지 않았다면, 끝까지 저항하지 못했을지도 몰라. 그, 그러니까 고마워...... 고, 고백 같은거 아니니까 착각하지 마!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5518_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "난 그 녀석들의 허무한 꿈 속에서 살고 있었어. 내 인생을 선택할 권리조차 주어지지 않은 채, 뭔지 모를 예언 때문에 평범한 삶마저 누리지 못했어... 그런 삶으로 돌아가지 않기 위해서라면, 무엇이든지 할 거야."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5519_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"낮게 숙인 수련이 주변에서 한숨을 내쉽고, \n자는 자작나무 사이에서 그녀가 가끔 깨어납니다; \n새 한 마리가 둥지에서 떨리며 소리를 내고, \n신비로운 노래가 금빛 별들에서 내려옵니다.\" \n아, 들으셨나요? 죄송합니다, 이건 제가 매우 좋아하는 문장이에요……함께 읽으시겠어요?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "잡담·독서에 대해"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "숙녀의 방에 제멋대로 들어오지 마, 숙녀의 외양에도 참견하지 마. 알겠으면 내려가, 이제 쉴 거야."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5521_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "나를 상대로 잘난척하지 않는 게 좋을 거야. 주제를 알라고! 진정한 주인이 누구인지, 두 눈 똑바로 뜨고 잘~ 보라고."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5522_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "자, 상품을 진열하도록 할까요?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "해냈군! 럼주로 승리를 축하하자고!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "사라져라."
  },
  Voice_5525_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5526_AwakerVoiceContent = {
    Text = "내게 맡겨주세요!"
  },
  Voice_5526_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5527_AwakerVoiceContent = {
    Text = "이몸에게 짓밟히는 것, 기분 좋지?"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5528_AwakerVoiceContent = {Text = "참아요!"},
  Voice_5528_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5529_AwakerVoiceContent = {
    Text = "눈가리개 아래의 모습이 그렇게 궁금해? 더 적합한 상황에서 보여줄게, 너무 조급해하지 마."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "벌써 끝이야? 흥미가 생기기 시작한 참인데."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "야, 나한테 손대지 마. 진정한 전사는 외부 도움에 의존하지 않는다."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5531_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "아이기스가 강해졌어요... 이 눈으로, 적들이 움직이지 못하도록 묶어둘게요!"
  },
  Voice_5532_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5533_AwakerVoiceContent = {
    Text = "미사그 대학과 부대는 별 차이가 없다. 우리는 모두 전선에 무기를 닦고 전투 준비를 한다."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5534_AwakerVoiceContent = {Text = "완벽해!"},
  Voice_5534_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5535_AwakerVoiceContent = {Text = "완벽해!"},
  Voice_5535_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5536_AwakerVoiceContent = {
    Text = "나는 수갑을 차일 수 있고, 너의 앞에서 머리카락을 잡혀 무릎을 꿇고, 너의 노예가 될 수 있다. 이 모든 것은 아무 문제 없어——그냥 나에게 사람을 죽이게 해줘, 조각가, 등불, 지나가는 천식 할머니…… 아무든지, 나는 그들의 목을 찢고, 그들의 피를 다 마실타래 것을 보장해."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5536_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "융식 상처에서 흘러나오는 것은 검은색 점액뿐만 아니라 끊임없는 영감이다. 솔직히 말하면, 조금 더 있어도 괜찮을 것 같아."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "두려움? 하하하하, 그렇다면 좋지 않겠니! 모든 걸 저주하라. 나는 너희들의 공포를 맛보고 싶을 뿐이다."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5538_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "재미있네, 네 피 맛이… 정말 달콤해, 꿀술 같아."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5539_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "그때, 수만 명이 내 이름을 한 목소리로 환호했고, 「유우하시」라는 이름의 바다가 모든 것을 덮어버렸어요. 나는 방금 대머리 소심쟁이의 목을 비틀어 끊은 것을 축하했습니다. 그 느낌은 정말 말로 표현할 수 없을 만큼 짜릿했어요. 나의 동료로서, 당신은 반드시 이해할 거예요."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5540_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5541_AwakerVoiceContent = {Text = "잠깐!"},
  Voice_5541_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5542_AwakerVoiceContent = {Text = "아야!"},
  Voice_5542_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5543_AwakerVoiceContent = {Text = "아파!"},
  Voice_5543_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5544_AwakerVoiceContent = {Text = "윽!"},
  Voice_5544_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5545_AwakerVoiceContent = {
    Text = "광역 아카이브에서 「융식」검색 중... 필요 없다, 알겠습니다. 융식에 대한 에리카의 의견을 알고 싶다, 알겠습니다. 깨어남체 개인 도메인에서 「대융식 병기」 검색 중... 검색 결과: 「0」."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "위작이란 연기나 먼지와 같이 연약하여, 자그만한 바람만으로도 날아가버리고 만답니다..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_5546_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "조금 시끄럽네, 학생들인가? \n그들은 알바트로스와 닮았어, 그 새를 아나요? 끝없는 활력으로 여정이 영원히 끝나지 않을 것 같아……"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5548_AwakerVoiceContent = {Text = "하!"},
  Voice_5548_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5549_AwakerVoiceContent = {Text = "흥."},
  Voice_5549_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5550_AwakerVoiceContent = {
    Text = "검술에 재능이 있는 라모나를 제외하면, 학교에는 고리타분한 녀석들뿐이라 너무 지루해... 설마 너도 그런 부류는 아니겠지? 조사 보고서 같은 걸 쓰면 즐거워한다든가?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "별 일도 아니군."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "다양한 엄마가 있어. 좋은 엄마도 있고, 나쁜 엄마도 있어. 주인은, 좋은 엄마."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5552_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "주군을 지키지 못한 저에게, 부디 벌을..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "식장은 예약했어? 정원은 최소 150야드를 넘겨야 해!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5554_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "죽어가는 사람의 진한 피는 미끄러운 액체입니다. 목에 가볍게 한 번 긋기만 하면, 피가 이빨 사이를 따라 따뜻한 가는 줄기로 변해 내 배로 천천히 흘러 들어갑니다......ㅎㅎ, 맛있네요."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "잡담·피에 대해"
  },
  Voice_5556_AwakerVoiceContent = {Text = "아"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5557_AwakerVoiceContent = {Text = "헤이!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5558_AwakerVoiceContent = {Text = "에이"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "당신의 자비로운 마음에 감사드립니다. 저에게 거처를 제공해 주셔서 감사합니다. 부디 저 때문에 당신에게 비극적인 운명이 찾아오지 않기를 바랍니다…"
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "나는 먼 이국의 별에서 왔습니다. 그곳은 혹독한 바람과 눈보라가 몰아치는 극도로 차가운 곳입니다. 하지만 괜찮습니다. 제 저택에는 천 명이 넘는 종복들이 있어서 그들의 존재가 큰 위안과 따뜻함을 줍니다."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "잡담·과거에 대해"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "이곳에서 쓰러질 수는 없습니다!"
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "이곳에서 쓰러질 수는 없습니다!"
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "아이야, 세상에 어떻게 이렇게 교만한 손님이 있을 수 있겠습니까? 「세상에서 가장 잘 쓰이는 무기」를 원한다고 했어요. 제가 그에게 증오로 가득 찬 머리로 바꿔야 한다고 말했더니, 그는 불만스럽게 떠났어요……"
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "잡담·골리아에 대해"
  },
  Voice_5563_UnlockDesc = {
    Text = "깨어남체「골리아」획득 후 개방"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "너의 그, 세계를 위해서라면 목숨도 아깝지 않다는 표정을 보고 있으면, 온몸에 소름이 끼쳐."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5564_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "연구 금지령이 내려지기 전, 조금만 더 했으면 이 융식 피난소를 없애버릴 수 있었는데... 정말 유감이야."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5565_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "맞아, 예비 몸은 얼마든지 있었어. 융식으로부터 도망칠 기회도 말이지. 하지만, 진리로 통하는 문이 눈앞에 열렸을 때, 눈을 돌릴 수 있는 학자는 없어. 나는 마음 속 목소리에 답했을 뿐이야. 후회는 없어."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5566_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "세계의 진실타래, 세계의 시작, 세계의 끝, 모든 게 무의미해. 네가 진실타래로 향하는 길을 걷고자 한다면, 널 이끌어줄 수도 있어... 옛날처럼 말이지."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5567_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "나를 멈춰도, 종언을 멈출 수는 없어... 하지만, 이 대학과 너는 마지막까지 남겨주도록 할게. 종언의 순간, 높은 탑의 정상에서 황혼을 바라보며, 문명의 붕괴를 지켜본다... 그게 나와 너의 결말이야."
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5568_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5569_AwakerVoiceContent = {Text = "알겠어."},
  Voice_5569_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5570_AwakerVoiceContent = {Text = "사라져."},
  Voice_5570_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5571_AwakerVoiceContent = {
    Text = "저의 기도가, 조국을 다시 깨우는 종소리가 된다면 좋겠습니다만..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "나는 틴커트 외에 나를 받아들일 사람이 있을 거라고 생각해 본 적이 없어요. 당신과 만날 수 있어 정말 다행이에요, 수호자. 나는 힘을 제어하는 법을 최선을 다해 배울 거예요. 그렇게 하면 당신을 안을 때 당신의 생명력을 빼앗지 않을 거예요…… 안기는 건가요? 인간이 감사를 표현하는 방법?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5572_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "나는 여기 남아 있어도 보상이 필요하지 않나요? 당신의 여기서의 지위를 높이는 데 도움을 줄 수 있어요. 그들의 생명을 흡수할 것이라는 위협만으로 충분해요, 예전에 틴커트를 도왔던 것처럼…… 아! 이, 이 일은 다른 사람에게 절대 말하지 말아요!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5573_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "죄송합니다, 저는 다른 동류와 달리 부족한 존재입니다……"
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5574_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "우수한 시녀는 살롱을 더욱 빛나게 만들 수 있지만, 연두색의 시녀…… 잠시 더 고민해 보겠습니다……"
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "잡담·카렌에 대해"
  },
  Voice_5575_UnlockDesc = {
    Text = "깨어남체「카렌」획득 후 개방"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "틴커트는 제 쌍둥이 여동생으로, 저와 달리 항상 빛나고 있어……\n제가 그녀에게 부담을 주지 않았다면, 그녀는 더 아름다운 미래를 맞이했을 것이고, 그녀의 노래는 온 은하계에 울려 퍼졌을 것입니다……"
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5576_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "요람이 너무 좁아서 몸을 펼 수 없어… 하지만 틴커트는 모든 사람의 안전을 위해 내가 요람을 떠나지 않게 했어… 그녀가 그렇게 바라는 거라면, 나는 들어줄 거야."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5577_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "저는 삶과 죽음의 사이에 있는 듯한 존재입니다. 제 곁에선 우울이 파도와 같이 퍼지고, 비극이 끊임없이 다가옵니다. 그래도, 당신을 위해 시를 읊어도 되는 걸까요? ...그렇군요. 이럴 때는 더욱 달콤한 단어가 어울릴 지도 모르겠어요..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5578_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "「장미는 아직 피지 않았거늘, 새벽은 오네」"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5579_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "당신께선 무엇을 원하시나요? 미사여구? 세계에 자랑할 만한 명성? 아니라면, 단어 뒤에 숨겨진, 피가 통하는 진심인가요?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5580_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "눈에 보이지 않는 먹으로, 일그러진 꽃봉우리를 그린다... 이 유령 같은 허망한 장미는, 시의 영감이 되는 것입니다..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5581_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "순종하라...!"
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "영지 깨어남·2"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "신의 나라에 재생을!"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "영지 깨어남·3"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "당신께서 바라신다면, 다시 태양 아래를 걷겠습니다... 시테에 있던, 그 시절처럼..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5582_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "헤헤, 당신은 파괴된 우주를 보고 싶나요? 아이, 지금 되돌아가도 늦었어요!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5583_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "달콤한 죽음을 음미해."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "달콤한 죽음을 음미해."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "피 한방울 남기지 않고 짜내주겠어!"
  },
  Voice_5586_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5587_AwakerVoiceContent = {Text = "싫어..."},
  Voice_5587_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5588_AwakerVoiceContent = {
    Text = "짐의 위광을, 똑똑히 보아라"
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "새벽 4시의 대학 공기는 상쾌하고, 함께 운동해 주셔서 기쁩니다. 정말로, 조각은 힘든 일입니다."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "잡담·아침에 대해"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "이 힘, 느낌이 꽤 좋네."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5590_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "나는 물건을 사서 돈을 안 지불하는 사람들을 싫어합니다. 가게를 오래 운영하다 보면 이런 상황을 겪게 되겠죠. 어쩔 수 없네요, 저도 직접 나서서 계산을 받아야겠습니다~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "천천히 고문하다."
  },
  Voice_5592_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5593_AwakerVoiceContent = {
    Text = "천천히 고문하다."
  },
  Voice_5593_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5594_AwakerVoiceContent = {
    Text = "개시합니다."
  },
  Voice_5594_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5595_AwakerVoiceContent = {
    Text = "기동 시작."
  },
  Voice_5595_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5596_AwakerVoiceContent = {
    Text = "함께 이곳을 시끌벅적한 바다로 만들자!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "뭐? 설마 내 입에서 감사의 말이라도 듣고 싶은 거야?"
  },
  Voice_5597_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5598_AwakerVoiceContent = {
    Text = "공물로는 불합격이네... 그래도 뭐, 애써서 준비했으니까. 못 받아줄 정도는 아니야."
  },
  Voice_5598_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5599_AwakerVoiceContent = {
    Text = "이렇게 한다고, 내가 네 말대로 따라줄 거라 생각했어?"
  },
  Voice_5599_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5600_AwakerVoiceContent = {Text = "하앗!"},
  Voice_5600_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5601_AwakerVoiceContent = {Text = "가자!"},
  Voice_5601_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5602_AwakerVoiceContent = {
    Text = "은혜를 갚지 않는 몬스터, 암살자, 살인자, 당신이 인정할 가치가 있니? 괴인."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5602_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "무론 얼마나 많은 쿠션이 쌓여 있어도, 청금석 옥좌는 깃털 침대와 비교할 수 없다. 이 점에서 볼 때, 너희들 여기에도 장점이 있군."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "작은 벌."
  },
  Voice_5604_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5605_AwakerVoiceContent = {
    Text = "나는 고독을 싫어해요, 끝이 보이지 않는 어둠 속에서 누군가의 감정을 걱정하는 것을 싫어해요… 그래서, 저를 버리지 말아요, 괜찮을까요?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "만약 내가 당신이었다면, 모든 깨어남체를 장롱에 가두었을 거예요! 미친 개가 장롱에서 나온 후에는 항상 주인을 가장 먼저 물어죽입니다."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5606_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "이번 회의에 한 시간 늦었어요——모두 그 노예 제도를 폐지한 문제를 일으키는 자들 때문이에요, 이제 머리를 빗겨줄 사람이 없네요!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5607_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "상상할 수 없어, 나의 고향이 이렇게 소멸하다니… 그곳은 위대한 로마였다! 당신이 듣지 못했을 리가 없어!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5608_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "준비는 됐어? 처음이 중요한 법이라고!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "이건 주께서 내리신 축복입니다."
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "가련한 눈빛을 거두세요. 나는 그런 걸 좋아하지도 않고 필요하지도 않아요. 그렇게 계속 나를 바라보면 참을 수 없어 당신을 무자비하게 고문할 거야…… 당신도 상황이 통제 불가능해지길 원하지 않을 테니까, 좀 더 순종적으로 굴고, 내 말을 잘 들어. 제대로 된 격투사가 되어 주겠지……"
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5611_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "별*조용히* 다시 묻지 마세요. 내가 소홀히 하여, 경솔하게 행동하여 격투사가 도망쳤고, 결국 가족 모두가 죽었습니다! 지금의 로마 제국처럼 불타서 재도 남지 않았습니다!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5612_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "각자의 재능을 가진 분들에 비해 닝피아는 어떤 공적도 세우지 않고, 어떤 가치도 창조하지 않은 평범한 인간에 불과합니다. \n저를 깨어남시킨 것은…… 아마도 작은, 초라한 소망들이었을 것입니다……"
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "오늘 나는 다시 교칙을 어기고 수업에 5분 늦었습니다… 그래서, 나는 가장 엄격한 처벌을 수락하기를 간청합니다. 만약 수호자가 집행한다면 더 좋겠습니다."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "도구도 유지보수가 필요해요. 적합한 도구 세트는 기계공의 영혼이죠."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5615_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(비웃음의 인내심)"
  },
  Voice_5616_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5617_AwakerVoiceContent = {
    Text = "다음에 또 실타래패하면, 관찰 처분을 내릴 거야."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "전투 외의 일은 재미없지만, 자신의 책무를 다하는 것은 당연하지 않겠느냐? 이 별에서도 해야 할 일은 확실타래히… 어이, 설마 내가 싸움밖에 못한다고 생각한 건 아니겠지?!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "잡담·일에 대해"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "저에게 다가오는 사람은 언제나, 인생에서 가장 슬픈 체험을 떠올리고는, 눈물을 흘립니다. 이런 저라도, 성장해도 괜찮은 걸까요?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5619_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5620_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5621_AwakerVoiceContent = {
    Text = "이렇게요?"
  },
  Voice_5621_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5622_AwakerVoiceContent = {
    Text = "여기서는 더럽고 냄새나는 신문 감옥보다 훨씬 좋다! 소파에 누워있거나 벽구석에 있어도 모두 편안해!"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "브라운……!"
  },
  Voice_5623_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5624_AwakerVoiceContent = {
    Text = "달팽이 껍질，어디로 갔을까……"
  },
  Voice_5624_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5625_AwakerVoiceContent = {Text = "교활해!"},
  Voice_5625_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5626_AwakerVoiceContent = {
    Text = "나사 껍데기가 어디로 갔어！"
  },
  Voice_5626_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5627_AwakerVoiceContent = {
    Text = "흐르는 은하……"
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "오레타는 갑자기 사라져버리는 친구가 싫어... 그래도그래도, 다시 돌아온다면 용서할 거야!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "혼자 배를 타고 바다를 건너는 여자, 여신 외에도 미친 여자다. 나는 미리암을 여신으로 생각한 것은 정말 큰 착각이었다."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해"
  },
  Voice_5629_UnlockDesc = {
    Text = "깨어남체「미리암」획득 후 개방"
  },
  Voice_5630_AwakerVoiceContent = {Text = "윽!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "카시아 씨의 매직 쇼를 살짝 보러 갔었습니다. 그녀는, 사람들에게 많은 기쁨을 안겨주고 있어서, 슬프게만 하는 저와는 너무나 다르네요... 네? ...눈물은 웃음과 마찬가지로 소중하다, 라는 말씀이신가요? 그렇다면 조금은 마음이 놓이네요."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "잡담·카시아에 대해"
  },
  Voice_56313_UnlockDesc = {
    Text = "깨어남체「카시아」획득 후 개방"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "시와, 불꽃과, 슬픔은 너무나 닮아있습니다. 모르는 사이에 삼켜지고... 깨닫게 되면, 그 세계에서 빠져나올 수 없게 되죠..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "추억의 시가 마음의 정원을 일깨우는구나."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "시와 꽃은, 같습니다. 어느 쪽이든 덧없는 것, 그리고 영원히 마음에 남는 것... 이 끝없는 세계 속에서, 아주 자그만한 마음의 틈새에, 시와 꽃은 새겨집니다. 어느 누구라 한들, 한 편의 시에 침묵하고, 한 송이의 꽃에 멈춰서서, 마음이 동하는 것 입니다."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "잡담·시에 대해"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "지금 계절의 시테에선, 어떤 꽃이 피어나고 있을까요...? 전 이미, 잊어버리고 말았습니다..."
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "잡담·시테에 대해"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "당신께선, 제 펜에서 태어난 문자를 시의 세계로 돌려놓아 주셨습니다. 저는 지금부터, 당신의 이야기를 읊어가고 싶습니다."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해·1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "피어나는 꽃은 아름다우나, 흩날리기 전의 반짝임이라는 사실타래이, 슬퍼서 견딜 수 없습니다. 그래도 저는, 아무리 슬픈들 꽃을 위해 그곳에 있겠습니다. 슬픔을 두려워해 눈을 돌린다면, 꽃이 슬퍼할테니까요."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "잡담·고통에 대해"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "에리카가 「자는」 동안 이 몸의 내부 구조를 연구하기 위해 벤코르는 밤에 그녀의 사무실타래에서 수면할 것을 요구했습니다. \n에리카가 수면 중에도 일부 의식을 유지한다는 것을 알려야 하나요?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "잡담·윙클에 대해"
  },
  Voice_5631_UnlockDesc = {
    Text = "깨어남체「윙클」획득 후 개방"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "붉은 여인, 소렐 씨는 아름답습니다. 강함과 자신감, 운명에 맞서는 우아한 미소, 붉은 장미처럼 늠름하고, 힘차면서 깨끗한 생명력이, 제게는 부러울 따름입니다..."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "잡담·소렐에 대해"
  },
  Voice_56320_UnlockDesc = {
    Text = "깨어남체「소렐」획득 후 개방"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "어제, 새로운 시를 썼습니다. 아직 누구에게도 보여주지 않아서... 그리 좋은 시가 아닐 지도 모르겠지만, 부디 읽어봐 주실타래 수 있나요...?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해·2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "학생들의 시인 모임에서 지도자가 되어 달라 부탁 받았습니다만... 받아들일 수 없었습니다. 저 같은 게 지도자가 되어도, 그들에게 우울과 실타래망을 안겨줄 뿐이니까..."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "가치 없는 것이란, 이 세상에 존재하지 않습니다. 황금시대의 용맹한 시도, 늘그막의 연민을 불러 일으키는 시도, 모두 마음에 울립니다. 화려한 장식에는 동경이 모이고, 삭아가는 낡은 천에는 역사가 쌓입니다."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "님피아 씨와 만날 때마다, 그 수련 그림을 떠올립니다. 그녀에게는 수련과 같은 정적과, 쓰면서도 맑은 향기를 느끼게 됩니다... 그녀의 눈에, 세계는 어떻게 비춰지고 있는 걸까요."
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "잡담·님피아에 대해"
  },
  Voice_56324_UnlockDesc = {
    Text = "깨어남체「님피아」획득 후 개방"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "한참 전부터, 제 주변엔 「유령」의 기척이 있었습니다. 홀려버린 걸까요... 그 존재는 나날이 제가 가진 세상에 대한 기대를 잃게 만듭니다. 하지만, 혹시 정말로 유령이라고 한다면, 사라진 우유와 물은 어디로 간 걸까요..."
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "잡담·유령에 대해"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "제 몸은 융식에 침식되지 않았습니다. 이 검은 액체는, 평범한 먹입니다. 모든 분들이 상당히 신경 쓰고 계신 것 같습니다만... 융식이 있거나 없거나, 모든 것은 언젠가 무로 돌아갑니다. 그렇지요?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "열쇠 무덤의 묘석에서, 수호자의 이름을 봤습니다... 저의 생전 기억은 괴로웠으나, 잊으려 한 적은 없습니다. 수호자에게 있어서도, 잃어버린 기억은 분명 둘도 없는 것이라 생각합니다."
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "잡담·기억에 대해"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "만약 아름다움을 찬양하기 위해 시가 존재한다면, 모든 시인은 그녀를 논하지 않으면 안되겠지요. 선인들이 말하는 나이팅게일의 노래 소리란, 그녀에게야말로 바쳐져야 할 단어입니다."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "잡담·틴커트에 대해"
  },
  Voice_56328_UnlockDesc = {
    Text = "깨어남체「틴커트」획득 후 개방"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "그녀의 춤은 너무나 아름다워서... 설령 그 몸에 둘러진 녹색 불꽃에 타오른다 한들, 무심코 닿고 싶어집니다..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "잡담·리즈에 대해"
  },
  Voice_56329_UnlockDesc = {
    Text = "깨어남체「리즈」획득 후 개방"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "원질을 흡수하는 대신, 이런 방식을 쓰는군요?"
  },
  Voice_5632_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5633_AwakerVoiceContent = {
    Text = "아름다워, 정말로 아름답네요."
  },
  Voice_5633_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5634_AwakerVoiceContent = {
    Text = "어떤 보수를 원하시나요, 손님?"
  },
  Voice_5634_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5635_AwakerVoiceContent = {
    Text = "빨리 끝내고 돌아가야지."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "신선한 피를 바칩시다."
  },
  Voice_5636_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5637_AwakerVoiceContent = {Text = "우으..."},
  Voice_5637_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_56386_AwakerVoiceContent = {
    Text = "전류, 준비 완료. 전류, 발사."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "거리 제일의 괴도를 얕보지 말라고!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "쇼의 시작이야! 모두, 박수~!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "이 땅에 떠올라라, 삼라의 환상이여!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "다시 거리가 줄었어..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5638_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "떨어져라, 불타라, 죽을 때까지 춤춰라!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "모든 방황하는 자들이여, 죽음의 도시로 가거라."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "남은 에너지를... 너에게 줄게!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "거리 제일의 괴도를 얕보지 말라고!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "적이야? 적이라면, 공격 명령을 내려주세요. \n검은 점액은 적... 그럼, 릴리도 적?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "토르소 번호 EA307881, 모터 번호 MF311028, 오토마톤 에리카입니다. 잘 부탁드립니다."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5641_AwakerVoiceContent = {
    Text = "적을 철저히 때려부술 때까지, 전력으로 싸우자고!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "안녕하세요, 저는... 어라? 혹시 내 이름을 알려줄 수 있을까?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5643_AwakerVoiceContent = {
    Text = "학교에 도착한 후에야 나는 자신이 감염된 ‘융식’이라는 병을 이해하게 되었습니다. 그 전에 부모님은 항상 나에게 바다를 멀리하길 바랐는데, 이제 보니 이 감염이 내가 바다와 가까워진 행동과 혹시 확실타래하게 관련이 있는지도 모릅니다…"
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "널 실타래망시키지는 않을게."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "뜨거운 숨결을 느껴봐!"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5646_AwakerVoiceContent = {Text = "가."},
  Voice_5646_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5647_AwakerVoiceContent = {Text = "회전해."},
  Voice_5647_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5648_AwakerVoiceContent = {
    Text = "아이기스, 힘낼게요!"
  },
  Voice_5648_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5650_AwakerVoiceContent = {
    Text = "드디어 그 날이 왔네요..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5651_AwakerVoiceContent = {
    Text = "죄, 죄송합니다!"
  },
  Voice_5651_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5652_AwakerVoiceContent = {
    Text = "이걸로는 부족하군... 어이, 한번 더 죽여도 되나?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "수호자, 나는 당신과 이야기해야 합니다. 우리가 최종 승리를 거두기 전에, 일부 사람들은 그런 사치와 낭비를 해서는 안 됩니다. 알아 두십시오, 저는 그런 사람들의 사치스러운 생활을 위해 싸우지 않습니다."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "잡담·소렐에 대해"
  },
  Voice_5654_UnlockDesc = {
    Text = "깨어남체「소렐」획득 후 개방"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "포로가 되어버리면 얼마나 심한 일을 당하게 될지... 후후..."
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5656_AwakerVoiceContent = {Text = "으랴!"},
  Voice_5656_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5657_AwakerVoiceContent = {
    Text = "난 무엇도 두렵지 않아!"
  },
  Voice_5657_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5658_AwakerVoiceContent = {
    Text = "흐아암... 지루해. 있잖아, 쉴 때 마실타래 허브티는 준비했어?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "엄마, 만져볼래? 엄청 부드럽대."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5659_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "랄랄라~ 랄랄라~♪ 청소 정말 좋아, 깔끔하고 깨끗해지면, 기분이 좋아져~♪"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "잡담·일에 대해"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(참을 수 없는 통증)"
  },
  Voice_5661_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5662_AwakerVoiceContent = {
    Text = "음… 좋다."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(참을 수 없는 통증)"
  },
  Voice_5663_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5664_AwakerVoiceContent = {
    Text = "(참을 수 없는 통증)"
  },
  Voice_5664_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5665_AwakerVoiceContent = {
    Text = "분노가 타오르다!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "많은 사람들이 융식으로 인해 미쳐버렸다. 솔직히 말하면, 나는 이미 충분히 미쳤으니 융식이 나에게는 큰 영향을 주지 않을 거야."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "피에 녹아버려."
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "좋은 도구가 있다면, 싸움에서 이미 절반은 이긴 거야!"
  },
  Voice_5668_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5669_AwakerVoiceContent = {
    Text = "다시 태어난 것 같아."
  },
  Voice_5669_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5670_AwakerVoiceContent = {
    Text = "나쁘지 않네."
  },
  Voice_5670_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5671_AwakerVoiceContent = {
    Text = "더 강력한 일격을 휘두를 수 있겠어."
  },
  Voice_5671_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5672_AwakerVoiceContent = {
    Text = "출근율을 유지하면서, 연구나 신인 육성도 해야 하는데... 아무래도 시간 압축 역전 실타래험을 진행할 필요가 있을 것 같네."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5672_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "모험까지 앞으로 한 걸음."
  },
  Voice_5673_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5674_AwakerVoiceContent = {
    Text = "다른 사람들이 물에 가까이 가지 않게 해줘요. 당신의 사랑의 불꽃이 꺼질 수 있어요?"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "전투 끝까지!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "정말 용감하시네요. 이 촉수들을 보고도 광기에 흡수되는 것을 두려워하지 않나요?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5676_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5677_AwakerVoiceContent = {Text = "아야!"},
  Voice_5677_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5678_AwakerVoiceContent = {Text = "아야!"},
  Voice_5678_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5679_AwakerVoiceContent = {
    Text = "그만해주세요!"
  },
  Voice_5679_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5680_AwakerVoiceContent = {
    Text = "만져볼래요? 제 심장은 당신의 존재로 인해 뛰고 있어요."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5680_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "녀석들도 즐거워 보여. 고마워, 주인."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5681_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "릴리 안에서, 무언가가 깨어나는 것 같아... 따뜻해서, 눈물이 날 것 같은, 그런 무언가가. 엄마, 같이 축하해 줘."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5682_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "엄마랑 같이 있으면, 행복해."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5683_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "더는 못 먹겠어, 배가 빵빵해. 이 의식이 끝나면, 릴리는 더 강해질까?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5684_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "나는 바다를 좋아해, 매우 아이러니하지 않을까? 내가 가진 모든 것이 이미 깊은 바다에 가라앉았으니까…"
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5686_AwakerVoiceContent = {Text = "조심해!"},
  Voice_5686_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5687_AwakerVoiceContent = {
    Text = "싫어하는 것? 딱히 없어. 너는 먼지나 잎사귀를 싫어하니? 그런 것과 똑같아."
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "메이드 분의 연회 초대를 몇 번이나 거절해서, 조금 상심하게 만든 것 같습니다…. 죄송스럽지만, 노는 것보다 주군의 안전이 먼저니까요!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "잡담·카렌에 대해"
  },
  Voice_5688_UnlockDesc = {
    Text = "깨어남체「카렌」획득 후 개방"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "주군이 있기에 기사가 있습니다! 자, 뭐든지 말씀해주세요!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "……이것은 아마도 토크 스패너가 필요할 것 같아요……음, 죄송합니다, 당신이 방금 저를 부르셨나요?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5691_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5692_AwakerVoiceContent = {Text = "대담!"},
  Voice_5692_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5693_AwakerVoiceContent = {
    Text = "(우아한 경음)"
  },
  Voice_5693_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5694_AwakerVoiceContent = {Text = "우으..."},
  Voice_5694_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5695_AwakerVoiceContent = {
    Text = "적당히 해."
  },
  Voice_5695_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5696_AwakerVoiceContent = {
    Text = "부드럽게 해줘."
  },
  Voice_5696_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5697_AwakerVoiceContent = {
    Text = "역시 집중하긴 어렵군..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "그녀는 밤이면 자주 내 근처에 머물러 있어요, 내 이 머리가 너무 눈에 띄는 걸까요?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "잡담·윙클에 대해"
  },
  Voice_5698_UnlockDesc = {
    Text = "깨어남체「윙클」획득 후 개방"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "저는 파괴의 강림을 기다리며, ‘저항’이라는 선택을 생각해 본 적이 없었습니다…… 당신은 저처럼 영혼이 얕은 저를 소멸에서 건너 데려가 주실타래 수 있을까요? 죽음에서 살아남은 세계에서도 여전히 저에게 구원을 베풀어 주시겠습니까……"
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5699_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "이미 당신의 사도로 깨어남했으니, 당신의 평안과 기쁨 외에는 아무것도 바라지 않습니다. 이것이 저의 원…으아……아…… 역시, 생존, 생존, 생존, 생존, 살아남아야……"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5700_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "내 사랑에 빠지지 않는 걸 시켜볼래? 당신이 나를 깨어남시킨 건, 내 품의 온기를 위해 그런 것이 아니었나?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5701_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "불분명한 출신의 여자와 얽히고 싶지 않으시다고요, 좋아, 좋아. 니느웨의 망국군주, 의도를 관통하려는 시나의 사람, 유프라테스 성수 아래에서 의지를 빼앗긴 소녀……어디부터 듣고 싶으세요?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5702_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "왜 항상 저를 피해 다니세요? 수줍어했나요? 진짜 귀엽네요. 당신의 욕망을 직시하지 못하는 이런 모습……"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5703_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "말도 안 돼, 정말이지 말도 안 돼! 이몸이 다른 사람과 같은 테이블에서 차를 마시게 하다니! 뭐, 수제 쿠키는 나쁘지 않네. 저녁식사가 끝나면 내 방에 가져다 놔."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5705_AwakerVoiceContent = {Text = "읏쌰!"},
  Voice_5705_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5706_AwakerVoiceContent = {Text = "먹어라!"},
  Voice_5706_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5707_AwakerVoiceContent = {
    Text = "융식…고향의 학당에도 융식에 관한 기록이 있었던 것 같아요. 그, 카렌은 책 읽는 걸 싫어해서 다 잊어버렸어요!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "다시 출항하고 싶으신가요? 당신이 제 과거의 실타래수를 신경 쓰지 않는다면, 제가 그렇게 해보겠습니다."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5708_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "싫어하는 것? 그게 너무 많아——직원들을 밤 늦게까지 일하게 하는 사장, 자기만 아는 수녀, 꼬르륵거리는 배, 깨진 유리가 박힌 검은 빵……"
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "아이기스가 잘못했어요. 전부, 제 잘못이에요..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "끝내겠어!"
  },
  Voice_5711_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5712_AwakerVoiceContent = {
    Text = "한나 양반님의 도움으로 합창단 연습을 듣게 되었습니다. 찬송가는 배노래와 매우 다르며, 항해를 보호하는 시간 동안 이렇게 독특한 선율은 들어본 적이 없습니다."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "이건 어떠냐!"
  },
  Voice_5713_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5714_AwakerVoiceContent = {
    Text = "이건 어떠냐!"
  },
  Voice_5714_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5715_AwakerVoiceContent = {
    Text = "무서워~!"
  },
  Voice_5715_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5716_AwakerVoiceContent = {Text = "윽..."},
  Voice_5716_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5717_AwakerVoiceContent = {
    Text = "안녕하세요, 새로운 주인님! 오늘의 메뉴는 민달팽이 푸딩, 개구리 스튜, 그리고 녹염주입니다! 원하시는 걸로 드세요~"
  },
  Voice_5717_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5718_AwakerVoiceContent = {
    Text = "그것이 본원의 형태로 회귀한 것인가……아니, 내가 상상했던 것과는 조금 다르다. 하지만, 나도 그런 모습이 될 수 있다면 좋겠어……"
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "잡담·심해 혈통에 대해"
  },
  Voice_5718_UnlockDesc = {
    Text = "깨어남체「툴루」,「머피」,「미리암」,「골리아」중 하나 획득 후 개방"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "기회를 기다립니다."
  },
  Voice_5719_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5720_AwakerVoiceContent = {Text = "받아라!"},
  Voice_5720_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5721_AwakerVoiceContent = {
    Text = "어린 양들이여, 신의 자비로 구원받기를."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "어린 양들이여, 신의 자비로 구원받기를."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5723_AwakerVoiceContent = {Text = "죽어!"},
  Voice_5723_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5724_AwakerVoiceContent = {Text = "하!"},
  Voice_5724_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5725_AwakerVoiceContent = {Text = "죽어!"},
  Voice_5725_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5726_AwakerVoiceContent = {
    Text = "발설치 마라."
  },
  Voice_5726_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5727_AwakerVoiceContent = {
    Text = "그녀도 가련한 사람으로, 결국 운명에 짓밟히게 될 것입니다. 왜냐하면, 그분이 진정으로 강림하는 순간이 바로 내가 그녀에게 죽음을 선사할 때이기 때문입니다."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해"
  },
  Voice_5727_UnlockDesc = {
    Text = "깨어남체 「미리암」을 획득하면 해금됩니다"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "피로 물들여라!"
  },
  Voice_5728_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5729_AwakerVoiceContent = {
    Text = "복수……!"
  },
  Voice_5729_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5730_AwakerVoiceContent = {Text = "아파..."},
  Voice_5730_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5731_AwakerVoiceContent = {Text = "으으..."},
  Voice_5731_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5732_AwakerVoiceContent = {Text = "으으..."},
  Voice_5732_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5733_AwakerVoiceContent = {Text = "아야..."},
  Voice_5733_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5734_AwakerVoiceContent = {
    Text = "당신은 저와 함께 가라앉고 싶으세요?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5735_AwakerVoiceContent = {Text = "꺼져라!"},
  Voice_5735_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5736_AwakerVoiceContent = {
    Text = "싫어하는 거라면... 그래, 어질러진 책상과 옷장, 먼지가 잔뜩 쌓인 창틀... 그래, 네 방 말하는 거야. 내일 7시까지는 깨끗하게 치우도록 해, 알겠어?"
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5737_AwakerVoiceContent = {Text = "훗"},
  Voice_5737_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5738_AwakerVoiceContent = {Text = "재밌군!"},
  Voice_5738_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5739_AwakerVoiceContent = {Text = "하하하!"},
  Voice_5739_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5740_AwakerVoiceContent = {
    Text = "당신을 위해서라면, 이 요람에서 벗어나는 것도..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "원하십니까?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5742_AwakerVoiceContent = {Text = "봐요~!"},
  Voice_5742_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5743_AwakerVoiceContent = {
    Text = "더블,더블,더블!"
  },
  Voice_5743_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5744_AwakerVoiceContent = {
    Text = "이것은 8살 때 받은 첫 번째 빨간 무용화를 생각나게 해요. 정말 좋아했어요, 감사합니다. 수호자."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5744_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "친구... 주인은 친구? 아니면, 엄마?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "나의 가호도, 통하지 않을 때가 있어..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(음성)"},
  Voice_5747_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5748_AwakerVoiceContent = {Text = "으우우."},
  Voice_5748_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5749_AwakerVoiceContent = {Text = "으우우."},
  Voice_5749_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5750_AwakerVoiceContent = {
    Text = "좋아하는 것? 펠로폰네소스 (Peloponnesus) 전쟁장에서 누군가가 나에게 이 질문을 했었어…… 이미 늦었지, 나는 이런 개인적인 취향을 버렸다."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "쉿... 내가 강해졌다는 사실타래은, 「그녀들」에게 비밀로 해줘."
  },
  Voice_5751_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5752_AwakerVoiceContent = {
    Text = "고마워... 라고, 「그녀들」이 말했어."
  },
  Voice_5752_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5753_AwakerVoiceContent = {
    Text = "그, 이건 뭐야?"
  },
  Voice_5753_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5754_AwakerVoiceContent = {
    Text = "이런 짓을 해 봤자, 나와 심연 사이의 거리가 줄어들 뿐이야."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5754_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "당신은 나의 사랑스러운 하인입니다. 나는 알고 있어요, 당신들은 이를 친구, 동료, 동지…라고 부르지만 상관없어요, 당신이 원하는 대로 해도 좋아요."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "답을 얻었어... 내가 바란 답은 아니었지만, 답을 얻은 거야."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5756_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "공포? 아니면 슬픔? 그 불안해보이는 표정, 정말 매력적이야."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5757_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "죽음과 소멸의 냄새가 다가오고 있어."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5758_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "여기서의 생활? 나, 나쁘진 않으려나. 돌 씨에게, 기계과학과 정신에 관한 연구결과를 알려주면, 전기를 계속 켜두고 있어도 용서해주시거든."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "젠킨과 브라운이 학교 생활을 즐기고 있다면, 장난 정도는 받아줄 수 있어. 아버지의 양복 단추보다는, 그녀의 자유 쪽이 중요하지. 게다가 아버지한테 예비 단추 쯤이야 얼마든지 있을 거야."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_5760_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "떠날 수 없어……"
  },
  Voice_5761_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5762_AwakerVoiceContent = {
    Text = "열등한 종족에서 벗어난 나에게는 이런 영향 따위 두렵지 않다. 내가 깃든 육체가 부서져도 고귀한 혈통은 사라지지 않는다."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "거짓 웃음을 짓는 사람들을 싫어해! 그들로부터는 어떤 감정도 훔칠 수 없어!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "어어? 왜 다들 조용한가요? 카렌은 침묵이 싫어요. 그래! 모두에게 이야기를 들려줄게요. 옛날 옛적에, 어느 산이 있었답니다..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "미래를 이 손으로 붙잡을 거야, Tokuli-Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "미래를 이 손으로 붙잡을 거야, Tokuli-Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "만일 당신이 그의 존재를 감지하기 위해 있다면, 나는 일시적으로 당신의 무례를 용서하겠습니다."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "하지 않으려고 해……"
  },
  Voice_5768_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5769_AwakerVoiceContent = {
    Text = "가까이 오지 마세요!"
  },
  Voice_5769_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5770_AwakerVoiceContent = {
    Text = "이제야 당신과 걸음을 맞출 수 있게 되었습니다!"
  },
  Voice_5770_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5771_AwakerVoiceContent = {
    Text = "한 사람 몫을 하는 기사가 되기 위해, 한 걸음 전진했습니다!"
  },
  Voice_5771_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5772_AwakerVoiceContent = {
    Text = "저를 선택해 주셔서, 진심으로 영광입니다."
  },
  Voice_5772_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5773_AwakerVoiceContent = {
    Text = "목욕탕은 시간을 보내기 좋은 곳으로, 음식이 맛있을 뿐만 아니라 근육을 이완시켜주는 서비스도 제공합니다. 괜찮아 보이죠? 그렇다면 학교에도 바로 하나를 지어보세요!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "떠나지 마!"
  },
  Voice_5774_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5775_AwakerVoiceContent = {Text = "라저ー."},
  Voice_5775_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5776_AwakerVoiceContent = {
    Text = "(통증을 느끼는 음성)"
  },
  Voice_5776_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5777_AwakerVoiceContent = {
    Text = "(비웃음의 인내심)"
  },
  Voice_5777_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5778_AwakerVoiceContent = {
    Text = "(비웃음의 인내심)"
  },
  Voice_5778_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5779_AwakerVoiceContent = {
    Text = "(비웃음의 인내심)"
  },
  Voice_5779_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5780_AwakerVoiceContent = {
    Text = "맡겨주세요."
  },
  Voice_5780_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_57818_AwakerVoiceContent = {
    Text = "나를 모욕한 자들이여, 대가를 치러라!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "나를 모욕한 자들이여, 대가를 치러라!"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "맡겨주세요."
  },
  Voice_5781_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_57820_AwakerVoiceContent = {
    Text = "조국으로 돌아가는 길을 찾아낼지니!"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "살육의 연회를 즐겨보자고!"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57822_AwakerVoiceContent = {
    Text = "조국으로 돌아가는 길을 찾아낼지니!"
  },
  Voice_57822_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57823_AwakerVoiceContent = {
    Text = "거짓된 사명, 정해진 미래, 끝까지 저항할 거야!"
  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "거짓된 사명, 정해진 미래, 끝까지 저항할 거야!"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "살육의 연회를 즐겨보자고!"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "나와 뒤섞여, 묘목이 되자꾸나."
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "깨달아라, 나의 절망과 분노를!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "깨달아라, 나의 절망과 분노를!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "나와 뒤섞여, 묘목이 되자꾸나."
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "저는 오레타에게 말하기가 좀 부끄러웠어요. 제가 그녀가 상상하는 것만큼 어리지 않다는 걸…… 제게 '여동생'이라고 부르지 말라고 설득해 주실타래 수 있을까요?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "잡담·오레타에 대해"
  },
  Voice_5782_UnlockDesc = {
    Text = "깨어남체「오레타」획득 후 개방"
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "잃어버린 묘소, 르뤼에의 베일은 밝혀졌다."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "잃어버린 묘소, 르뤼에의 베일은 밝혀졌다."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "약속을 지킬 때가 온 것 같구나."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "약속을 지킬 때가 온 것 같구나."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "모든 것은 신께서 정하신 대로."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "모든 것은 신께서 정하신 대로."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "별들로부터의 초대를!"
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "나도, 별처럼 빛날 수 있어."
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "나도, 별처럼 빛날 수 있어."
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "별들로부터의 초대를!"
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5783_AwakerVoiceContent = {
    Text = "물러나세요!"
  },
  Voice_5783_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_57840_AwakerVoiceContent = {
    Text = "다함께 가자!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "지저에 숨은 신이, 이곳에서 심판을 내린다."
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "지저에 숨은 신이, 이곳에서 심판을 내린다."
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "푸른 하늘을 나는 새야, 기도에 답해주렴."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "푸른 하늘을 나는 새야, 기도에 답해주렴."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "움직이지 마! 움직이지 마! 움직이지 마!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "피의 사슬에 떨고, 피의 사슬에 사라져라!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "피의 사슬에 떨고, 피의 사슬에 사라져라!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "다함께 가자!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "움직이지 마! 움직이지 마! 움직이지 마!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5784_AwakerVoiceContent = {Text = "후후."},
  Voice_5784_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_57850_AwakerVoiceContent = {
    Text = "세계를 손에 넣을 펠리시테인의 힘을, 똑똑히 봐라!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "세계를 손에 넣을 펠리시테인의 힘을, 똑똑히 봐라!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5785_AwakerVoiceContent = {Text = "약해!"},
  Voice_5785_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5786_AwakerVoiceContent = {
    Text = "머리 조심하라고!"
  },
  Voice_5786_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5787_AwakerVoiceContent = {
    Text = "음... 주인님, 혹시 기분이 안 좋으신가요? 자, 카렌의 웃긴 얼굴을 보세요! 에헷! 어떤가요? 기분이 조금은 나아지셨나요?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "세계를 해석하고, 인류의 지성을 증명한다!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "나는 복도에서 기분 나쁜 느낌을 주는 사람들을 만났다. 상황에 따라 당신이 그들과 협동해야 할지도 모르지만, 항상 경계를 유지해야 한다. 전쟁보다 더 잔혹한 것은 오직 인간의 마음뿐이며, 가장 두려운 배반은 종종 내부에서 비롯된다."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "잡담·@2에 대해"
  },
  Voice_5789_UnlockDesc = {
    Text = "깨어남체「히로」또는「릴리」획득 후 개방"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "숙제는 이미 끝냈지? 지금부터 론디니움시에 갈 건데, 같이 갈래? 응? 수학 숙제를 못 풀겠다고?! 설마 미적분을 이해 못 하는 사람이 있다니... 괜찮으면 도와줄까?"
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "잡담·공부에 대해"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "저는 당신에게 맹세합니다, 그 상점주는 단풍단백로의 살롱에서 분명히 모습을 드러낸 적이 있습니다… 원래 이렇게, 그때부터 그녀는 그런 모습이었군요. 모릅니다, 그녀의 손에서 얼마나 많은 비밀을 얻을 수 있을지?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "잡담·다포딜에 대해"
  },
  Voice_5791_UnlockDesc = {
    Text = "깨어남체 「다포딜」획득 후 개방"
  },
  Voice_5792_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5792_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5793_AwakerVoiceContent = {
    Text = "조심해, 부서지지 않게 해."
  },
  Voice_5793_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5794_AwakerVoiceContent = {
    Text = "오레타는 모두와 노는 게 제일 좋아! 너도 같이 놀래? 이 아이는 제리, 저 아이는 헤라, 저기는 제리... 어라?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "이 일격으로, 설욕을 풀겠습니다...!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "다프다일의 작은 가게가 문을 열었습니다. 준비를 제대로 하지 않은 아이들은 함부로 들어오는 것이 좋지 않아요?"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5796_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "목에는 손대지 말아주세요... 보이지 않는다고 해서 존재하지 않는 건 아닙니다."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "동물이든, 인간이든, 깨어남체든 신념이 있는 녀석을 좋아해. 전투력이 높은 강자라면 더더욱 좋고."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5799_AwakerVoiceContent = {Text = "가."},
  Voice_5799_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5800_AwakerVoiceContent = {
    Text = "걱정하지 마세요!"
  },
  Voice_5800_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5801_AwakerVoiceContent = {
    Text = "라몬나는 잃는 걸 싫어해…… 죄송해요, 제 말은, 저는 이별을 좋아하지 않아요. 이건 정말 슬퍼요."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "나는 성직자들과 잘 지내지 못해요. 그들은 무미건조하고 고지식하며, 허리띠를 자신들이 경외하는 「신」에게 맡겼죠. 정말 아쉽습니다, 살바도르 선생님은 분명히 매우 달콤한 향기를 풍기는데……"
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "잡담·살바도르에 대해"
  },
  Voice_5802_UnlockDesc = {
    Text = "깨어남체「살바도르」획득 후 개방"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "마음껏 싸울 수 있다면 만족한다. 설령 패배라고 해도 말이지."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "누가 부드러운 침대와 바람이 새지 않는 하수…… 그리고 방을 싫어할까요."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "……나를 기억하게 하지 마…… 엘워스에 갇혀 있던 날들……"
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "불타올라라!"
  },
  Voice_5806_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5807_AwakerVoiceContent = {
    Text = "불타올라라!"
  },
  Voice_5807_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5808_AwakerVoiceContent = {
    Text = "피비린내를 따라 왔는데... 신선한 혈액팩은 있어?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5809_AwakerVoiceContent = {
    Text = "음─ ...아그리파도 친구가 많이 있지만, 모두 무서워하는 거 같아. 혹시 아그리파는 친구의 밥을 뺏거나 하는 걸까?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "잡담·아그리파에 대해"
  },
  Voice_5809_UnlockDesc = {
    Text = "깨어남체「아그리파」획득 후 개방"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "제 삶에는 오직 춤뿐입니다. 다른 지식을 배우라고 해도 성장하기 어렵습니다. 하지만 모두가 착한 사람들이라, 허영이나 돈 때문에 저를 팔아넘기지 않을 거예요. 그걸 느낍니다."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "겁쟁이, 나와 비슷한 강력한 힘을 가지고 있으면서도 이렇게 스스로를 억누르다니, 이건 자발적으로 목줄을 차는 것과 무엇이 다른가!"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "잡담·릴리에 대해"
  },
  Voice_5811_UnlockDesc = {
    Text = "깨어남체「릴리」획득 후 개방"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "부족해... 힘을 더..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5813_AwakerVoiceContent = {Text = "물러나."},
  Voice_5813_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5814_AwakerVoiceContent = {
    Text = "걱정할 필요 없어."
  },
  Voice_5814_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5815_AwakerVoiceContent = {
    Text = "타피오카, 보울러 해트, 헌팅 캡, 베레모… 정말로, 당신네 상류 사회의 신사들이 탈두를 가리기 위해 최선을 다하는 모습이 웃깁니다."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "잡담·예절에 대해"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "저는 그 사람을 매우 동경합니다. 백합처럼 고결하고 우아한 항해의 신…… 그런 그녀조차도 자신의 운명을 통제할 수 없다고 결국 바다 속으로 가라앉았다는 말씀인가요? 이건 정말 상상하기 어렵습니다……"
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "잡담·셀레스트에 대해"
  },
  Voice_5816_UnlockDesc = {
    Text = "깨어남체「셀레스트」획득 후 개방"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "거인에게 이길 수 있는 놈따위, 이 세상에 없다고!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "거인에게 이길 수 있는 놈따위, 이 세상에 없다고!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "으으, 젠장...! 힘 같은 건, 나를 이 몸에 가둬둘 뿐인데...!"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5819_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "계속 밝은 곳에 있고 싶어... 그래, 극점! 이 별에서 극점만 남게 된다면!"
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5820_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "나, 난, 중요한 임무 같은 건 맡을 수 없고, 빛을 쫓는 것 밖에 할 수 없어. 그러니까 제발, 너는 계속 이대로 빛나줘..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5821_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "혹시 다시 의식을 옮길 수 있다면, 별이 되고 싶어..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5822_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "아무리 계산해봐도, 의식 전달을 위한 공식이 풀리지 않아..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5823_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "어서 오세요! 파티랍니다!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "어서 오세요! 파티랍니다!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "안녕, 오레타야~ 1, 2, 3... 와아, 새로운 아이가 늘었어~ 다들 오레타의 친구가 되고 싶은 거지? 엣? 반대? 오레타가 모두의 친구가 되는 거야? 후후, 그것도 재밌을 것 같네!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5827_AwakerVoiceContent = {
    Text = "너희들은 이 작은 장난감을 권총이라고 부르나? 그림자에 숨어 상대방을 기습하는 것밖에 못 하다니, 정말 약자의 무기구나."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "무의미해. 이런 것 따위 전혀 의미 없어."
  },
  Voice_5828_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5829_AwakerVoiceContent = {
    Text = "너는 아무것도 모르고 있어."
  },
  Voice_5829_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5830_AwakerVoiceContent = {
    Text = "내가 \"구세주\"의 조력자가 되기라도 바라는 거야? 그런 하찮은 꿈은 빨리 버리도록 해."
  },
  Voice_5830_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5831_AwakerVoiceContent = {
    Text = "죄송해요, 너 내 나사를 본 적 있어? 정말 이상해, 그 쥐 귀를 가진 애가 있으면 나는 내가 물건을 어디에 놓았는지 더 쉽게 잊어버리는 것 같아……"
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_5831_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "저와 주의 재회를 위해 협력해주신 것, 평생 잊지 않겠습니다..."
  },
  Voice_5832_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5833_AwakerVoiceContent = {
    Text = "선율을 그리듯 깎아주겠어!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "저의 소원, 인정해주시는 겁니까?"
  },
  Voice_5834_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5835_AwakerVoiceContent = {
    Text = "내 기대에 부응하는 지휘를 부탁해."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "강해진 건 이 몸인가, 아니면 나라는 의식인가. 흥미로운 주제네."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5836_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5837_AwakerVoiceContent = {Text = "물러서."},
  Voice_5837_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5838_AwakerVoiceContent = {Text = "비켜."},
  Voice_5838_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5839_AwakerVoiceContent = {
    Text = "살고자 하는 의욕이 혈관을 돌아다니고, 외치며, 지구상의 온갖 곳에 피를 남기고 싶다는 충동에 사로잡히지... 아아, 소란을 피워서 미안해. 나는 타이스. 나를 불러냈다는 건, 벌써 나와 섞일 준비가 되었다는 거지?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5840_AwakerVoiceContent = {
    Text = "검은 액체의 괴로움을, 아이기스가 대신 맡아줄 수 있다면 좋았을텐데... 아이기스는... 이 세상에 어울릴 수 없는 존재니까요..."
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "「취미는 리만 가설 풀기」? …그건 그 공작의 입버릇이지, 내가 아니야. 그런 것보다는 원자량의 기준치 연구가 훨씬 더 흥미로워."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "고향에서 쫓겨나 바다를 떠도는 경험은... 한 번으로 충분해."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "잘 보라고!"
  },
  Voice_5844_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5845_AwakerVoiceContent = {
    Text = "잘 보라고!"
  },
  Voice_5845_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5846_AwakerVoiceContent = {
    Text = "당신이 이 정의를 지킬 수 있다면, 나는 항상 칼날의 역할을 감당하겠습니다."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "여기에서 「화가」에 대한 전설이 흘러나오고 있다는 것을 아셨나요? 그 표현주의적인 그래피티 스타일에서 난 익숙한 냄새를 맡았어……"
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "아파서, 기분 좋아!"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "내 분노를 보시오!"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "이 승리를 시로 읊어보도록 하죠."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "커다래져라."
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5852_AwakerVoiceContent = {Text = "받아라!"},
  Voice_5852_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5853_AwakerVoiceContent = {Text = "에이!"},
  Voice_5853_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5854_AwakerVoiceContent = {
    Text = "아마 커서 나중에, 내가 자신을 제어할 수 있게 되면, 다른 사람의 생명력을 빼앗지 않을 수 있을 거야…… 조금만 있으면 생존할 만큼 충분할 거야."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5854_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "무거워진 것 같아요. 요람이 제 무게를 견딜 수 있을까요?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5855_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "힘이 곧 넘칠 것 같아. 등 뒤가 간지러운데 이제 커야 할 때인가 봐?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_5856_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "아이의 모습이지만, 지금의 나는…… 이미 너를 보호할 힘을 갖췄어."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5857_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "나는 열심히 자랄게요."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_5858_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "무지한 놈, 왜 나를 깨어남시키려고 하는 거야?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5860_AwakerVoiceContent = {
    Text = "나는 신의 어머니가 될 것이다!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "큭큭, 이걸로 몇 번째 소환이지...? 어이 인간, \"식사\" 준비는 되어있겠지? 배가 고픈 나는, 뭘 저지를지 알 수 없다고?"
  },
  Voice_5861_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5862_AwakerVoiceContent = {
    Text = "문 너머로!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5863_AwakerVoiceContent = {
    Text = "어리석다."
  },
  Voice_5863_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5864_AwakerVoiceContent = {Text = "하하"},
  Voice_5864_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5865_AwakerVoiceContent = {
    Text = "으으, 제법 하잖아. 다음에는 반드시 이겨주겠어."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "무례한 놈!"
  },
  Voice_5866_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_5867_AwakerVoiceContent = {
    Text = "파멸에도 아름다움이 있지만, 너에게는 어울리지 않네."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "당신은 저에게 가장 중요한 청중이십니다. 언제든지, 저는 당신을 위해 노래할 준비가 되어 있으며, 모든 것을 바칠 것입니다."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "좋아하는 것? 수초, 어군, 회랑의 기둥, 미로…… 물론 본 적이 있어요! 오언 삼촌의 그 책에 다 나와 있어요!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "조사 임무를 위한 준비입니까? 알겠습니다."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5870_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "내 이름은 셀레스트. 당신이 바라는 한, 계속 이곳에 있을게."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5872_AwakerVoiceContent = {
    Text = "이 역류를 맛보도록 해!"
  },
  Voice_5872_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5873_AwakerVoiceContent = {
    Text = "후배로서 존중을 보여라. 군대에서는 연장자와 후배의 순서가 엄격하며, 명령은 반드시 지켜져야 한다. 허용된 범위를 넘는 행동은 징계를 받게 된다."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "그 장난감을 수리해주길 바라는 거야? 별로 상관없지만, 나의 서비스를 받을 용기가, 너에겐 있을까?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "잡담·발명에 대해"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "당신은 이곳의 주인님이지만, 제 살롱의 손님입니다. 당신의 방문을 위해 최상의 대접을 준비했습니다——빨간색 언더스커트를 좋아하시나요, 아니면 하얀 장미색 파자마를 좋아하시나요?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "미안, 두더쥐같은 나에게 이곳의 햇빛은 너무 눈부셔서..."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "모든 것을 침식하고 소멸시키는…… 정말 대단한 무기였다. 당시의 내가 그 사실타래을 알았다면…… 후."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "소문에 따르면, 불꽃 속에서 경련하는 인체는 마치 춤추기와 같다고 한다."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "잡담·화염에 대해"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "밤에 나가는 건 그만두자. 2000 루멘의 광원을 갖고 나가도, 완벽하다고는 말할 수 없어... 어둠에 발을 디디면, 눈꺼풀 뒤에 숨어든 악마가 따라와서, 먹히고, 붙잡혀서, 집어삼켜져... 아무 것도 남지 않을 때까지."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "잡담·밤에 대해"
  },
  Voice_5881_AwakerVoiceContent = {Text = "울어봐."},
  Voice_5881_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5882_AwakerVoiceContent = {
    Text = "받았습니다."
  },
  Voice_5882_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5883_AwakerVoiceContent = {
    Text = "그것은 생명의 갈망으로, 먼 하늘로의 회귀를 위해 백조가 힘차게 분투한다."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5883_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "어느 쪽이 진짜일까?"
  },
  Voice_5884_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5885_AwakerVoiceContent = {Text = "도와줘!"},
  Voice_5885_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5886_AwakerVoiceContent = {Text = "끼약!"},
  Voice_5886_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_5887_AwakerVoiceContent = {Text = "으읏!"},
  Voice_5887_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5888_AwakerVoiceContent = {Text = "끼얏!"},
  Voice_5888_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5889_AwakerVoiceContent = {
    Text = "아, 브라운이 여기로... 아, 안 돼요. 아이기스는 젠킨에게 말을 걸지 않는 편이 나아요. 친구가 되고 싶었는데, 결국, 젠킨의 악몽이 되어버렸으니까... 아이기스를 보고 싶지 않을 거에요."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_5889_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "예배당? 매우 감사하지만, 사실타래 저는 그렇게 옛날식이 아닙니다. 마음속에 언제나 자비로운 신의 가르침을 간직하고 그분의 뜻을 실타래천한다면, 제 영혼은 그분의 영광에서 멀어지지 않을 것입니다."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "잡담·성당에 대해"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "오지에라고 합니다. 당신과 나눈 계약대로, 오늘부터 충실타래한 기사로써, 어떠한 적으로부터든지 당신을 지키겠습니다. 이 맹세, 평생 잊지 않을 겁니다."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5892_AwakerVoiceContent = {
    Text = "겹눈을 가진 그 깡마른 여자, 스파르타의 버러지들 같은 냄새가 나."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "잡담·아그리파에 대해"
  },
  Voice_5892_UnlockDesc = {
    Text = "깨어남체「아그리파」획득 후 개방"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "좋아하는 것? 물론 좋은 운. 매일 나갈 때마다 좋은 기운을 얻으려고 해요."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "여, 여기에 숨어있는 건, 한나 씨에겐 말하지 말아주세요... 아직, 마음의 준비가 되지 않았어요..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "잡담·한나에 대해"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "이걸로 어때?"
  },
  Voice_5895_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5896_AwakerVoiceContent = {
    Text = "당신은 저의 귀한 손님입니다. 알아야 해요, 저는 오직 당신만 신용 판매를 허용하고 있어요. 결국, 몇 년 동안 이렇게 완벽한 머리를 본 적이 없었어요……"
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5897_AwakerVoiceContent = {Text = "아파!"},
  Voice_5897_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5898_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_5898_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5899_AwakerVoiceContent = {Text = "아파!"},
  Voice_5899_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5900_AwakerVoiceContent = {
    Text = "좋아하는 것……왕은 그런 모습이 어울리지 않지만, 거슬리는 상소문과 기도에서 벗어나 부드러운 소파 위에 웅크려 있다면, 나는 당연히 편안함을 즐길 것이다."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "여회는 너희의 불경한 행위를 영면을 구하는 것으로 이해할 것이다."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "싫어?? 나는 도망칠 수 없는 운명과 필연적으로 일어날 비극을 싫어해."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5903_AwakerVoiceContent = {Text = "흥!"},
  Voice_5903_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5904_AwakerVoiceContent = {Text = "으..."},
  Voice_5904_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5905_AwakerVoiceContent = {
    Text = "오지 마!"
  },
  Voice_5905_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5906_AwakerVoiceContent = {
    Text = "오야, 내 비밀을 알아내고 싶나? 이 이름, 이 신체, 이 용모, 이 목소리는 모두 산페드로의 한 머리의 여주인으로부터 왔다. 그녀와 나는 거래를 했다……그녀가 죽은 후, 나는 그녀가 되었다. 그녀의 행방……그건 나의 가장 멋진 컬렉션이지?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5906_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "당신은 즐거운 손님입니다. 저도 당신의 독특한 머리에 매료되었네요…… 만약 양도할 생각이 있다면, 꼭 제 가게를 찾아주세요. ㅎㅎ…… 그냥 농담입니다."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5907_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "제 진짜 정체를 알고 싶으세요? 아직은 때가 이르죠. 당신은 이것만 믿으면 돼요: 길을 잃은 아이들은 모두 제 가게에서 집을 찾을 수 있어요. 당신도 포함해서요?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5908_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "아무도 상처받지 않는 세계가, 탄생한다."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "아직 끝나지 않았습니다!"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5911_AwakerVoiceContent = {
    Text = "당신이 그렇게 열심히 일하는 모습을 보니, 보수를 이렇게 빨리 받는 게 좀 부끄럽네요. 그래서, 당신의 머리는 당분간 원래 자리에 두겠습니다. \n하지만 잊지 마세요, 그것은 이미 제 소유물로 예약되었답니다?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5911_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "과거의 나는 이런 모습이 아니었다. 그녀가 나에게 신생을 주었다. 그렇게 말하면, 당신도 나에게 제2의 생명을 준 사람이다. 당신의 머리도 정성스럽게 간직하겠습니다."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5912_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "어둠에서 도망치겠어."
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "모험이 이렇게 위험한 거였다니..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "그 멍청한 여자애가 나를 보면 바로 도망치는 거야? 다음번엔 그녀의 헤어를 밟아서, 어디로 도망칠지 한번 보자."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "잡담·아이기스에 대해"
  },
  Voice_5915_UnlockDesc = {
    Text = "깨어남체「아이기스」획득 후 개방"
  },
  Voice_5916_AwakerVoiceContent = {Text = "으읏!"},
  Voice_5916_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5917_AwakerVoiceContent = {
    Text = "하하하하!"
  },
  Voice_5917_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5918_AwakerVoiceContent = {
    Text = "서로 죽여보자!"
  },
  Voice_5918_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5919_AwakerVoiceContent = {
    Text = "그 꼬마는 영성이 가득한 아이야. 길거리에서 살아남기 위해서는 이런 지혜가 필요해요. 만약 제가 아직 바깥에서 사건을 수사하고 있다면, 분명히 그녀와 좋은 관계를 맺었을 거예요."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_5919_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "그 성부가 모든 인간을 구할 수는 없어. 한 명이나 두 명, 운 좋게 구할 수 있을 지는 몰라도, 모든 사람을 늪에서 끌어올리는 건 불가능해... 신앙이 무너졌을 때 그가 어떻게 될지, 정말 기대되네."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "잡담·살바도르에 대해"
  },
  Voice_5920_UnlockDesc = {
    Text = "깨어남체「살바도르」획득 후 개방"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "당신은 렌티니언의 하수도에서 필요한 모든 것을 찾을 수 있습니다: 연어, 비누, 반쯤 마신 위스키……\n뭐, 제가 왜 이렇게 잘 아냐고요? 저는 오라버니의 시체를 끌고 그 안에서 2.5km나 기어갔어요……"
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "잡담·하수도에 대해"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "무릎 꿇어!"
  },
  Voice_5922_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5923_AwakerVoiceContent = {
    Text = "무릎을 꿇어."
  },
  Voice_5923_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5924_AwakerVoiceContent = {
    Text = "전장 밖의 진실타래의 세계를 목격한 후, 한 시절 ‘영웅’의 가치를 의심했지만, 다행히도 당신을 만났습니다. 정직하고 용감하며 흠 없는 당신을 존경합니다. 나는 당신의 휘하에서 세계의 평화와 안정을 위해 전력을 다해 싸우겠습니다. 이번에는 반드시 나의 속죄를 완성하겠습니다."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5924_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "야아! 아차……"
  },
  Voice_5925_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5926_AwakerVoiceContent = {
    Text = "이것이 나의 힘이야."
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "그 알고 있다는 듯한 표정이 싫어. 내가 미쳤다고, 불쌍하다고, 멋대로 생각하고 있겠지? 내가 보기에 너야말로 태양에 눈이 먼 이카루스처럼, 아주 불쌍해 보여."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "제가 선두에 서겠습니다!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "그 녀석들은 묘한 느낌이 난다. 이 별에 태어난 존재가 아닌 것 같구나."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "잡담·행성 밖의 존재에 대해"
  },
  Voice_5929_UnlockDesc = {
    Text = "깨어남체「윙클」,「틴커트」,「파인트」,「완다」중 하나 획득 후 개방"
  },
  Voice_5931_AwakerVoiceContent = {Text = "(음성)"},
  Voice_5931_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_5932_AwakerVoiceContent = {
    Text = "소멸해라!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_5933_AwakerVoiceContent = {Text = "안돼..."},
  Voice_5933_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5934_AwakerVoiceContent = {
    Text = "몬스터가 되어도 상관없다. \n 내가 원하는 것은 처음부터 끝까지 복수의 힘뿐이다."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5934_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "상대방을 제거하는 것 외에 당신이 원하는 것이 또 있나요? 대가로 나는 당신의 소원을 이룰 것입니다…물론 능력 범위 안에서."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_5935_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(음성)"},
  Voice_5936_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_5937_AwakerVoiceContent = {
    Text = "파트너요?……고려해 보겠습니다. 제가 명확히 결정하기 전까지는 쉽게 죽지 마십시오."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_5937_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "융식은 이미 수백만 명의 삶에 영향을 끼치고 있어. 온 인류의 존망이 우리 손에 달려 있어."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "전력 풀 가동!"
  },
  Voice_5939_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5940_AwakerVoiceContent = {
    Text = "바다의 광기를 조심해."
  },
  Voice_5940_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5941_AwakerVoiceContent = {
    Text = "바다의 광기를 조심해."
  },
  Voice_5941_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5942_AwakerVoiceContent = {Text = "헤이!"},
  Voice_5942_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5943_AwakerVoiceContent = {
    Text = "나는 그분의 왕녀이자 그분의 어머니다. 너는 그분 앞에서 중요하지 않은 개미새끼에 불과하다."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "전부 정리됐어. 자, 개선의 돛을 올리자."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "나에게 가까이 오지 마. 당신은 왕녀의 놀이감이 되고 싶은가, 아니면 신의 탄생의 희생물이 되고 싶은가?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5945_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "압도적인 승리를 보여주자고!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "압도적인 승리를 보여주자고!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "나는 당신이 윤리의 질서를 뒤집는 빛나는 순간을 증언하는 사람으로 되는 것을 허락합니다."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5946_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "공동인가? 공중에서 물건 가져오기에도 종종 이런 공동이 생겨요! 카시아가 만든 공동은 이차원으로 연결되는데, 융식의 것도 그럴까요?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "수호자, 나는 신의 어머니의 권능으로 깊은 바다의 왕좌 곁에 당신을 위한 자리를 마련할 것이다. 당신은 파괴 후 재생성의 시대를 증언하게 될 것이다. 감사하라, 이것이 신의 어머니의 약속이다."
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5948_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "네가 이렇게 공손한 태도를 보여주는 만큼, 내가 답변을 내려주마. 처음에는 물론 갈등도 있었다. 그러나 이제는 내가 깨달았다. 나의 사치스러운 삶이 모두 그분으로부터 비롯되었음을. 죽음은 끝이 아니며, 그분은 나를 다시 탄생시켜 이 비정상적인 순환을 통해 영원한 삶을 누리게 하신다……"
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5949_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "그 여자의 소원은 정말이지 꼴사나워. 소멸로부터 살아남을 수 있는 존재는 없어. 설령 그게 신이라 해도 말이야."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "잡담·타이스에 대해"
  },
  Voice_5950_UnlockDesc = {
    Text = "깨어남체「타이스」획득 후 개방"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "나는 통령이지만, 만능의 존재가 아니니 당연히 실타래수를 저지를 수 있다. 지금 그 여자가 모든 사람을 끌어들인 행동은 내 무심한 실타래수였다… 그래서, 나는 네가 나를 보필해야 한다. 언제든 나의 소환에 응할 수 있도록, 너는 내 침궁에 침상을 두는 것이 허용된다."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5951_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "너는 재앙에 직면하는 임무를 맡고 있는 거야, 네 나이에겐 정말 무거운 부담이겠구나…… 만약, 처음부터 자신의 미래를 바꿀 수 없다는 걸 알았다면, 그렇게 충실타래하게 임무를 수행했을까? 서두르지 말고, 내가 잠들 때 생각해보렴, 나는 너의 대답이 궁금해."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5952_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "여기를 깨어남시킨 후로는 이미 상당한 시간이 흘렀는데, 네가 나에게서 얻고 싶은 것이 하나도 없나? 신의 계시, 절대적으로 이루어질 예언, 심지어는 가라앉은 대륙의 보물——정말로 알고 싶지 않은 거야?\n흠……기묘한 놈."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5953_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "나는 결코 누구에게도 숭배를 요구한 적이 없다. 어리석은 자들의 자처하는 행동은 나로 하여금 더욱 피곤하게 만든다…… 물러가라, 휴식 시간이다."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5954_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "네게서는 나의 신하와 비슷한 품성을 전혀 찾아볼 수 없구나……그래, 어쩌면 그것이 좋은 일일지도. 그 여자만 생각해도 피곤해지는데."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5955_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "신, 모두에게 공평하다."
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "알아, 넌 특수한 관객이야. 널 파르르 하고 다른 차원으로 보낼 수는 없지, 안 그러면 큰 문제가 생길 거야. 응, 다른 사람에게 그런 적이 있어? 싫어, 묻지 말아요. 그건 제 비밀이에요!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "아이야, 당신은 이 모습에 관심이 있나요? 보면 잃는 것이 있으면 얻는 것도 있는 것 같아요. 이건 아마도 나 레이크의 좋은 운 중 하나일 거예요?"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "미사그는 나에게 가장 많은 기억을 남긴 장소이자, 나의…가장 따뜻한 집입니다."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "맡겨 줘!"
  },
  Voice_5960_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5961_AwakerVoiceContent = {Text = "허술해!"},
  Voice_5961_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5962_AwakerVoiceContent = {
    Text = "깊은 바다의 성가!"
  },
  Voice_5962_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5963_AwakerVoiceContent = {
    Text = "나에게 주어진 것——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "스킬·1·정해"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "여전히 나를 「라모나」라고 생각해준다면, 앞으로도 그 이름으로 불러줘."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5965_AwakerVoiceContent = {
    Text = "어떻게, 너도 내 분노를 이용하고 싶은 거야?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_5965_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "이치를 밝혀내리."
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "손에 넣은 음식은 바로 먹는다! 이게 길거리에서 살아남는 요령이야."
  },
  Voice_5967_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_5968_AwakerVoiceContent = {
    Text = "배부른 느낌이야."
  },
  Voice_5968_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_5969_AwakerVoiceContent = {
    Text = "음... 가려워. 브라운, 등 좀 긁어줘."
  },
  Voice_5969_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_5970_AwakerVoiceContent = {
    Text = "새 부품은 기체의 작동을 원활하게 합니다. 이것은 「좋아한다」라고 말할 수 없습니까? 죄송합니다, 질문의 의미를 이해할 수 없습니다. 기계 인형에 취향은 없습니다."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_5971_AwakerVoiceContent = {Text = "받아라!"},
  Voice_5971_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5972_AwakerVoiceContent = {Text = "받아라!"},
  Voice_5972_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5974_AwakerVoiceContent = {
    Text = "잘 생각해봐."
  },
  Voice_5974_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_5975_AwakerVoiceContent = {
    Text = "냉정하게."
  },
  Voice_5975_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_5976_AwakerVoiceContent = {
    Text = "벤코르 양과 저는 마찬가지로 이 행성에 고향이 없습니다… 틴커트를 제외하고, 제 고향에는 저를 잡아둘 만한 것이 아무것도 없습니다. 벤코르 양은 그녀의 고향에 대해 어떤 감정을 가지고 있을까요?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "잡담·윙클에 대해"
  },
  Voice_5976_UnlockDesc = {
    Text = "깨어남체「윙클」획득 후 개방"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "뒤에서 접근하지 마세요, 목이 부러지고 싶지 않다면."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_5977_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "히익! 어째서 길고양이가 돌아다니게 내버려두는 거야!? 사람을 할퀴면 어쩌려고!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "내 눈빛이 불편하게 느껴졌나? 그렇다면 그게 맞아. 바로 그 잔인함 덕분에 연옥에서 살아남을 수 있었다."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_5979_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "화려한 말은 그만두고, 당신이 나에게서 무엇을 얻고 싶은지 말해봐. 내 이성을 유지하기 위해 힘을 쏟는다면, 분명히 무언가를 수취하고 있겠지."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_5980_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "나의 복수 대상은 언제나 스파르타인이었지만, 이제 그 도시국가조차 존재하지 않아…… 그래도, 네 칼이 되는 것도 나쁘지 않겠어. 나는 겨우 너를 내 동료로 인정하지만, 배신하면 네 심장을 빼낼 거야."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_5981_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "나의 이 두 손은 피로 물들었다. 나의 연약한 동족들은 내 복수를 이해하지 못했고, 그들은 뒤에서 내 잔인함, 내 무지, 내 배은망덕을 수군거렸다… 복수는 언제나 단지 나 자신을 위한 것이었으며, 다른 누구와도 관련이 없었다."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_5982_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "더 많은 강철을 사용해야 합니다."
  },
  Voice_5983_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5984_AwakerVoiceContent = {
    Text = "더 많은 강철을 사용해야 합니다."
  },
  Voice_5984_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5985_AwakerVoiceContent = {Text = "죽어."},
  Voice_5985_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_5986_AwakerVoiceContent = {
    Text = "나는... 음, 윙클라고 불러줘. 다들 그렇게 부르니까. 응, 그거면 돼."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5987_AwakerVoiceContent = {
    Text = "이 몸을 방패로, 주군을 지킨다!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "이 몸을 방패로, 주군을 지킨다!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "\"호두까기 인형\"은 본래 여자아이의 로맨틱한 환상 동화였으나, 그 추악한 얼굴의 자들은 그 속에서만 우아하게 날아다니는 신체와 저급한 생리적 욕망을 보았을 뿐…… 역겹다."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "반드시 죽인다!"
  },
  Voice_5990_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_5991_AwakerVoiceContent = {
    Text = "판디아......그녀가 이것을 훈련이라고 부르다니? 하하......잠깐 웃고 가야겠어. 인간은 역시 너무 마음이 약해서, 무엇을 해도 마치 놀이처럼 보이네."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "잡담·판디아에 대해"
  },
  Voice_5991_UnlockDesc = {
    Text = "깨어남체「판디아」획득 후 개방"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "다가오지 마!"
  },
  Voice_5992_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5993_AwakerVoiceContent = {
    Text = "다시 소개해달라고? 어쩔 수 없네. 나는 젠킨, 여기는 브라운이야. (찍!) 절대 잊지 마! 우리 이름을 틀리면 이 등불로 잔뜩 두들겨 팰 거니까! (찍!?)"
  },
  Voice_5993_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_5994_AwakerVoiceContent = {
    Text = "돌아라, 돌아라!"
  },
  Voice_5994_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_5995_AwakerVoiceContent = {
    Text = "같이 춤추자!"
  },
  Voice_5995_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_5996_AwakerVoiceContent = {
    Text = "쇼의 시작이야! 모두, 박수~!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_5997_AwakerVoiceContent = {Text = "흥."},
  Voice_5997_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_5998_AwakerVoiceContent = {
    Text = "한 점의 돌, 두 개의 조각도, 그리고 태양을 향한 붓꽃 세 송이... 당신이 원하는 모든 것을 창조할 수 있습니다."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_5998_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_5999_AwakerVoiceContent = {Text = "크읏!"},
  Voice_5999_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6000_AwakerVoiceContent = {
    Text = "그 정도냐?"
  },
  Voice_6000_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6001_AwakerVoiceContent = {Text = "이쪽."},
  Voice_6001_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6002_AwakerVoiceContent = {
    Text = "이 무의미한 싸움……"
  },
  Voice_6002_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6003_AwakerVoiceContent = {Text = "(음성)"},
  Voice_6003_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6004_AwakerVoiceContent = {
    Text = "티베리우스가 죽은 후, 로마의 시민들은 마침내 오랜 소원을 이루었습니다——그를 티베르 강에 던져 물고기에 먹히게 한 것입니다. 물론, 그 대가로 칼리굴라에게 경기장에 던져져 제 오락거리가 되었습니다."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(음성)"},
  Voice_6005_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6006_AwakerVoiceContent = {
    Text = "나는 그 소녀가 나와 비슷한 힘을 가지고 있다는 것을 느낄 수 있다. 그녀는 아직 그 힘의 강함을 완전히 이해하지 못하고 있다. 당신 때문에 적절히 그녀를 훈련시켜 주겠습니다."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "잡담·릴리에 대해"
  },
  Voice_6006_UnlockDesc = {
    Text = "깨어남체「릴리」획득 후 개방"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "젠장, 아직도, 아직도 나를 바보 취급하는 거냐?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "존재의 증명."
  },
  Voice_6008_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6009_AwakerVoiceContent = {
    Text = "존재의 증명."
  },
  Voice_6009_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6010_AwakerVoiceContent = {
    Text = "나는 모든 것이 원인을 가지고 있다고 믿지만, ……그런 무의미한 폭력, 형제자매들이 서로 등을 돌리고 증오향하는 편견은 정말로 슬픔을 감출 수 없게 만듭니다. 만약 나를 불쾌하게 하는 것이 있다면, 아마도 이것이겠죠."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "이 힘은 쓰고 싶지 않았는데."
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "방심하지 마."
  },
  Voice_6012_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6013_AwakerVoiceContent = {Text = "흥."},
  Voice_6013_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6014_AwakerVoiceContent = {
    Text = "저, 저를 봐주세요!"
  },
  Voice_6014_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6015_AwakerVoiceContent = {
    Text = "이게... 저주받은 피..."
  },
  Voice_6015_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6016_AwakerVoiceContent = {
    Text = "카시아는 대단해! 깜짝하고 토끼를 꺼낼 수 있어!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "잡담·카시아에 대해"
  },
  Voice_6016_UnlockDesc = {
    Text = "깨어남체「카시아」획득 후 개방"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "스탠바이 OK!♪"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "융식… 부인할 수 없지만, 이 세상에는 권력으로도 조작할 수 없는 것이 확실타래하게 존재한다."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6019_AwakerVoiceContent = {Text = "아——."},
  Voice_6019_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "녹염 속에서 춤추게 해 줄게."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "신경쓰지 말도록. 흉터는 전사의 훈장이다."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "이 근육을 떨리게 하라...... 그것은 당신의 목을 베기 위해 항상 준비되어 있다......"
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "뭐야뭐야? 밥 먹을 시간? 아니면 놀 시간?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6024_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "오레타가 이렇게 강해지면, 친구들도 더 이상 사라지거나 하지 않을 거야!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6025_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "실타래비아 선생님이 말했어, 누가 뭘 줬다면 꼭 고맙다는 말을 하세요, 라고... 고마워고마워고마워!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6026_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "이번엔 오레타가 술래야! 숨어숨어! 5초만 기다려줄게! 5, 4......"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6027_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "숨바꼭질을 시작했더니 모두 없어져버렸어. 오레타, 꼭 모두 찾아낼 거니까!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6028_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "해저에서 유의 유골이 발견되었기 때문에 유가 물을 좋아한다고 생각하고, 유의 침전 밖에 온천을 만들고 싶다는 거야? \n하……그렇게 해라, 이런 사소한 일로 유를 괴롭히지 말아라."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "바다를 떠도는 작은 물방울이자, 주의 충실타래한 하인... 미리암입니다. 당신께 인사드립니다."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6031_AwakerVoiceContent = {
    Text = "내 차례네."
  },
  Voice_6031_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6032_AwakerVoiceContent = {Text = "이얏!"},
  Voice_6032_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6033_AwakerVoiceContent = {
    Text = "놀랐어. 네가 무심하게 던진 한 마디에, 몇 달째 지속되던 슬럼프가 사라졌어."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6033_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "연회에서 만난 귀족 숙녀들과 비교하면, 머피의 성격은 정말로 사랑스럽다."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_6034_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "심리 치유 대가? 그건 아이들이 지나치게 칭찬한 거야. 나는 그저 할 수 있는 대로 들어주고, 그들의 마음속 우울함을 풀어주는 것뿐이야—항상 그래왔듯이."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "날 얕보지 마!"
  },
  Voice_6036_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6037_AwakerVoiceContent = {
    Text = "날 얕보지 마!"
  },
  Voice_6037_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6038_AwakerVoiceContent = {
    Text = "목마르지? 감옥에서 깨끗한 물은 정말 드문 좋은 것이야."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6038_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "좋은 아이 착한 아이~ 반드시 끝까지 해내야 해요~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6039_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "당신은 이미 제 달콤한 트랩에 빠졌겠죠?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6040_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "노력해, 조금 더 노력해~ 곧 그 극락의 최고점에 도달할 거야~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6041_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "내가 미사그 대학에 입학한 건 열네살 때였어. 만약 그대로 졸업했다면, 지금쯤 나는 「교장 선생님」이라고 불렸을지도 모르겠네."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "그 작은 뇌는 방금 전에 있었던 일도 기억하기 어려운가 보네."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "당신이 내 소원이 무엇인지 물어보는 거예요? 항해와 안전한 여행을 기원하는 것이 안 될까요? \n다른 것은 생각해 본 적이 없어요……하지만 잘 생각해 보고 다시 말해줄게요."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6044_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "「우주의 비밀을 알고 싶다, 나를 지배하는 이 힘이 무엇인지 알아내고 싶다」였던가. 이 소설, 줄거리는 마음에 들지 않고, 유사과학적인 부분은 헛웃음이 나올 정도로 유치해. 하지만 이걸 읽었으니, 내 이야기를 조금은 이해하겠지... 응? 왜 아직도 읽지 않은 거야?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6045_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "미션과 운명은 비슷한 것입니다. 쉽게 내려놓을 수 없고, 내려놓을 필요도 없습니다."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6046_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "늘 바쁜 것 같다고? 맞아. 조수들도 이것저것 해주고 있지만, 나를 대신할 수 있는 사람은 없으니까. 도움이 되고 싶다면....그래, 내가 잘 살아있는지 가끔씩 확인해줄래?"
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6047_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "화났냐고? 틀렸어. 미소를 지을 때 얼굴 근육이 얼마나 필요한지 저번 수업 때 얘기했잖아? 뭐, 너라면 분명 기억이 안 나겠지만. 정답은 최소 17개야. 난 쓸데없는 짓은 하지 않는 주의야. 너에게 화낼 이유도 없고."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6048_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "라몬나 양은 내가 모든 사람에게 맞춰줄 필요가 없다고 말했어요. 당신이 이 말의 의미를 이해하겠어요?……내가 더 이상 보호해줄 필요가 없다는 건가요?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6049_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "심사 대기 중인 레포트 13건, 수리 대기 중인 통신기 6대, 은핵 정제 실타래험 관찰 5건... 나를 방해할 정도로 한가하다면, 그 허술한 대뇌피질이라도 늘려보는 게 어때?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6050_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "다음에야말로 조국이 저의 부름에 답해주기를."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "잠금 해제."
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "저는 정말 기쁩니다… 당신은 저를 이렇게 편애해 주시네요."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6054_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "다른 사람들은 당신의 편애 때문에 화를 낼 거예요."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6055_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "아마도 당신도 저를 원하시나요?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6056_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "겨우 끝났다, 이걸로 잠깐이나마 그 검고 미끈미끈한 것들과 작별이야..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "저를 위해 이렇게 많은 것을 해주셔서, 당신의 사랑이 이미 제 안에 하나가 되었습니다……"
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6058_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6059_AwakerVoiceContent = {Text = "헤이!"},
  Voice_6059_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6060_AwakerVoiceContent = {
    Text = "위험해요."
  },
  Voice_6060_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6061_AwakerVoiceContent = {
    Text = "이만큼 했으니 이제 성과를 즐길 차례야? 조금 더 가까이 와봐, 실타래망시키지 않을게~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6061_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "수, 수호자님의 마음은 알겠어요... 서툴지만, 전력을 다해 싸울게요!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6062_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "시, 시선이 부담스러워요... 아이기스가, 잘못한 게 있나요?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6063_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "수호자님의 기대를 저버릴까봐... 아이기스는 불안해요..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6064_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "그, 그렇게 바라보지 말아주세요... 저주가 두렵지 않으신가요?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6065_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "아, 아이기스의 눈을 보지 말아주세요... 수호자님을 다치게 할까봐, 무서워요... 아이기스는... 괴물이니까..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6066_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "야수의 후각 같은 건 그냥 운이에요. 잘못 보지 말아요?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6067_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "여기서 멈출 수는 없어..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "힘, 끊임없이!"
  },
  Voice_6069_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6070_AwakerVoiceContent = {
    Text = "힘이 넘친다!"
  },
  Voice_6070_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6071_AwakerVoiceContent = {
    Text = "당신은 바다를 좋아하나요? 나는 무론 어떤 경우에도 바다를 좋아합니다. 여전히 많은 해 전 그 날, 바다는 그렇게 부드럽게, 오래도록 갈망해온 죽음을 불행한 나에게 선물했습니다."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "이런 쾌감은 처음 느껴봐..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "이 암류는 적을 찢는다."
  },
  Voice_6074_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6075_AwakerVoiceContent = {
    Text = "이 암류는 적을 찢는다."
  },
  Voice_6075_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6076_AwakerVoiceContent = {
    Text = "저는 항상 한 사람을 기다려왔습니다. 진실타래한 사랑, 고통, 그리고 욕망을 가르쳐줄 수 있는 사람을요. 당신은 저를 만족시킬 수 있나요? 저를 어둠의 감옥에서 구원해 주실타래 수 있나요?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6076_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "당신은 진실타래을 알고 싶나요? 나는 감옥을 싫어하고, 어둠을 싫어해서 죽을 것 같아요. 주목받고 싶고, 불타오르고 싶어요…"
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6077_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "모든 사람들의 미래에, 영원한 행복을."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "나를 즐기고 싶으신가요? 그렇다면 저의 노예가 되어주세요. 제가 당신을 녹일 정도로 뜨겁게 만들어 드릴게요~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6079_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "오오, 짐에게 바치는 공물이구나."
  },
  Voice_6080_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6081_AwakerVoiceContent = {
    Text = "다 지겨워, 다 지겨워. 겁에 질린 거대한 죄수들에 비하면 이건 그냥 아이들 놀이야. 아니면 너라도 나랑 놀아줘~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6081_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "더 많은 노예가 갖고 싶어, 그들의 신음과 애원을 듣고 싶어—\n더 많은 노예를 가져다줘~ 부탁해~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6082_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "죄송합니다. 또 과거에 잠겨 있었습니다. 그렇게 슬픈 표정은 하지 말아주세요. 저기, 당신의 얘기를 들려주실타래 수 있을까요? 시를 쓰고 싶다는 충동을 느껴본 적은 있으신가요? 당신의 모험, 견문, 기쁨, 슬픔, 그것들이 시냇물이 되어, 마음에서부터 손가락으로 흐르고 있지 않으신가요?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6083_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "저는 본래 두루마리에 묻은 얼룩과 같아, 언젠가 사라졌어야 할 존재였습니다. 당신과의 연이 태어나, 지금 여기에 존재할 수 있다는 건, 분명 기적이나 마찬가지. 이 다시 없을 나날들을 양식으로, 시대를 뛰어넘은 시를 창작하고 싶습니다."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6084_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "시란, 누군가에게 읽히기 위해 만들어진다고 들은 적이 있습니다... 당신의 견해도, 들려주실타래 수 있을까요?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6085_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "이런 경험을 하신 적은 있나요? 타인의 죄를 용서한 것으로, 결국은 자신이 보다 상처받게 된다는 이야기. 사람에게 장미를 바치어도, 내 손에 향기는 간데없이, 가시자욱에 스며든 피 뿐."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6086_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6087_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6088_AwakerVoiceContent = {Text = "...!"},
  Voice_6088_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6089_AwakerVoiceContent = {Text = "아...!"},
  Voice_6089_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6090_AwakerVoiceContent = {
    Text = "틀렸어..."
  },
  Voice_6090_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6091_AwakerVoiceContent = {Text = "아앗...!"},
  Voice_6091_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6092_AwakerVoiceContent = {
    Text = "위대한 가호를, 이곳에."
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "위대한 가호를, 이곳에."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "융식 현상 때문에 몸이 두 구나 찌그러졌어. 모든 것이 소멸되기 전까지 밝혀내야 할 게 산더미야. 쉴 틈이 없어… 너도 좀 도와줘. 일단 간단한 실타래험 재료 준비부터 부탁할게. 설마 심부름 하나 못할 정도로 바보는 아니겠지."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6094_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "나는 단풍단백로의 스테인드글라스를 좋아합니다. 그것은 사람들의 얼굴에 다른 색깔을 더해줍니다: 절망의 보라색, 아첨의 파란색, 물론, 제가 가장 좋아하는 야심의 빨간색…"
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "이곳에서 종종 주님의 기운을 느낄 수 있지만, 아직 그분을 마주할 준비가 되지 않았는지도 모르겠어요……어찌 되었든, 머물 곳을 마련해 주셔서 감사합니다."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "배반은 사람을 몬스터로 만들며, 어느 쪽이든 마찬가지입니다. 그래서 나는 배반자를 증오합니다."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "하멜른입니다. 도움이 될 수 있다면, 무엇이든지."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_60986_AwakerVoiceContent = {
    Text = "예전에 저는 음악에 천부적인 재능을 가진 사람을 만난 적이 있습니다. 그가 쓴 협주곡과 교향곡은, 한 번 들으면 잊을 수 없는 것이었죠... 그는, 진정한 천재였습니다."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "잡담·친구에 대해"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "전략에 시간을 할애하는 건 좋아하지 않습니다. 음악에 비해 예술적인 가치가 떨어지니까요. 하지만, 나아가야 할 길에 문제가 있다면... 지고한 음악을 위해, 저는 모든 모략을 구사하겠습니다."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "잡담·전략에 대해"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "불쾌하군."
  },
  Voice_60988_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_60989_AwakerVoiceContent = {
    Text = "또입니까... 이 선율은 대체 뭡니까? 지난번에 들은 후로 머릿속에 계속 맴돌아서... 소리가 멈추질 않습니다."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_60989_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6098_AwakerVoiceContent = {Text = "크읏..."},
  Voice_6098_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_60990_AwakerVoiceContent = {
    Text = "기술적인 측면에서 보면, 계책을 짜는 것도 오케스트라를 지휘하는 것과 마찬가지입니다. 인간의 감정, 욕망... 그것들은 오선보 위의 음표처럼, 명확하고 순종적으로 제 박자에 맞춰 춤을 춥니다. 음악을 갈고닦는다는 건, 그 모든 것을 이해하는 것과 마찬가지입니다."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "잡담·공통성에 대해"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "조금만... 완성까지 아주 조금만 남았는데! 완성하지 못하면, 이 곡을 들려주지 못한다면...!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_60991_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_60992_AwakerVoiceContent = {Text = "윽..."},
  Voice_60992_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_60993_AwakerVoiceContent = {
    Text = "불쾌하군."
  },
  Voice_60993_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_60994_AwakerVoiceContent = {Text = "윽..."},
  Voice_60994_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_60995_AwakerVoiceContent = {
    Text = "음악은 언어를 초월하고, 문자를 초월하며, 모든 것을 초월합니다. 음악이 완벽하지 않다면, 저는 완벽이란 것을 모릅니다."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_60995_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "박자에 맞춰서."
  },
  Voice_60996_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_60997_AwakerVoiceContent = {
    Text = "완벽한 조율입니다."
  },
  Voice_60997_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_60998_AwakerVoiceContent = {
    Text = "리허설의 중요성을 이해하신 듯 하군요."
  },
  Voice_60998_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_60999_AwakerVoiceContent = {
    Text = "최고의 퍼포먼스를 선사하겠습니다."
  },
  Voice_60999_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6099_AwakerVoiceContent = {
    Text = "부러워하나? 이 단단한 비늘은 고귀한 혈통의 증명이다."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "사람들로부터 찬사를 받은 적도 있지만, 제게 있었던 것은 진정한 재능이 아닙니다. 단지 전임자를 잘 모방했을 뿐, 그게 전부입니다."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "잡담·작품에 대해"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "관악기와 현악기가... 얽히고, 더해지고, 다시 교차한다. 아아, 생각났습니다. 이 곡은 제가 요절한 천재, 추락한 신성을 위해 쓴 레퀴엠입니다."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_61001_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "음? 저에게 새로운 악장을 보여주고 싶으신 겁니까?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "이 곡으로 영혼을 애도합시다."
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "저 녹색 무용수는 궁중 무용단 수석에 걸맞는 우아한 몸놀림을 갖추고 있습니다. 기회가 된다면 함께 공연해보고 싶군요."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "잡담·리즈에 대해"
  },
  Voice_61004_UnlockDesc = {
    Text = "깨어남체「리즈」획득 후 개방"
  },
  Voice_61005_AwakerVoiceContent = {Text = "Arioso."},
  Voice_61005_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_61006_AwakerVoiceContent = {
    Text = "오케스트라에는 수석이 있지만, 수석만으로는 오케스트라를 이룰 수 없습니다. 따라서 저희 오케스트라에서는, 자만에 빠진 연주자를 필요로 하지 않습니다."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "어디선가 아름다운 선율이... 이 근처에 리허설 중인 오케스트라가 있습니까?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_61007_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_61008_AwakerVoiceContent = {Text = "Dal Segno."},
  Voice_61008_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_61009_AwakerVoiceContent = {Text = "Da Capo."},
  Voice_61009_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6100_AwakerVoiceContent = {Text = "죽어라!"},
  Voice_6100_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_61010_AwakerVoiceContent = {
    Text = "그래, 그래! 이것이야말로 최후의 미사! 음악 그 자체에게 바치는 레퀴엠!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_61010_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "아, 수호자. 마침 잘 오셨습니다. 이 악장의 해석에 대한 당신의 의견을 묻고 싶습니다."
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "현악기, 시작."
  },
  Voice_61012_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_61013_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_61014_AwakerVoiceContent = {
    Text = "복잡하게 뒤엉킨 영혼의 비통한 선율... 확신했습니다. 저는 이걸, 어디선가 들어본 적이 있다고."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_61014_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "이성과 질서라는 사다리를 올라, 저는 마침내 하늘의 문을 열었습니다. 하지만 그 문 너머에는 이성도 질서도 존재하지 않았죠. 맞습니다, 진정한 음악이란, 그것들을 초월한 끝에 있는 것입니다."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "잡담·이성에 대해"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "지휘에 주목해주시길. 1, 2, 3."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "당신들의 오케스트라는 엉망진창입니다. 어쩔 수 없군요, 제가 계획을 세워드리죠. 안심하세요, 은상절 전까지 반드시 완벽한 프로그램을 만들어 드리겠습니다."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "의식의 깊은 곳에서 태어난 곡... 이것을 처음 들은 날을, 지금도 잊을 수 없습니다. 현실타래 세계는 사라지고, 음표와 코드가 빚어낸 순수하고 숭고한 음악만이 저를 가득 채웠습니다."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "유감입니다. 리허설이 부족했던 듯 하군요."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6101_AwakerVoiceContent = {Text = "명령."},
  Voice_6101_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_61020_AwakerVoiceContent = {
    Text = "보통 이런 권유는 거의 하지 않습니다만, 당신도 시도해보지 않으시겠습니까? 지휘봉을 휘둘러, 악곡에 새로운 생명을 불어넣는 일 말입니다."
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_61020_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "저는 말보다 음악을 통해 마음을 전하고 싶습니다. 하지만, 당신과의 대화는…수없이 리허설을 거듭한 오케스트라와 같이, 매끄럽고 기분 좋게... 마음을 떨리게 합니다. 음악에 있어서도, 개인적으로도, 당신은 특별한 존재인 것 같습니다."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_61021_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "오케스트라에서는 각 악기마다 호흡을 맞추는 것이 중요합니다. 각각의 파트가 어떻게 들어가고 어떻게 빠지는지에 따라 곡의 인상이 크게 달라지죠. 깨어남체들의 전투가 콘서트라면, 당신의 지휘는 상당히 훌륭합니다."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_61022_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "당신도 이 곡을 좋아하십니까? 단 4소절만으로 모티브를 드러내, 관악기가 선율을 밀어 올려, 진정한 주제로 이끈다... 이 혁신적인 구성은 후에 많은 사람들에게 영향을 주어, 수많은 명곡을... 실타래례, 그만 흥분했습니다."
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_61023_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "완벽한 연주였습니다."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_61025_AwakerVoiceContent = {Text = "Forte."},
  Voice_61025_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_61026_AwakerVoiceContent = {Text = "Accent."},
  Voice_61026_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_61027_AwakerVoiceContent = {
    Text = "누구나 자신만의 선율을 가슴에 품고 있습니다. 그것들은 이성과 육체에 갇혀, 오직 광기 속에서만 완전히 피어날 수 있습니다."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "음악이야말로 진정한 칭송을 받을 가치가 있습니다."
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "음악이야말로 진정한 칭송을 받을 가치가 있습니다."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6102_AwakerVoiceContent = {Text = "가."},
  Voice_6102_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_61030_AwakerVoiceContent = {
    Text = "이것이 최후의 레퀴엠이 되리라!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "비명을 지르며 용서를 빌어!"
  },
  Voice_6103_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_61049_AwakerVoiceContent = {
    Text = "이것이 최후의 레퀴엠이 되리라!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(음성)"},
  Voice_6104_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6105_AwakerVoiceContent = {
    Text = "당신도 녹화염에 가라앉고 싶습니까?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "감히 정신을 빼앗기다니?"
  },
  Voice_6107_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6108_AwakerVoiceContent = {Text = "집중해!"},
  Voice_6108_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6109_AwakerVoiceContent = {
    Text = "대학에서 어떻게 이렇게 귀여운 아이가 있을 수 있을까~ 내가 그에게 \"노예가 되지 않을래?\"라고 말했더니, 얼굴이 붉어지면서 머뭇머뭇 \"나는 이미 수호자의 기사야\"라고 중얼거렸어……\n분명히 이건 전혀 충돌되지 않잖아~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "잡담·오지에에 대해"
  },
  Voice_6109_UnlockDesc = {
    Text = "깨어남체「오지에」획득 후 개방"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "왕녀에게 접근하지 마."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "스킬·1·노도"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "숙명을 수락하라."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "스킬·1·조수"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "조국으로의 문이 멀어져 간다... 안 돼... 나를 두고 가지 마..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "길을 비켜!"
  },
  Voice_6113_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6114_AwakerVoiceContent = {
    Text = "길을 비켜!"
  },
  Voice_6114_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6115_AwakerVoiceContent = {
    Text = "스스로의 행위에 대가를 치르는 건, 당연하잖아?"
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "죽고 싶어?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "내가 또 융식에 걸린 것 같아…… 내 마음이 융식당했어! 아스피린 몇 알과 채찍, 그리고 한 점의 통증만 있으면 치유될 거야……"
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "당신도 이 괴상한 문제를 해결할 방법이 없어? 그럼 융식을 쫓아다니는 건 정말로 목숨을 아끼지 않는 거야."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "나는 로마 최후의 전사, 유우하시다!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6120_AwakerVoiceContent = {Text = "으우우."},
  Voice_6120_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6121_AwakerVoiceContent = {
    Text = "나는 로마 최후의 전사, 유우하시다!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "융식…? 물론 알아, 주종 관계가 해제되는 거잖아, 이거 어려울 게 뭐 있어."
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "우매한 저입니다만, 조금은 신께 다가간 것 같습니다."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6123_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "음... 힘이 꽤 좋은걸."
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "여기 인테리어가 너무 촌스럽지 않나요? 귀신이 나올 것 같아서 섬뜩해요."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "여기에는 울창한 초목, 안락한 공기가 있으며 언니의 병도 치료할 수 있어서 우리 두 사람에게는 가장 아름답고 새로운 집이 될 것입니다."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "예상치 못하게 여기서 재회하게 되다니… 그 이후로 누나가 어떤 생활을 했는지 모릅니다. 어떻게 물어봐도 괜찮다고만 하네요… 죄송합니다, 저희 자매가 다시 만날 수 있게 해주셔서 감사드립니다."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "잡담·파인트에 대해"
  },
  Voice_6127_UnlockDesc = {
    Text = "깨어남체「파인트」획득 후 개방"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "국가 부흥의 밑거름이 되어주시죠."
  },
  Voice_6128_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6129_AwakerVoiceContent = {
    Text = "국가 부흥의 밑거름이 되어주시죠."
  },
  Voice_6129_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6130_AwakerVoiceContent = {
    Text = "진정해... 진정해..."
  },
  Voice_6130_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6131_AwakerVoiceContent = {
    Text = "제 몸에는 많은 「저」가 있어요, 즐거운, 슬픈, 분노하는… 그들은 스펀지 케이크를 좋아하고, 그들은 렌티니언의 비 오는 날을 싫어해요. 그들은 모두 「24」라고 불리고, 그들은 모두 당신을 존경합니다."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6131_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "나는 과거에 매일 밤까지 일했습니다. 직물 제작, 세탁, 청소, 보모, 심지어 청소부까지... 돈을 벌기 위해 뭐든지 했습니다. 그때는 살아가는 것이 전부였습니다. \n지금은 신선한 음식, 따뜻한 침대, 그리고 당신처럼 친절하신 분이 계셔서... 정말 상상도 못했습니다."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6132_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "무론, 우리는 스테이크와 침대를 함께 나눌 것이며, 절대로 귀하에게 불편을 끼치지 않을 것입니다."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6133_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "하하, 그 여자가 내가 나오는 게 무서워서 밤에 잠도 못 자. 편하게 해, 선물 때문에 널 죽이지 않을 거야. \n나는 누구? 물론 「24」지, 하하하하!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6134_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "지금 기분이 정말 좋아요. 뭐, 제가 이미 다른 무언가에 마음을 빼앗겼다고? 헛... 헛소리......어..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6135_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "신하로서 너는 꽤나 상식적이다. 다음 깊은 잠에 들기 전, 내가 겨우 자존심을 내려놓고 이 순간을 머물러 있겠다."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "음, 오늘의 바다는 따뜻해..."
  },
  Voice_6137_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6138_AwakerVoiceContent = {
    Text = "꿈속을 날아다니던 하얀 새가, 내려와 앉았네."
  },
  Voice_6138_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6139_AwakerVoiceContent = {
    Text = "당신의 바람대로, 내 존재가 더욱 확고해졌어."
  },
  Voice_6139_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6140_AwakerVoiceContent = {
    Text = "만족, 만족!"
  },
  Voice_6140_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6141_AwakerVoiceContent = {
    Text = "좋은 냄새!"
  },
  Voice_6141_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6142_AwakerVoiceContent = {
    Text = "내게 맡겨 줘!"
  },
  Voice_6142_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6143_AwakerVoiceContent = {
    Text = "이 일격으로 끝내겠어!"
  },
  Voice_6143_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6144_AwakerVoiceContent = {
    Text = "우리들의 연회에 어서 와!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "광기 폭발·광란"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "이 소녀의 몸에 흐르는 것은 의심할 여지 없이 나의 피…아니, 내 나이로는 아직 자손을 남길 만큼 충분하지 않다. 하지만 그녀의 힘은 분명히 나와 같은 근원이다."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "잡담·신의 혈맥에 대해"
  },
  Voice_6145_UnlockDesc = {
    Text = "깨어남체「아이기스」또는「머피」획득 후 개방"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "주인님의 은혜, 평생 잊지 않을 거에요!"
  },
  Voice_6146_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6147_AwakerVoiceContent = {
    Text = "냠냠... 달고 맛있어요!"
  },
  Voice_6147_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6148_AwakerVoiceContent = {
    Text = "카렌은 다이어트 중이라, 이렇게 많이 먹을 수 없어요~"
  },
  Voice_6148_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6149_AwakerVoiceContent = {
    Text = "흥, 내 상대가 되기에는 한참 모자라."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "예술의 해석을 듣고 싶어? 그런 건 철도 주식에 대해 묻는 것만큼 터무니없는 질문이야. 제발 불쌍한 예술가를 괴롭히지 마."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "아, 아이기스가... 뭔가 잘못했나요?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "당신의 기도, 확실타래히 들었어."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "당신의 기도, 확실타래히 들었어."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "흥, 불경한 자구나."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "아, 방금 지나간 분이 그분이었나요? 아니요, 괜찮습니다. 제가 지난번에 인사를 했을 때도 저를 알아보지 못했어요… 분명히 저는 감옥에서 그가 저를 데리고 가기를 계속 기다렸는데, 폭동이 일어날 때까지도 그는 오지 않았어요…"
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "잡담·N에 대해"
  },
  Voice_6155_UnlockDesc = {
    Text = "「조사 임무」제7장 완료 후 개방"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "인간의 부름에 응하고 계약을 맺은 것은 아직 이루지 못한 내 책무를 다하기 위해서다. 네 힘이 나와 견줄 정도로 강해진다면 그만큼 좋은 일이 없지."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "누나, 브라운, 빈민원의 겁쟁이, 그들이 친구라면 충분해. 음… 좋아, 너도 포함시켜줄게. 브라운, 수호자한테 사탕 하나 주세요. \n「지지?!」"
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6157_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "동부 빈민가는 아이들이 살아가기에 적합하지 않습니다. 교활한 노무책임자는 신문배달 소년의 월급을 깎아먹는 방법을 갖가지로 찾아내고, 우유배달 소년의 속도를 까다롭게 따지고... 흠을 잡습니다! 즉, 거리에서 살아남으려면 자신만 믿을 수 있으며, 누구도 믿을 수 없습니다."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6158_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "내 \"나쁜 습관\"을 한두 번에 고칠 수는 없어, 이해해 줄 수 있겠지? 다리 밑이나 우수구에서 자고, 쓰레기를 먹으며 살아가는 것도 이미 충분히 힘들어… 일어나자마자 이불을 정리하는 데 바로 익숙해지라는 건 무리야! 적어도 약 보름 정도는 적응 시간이 필요할 거야!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6159_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "공간에서 길을 잃은 기분은 정말 좋지 않아. 네가 나를 거기서 빼줘서 고마워. 무슨 일이든 직설적으로 말해도 돼. 하지만 내가 꼭 도와줄 수 있을지는 모르겠어. \n나이가 아직 어려서, 나 같은 아이를 곤란하게 하지는 않겠지~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6160_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "헤이, 서쪽 놈! 브라운을 봤어? 그 배가 고픈 놈이 또 뭐 맛있는 냄새를 맡고 달려갔겠지."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6161_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"강한 자들이 자신의 힘으로 다른 이들을 해치지 않아야 한다. 왜냐하면 너희들은 나의 피를 공유하고 있기 때문이다.\" — 나는 자비의 신의 가르침을 깊이 새기고 있으며, 이 힘을 주변 사람들을 지키는 데 사용할 것이다."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6162_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "우주의 시작점에서 무엇을 봤는지 알고 싶어? 알려줄게. 그곳에는 말이지... 아무 것도 없었어."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6163_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "더 밝아졌습니다."
  },
  Voice_6164_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6165_AwakerVoiceContent = {
    Text = "영원의 등불이여..."
  },
  Voice_6165_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6166_AwakerVoiceContent = {
    Text = "조국과의 연결이 한층 더 강해졌습니다."
  },
  Voice_6166_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6167_AwakerVoiceContent = {
    Text = "이 세상의 사람들을 고통으로부터 해방시킬 수 있다면, 저는 만족합니다."
  },
  Voice_6167_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6168_AwakerVoiceContent = {
    Text = "창백한 전령이여, 무엇이든 명령을. 당신의 불꽃으로 저를 인도해 주소서."
  },
  Voice_6168_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6169_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_6169_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6170_AwakerVoiceContent = {
    Text = "육체만이 아니라, 마음 또한 갈고닦아야 합니다."
  },
  Voice_6170_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6171_AwakerVoiceContent = {Text = "으우우."},
  Voice_6171_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6172_AwakerVoiceContent = {Text = "아파!"},
  Voice_6172_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6173_AwakerVoiceContent = {Text = "으우우."},
  Voice_6173_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6174_AwakerVoiceContent = {
    Text = "음, 네 체온은 산호에게 조금 높네. 그래도, 따뜻하고 열기가 느껴져서 좋아."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "아……무엇을 도와드릴까요? 가능하다면，뒷방으로 가서 이야기를 나누는 게 어떨까요……"
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "아직 피어나지도 않았는데 이미 시들었고, 마치 물에 잠긴 수련처럼… 그 차가운 거센 파도 속에서 약하게 평온을 갈망하며, 자신의 행복을 추구할 용기가 없었어… 그것이 바로 나, 수호자야."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6176_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "나는 과거에 이런 고민에 빠져본 적이 있습니다: 고통이 생명 자체보다 더 길다면? 그렇다면 고문받는 깨어남보다 평온한 영원한 잠이 더 행복할까요? 깨어남 이후에도 한동안 그 속에 빠져있었지만, 당신이 이 피난처를 가져다주실타래 때까지……"
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6177_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "요양원에 있을 때, 저는 친구를 사귀어 보려고 했지만, 모두가 저에게 다가오기를 꺼렸어요… 이 뼈를 갉아먹는 독 때문일까요? 그래도, 저에게 다가올 때 조심해 주세요."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6178_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "야간의 바람이 전하는 종소리는 사람을 평온하게 만듭니다. 돌 의자에 앉아 잠시 듣고 싶으신가요? 제가 사진으로 자리를 깔아드리겠습니다."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6179_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "해장례를 들어보신 적이 있나요? 제가 생전에 살던 작은 마을에는 주민들이 고인의 시신을 바다에 가라앉히는 풍습이 있었습니다. 그래서 바다는 모든 사람의 마지막 안식처였습니다. 그리고 저는 일찍이 바다의 품으로 돌아간 사람……"
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6180_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6181_AwakerVoiceContent = {Text = "흥!"},
  Voice_6181_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6182_AwakerVoiceContent = {Text = "아"},
  Voice_6182_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6183_AwakerVoiceContent = {Text = "야!"},
  Voice_6183_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6184_AwakerVoiceContent = {Text = "아"},
  Voice_6184_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6185_AwakerVoiceContent = {
    Text = "작전 일지가 저장되었습니다. 수고하셨습니다."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6186_AwakerVoiceContent = {Text = "(통음)"},
  Voice_6186_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6187_AwakerVoiceContent = {Text = "(통음)"},
  Voice_6187_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6188_AwakerVoiceContent = {Text = "(통음)"},
  Voice_6188_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6189_AwakerVoiceContent = {
    Text = "...계속할 수 있어."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6190_AwakerVoiceContent = {
    Text = "살롱을 방문한 손님께는, 최고의 대접을 해드리죠. ...하지만 입장료로, 상응하는 비밀을, 말해주셔야만 한답니다."
  },
  Voice_6190_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6191_AwakerVoiceContent = {
    Text = "새로운 것들을 좋아합니다. 천년의 여행에서 저는 많은 흥미로운 혁신과 발명을 보았습니다. 예를 들어, 시의 형식, 영화의 화면 등이 있습니다. 인간은 정말 재미있는 생명체네요."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "음, 릴리는 그 사람 알아. 엄마가 나가있을 때, 릴리랑 같이 지냈어."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "잡담·다포딜에 대해"
  },
  Voice_6192_UnlockDesc = {
    Text = "깨어남체 「다포딜」획득 후 개방"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "짐의 잠을 깨운 것은, 네놈인가?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6196_AwakerVoiceContent = {
    Text = "신성? 오직 어리석은 자만이 그런 허상에 목숨을 맡길 것이다. 신성에게 의존하기보다는 어떻게 강해질지 더 생각해 보세요."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "어떤 격투사의 주인도, 불과 저열한 벌레일 뿐이다."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "잡담·아그리파에 대해"
  },
  Voice_6197_UnlockDesc = {
    Text = "깨어남체「아그리파」획득 후 개방"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "이긴다면, 자손 번영의 재료를 받아갈게."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "좋아하는 친구들! 동료! 후후, 오레타랑 계속계속 사이좋게 놀아줘."
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "나는 지금, 흥분된 상태다. 죽고싶지 않다면, 나한테서 떨어지는게 좋을 거다."
  },
  Voice_6200_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6201_AwakerVoiceContent = {
    Text = "그 사람은... 그, 저런 태도로 나와도 정말 괜찮은 건가요? 사람을 때리면 안된다고, 사라 선생님이 말씀하셨는데..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_6201_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "승리의 영광을 당신께 바치겠습니다."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "더, 더는 못 먹겠어~"
  },
  Voice_6203_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6204_AwakerVoiceContent = {
    Text = "마음의 구멍이 채워지고 있어~♡"
  },
  Voice_6204_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6205_AwakerVoiceContent = {
    Text = "더 뜨거워졌어~"
  },
  Voice_6205_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6206_AwakerVoiceContent = {
    Text = "그 아이를 알아요. 그녀는 가끔 멀리서 공연을 지켜보곤 해요. 그녀가 오지 않는 게 좋아, 그렇지 않으면 작은 관객들은 \"심신이 지치게\" 될 거예요!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "잡담·파인트에 대해"
  },
  Voice_6206_UnlockDesc = {
    Text = "깨어남체「파인트」획득 후 개방"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "틴커트는 은혜를 잊지 않고 갚는 것이 중요하다고 했습니다. 그래서, 나의 힘닿는 곳이라면 무엇이든 도와드릴 것입니다……"
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "안녕하세요, 수호자 님. 도와드릴 일이 있을까요?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "언젠가는 선봉에 설 지도자로 전장에 복귀할 것이다."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6209_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "믿을 수 있어? 나는 부러진 다리뼈가 치유되고 있다고 느껴져."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6210_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "진심으로 당신의 신뢰에 감사드립니다. 이렇게까지 성장할 수 있게 도와주시다니, 정말 놀랍고 감사할 따름입니다. 당신도 정의를 추구하는 분이시라 믿습니다. 저는 여기서 군인으로서의 영광을 이어가겠습니다."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6211_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "여정을 시작하는 날이 다가오고, 가슴속에서 끓어오르는 열정이 느껴집니다."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6212_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "전사로서의 명예가 회복되고 있습니다."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6213_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6214_AwakerVoiceContent = {Text = "으우우."},
  Voice_6214_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6215_AwakerVoiceContent = {Text = "아팟!"},
  Voice_6215_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6216_AwakerVoiceContent = {Text = "으우우."},
  Voice_6216_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6217_AwakerVoiceContent = {Text = "치사해!"},
  Voice_6217_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6218_AwakerVoiceContent = {
    Text = "윽, 미안! 다음에는 잘 할게!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "내 이름을 부르는 소리를 들었다, 아그리파, 아그리파, 아그리파……"
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6219_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "나는 보았다… 그분이 우물 아래의 다크에서 기어올라오며, 수많은 눈이 육알에서 나타났다. 그것들은 나를 응시하며, 나를… 미로의 신이라고 불렀다."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6220_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "나는 결투를 관람하고 싶은 아주 강한 충동이 있다… 만약 장소가 미로라면 더욱 좋을 것이다."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6221_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "계약……그래, 너와 주종 계약을 맺어야겠다, 영원히 무효가 되지 않는 주종 계약……"
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6222_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "フン……나쁘지 않네. 더 많이 가져와. 이 거미 새끼들의 배를 채워야 해."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6223_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "어떤 더러움과 역겨움이냐! 아아——그만 말씀해 주세요! 제발! 그것을 보지 않게 해 주시고, 또 제 귀에 그 이야기를 꺼내지 말아 주세요…"
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "내 과거는 차분하게 진행되어, 적도 해역처럼 평온하여 특별히 언급할 것이 없습니다."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6225_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "응? 엄마, 안아줘... 음... 따뜻해..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "별먼지여……"
  },
  Voice_6227_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6228_AwakerVoiceContent = {
    Text = "어라, 길을 잃으셨나요?"
  },
  Voice_6228_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6229_AwakerVoiceContent = {
    Text = "소용 없습니다."
  },
  Voice_6229_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6230_AwakerVoiceContent = {
    Text = "매번 배신자들이 무릎을 꿇고 울며 용서를 빌던 모습을 떠올릴 때마다 나는 한결 편안함을 느끼고, 마음속의 불꽃도 약간 사그라지는 것 같다."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "선주가 저를 집에서 데려가 항해의 성녀라는 사명을 부여했다. 그때부터 제 생명의 의미는 더 이상 스스로 통제할 수 없게 되었다. 누군가 말하기로, 적어도 이 두 번째 깨어남체로서의 삶에서는 자신의 소원을 위해 살아야 한다고 했다… 나를 도와줄 수 있겠습니까? 나를 자기중심적으로 만들어 주고, 저의 소원을 찾아주세요."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6231_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "아그리파야. 네게 볼일은 없어. 하지만 내 검투사가 되고 싶은 거라면, 이야기는 달라지지."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6233_AwakerVoiceContent = {
    Text = "타비……우리가 상상한 것보다 훨씬 위험해. 내가 없을 때는 그녀를 매우 조심해야 해."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "잡담·타비에 대해"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "이 연역법으로... 세계를 해석하겠어!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "이 연역법으로... 세계를 해석하겠어!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "자유롭게 반짝이세요!"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "내 모든 것을 걸고."
  },
  Voice_6238_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6239_AwakerVoiceContent = {
    Text = "내 모든 것을 걸고."
  },
  Voice_6239_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6240_AwakerVoiceContent = {
    Text = "그대로 썩어 없어져."
  },
  Voice_6240_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6241_AwakerVoiceContent = {
    Text = "그대로 썩어 없어져."
  },
  Voice_6241_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6242_AwakerVoiceContent = {
    Text = "미소와 예의는 나와 다른 사람 사이에 거리를 유지하고 무미건조한 일상으로부터 멀어지게 도와주는 갑옷입니다. 제 진실타래한 모습......저는 당신께 보여드리는 것을 꺼리지 않아요."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6242_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "생각들이 하얀 석회질로 쌓이고, 아름다운 산호로 씻겨나갑니다. 그것들은 저와 하나가 되어, 제 맥박이 뛰고 있습니다...... 당신은 듣고 싶으신가요?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6243_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "영감은 바닷물에서 끊임없이 솟아오르는 거품처럼: 가볍게 닿으면 사라집니다. 당신도 그렇습니까?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6244_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "전쟁, 약식, 명리는 모두 인간의 욕망입니다. 겸손한 조각사는 인간이 추구하는 것들에 관심이 없으며, 그녀는 오직 아름다움의 노예가 되기를 원합니다."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6245_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "아름다운 인생은 열정에 있습니다. 때때로 자신에게 너무 엄격하지 않아도 됩니다."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6246_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "이 정도의 상처..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6249_AwakerVoiceContent = {Text = "으우우."},
  Voice_6249_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6250_AwakerVoiceContent = {Text = "젠장!"},
  Voice_6250_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6251_AwakerVoiceContent = {Text = "으우우."},
  Voice_6251_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6252_AwakerVoiceContent = {
    Text = "융식 현상은 다양한 이변과 재앙을 초래합니다. 아마도 저의 나라는 바로 이 재해 때문에 깊은 바다로 가라앉았던 것이지요…"
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6253_AwakerVoiceContent = {Text = "핫!"},
  Voice_6253_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6254_AwakerVoiceContent = {Text = "야~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "거인의 위엄!"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_6256_AwakerVoiceContent = {Text = "먹어라!"},
  Voice_6256_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6257_AwakerVoiceContent = {
    Text = "희생은 피할 수 없습니다."
  },
  Voice_6257_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6258_AwakerVoiceContent = {
    Text = "잘 싸웠다. 이 순간이야말로 전사의 명예지."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "너, 어째서 그 여자를 들여보낸거야?! 50걸음 이내 거리에 들어오지 못하게 해!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해"
  },
  Voice_6259_UnlockDesc = {
    Text = "깨어남체「미리암」획득 후 개방"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "왜 강해지고 싶은가? 내 부족에서는 약자는 옷을 벗기고, 머리카락을 밀어버리며, 당신이 상상할 수 있는 가장 더러운 모욕을 받게 된다—약자가 되는 대가는 모든 사람이 감당할 수 있는 것이 아니다."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6260_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "행운의 여신이여!"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "역시... 인간의 힘에는 한계가 있나 보네."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "굳었던 몸이 조금 풀린 것 같다."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6263_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "내 사랑을 더 깊게 만드는 것이 당신의 욕망인가요?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6264_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "원하는 대로 날뛰어 봐!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6266_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_6266_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6267_AwakerVoiceContent = {Text = "으우우."},
  Voice_6267_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6268_AwakerVoiceContent = {Text = "꺄아!"},
  Voice_6268_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6269_AwakerVoiceContent = {
    Text = "아아, 용서 못 해..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6270_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6271_AwakerVoiceContent = {
    Text = "대담하게!"
  },
  Voice_6271_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6272_AwakerVoiceContent = {
    Text = "비유——"
  },
  Voice_6272_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6273_AwakerVoiceContent = {
    Text = "이대로 계속 하면, 기말 시험에서 좋은 성적을 받을 수 있을 거야."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "빈민가에서 온 도둑이 있는 것 같네요. 게다가 토실타래토실타래한 쥐까지 데리고 있다던데... 후후, 주인님을 위해 더러운 것들을 치워보도록 하죠!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_6274_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "이봐요, 깊게 숨 쉬기—"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "재미있군. 너의 힘이 날이 갈 수록 성장하고 있어. 이대로 점점 강해진다면, 언젠가 그 녀석에게... 크흠... 내가 무슨 생각을... 너같은 약소한 생물에게 기대하다니."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6276_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "아무래도 말할 때가 온 것 같구나. 나는 별의 짐승, 로탄, 너에게 결투를 신청한다. 물론, 네 힘이 충분히 강해질 때까지는 내가 지켜주지. 인정한 상대를 죽게 놔두는 일을... 두 번이나 반복할 생각은 없다."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6277_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "흥... 라모나 녀석이, 왜 너를 파트너로 인정한 건지, 아직도 이해할 수가 없군. 확실타래히 너는 강하지만, 여전히 내 적수는 아니야."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6278_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "그래, 그렇게 경외하는 눈빛으로 나를 숭배해라. 이 별의 가장 오랜 유물인 내가, 약한 자들에게 숭배받는 것은 당연한 것이다. 별을 지켜 온 이 수천만년 동안, 내가 바란 단 한 가지는 오로지 싸우는 것 뿐. 불합리한 요구는 아니지 않느냐?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6279_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "흥, 꼬마들의 소꿉놀이에 어울려줄 시간은 없어. 혼자서 해."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6280_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "가호를 받지 못한 가엾은 영혼들에게, 마지막 안식을 내려줄게."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6282_AwakerVoiceContent = {Text = "경계."},
  Voice_6282_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6283_AwakerVoiceContent = {Text = "경보."},
  Voice_6283_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6284_AwakerVoiceContent = {
    Text = "머릿속에서 무언가가 비명을 지르고 있어."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6284_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "내 마음이 깊은 안개에 덮이고 있어..."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6285_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "비명소리가 더 커졌어. 안개도 더 짙어졌고."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6286_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "시곗바늘 소리가 나를 몰아붙이고 있어..."
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6287_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "종소리가 울릴 때, 나는 아직 여기 있을까요?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6288_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "...흥, 분수도 모르는 녀석. 이 나를 그렇게 간단히 묶어둘 수 있을 리가 없잖아?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6290_AwakerVoiceContent = {
    Text = "제발…… 당신들은 제 여동생 젠킨을 보셨나요? 그녀는 쥐를 데리고 다니는, 조금 사나운 여자아이예요. 저는 그것을 착각하지 않았어요."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_6290_UnlockDesc = {
    Text = "「조사 임무」제2장 완료 후 개방"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "지원해 주셔서 감사합니다."
  },
  Voice_6292_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6293_AwakerVoiceContent = {Text = "라저ー."},
  Voice_6293_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6294_AwakerVoiceContent = {
    Text = "부디 즐겨주시길."
  },
  Voice_6294_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6295_AwakerVoiceContent = {
    Text = "당신을 위해 노래하겠습니다."
  },
  Voice_6295_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6296_AwakerVoiceContent = {
    Text = "신입 수호자인가? 전력을 다해봐. 내 상대가 될 자격이 있는지 보자고."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6297_AwakerVoiceContent = {
    Text = "나는 평화주의자지만, 「그녀들」은 아닌 것 같아..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6298_AwakerVoiceContent = {
    Text = "발설치 마라."
  },
  Voice_6298_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6299_AwakerVoiceContent = {
    Text = "물러나세요!"
  },
  Voice_6299_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6300_AwakerVoiceContent = {
    Text = "이런 치욕을 겪게 되다니..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "준비는 됐으려나? 카시아의 마술쇼가 시작할거야! 집중해서 봐줘, 간다~! It's show time~!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6302_AwakerVoiceContent = {Text = "Tokuli-Li."},
  Voice_6302_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6303_AwakerVoiceContent = {Text = "하!"},
  Voice_6303_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6304_AwakerVoiceContent = {
    Text = "나는 실타래비아에게서 당신의 일정표를 받았는데, 이건 신입에게 너무 가혹합니다. 당신들이 올바른 일을 하고 있다는 것은 이해하지만, 신병에게 과중한 부담을 지우는 것은 팀에 불필요한 문제를 일으킬 수 있습니다. \n 당신이 신병이 아니라고 했나요? 아니, 나는 당신의 눈빛에서 많은 일을 아직 경험하지 못했다는 것을 알 수 있습니다."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6304_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "직무를 다하지 못한 제 모습이 싫습니다. 앗, 위로받고 싶은 건 아니에요! 과거의 실타래수가 있었기에 지금 주군께 도움이 되고 있다, 그렇게 생각하고 있으니까요."
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "저 남자랑은 말이 안 통해요. 인생에 그렇게 죄와 벌 따위가 많을 리가 없어요, 지금 당장 즐기는 게 더 중요하겠죠?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "잡담·살바도르에 대해"
  },
  Voice_6306_UnlockDesc = {
    Text = "깨어남체「살바도르」획득 후 개방"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "시간이 얼마 남지 않았어. 출격하자."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "쉽게 꺼지는 촛불, 검은 빵, 치마단의 실타래밥…… 특별한 이유는 없지만, 이런 것들이 싫은 건 당연하지 않은가?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "성녀인 이 몸 앞에, 무릎을 꿇어라!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "성녀인 이 몸 앞에, 무릎을 꿇어라!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "읊겠습니다."
  },
  Voice_6311_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6312_AwakerVoiceContent = {
    Text = "\"숙녀 옷장\",\"여공 가이드\"는 모두 멋진 독서물입니다… 사지 못하더라도 예쁜 드레스를 보는 것만으로도 좋습니다."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "정말 이상해, 다른 건 기억하기가 항상 어려운데, 너를 기억하는 데는 며칠밖에 안 걸렸어……뭐, 이미 세 달이 지났나? 정말 죄송해, 또 잊었네."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6314_AwakerVoiceContent = {Text = "들어줘."},
  Voice_6314_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6316_AwakerVoiceContent = {
    Text = "계속해서 몸놀림을 정돈해야겠어."
  },
  Voice_6316_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6317_AwakerVoiceContent = {
    Text = "푸에떼 턴은, 앞으로 20번 더 하면 되겠네."
  },
  Voice_6317_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6318_AwakerVoiceContent = {
    Text = "내 움직임, 정확했어?"
  },
  Voice_6318_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6319_AwakerVoiceContent = {Text = "앞으로!"},
  Voice_6319_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6320_AwakerVoiceContent = {
    Text = "브라운을 데리고, 튀자!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "짐 앞에 무릎 꿇어라!"
  },
  Voice_6321_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6322_AwakerVoiceContent = {
    Text = "짐 앞에 무릎 꿇어라!"
  },
  Voice_6322_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6323_AwakerVoiceContent = {
    Text = "인간이 욕망 앞에서 보이는 다양한 표정은 언제나 나를 놀라게 한다. 아쉽게도, 인간은 너무 약함이고 너무 작아서… 그 점만 생각하면 마치 마음속을 고양이가 긁는 것처럼 괴롭다."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "그녀의 기억에서 나는 「융식」에 대한 많은 과거를 보았지만, 당신에게 말하려고 할 때마다 내 의식이 중단됩니다. 아마도 이는 그녀가 일으킨 문제일 것입니다."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "이대로 소멸해도, 괜찮을 텐데..."
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "한 명의 합격된 하인은 약해 보이고, 머리가 비어 있어야 합니다—— 나는 순종적인 양을 좋아합니다."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "당신과 저의 만남은, 모두 신의 뜻입니다. 재앙을 쫓는 창백한 불꽃이여... 고통받는 사람들을 구하기 위해서라면, 저는 기꺼이 당신의 힘이 되겠습니다."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6328_AwakerVoiceContent = {
    Text = "피 한방울 남기지 않고 짜내주겠어!"
  },
  Voice_6328_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6329_AwakerVoiceContent = {
    Text = "시도해 본 적이 있나? 융해진흙을 직접 몸에 주입해 보는 거 말이야. 검은색 점액은 독사처럼 당신의 심장으로 올라가고, 그 다음...빵! 당신의 몸은 따뜻한 액체로 터져버릴 거야. 역겹지만, 매우 효과적이다."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "흥, 약자들이 모여 따뜻함을 느끼는 곳."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "일정 시간마다 그 모터사이클을 탄 소녀가 내 의족 관리를 도와줍니다. 하지만 최근 점검이 너무 자주 있는 것 같은데, 그렇지 않나요?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "잡담·노틸라에 대해"
  },
  Voice_6331_UnlockDesc = {
    Text = "깨어남체「노틸라」획득 후 개방"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "우리 사이의 관계? 물어볼 필요 있니? 정확히 네가 상상하는 그런 관계야?"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "자신 있는 장르는 아니지만, 꼭 원하신다면 어떻게든..."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "너의 눈 밑의 그림자가 또 진해졌어...... 그렇게 고생할 필요는 없는데. 너도 나처럼 여유를 즐길 줄 알아야 해."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6334_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "기다리거라, 짐의 허락도 없이 대체 무슨..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6335_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "좋다...... 원래 모습에 가까워지고 있다."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6336_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "이것은 「녹색 부패」와 맞설 수 있는 힘입니다... 당신은 건드리지 말아야 할 것을 건드렸어. 나는 다시는 당신을 떠나게 하지 않을 거야."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6337_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "쉿......새벽 강가의 아침 빛, 아마도 처음 보는 것이겠죠? 이것은 당신의 충성에 대한 보상입니다."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6338_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "이\"@1@2계시록\"을 주겠네. 영지를 시작하거나 빠르게 잠들 수 있게 도와줄 거야."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6339_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "속세는 너무나 소란스럽습니다. 학교 안에 조용한 장소가 있다면 좋겠습니다만... 아니요, 난방은 필요 없습니다. 수행을 쌓아야지만, 제 기도가 신들께 닿을 것이기에..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "이 몸에서 떨어지는 것이 왁스인지 꿀인지 당신이 한 번 맛봐서 알 수 있겠죠?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6341_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "처, 처음 뵙겠습니다. 아, 아이기스에요... 저, 저는 신경쓰지 말아주세요!"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6343_AwakerVoiceContent = {
    Text = "아직 내가 「라몬나」라면, 우리는 여전히 파트너겠지?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "다크서클이 심한 그 아가씨가, 「영원히 햇빛 아래에서 사는」 방법을 제게 물어본 적이 있어요……확실타래히, 두 세계를 오가며 이동하면 되긴 하죠. 그런데 그녀는 어떻게 해도 차원 터널에 발을 들이려 하지 않더라고요……정말 난감해요."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "잡담·윙클에 대해"
  },
  Voice_6344_UnlockDesc = {
    Text = "깨어남체「윙클」획득 후 개방"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "판디아의 낙원에 어서와! 채찍으로 맞을 준비는 됐어?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6346_AwakerVoiceContent = {
    Text = "신께서 당신을 인정하신 이상, 저는 당신을 적으로 보지 않습니다."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "무엇이 내게 있다고? 나를 억울하게 하지 마세요! 그녀의 낡은 나사들이 없어졌을 때 나는——브라운, 제발!……하하, 당신은 아무것도 보지 않은 걸로 하세요?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "잡담·노틸라에 대해"
  },
  Voice_6347_UnlockDesc = {
    Text = "깨어남체「노틸라」획득 후 개방"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "모험이란 건, 이야기에 쓰여있는 것처럼 재미있는 법이네! 그 이야기는... 무슨 제목이었더라?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...딸꾹. 아, 죄송해요, 너무 많이 빨아들였나봐요."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "인간의 몸에 들어오고 나서부터, 동료들로부터 소식이 전혀 들리지 않게 됐어. 혹시 모두 다 악마에게 잡혀버렸고, 내가 종족의 마지막 한 명일지도 모른다고 생각하면, 무서워서 견딜 수 없어... 도와줘 수호자, 네 곁에 있게 해줘, 날 어둠에 떨어뜨리지 말아줘..."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6350_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "별이 멸망한 뒤, 나는 내 몸을 버리고 인간의 육체로 의식을 옮겼어... 그랬는데도 검은 악마가 물고 늘어져서, 내 정신을 속박하고, 괴롭히고 있어! 녀석들은 나를, 세계 째로 새까만 수렁으로 끌어당기려 하고 있다고!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6351_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "부탁이야, 수호자... 위치 측정 시스템에서 떨어지지 않을 수만 있다면, 어둠 속에 들어가는 거랑, 그, 그 검은 녀석과 맞서는 것만 아니면... 뭐든지 할게! 위치 측정 시스템 근처에 있게 해 줘! 이제 곧 모성의 잔해가 발견될 거야! 앞으로 12억번만 계산하면!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6352_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "네 보급분으로 카페인 정제를 두 개만 신청해줄 수 있을까? ...나, 잘 수가 없거든. 어째서 잘 필요가 있어? 절대 안돼! 그게, 눈을 감으면 어둠이, 끝없는 어둠이..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6353_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "우왓! 다가오지 마! 머, 먼저 어둠의 하수인이 아닌 걸 증명해! 그래, 하수인들. 옷을 벗고, 그 검고 끈적끈적한 게 붙어있는지를 보여주면 악마인지 어떤지 아니까..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6354_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "묻지 말아줘, 아무 것도 묻지 마...! 내가 제일 싫어하면서 무서운 게 뭔지, 이미 알고 있으면서! 어둠이야, 끝 없는 어둠이라구!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "융식을 치료하는 방법? 그런 건 어디에도 존재하지 않아요. \n어떻게 감염되지 않았는지 묻는 거예요? ㅎㅎ……「보이지 않으면」 그만이에요?"
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "주인, 고마워."
  },
  Voice_6357_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6358_AwakerVoiceContent = {
    Text = "녀석들도 기뻐하고 있어."
  },
  Voice_6358_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6359_AwakerVoiceContent = {
    Text = "릴리, 더 크게 자랐어."
  },
  Voice_6359_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6360_AwakerVoiceContent = {
    Text = "눌러 뭉개면 돼?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "매일 잠만 자고, 내 기대를 저버린 그 게으름벵이는 왜 소환한 거냐! 얼굴만 봐도 구역질이 날 것 같구나."
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "잡담·툴루에 대해"
  },
  Voice_6361_UnlockDesc = {
    Text = "깨어남체「툴루」획득 후 개방"
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "역겹다！"
  },
  Voice_6362_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6363_AwakerVoiceContent = {Text = "짜증나!"},
  Voice_6363_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6364_AwakerVoiceContent = {
    Text = "같이 바다를 보러 가지 않으실타래래요? 페브르도 괜찮아요. 제가 안내를 해드릴게요.... 당신이 가고 싶은 곳이라면, 세상의 끝까지 함께할게요."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6364_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "바다에는 바다만의 언어가 있답니다. 저도 종종 연못의 물고기와 고향에 대한 이야기를 나누고 있어요. 만약 물고기들과 대화하고 싶으시다면, 제가 통역해드릴까요?"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6365_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "당신에게 구원받고, 너무 행복해서 두려워요... 말해주세요, 이건 꿈이 아니라고. 당신은 저를 두고 바다로 사라지거나 하진 않을 거라고, 그렇죠...?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6366_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "이게 「행복」이라는 것일까요? 저에게는 과분한 소원일 거라... 생각했는데..."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6367_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "몸이 따뜻해. 마치 상냥하게 바다에 감싸인 듯한... 신기한 느낌."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6368_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "그것이 그의 조각인가? 좋아 보인다, 왕의 위엄이 느껴진다."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "잡담·툴루에 대해"
  },
  Voice_6369_UnlockDesc = {
    Text = "깨어남체 「툴루」를 획득하면 해금됩니다"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "이, 이 이상은 안돼... 바, 발견되고 말거야!"
  },
  Voice_6370_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6371_AwakerVoiceContent = {
    Text = "이렇게 하면 의식을 계속 유지할 수 있을까?"
  },
  Voice_6371_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6372_AwakerVoiceContent = {
    Text = "위험해, 위험해, 위험해, 이러면 무조건 들킬 거야..."
  },
  Voice_6372_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6373_AwakerVoiceContent = {
    Text = "이겼다! 기뻐? 있잖아, 「기쁘다」는 건 어떤 느낌이야?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "좋아하는 것? 나는 틴커트의 요람곡을 좋아해…… 당, 당연히 당신이 부르는 것도 매우 아름답습니다!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "그는 유능한 전사이니, 저도 「동료」라고 인정하고 있습니다... 「동료」의 정의가 이상하다, 라니, 자세히 말씀해주실타래 수 있을까요."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "잡담·골리아에 대해"
  },
  Voice_6375_UnlockDesc = {
    Text = "깨어남체「골리아」획득 후 개방"
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "유성아……"
  },
  Voice_6378_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6379_AwakerVoiceContent = {Text = "아——"},
  Voice_6379_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6380_AwakerVoiceContent = {
    Text = "넘치는 힘이, 몸을 채워간다..."
  },
  Voice_6380_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6381_AwakerVoiceContent = {
    Text = "날아가렴!"
  },
  Voice_6381_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6382_AwakerVoiceContent = {
    Text = "좋군, 생각보다 유능하지 않나."
  },
  Voice_6382_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6383_AwakerVoiceContent = {
    Text = "스물,스물한,스물네……어라, 내가 몇까지 세고 있었지? 하나, 둘, 셋……"
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6383_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "나는 마침내 이전에 얼마나 많은 재료가 있었는지 알아냈습니다. 이렇게 하면 보수를 더 빨리 완료할 수 있겠네요—어? 이건 어디서 온 거야?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6384_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "최근 수리 효율이 높아진 것 같아. 네 덕분에 이렇게 빨리 모험을 갈 수 있을 거야."
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6385_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "나는 기억이 조금 날 것 같아…… 어제 네가 나한테 7스패너를 건네준 거 아니야?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6386_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "수리, 보완, 완성! 미지의 모험, 신비한 세계, 오다!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6387_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6389_AwakerVoiceContent = {
    Text = "자기 자신을 속이지 마세요. 정신적인 족쇄 역시 족쇄이며, 공정하다고 할 수 없습니다."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "이걸로 나도 깨어남체에 가까워졌을까? 수호자, 나를 제대로 지켜봐 줘."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6390_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "자, 가자! 세계를 구하러!"
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6391_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "상쾌한 기분이네. '종의 기원'을 한 번에 읽었을 때와 비슷한 느낌이야."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6392_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "강해졌으니, 이번 임무는 나 한 명에게 맡겨 보겠어?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6393_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "전투력은 괜찮지만, 기억력이나 사고력의 성장이 느려. 역시 모든 건 자신의 머리로 생각하라는 거겠지."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6394_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "나는 그들에게도 인생이 뒤집히고, 모든 것을 잃고, 수많은 사람들에게 밟히는 맛을 느끼게 할 것이다."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6395_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "나의 수치, 내가 잃은 모든 것…… 나는 그들에게 대가를 치르게 만들겠다, 그들 모두에게."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6396_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "얼마나 달콤한 증오인가, 원수의 피로 곁들인다면, 그것은 세상에서 가장 맛있는 요리가 될 것이다."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6397_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "앗! 뒤에서 오지 말아줘!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "뜨거운 불꽃이 내 가슴에서 타오르고…… 그렇다, 나는 결코 잊지 않았고, 잊을 수도 없다."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6399_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "시의 마음을, 풀어주리."
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6401_AwakerVoiceContent = {Text = "(경음)"},
  Voice_6401_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6402_AwakerVoiceContent = {Text = "(경음)"},
  Voice_6402_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6403_AwakerVoiceContent = {Text = "(경음)"},
  Voice_6403_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6404_AwakerVoiceContent = {Text = "(경음)"},
  Voice_6404_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6405_AwakerVoiceContent = {
    Text = "진짜 간지러워! 시녀가 깃털로 발바닥을 간지럽히는 것 같아, 너*소리 없음* 일부러 한 거 아니야."
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6405_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "좋은 꿈을."
  },
  Voice_6406_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6407_AwakerVoiceContent = {
    Text = "좋은 꿈을."
  },
  Voice_6407_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6408_AwakerVoiceContent = {
    Text = "평온을 주세요…!"
  },
  Voice_6408_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6409_AwakerVoiceContent = {
    Text = "우아하게 행동하세요."
  },
  Voice_6409_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6410_AwakerVoiceContent = {
    Text = "들리시나요?"
  },
  Voice_6410_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6411_AwakerVoiceContent = {
    Text = "들리시나요?"
  },
  Voice_6411_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6412_AwakerVoiceContent = {
    Text = "비가 왔다. 비는 모든 것을 씻어내는데, 상한 음식, 고집스러운 더러움, 그리고 나처럼…… 여분의……"
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "복수의 파도는 멈추지 않는다!"
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "피로 적셔라!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6415_AwakerVoiceContent = {Text = "야!"},
  Voice_6415_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6416_AwakerVoiceContent = {Text = "여기야!"},
  Voice_6416_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6417_AwakerVoiceContent = {
    Text = "나는 전혀 두려워하지 않아."
  },
  Voice_6417_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6418_AwakerVoiceContent = {Text = "조심!"},
  Voice_6418_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6419_AwakerVoiceContent = {
    Text = "고통도 겪지 않고, 슬픔에도 감염되지 않으며, 병마의 고통이나 검은 시련에도 침식당한 적 없는 세계——이것은 아마 영원히 이룰 수 없는 이상향일지라도, 나는 평생을 두고 이를 추구할 것이다."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "영원한 왕국의 아름다움에 복종하라!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "영원한 왕국의 아름다움에 복종하라!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "어라, 또 공양하러 온 거니? 착한 아이네."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6422_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6423_AwakerVoiceContent = {Text = "아파?"},
  Voice_6423_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6424_AwakerVoiceContent = {
    Text = "더 집중해서."
  },
  Voice_6424_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6425_AwakerVoiceContent = {
    Text = "천 년을 살아왔어도, 방심할 때는 있는 법이랍니다."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "그 날, 마치 흐드러지는 장미와도 같이, 질투의 불길이 퍼져나갔습니다... 붉게 타오르는 업화 속에서, 모든 시는 재가 되어, 흩어졌습니다..."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6426_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "새로운 마술을 배웠어!"
  },
  Voice_6427_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6428_AwakerVoiceContent = {Text = "조심해."},
  Voice_6428_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6429_AwakerVoiceContent = {
    Text = "마술 지팡이와 춤추고 싶어졌어!"
  },
  Voice_6429_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6430_AwakerVoiceContent = {
    Text = "음, 이 텅 빈 느낌, 익숙하네~"
  },
  Voice_6430_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6431_AwakerVoiceContent = {
    Text = "관절의 움직임이 부드러워졌어."
  },
  Voice_6431_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6432_AwakerVoiceContent = {
    Text = "그 불길한 어둠은 제 형체 없는 중검과 조금 비슷하네요. 하지만 걱정 마세요! 수호의 검이 주군을 다치게 할 일은 절대 없습니다!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6433_AwakerVoiceContent = {Text = "덤벼봐."},
  Voice_6433_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6434_AwakerVoiceContent = {
    Text = "그럭저럭이네."
  },
  Voice_6434_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6435_AwakerVoiceContent = {
    Text = "전력을 다할게."
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "오늘은 뭘 하고 놀 거야?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "지하실타래에는 물이 많고, 부드럽고 차가운 느낌이에요. 그래서 제 몸은 항상 수증기로 둘러싸여 있어요…… 마치 하늘과 땅 사이에서 제가 유일한 육체인 것 같아요. 가끔은 정말 물에 녹아들고 싶어요. \n하지만 그렇게 되면 저는 더 이상 존재하지 않게 되고, 당신을 만나지도 못할 거예요."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6437_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "비밀을 하나 알려드릴게요...... 사실타래 저는 피를 싫어합니다. 그 색깔도, 그 맛도 싫습니다. 하지만 저는 그것 없이는 살 수 없어요. \n...... 저는 피를 식도로 삼켰다가 다시 전부 토해냅니다...... 저는 저 자신을 혐오합니다."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6438_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "음! 당신의 피…… 메드의 향기가 납니다. 아마 이 비밀을 아는 사람은 나뿐일 거예요, 그렇죠?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6439_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "내 상상 속에서는 용감한 기사가 나를 어둠에서 끄집어내고 쇠사슬로 나를 묶습니다. 그는 나를 때리거나, 욕하거나, 나에게 무슨 일이든 할 수 있습니다—고통이 바로 내가 살아 있음을 증명합니다. \n당신은 제 기사가 되어주실타래 의향이 있으신가요?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6440_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "피가 강물처럼 흐른다. 나는 당신의 것입니다—이런 감각은 이제껏 이렇게 강렬했던 적이 없다."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6441_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "이것이 복수의 여신의 의지다!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "이것이 복수의 여신의 의지다!"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "안 돼요!"
  },
  Voice_6444_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6445_AwakerVoiceContent = {
    Text = "너무 더럽다! 진짜!"
  },
  Voice_6445_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6446_AwakerVoiceContent = {
    Text = "아이기스, 봤어요!"
  },
  Voice_6446_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6447_AwakerVoiceContent = {
    Text = "아이기스, 봤어요!"
  },
  Voice_6447_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6448_AwakerVoiceContent = {
    Text = "팁, 물론 팁이죠. 학교 식당의 멍청한 웨이터들을 봐요! 다용도 의자도 미리 준비하지 않으면서, 이렇게 되면 추가 보상을 바라는 건 꿈도 못 꾸겠죠!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6449_AwakerVoiceContent = {
    Text = "까만 거."
  },
  Voice_6449_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6450_AwakerVoiceContent = {
    Text = "나를 나가게 해줘!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "스킬·광란 1"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "이렇게 하지 마......"
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "스킬·우울 1"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "그렇게 겸손할 필요는 없습니다, 창백한 메신저님. 우리 사이에는 장벽이 없어야 합니다. 우리는 모두 신의 유물이며, 진흙과 시험으로 가득 찬 이 길을 함께 전진하고 있기 때문입니다."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6452_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "물론 그들을 두려워하지 않습니다. 녹아내림의 저주로 고생하는 가련한 생명체들, 그들에게는 오직 슬픔만 느낍니다. 그들의 고통을 대신 견디어 줄 수 없다는 것을 알고 있지만, 그들이 조금이라도 위안을 얻을 수 있도록 내가 할 수 있는 모든 것을 주고 싶습니다."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6453_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "나와 함께 기도할래, бледный огонь? 오늘 우리의 전투로 죽은 자들을 위해 기도하자. 그들이 녹아내림의 저주로 인해 광기에 빠졌더라도 여전히 자비로운 신의 유물이며, 너와 나의 형제자매들이다. 그들이 마땅히 누려야 할 평안을 누리길 바란다."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6454_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "붉은 불꽃이 나를 긴장시키더라도, 나는 당신을 위해 다시 한 번 불타는 나무 무대를 밟을 것입니다. 이에 대해 걱정하지 마세요, 나의 백염, 당신이 가져다 줄 행복 앞에서 나의 희생은 아무것도 아닙니다."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6455_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "후회? 아니, 물론 아닙니다. 제 죽음이 그들에게 고통을 덜어주고 더 많은 시간을 벌어주었습니다. 그것으로 충분합니다. 하지만…… 당신이 저에게 솔직하셨으니, 저도 당신에게 숨기지 않겠습니다: 그날의 화형은 제 마음에 상처를 남겼습니다."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6456_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "약속을 해줄 수 있을까? 음…… 우리 약속해, 어떤 일이 있어도 라몬나를 영원히 기억해줘, 어떠니?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6457_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "나는 이런 모습이 되기로 선택한 것을 후회하지 않습니다. 다시 한 번 기회가 주어진다면, 나는 똑같은 선택을 할 것입니다. 하지만, 수호자, 나는 무서워요… 「라몬나」가 이 세상에 어떤 흔적도 남기지 않을까 봐."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6458_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "걱정하지 마세요, 눈가리개는 제 시야를 방해하지 않습니다. 오히려 이렇게 하면 모든 것을 다 보지 않아도 됩니다."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6459_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "내 표정이 낯설게 보이나요? 분명히 조절하려고 주의했는데... 보니까 그녀의 존재가 점점 더 강해지고 있나 봐."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6460_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "해결해야 할 수수께끼와 구해야 할 사람이 너무 많습니다. 제가 얼마나 더 행동할 수 있을지 모르겠습니다. 모든 사람들을 보호할 수도 없네요…… 정말 난처합니다."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6461_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "아직도 나에게 더 베팅할 생각이야? 마음대로 살기도 쉽지 않네. 안심해, 문제를 해결하면서 최대한 편하게 처리할게."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6462_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "이 지경이 되었으니 진짜 실타래력을 발휘해야겠죠? 사건 현장은 어디인가요? 모든 운을 태우더라도 기한 내에 용의자를 반드시 잡아오겠습니다！"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6463_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "아이야, 너에게 이렇게 많은 도움을 받았으니, 몇 가지 비밀을 알려줘야겠어: 사실타래, 나는 아마 이 세상에서 가장 운이 없는 사람일 거야."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6464_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "너는 내 말을 마음에 두지 않는 것 같아… 그렇다 그렇게, 나는 여전히 너를 위해 적을 파괴할 거야. 어쨌든 이 발톱과 이빨도 우연히 얻은 것이니까, 그렇지?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6465_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "내 운은 반드시 동료에게 전달되지 않을 수도 있어. 너도 그 말 들어봤지? \"행운의 토끼 발은 토끼에게는 별로 도움이 되지 않아.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6466_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "네놈의 영혼에, 짐의 낙인을 남겨주도록 하마."
  },
  Voice_6467_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6468_AwakerVoiceContent = {
    Text = "얼마나 짐의 힘을 원하는 거냐?"
  },
  Voice_6468_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6469_AwakerVoiceContent = {
    Text = "나의 이 모습을 보지 마세요, 나도 한때는 숙녀였어요……나는 자수를 할 줄 알았고, 테니슨을 읽을 줄 알았어요……맞아요, 노래 부르기도 할 줄 알아요: 그녀는 쉬지 않는 강물처럼, 내 피 속에서 흐르고 있어요~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "픽맨과 함께 흥미로운 설치 미술을 작업하고 있어. 같이 예술의 탈구축과 추상, 표상주의에 대해 의논하면서... 어머, 오레타? 왜 쓰러져 있어?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "잡담·오레타에 대해"
  },
  Voice_6470_UnlockDesc = {
    Text = "깨어남체「오레타」획득 후 개방"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "웃어줬으면 해? 싱긋ー! 릴리, 웃고 있어?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "잡담·미소에 대해"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "정말 신선하네, 나는 평등한 우정을 얻게 되다니. \n하지만…… 널 지배할 권리를 조금 남겨두고 싶어, 우리 사이의 한 점 재미로 말이야. 오늘 밤 내 침실타래로 와봐, 인간들 사이의 감정에 대해 아직 배워야 할 것이 많거든……"
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6472_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "너가 가장 귀여운 부분을 알고 있나? 바로 나에게 「아니요」라고 말할 때야. 네 코가 찡그려져 눈썹이 살짝 올라가지… 맞아, 지금 그런 표정이야."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6473_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "나는 나의 하인들을 사랑합니다. 이 잘생긴 작은 녀석들이 융식에 놀라 떨면서 내 뒤에 숨은 모습이 정말 애틋하게 느껴집니다. 아름다운 이의 눈물은 언제나 사람을 매료시킵니다. 당신은 어떠세요? 당신도 융식을 두려워하나요?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6474_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "수호자, 당신이 싫어하는 놈이 있나요? 보답으로 내가 대신 훈련시킬 수 있습니다. 일주일도 안 돼 그놈은 마음을 씻고 당신의 발가락을 핥을 거예요."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6475_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "음…… 네가 어리석기는 하지만, 성가시게 하지는 않아. 내일부터 네가 나를 모시도록 해. \n네가 원하지 않아……? 이건 의견을 묻는 게 아니라 명령이야."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6476_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "오랜만에 이런 기분이네요. 저는 만전의 자세로 무대에 올라 여러분께 우주를 관통하는 음파를 선사하겠습니다."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6477_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "이런 것, 아무 의미도 없어."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6478_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "제가 승리의 꽃을 따 온다면, 사소한 보수를 주셨으면 합니다만..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6480_AwakerVoiceContent = {Text = "아"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "피격·우울 3"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "그 비행선은 협소하고 답답해 보였으며, 마치 우주에서 부유하는 금속 관처럼 느껴졌다. 나는 나의 길잡이 별을 기다리고 있었다. 당신이 나타날 때까지."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6481_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "이럴 수가?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "피격·광란 1"
  },
  Voice_6483_AwakerVoiceContent = {Text = "흐음..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "피격·우울 1"
  },
  Voice_6484_AwakerVoiceContent = {
    Text = "아파……"
  },
  Voice_6484_AwakerVoiceTitle = {
    Text = "피격·우울 2"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "뭉개버려라."
  },
  Voice_6485_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6486_AwakerVoiceContent = {
    Text = "뭉개버려라."
  },
  Voice_6486_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6487_AwakerVoiceContent = {
    Text = "지루하다."
  },
  Voice_6487_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6488_AwakerVoiceContent = {Text = "크앗...!"},
  Voice_6488_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6489_AwakerVoiceContent = {
    Text = "아직 버틸 수 있어."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6490_AwakerVoiceContent = {Text = "큿!"},
  Voice_6490_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6491_AwakerVoiceContent = {Text = "아앗!"},
  Voice_6491_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6492_AwakerVoiceContent = {
    Text = "무례한 자들이여, 작염의 정적 속으로 사라져라."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "조심해요, 다른 차원의 공간에 손을 넣으면 다시 빼낼 수 없어요!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "쓸모없는 것들, 다진 고기 통조림이 되고 싶은 거야?"
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "어라, 나한테 애교를 부리는 거야? \n정말 곤란하네, 이렇게 계속되면 나는 수호자가 완전히 성숙해질 때까지 기다릴 수 없겠어……"
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "자유 의지 속으로!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "싫어하는 것 말이냐... 역시, 어중간하게 포기하는 녀석이지. 그런 놈이 눈앞에 보인다면 때려죽여버릴지도 몰라."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "끝없는 목이여, 그 모습을 드러내라!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "끝없는 목이여, 그 모습을 드러내라!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6500_AwakerVoiceContent = {Text = "해!"},
  Voice_6500_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6501_AwakerVoiceContent = {Text = "해!"},
  Voice_6501_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6502_AwakerVoiceContent = {
    Text = "그렇게 나를 신뢰하나?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6502_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6503_AwakerVoiceContent = {Text = "돌아와."},
  Voice_6503_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6504_AwakerVoiceContent = {Text = "자!"},
  Voice_6504_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6505_AwakerVoiceContent = {
    Text = "물론 알지, 그건 나의 다른 면이니까. 하지만 그녀가 왜 저항하는 거지? 선택받은 자가 되는 운명을 받아들이고. 원하는 것을 쉽게 얻을 수 있는데?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_6505_UnlockDesc = {
    Text = "깨어남체 「머피」 획득 후 개방"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "반가워요, 다포딜이라고 합니다. 어떤 손님과의 거래로, 당신께 협력하게 되었어요. 제가 뭘 하면 될지, 말씀해주시겠어요? 어머나... 그 주문은 조금 비싸답니다?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*소리 없이* 뭐 하는 거야! 네 손을 자르겠다고!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6508_AwakerVoiceContent = {
    Text = "목이 잘리는 기분을 맛봐라!"
  },
  Voice_6508_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6509_AwakerVoiceContent = {
    Text = "하하하하!"
  },
  Voice_6509_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6510_AwakerVoiceContent = {
    Text = "장미의 가시에, 맺혀진 피는 시와도 같네."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "장미의 가시에, 맺혀진 피는 시와도 같네."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6512_AwakerVoiceContent = {Text = "보여라!"},
  Voice_6512_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6513_AwakerVoiceContent = {Text = "음…!"},
  Voice_6513_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6514_AwakerVoiceContent = {
    Text = "재앙 강림!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6515_AwakerVoiceContent = {Text = "주세요."},
  Voice_6515_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6516_AwakerVoiceContent = {
    Text = "...음, 이름은... 생각나지 않아. 아, 그래! 내 이름은 「24」, 그 사람들은 날 그렇게 불러... 안돼! 나오지 마! 지금은 안돼...!"
  },
  Voice_6516_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6517_AwakerVoiceContent = {
    Text = "보입니다..."
  },
  Voice_6517_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6518_AwakerVoiceContent = {
    Text = "등장……"
  },
  Voice_6518_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6519_AwakerVoiceContent = {
    Text = "저는 천상의 목소리라는 칭호를 감당할 수 없습니다…당신이 제 노래를 좋아해 주시기만 하면 됩니다."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "잡담·노래에 대해"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "옷이 더러워졌네요, 다음 살롱이 시작되기 전까지 갈아입어야겠어요..."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "따라잡힐 거야, 누구도 피할 수 없는, 영원한 어둠에..."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "매번 당신을 보면 당신이 나에게 가한 무형의 족쇄가 생각납니다. 당신이 살아있는 것만으로도 이미 제가 최대로 참는 것입니다."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "몇 번을 반복하더라도, 저는 당신을 지지하고, 함께 나아갈 것입니다."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "신의 은혜가, 당신의 영혼에 따스함을 건네줄 수 있기를."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "목적지 없는 여행을 좋아해. 늪, 묘지, 병동, 폐허가 된 성... 그런 곳에 가면, 항상 예상치 못한 수확을 얻을 수 있거든."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "영원의 나라로 통하는 문은, 이곳에 있습니다."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "아하하, 간지러워! 간지럽다니까~! 하아하아, 그렇다면~ 되돌려 줄거야~!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"백조의 죽음\", 무용수가 몸짓으로 생명의 갈망과 투쟁을 해석하는 작품입니다. 그 불길 속에서 왜곡된 자세도 그렇지 않을까요."
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "썰고, 썰고, 썰어 다지는 거야!! 그 사람들이 나에게 했던 것처럼... 흐흐... 흐흐흐..."
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "타이스와는 거리를 두는 게 좋아. 딱히 질투하는 건... 어디 사는 바보씨가, 그녀의 달콤한 함정에 걸리지는 않을까, 조금 걱정되는 것 뿐이야."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "잡담·타이스에 대해"
  },
  Voice_6530_UnlockDesc = {
    Text = "깨어남체「타이스」획득 후 개방"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "아... 고마워."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6531_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "너, 인재를 보는 눈이 있네."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6532_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "카렌의 고향은, 호수 가운데에 있는 돌로 된 마을이에요. 정말 아름다운 곳이에요!\n 부푼 상현달이 뜰 때마다, 모두들 화염 속에서 조용히 춤추고, 제사를 지냈어요...\n사실타래 카렌이 처음 대학에 왔을 때는, 매일 밤 고향이 그리워져서 항상 울었어요. 하지만 지금은 새로운 집에서 새로운 가족들이 생겼으니, 정말 행복해요!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6533_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "야~ 아직도 만족하지 않니? 와봐, 시간을 아끼면서 너를 조련해 볼게요~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "근육이 약하고, 얼굴이 초췌하지만, 이 죽은 사람 같은 눈만이 조금 가치가 있다. 빼내서 거미에게 주면 딱 좋을 것이다."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "더 강해지도록 도와주셔서 감사해요! 아, 아이기스도 수호자님의 기대에 부응하도록 노력할게요!"
  },
  Voice_6536_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6537_AwakerVoiceContent = {Text = "아앗!"},
  Voice_6537_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6538_AwakerVoiceContent = {Text = "싫어!"},
  Voice_6538_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6539_AwakerVoiceContent = {Text = "그만해!"},
  Voice_6539_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6540_AwakerVoiceContent = {Text = "꺄악!"},
  Voice_6540_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6541_AwakerVoiceContent = {
    Text = "라모나 양의 검술은 제 방식과 많이 다릅니다. 만약 주군께서, 제게 실타래력을 갈고닦을 기회를 주신다면... 무, 물론 제 실타래력을 기르기 위해서 말입니다!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6541_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "왜 다른 아이들과 같이 놀지 않느냐고요...? 말하기 조금 어렵습니다만... 전생에는 놀 기회가 거의 없었고, 친구라 부를 만한 사람도, 전에 모셨던 공주님... 앗! 주군 앞에서 다른 주인을 언급하다니, 죄송합니다! 무례를 용서해주세요!"
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6542_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "대학으로부터 승인된 수호자에게는, 상응하는 권한을 개방하고 있습니다."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "제가 배운 \"기사의 일곱 가지 미덕\"에 관심이 있으십니까? 정말 기쁩니다! 아, 크흠... 실타래례했습니다. 음, 주군께서 괜찮으시다면, 기꺼이 상대해드리겠습니다!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6544_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "사실타래, 저는 기사라고 말할 자격이 없습니다. 끔찍한 역병으로부터도, 침입자로부터도 전의 주인을 지켜내지 못했습니다. 이렇게 보잘것없는 저를 신뢰해 주셔서....정말 영광입니다. 이번에야말로 기사의 이름에 부끄럽지 않도록, 이 목숨을 걸고 당신을 지키겠습니다."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6545_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "상처를 주지 마세요."
  },
  Voice_6546_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6547_AwakerVoiceContent = {Text = "별로요~"},
  Voice_6547_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6548_AwakerVoiceContent = {
    Text = "승리로 향하는 길을 연다!"
  },
  Voice_6548_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6549_AwakerVoiceContent = {
    Text = "살해하지 마십시오."
  },
  Voice_6549_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6550_AwakerVoiceContent = {Text = "좋아~!"},
  Voice_6550_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6551_AwakerVoiceContent = {
    Text = "지금의 우리는 서로를 이해하지 못해. 물과 기름 같은 관계야."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "딱히 좋아하는 건 없어. 굳이 말하자면, 외부 임무를 좋아해."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "왜, 왜 나를 여기에 가두었나? ㅎㅎ…… 네가 이길 수 없어, 이 구속, 이 감옥을…… 모두 조각으로 만들어 버리겠다!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "모두를 지킬 거야."
  },
  Voice_6554_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6555_AwakerVoiceContent = {
    Text = "너희들, 매번 마법 공연을 보러 오는데, 질리지 않니? 얌전히 앉아 있어! 또 무대 위로 올라가면, 너희들을 다차원 공간에 던져버릴 거야!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "잡담·아이들에 대해"
  },
  Voice_6555_UnlockDesc = {
    Text = "깨어남체「아이기스」,「젠킨」,「릴리」,「머피」,「카렌」,「오지에」 중 하나 획득 후 개방"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "선물은 감사히 받을게요."
  },
  Voice_6556_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6557_AwakerVoiceContent = {
    Text = "주신 것에 대한 답례로는, 무엇을 원하시나요?"
  },
  Voice_6557_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6558_AwakerVoiceContent = {
    Text = "이 얼마나 아름다운지..."
  },
  Voice_6558_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6559_AwakerVoiceContent = {
    Text = "강력한 전류 감지, 곧 유지 보수를 진행합니다... 정상, 왜 과열이 없습니까?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6559_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "지난 계령 의식 후부터, 휴면 상태 중에 단편적인 영상을 보았습니다. 그 속에서 에리카는 당신처럼 피와 살이 있는 몸을 가졌고 눈물을 흘리고 있었습니다…이것은 꿈일까요?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6560_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "의식이 끝날 때마다, 가슴 부근에 고열이 감지됩니다. 해당 부위에는 에너지 관련 부품이 없는데, 왜 그런지 이유를 아십니까?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6561_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "찾았습니다. 모든 것은 <Del:영원히 흐르는 전류에 타죽어죽어죽어>—죄, 죄송합니다. 모듈의 일부— 경고, 경고, 에리카 이외의 의식 활동이 강해지고 있습니다. 삭제삭제삭제삭제... 안녕하세요, 무엇을 도와드릴까요?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6562_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "분석 결과, 휴면 상태의 에리카가 본 것은 원래 의미에서의 꿈이 아니라 에리카의—<Del: 비참한 살덩이 육체는 망해라>—기억이었다는 결론에 도달했습니다. 과부하와 같은 작열감은 아마도 '억울함'이라 불리는 감정으로 생각됩니다."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6563_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "쇼를 보고 싶은 사람은 객석으로 모여~"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6564_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "증오의 불꽃은 끊임없이 타오른다."
  },
  Voice_6565_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6567_AwakerVoiceContent = {
    Text = "나와 융합한 의지는 시끄러운 녀석이었어. 강해지면 강해질 수록, 목소리가 선명하게 들려... 정말이지, 하이드 공원의 거위들만큼이나 시끄러웠어."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6567_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "이 힘으로 배신자를 단죄해주겠어."
  },
  Voice_6568_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6569_AwakerVoiceContent = {
    Text = "아아... 고마워."
  },
  Voice_6569_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6570_AwakerVoiceContent = {
    Text = "수호자라니, 바보같은 농담이네. 슬슬 그 말도 안 되는 꿈에서 깨는 게 어때?"
  },
  Voice_6570_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6571_AwakerVoiceContent = {
    Text = "복수의 피가 끓어오른다..."
  },
  Voice_6571_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6572_AwakerVoiceContent = {
    Text = "일할 시간이다!"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "빠지면 안돼!"
  },
  Voice_6573_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6574_AwakerVoiceContent = {
    Text = "シュシュ!"
  },
  Voice_6574_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6575_AwakerVoiceContent = {
    Text = "식당 후문의 쥐덫을 버렸어요. 너무 위험해서 브라운이 그걸 밟으면 어떻게 하나요!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "이 느낌이 정말 이상해...... 내가 죽어가고 있는 걸까? 아니요, 구해주세요! 하지 말아요!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6576_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "꺼지지 않는 빛을 원한다고 했더니, 「날개가 없는데도 하늘을 나는 히드라의 표본」이라면 교환하겠다고 했어. 그런 정체 모를 생물, 어디서 찾으라는 거야!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "잡담·다포딜에 대해"
  },
  Voice_6579_UnlockDesc = {
    Text = "깨어남체 「다포딜」획득 후 개방"
  },
  Voice_6582_AwakerVoiceContent = {Text = "위험."},
  Voice_6582_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6583_AwakerVoiceContent = {Text = "경고."},
  Voice_6583_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6584_AwakerVoiceContent = {Text = "피격."},
  Voice_6584_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6585_AwakerVoiceContent = {
    Text = "사탕 포장지처럼 빛나요... 보물로 간직할게요!"
  },
  Voice_6585_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6586_AwakerVoiceContent = {Text = "피격."},
  Voice_6586_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6587_AwakerVoiceContent = {
    Text = "내 작은 가게는 우주의 어떤 차원, 어떤 위치에도 존재할 수 있으며, 물론 여기에 존재할 수도 있습니다. 게다가, 나는 미사그의 그 조심성 없는 아이들을 매우 좋아합니다?"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "...피망은, 맛없어."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "저와 당신의 관계는 돛과 배의 관계와 같습니다. 배가 없으면 돛은 존재할 필요가 없고, 돛이 없으면 배는 멀리 항해하기 어렵습니다. 그렇지 않나요."
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "성실타래한 무용수도 죽었고, 예술을 모독한 자도 죽었다. 그들은 타르 냄새가 가득한 불길 속에서 죽음을 맞았다. 죽음은 끝이 아니라 시작이다. 왜냐하면 인간만이 죽음을 맞이할 수 있으며, 무용과 예술은 영원하기 때문이다."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6590_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "당신의 이해에 감사드립니다. 아마 지금이 과거의 자신과 화해할 때인 것 같습니다…. 제가 옳은 일을 하고 있다고 믿습니다. 저는 춤의 명가의 이름을 훼손하지 않았습니다. 당신이 준비한 무대에 올라서, 당신의 바람대로 빛을 발휘하겠습니다."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6591_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6592_AwakerVoiceContent = {Text = "조심해."},
  Voice_6592_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6593_AwakerVoiceContent = {
    Text = "당신이 무대에 올라서 무대에서 빛나길 원하나요?\n이미 그럴 수 없습니다. 이 눈은 증오에 휩싸여 모든 것을 불태우는 것 외에는 아무것도 할 수 없습니다."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6593_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "그런 기분을 이해하시나요? 회전, 회전, 회전, 멈추지 않습니다. 뻣뻣하게 펴진 무릎이 아프고 시큰거려서, 발끝에서 흘러나온 검은 피가 발레 신발을 적시면서 여전히 멈추지 않습니다. 바로 내가 장난감이 되는 운명을 받아들이기 싫어서……"
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6594_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "나는 춤 실타래력이 뛰어난 궁정 무용가를 태워 죽인 것이 아니며, 발레 전당의 우아한 주인도 아니고, 고귀함과 아름다움을 이해하는 귀족도 아니었다. 오히려 몸을 파는 무능한 자들, 남을 배려하지 않는 아첨꾼들, 육욕에 빠진 더러운 속물들이었다... 당신은 나를 이해해 줄 거야, 그렇지?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6595_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "미끈미끈한 촉수를 기르는 녀석들도 싫고, 깊은 바다도 싫어... 잠깐, 다 이해한다는 듯한 얼굴 하지 마! 내가 부모를 무서워하는 아이라도 되는 줄 알아?"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6596_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "배려심이 깊구나, 고마워."
  },
  Voice_6597_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6598_AwakerVoiceContent = {Text = "각오해!"},
  Voice_6598_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6599_AwakerVoiceContent = {Text = "사라져!"},
  Voice_6599_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6600_AwakerVoiceContent = {
    Text = "브라운을 데리고, 튀자!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "하지 말아요..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "타격·우울"
  },
  Voice_6602_AwakerVoiceContent = {Text = "꺼져!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "방어·광란"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "레이아는 누구야? 오, 날 좀 때려달라고 한 여자. 하하, 재미있군... 여기가 그렇게 심심하지는 않겠어."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "잡담·레아에 대해"
  },
  Voice_6603_UnlockDesc = {
    Text = "깨어남체「레아」획득 후 개방"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "작은 언덕 위의 낙일은 종종 클리블랜드에서 보낸 시절을 떠올리게 해……클리블랜드, 나는 아직도 그 이름을 기억할 수 있다니, 이런 상처를 남긴 그곳……"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "잡담·황혼에 대해"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "아아... 별들이... 떨어져 간다..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "의심의 여지 없게 인간이다. 인간보다 더 더러운 생명체가 있을까?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "지금이야!"
  },
  Voice_6607_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6608_AwakerVoiceContent = {
    Text = "때려 부순다!"
  },
  Voice_6608_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6609_AwakerVoiceContent = {
    Text = "융식? 어... 응! 알아! 아이스크림은 금방 녹아버리지만, 모두랑 나누면 완전히 크림이 되기 전에 먹을 수 있어!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "이 힘으로 당신을 지키겠습니다."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6610_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "어라, 우리 가게에서 판매한 상품은 환불이나 교환이 불가능해요? 깊은 바다로 잠수하려면 확실타래히 잠수함이 필요하겠죠?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "잡담·카이커스에 대해"
  },
  Voice_6611_UnlockDesc = {
    Text = "깨어남체「카이커스」획득 후 개방"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "최고의 무대! 미사그 대학의 사생과 교직원들은 내가 진정한 마법을 선보이고 있다는 것을 이해할 수 있어요! 이거 마술사의 지인이겠죠?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "우주의 질서는 여기에서 변화하며, 파괴의 미래는 마법사의 믿음입니다!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6613_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "그, 조금만 더 여기에 있어도 될까요? 방해가 되지 않게 조용히 있을게요..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6614_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "세계를 해석하고, 인류의 지성을 증명한다!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "내 꿈속에서 자주 조수의 소리가 들린다. 그 소리는 점점 더 멀어지고, 점점 더 멀어진다. 나는 아마도 영원히 여기에 머물러야 할지도 모른다. 인간으로서."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "잡담·심해에 대해"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "더 많은 기억, 더 많은 감정, 더 많은 꿈——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6617_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6618_AwakerVoiceContent = {Text = "간다~!"},
  Voice_6618_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6619_AwakerVoiceContent = {
    Text = "눈 깜빡이지 말라구♪"
  },
  Voice_6619_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_6620_AwakerVoiceContent = {
    Text = "그분이 탄생하면… 이런 굴욕을 더 이상 견디지 않아도 될 거야…"
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "카렌을 뽑아주세요! 파티가 있는 곳에, 카렌도 있다!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "음? 나에게 관심이 있나요? 상상컨대…… 당신은 이미 대가를 치르기 위한 준비가 되었어요?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "용서 못해, 절대 용서 못해...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "별들이 그려내는! 반짝임의 선율!"
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "노래해라, 노래해! 목소리를 더 높여!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "엄마, 좋아해!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6627_AwakerVoiceContent = {Text = "덤벼봐."},
  Voice_6627_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6628_AwakerVoiceContent = {Text = "조심해."},
  Voice_6628_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6629_AwakerVoiceContent = {
    Text = "깨어남체는 호기심으로 식사를 할 수도 있지만, 식사가 꼭 필요한 건 아니야. 그러니 티타임 때마다 날 부르지 말아줘. 당분 섭취는 몸의 노화를 가속시킨다고."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "잡담·티타임에 대해"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "카렌은 어떤 벌이라도 달게 받을게요, 대신 주인님은 봐주세요!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "이거, 전부 먹어도 돼?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6633_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "싫어하는 것, 말인가요? 음... 아이기스는, 무능한 제 자신이 싫어요... 하지만 제가 이렇게 얘기하면, 젠킨은 분명 화낼 거예요..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "재가 되어라."
  },
  Voice_6635_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6636_AwakerVoiceContent = {
    Text = "재가 되어라."
  },
  Voice_6636_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6637_AwakerVoiceContent = {
    Text = "잘했어, 수호자. 말해봐, 이번에는 누구를 죽여야 하나?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6637_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "융식을 연구하기 위해, 이 학교는 세워졌어. 그리고, 이 학교에서 우리는 만났지. 융식으로부터 인류를 구하기 위해, 함께 싸우자!"
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "저는 그 양반님의 적의를 느낄 수 있어요. 제가 당신을 사랑하는 마음이 질투를 불러일으킨 거겠죠……보세요, 저 큰 날개고래의 입이 질투로 벌어졌잖아요."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "잡담·로탄에 대해"
  },
  Voice_6639_UnlockDesc = {
    Text = "깨어남체「로탄」획득 후 개방"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "주인님, 주인님! 오늘 카렌은, 해롤드 백화점에서 엄~청 예쁜 카메오 브로치를 봤어요! 저기, 주인님, 혹시 선물로 사주실타래 수 있나요? 평생의 소원이에요~"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "나는 밤의 방향표가 될 것입니다, 하지만 이 기간은 영구적이지 않습니다."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "엄마, 아파, 엄마..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "포기해! 승리는 나의 것이다!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "포기해! 승리는 나의 것이다!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "융식 아… 제 뇌 용량이 한정되어 있어 그렇게 복잡한 질병을 이해할 수 없어요… 수리가 필요한 기계가 있으면 언제든 저를 찾아주세요!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "와아! 오레타 잡혀버렸어! 벌칙으로 오레타한테 뭐든 부탁해도 좋아~ 아, 그래도 수업을 받으러 가라는 건 안돼."
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "주의 강림을 위해서라면, 어떠한 장애물이든지 배제하겠습니다..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "언젠가는 오른 아저씨가 나를 다시 바다의 집으로 맞이할 거야. 그 전까지는 어쩔 수 없이 너와 친구가 되는 것도 괜찮겠어."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6648_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"우리 가문에는 위대한 혈통이 흐르고, 선택된 자는 깊은 바다에서 영원한 안락을 누릴 것입니다.\"\n하지만, 바다를 떠나 학교에 와서야 이런 안락함을 느끼게 되었습니다. 당신은 나를 괴롭힌 사람들과 다릅니다. 그래서 다른 사람들이 당신을 괴롭히는 것을 허용하지 않을 것입니다."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6649_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "엄청 단단한 특제 재료!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "이런 인간 성분이 섞인 껍질에 갇혀 있는 게 정말 역겹다. 겨우 과거에서 벗어났는데, 지금은 다시 생각해야 하다니…"
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6651_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "알아, 위대한 혈통의 계승자가 다시 인간의 개가 되었구나. 하지만 네가 마음대로 나를 부릴 수는 없을 거야."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6652_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "흥, 너 같은 연약한 인간이 지휘 능력이라도 어느 정도 갖추고 있구나. 하지만 이 열등한 육체 때문에 내가 전력을 발휘할 수 없게 만든다."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6653_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "몸이 뜨거워졌어."
  },
  Voice_6654_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6655_AwakerVoiceContent = {
    Text = "도망쳐, 도망쳐... 도망쳐야 해!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "도망쳐, 도망쳐... 도망쳐야 해!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "고마워. 그러면, 나로부터도 보수를 줘야겠지."
  },
  Voice_6657_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6658_AwakerVoiceContent = {
    Text = "신경 쓰지 마."
  },
  Voice_6658_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6659_AwakerVoiceContent = {
    Text = "(통증을 느끼는 음성)"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6660_AwakerVoiceContent = {
    Text = "인간, 네가 약하긴 하지만 네 신념이 나를 감동시켰다. 내가 네 무기가 되어 함께 큰 소동을 일으키자!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6660_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "이것은 나의 모임입니다."
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "모두가 평등한 학교…… 너희들이 얼마나 무지한 희망을 품고 있는지 모릅니다. 네가 아무 잘못도 하지 않았더라도, 그들은 너를 발아래 두려고 할 것입니다. 나는 그 감정을 압니다."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "불결함의 근원을 끊겠어!"
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "광기 폭발·우울"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "나는 선원들을 보호하지 못한 죄로 처벌을 받았다. 그들은 내 소홀함 때문에 사라진 선원들이 영원히 가족들과 재회할 수 없다고 말했다‥ 융식이 그런 것인가?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "주께 한 걸음 더 가까워졌습니다."
  },
  Voice_6667_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6668_AwakerVoiceContent = {
    Text = "어째서? 어째서 깨어나시지 않으시는 겁니까?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "저는 시테 섬의 오를라입니다. 필명은 아무에게도 알려주지 않기로 약속했으니, 오를라라고 불러주세요."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6670_AwakerVoiceContent = {
    Text = "나는 모든 부정의 행위를 거부하며, 그 중 가장 심각한 것은 배반이다. 군대에서 동료에게 등을 맡길 수 없거나, 감히 맡기지 못한다면 전체 부대는 모래알처럼 흩어질 것이다."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "어째서 새까맣게 보이는데, 이렇게나 밝은 걸까? ...아냐, 아무 것도 아니야. 혼잣말이니까, 잊어줘."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_6672_AwakerVoiceContent = {Text = "으우우."},
  Voice_6672_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6673_AwakerVoiceContent = {
    Text = "(끈질긴 음성)"
  },
  Voice_6673_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6674_AwakerVoiceContent = {
    Text = "뭔가요!?"
  },
  Voice_6674_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6675_AwakerVoiceContent = {
    Text = "나는 생명을 좋아하고, 빛을 좋아해. 파인트가 밀폐된 껍질에서 나와 자신의 두 눈으로 이 세상을 보고 느끼기를 바래."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "안 보이지롱!"
  },
  Voice_6676_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6677_AwakerVoiceContent = {
    Text = "점검 작업을 계속하시겠습니까?"
  },
  Voice_6677_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6678_AwakerVoiceContent = {
    Text = "부품 정비가 완료되었습니다."
  },
  Voice_6678_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6679_AwakerVoiceContent = {
    Text = "사람은 배신의 마음을 가질 수 있지만, 도구는 그렇지 않습니다. 적절히 활용하기만 하면, 융식도 복수의 도구가 될 수 있습니다."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "잠복 천년의 기다림, 이 순간이 마침내 도래했다... 나야말로 페리시테인의 유일한 군주!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_6680_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "방금 지나간 것은 깊은 바다의 하이브리드인가? 음...... 이 똑바른 등을 보라. 오늘 밤에 그가 무릎을 꿇고 엎드리는 모습을 볼 것이다."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "잡담·카이커스에 대해"
  },
  Voice_6681_UnlockDesc = {
    Text = "깨어남체「카이커스」획득 후 개방"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "힘은 점차 손에 돌아오고… 다음 단계, 나의 권한을 되찾는다!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6682_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "여자의 거짓된 베일을 벗기는 데 한 걸음 더 가까워졌습니다."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_6683_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "진정해... 진정해..."
  },
  Voice_6684_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6685_AwakerVoiceContent = {
    Text = "두려워하지 마세요. 나는 통증의 한도가 당신들이 상상하는 것보다 훨씬 높을 수 있습니다."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6685_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "내가 보기에는, 아름답지만 어리석은 것이 가장 좋다. 아쉽게도 여기는 무용한 영리한 두뇌들이 너무 많다."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "적색거성의 핵융합 반응을 동력원 삼고, 행성의 중력붕괴에 의한 에너지를 보충하면, 영구기관을 만들어서 영원히 빛나는 빛을 밝힐 수 있어... 에? 여긴 영구기관을 만들기 위한 환경도, 적색거성도 없다고? 으으..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "아직 사냥은 끝나지 않았는데 말이지."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "나에게... 모든 걸 바쳐라!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "나에게... 모든 걸 바쳐라!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "슬슬 전장으로 향하지."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6692_AwakerVoiceContent = {Text = "기회다!"},
  Voice_6692_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_6693_AwakerVoiceContent = {
    Text = "여가 잠을 자는 동안, 넘쳐나는 꿈이 영의 끓음을 불러일으킬 것이다. 그러니, 여가 깊이 잠들 때에는 접근하지 말고, 더욱이 함부로 깨어남시키지 말아요."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "잡담·잠에 대해"
  },
  Voice_6694_AwakerVoiceContent = {Text = "기회다!"},
  Voice_6694_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6695_AwakerVoiceContent = {
    Text = "헤버트는 무서운 사람인데, 그의 고양이는 매우 온순하다……아니, 정확히 말하면 그건 두 마리의 고양이인가?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "잡담·허버트에 대해"
  },
  Voice_6695_UnlockDesc = {
    Text = "「조사 임무」제2장 완료 후 개방"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "그 머피라는 여자는 정말 화려하게 입었네요... 카렌도 옷을 갖춰입으면 지지 않겠지만... 음, 차라리 죽여버리면……."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_6696_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_6697_AwakerVoiceContent = {Text = "야~"},
  Voice_6697_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6698_AwakerVoiceContent = {Text = "편안해?"},
  Voice_6698_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6699_AwakerVoiceContent = {
    Text = "대학과 협력 관계를 맺을 때, 나한테 싸움은 시키지 않겠다고 약속했었는데..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6699_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "자만하지 말라. 때로는 고귀함에서 천박함까지 한 걸음 차이밖에 없다."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6700_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "안녕하세요, 제 이름은 파로스. 저를 부르셨다는 건, 항해 준비가 되어있다는 거겠죠."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_6702_AwakerVoiceContent = {
    Text = "후, 힘들어~, 이제 놀아도 돼?"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "아아……그의 빛은 너무 뜨겁고 눈부셔서 무시할 수 없게, 어리석은 광기가 제 감각을 가렸습니다……아니, 제 어리석음에 대해 어떤 변명도 할 수 없습니다……"
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "잡담·툴루에 대해"
  },
  Voice_6703_UnlockDesc = {
    Text = "깨어남체「툴루」획득 후 개방"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "짐의 꿈속에서 잠든 별들이여, 깨어나 신의 나라를 보여라!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "만물을 종언으로 이끌고, 세계의 법칙을 정지시킨다라, 재밌을 것 같지 않아?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6707_AwakerVoiceContent = {Text = "마셔라!"},
  Voice_6707_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6708_AwakerVoiceContent = {
    Text = "기분 좋구나!"
  },
  Voice_6708_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_6709_AwakerVoiceContent = {
    Text = "전투 명령을 입력해주세요."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "나는 별 사이를 떠돌던 날들에 수많은 이날을 꾸며봤어…… 감사합니다, 나와 틴커트가 다시 만나게 해줘서."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "잡담·틴커트에 대해"
  },
  Voice_6710_UnlockDesc = {
    Text = "깨어남체「틴커트」획득 후 개방"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "미사그 대학은 좋은 곳이에요, 특히 매주 열리는 지하 카지노……\n어라, 당신이 모르셨나요? 아, 실타래수했나……"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "융식 위기에 저항하겠다니, 인간의 자기만족일 뿐인데. 정말 웃기는 일이지."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "잡담·미사그 대학에 대해"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "결국 인간도 단지 얕은 동물에 불과하다. 몇 마디 말, 한 점의 암시만으로도 서로의 싸움을 일으킬 수 있다…… 흠, 이런 정도로는 흥미를 끌기엔 부족하다."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "잡담·인간에 대해"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "당신을 평범한 인간이라 생각한 건, 어리석은 일이었습니다. 당신 같은 신앙심 없는 인간이, 어떻게 마을을 지켜냈는지 신기합니다. 이건 바다의 성모가 아닌, 미리암으로서 여쭤봅니다만, 답해주실타래 수 있을까요..."
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6714_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "특별한 당신이야말로, 어리석고 문제투성이인 세상이 싫증나시는 건 아닌지요? 저는 영원의 왕국이야말로, 당신께서 돌아가실타래 장소라고 믿고 있습니다. 당신은 신들의 나라를 걷고, 성령의 연못에서 헤엄치며, 비옥한 토양에 뿌리를 내리게 되겠지요. 신을 위해, 저와 함께 일어납시다. 그리고 당신과 저는 함께 왕좌의 옆에 서서, 신국의 재건을 함께 기뻐하는 겁니다..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_6715_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "당신이나 저는 무능한 필멸자에 지나지 않습니다만, 그분은 다릅니다. 신의 대행자, 지상에 계신 신의 화신입니다. 그분의 훈시는 신들의 계시 그 자체로, 문명을 불멸로 인도합니다... 지금은 그분을 향한 신앙을 이해하지 못하시겠지만, 언젠가 당신도 그분께 신하로서 복종하겠지요."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6716_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "선택받은 자는 행복하다고 생각하시나요? 그들은 신의 힘을 나누어 받아, 장수를 누리고 있습니다. 신국이 다시 강림하고, 신의 의지가 다시 지상에서 숭상될 때, 그들은 긍지 있는 신도가 되는 겁니다. 이건, 약한 인간에게 있어 크나큰 은혜이자, 행복이 아닐까요."
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6717_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "신의 빛을 쬐는 기쁨은, 당신과 같은 신앙심 없는 분에겐 이해할 수 없겠지요. 안심해주세요. 저의 신께선, 당신의 무지와 무례를 용서해주십니다."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6718_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "수호자여, 빨리 끝내자꾸나."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6720_AwakerVoiceContent = {Text = "에헤헷!"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_6720_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "죽어라, 스파르타의 버러지들."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "돌 씨는, 자기처럼 육체를 버리면 융식에서 벗어날 수 있다고 말해줬지만... 무리무리무리무리! 수술하는 중에 의식을 잃잖아? 어둠은 그 틈을 놓치지 않을 거야..."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "잡담·돌에 대해"
  },
  Voice_6722_UnlockDesc = {
    Text = "깨어남체「돌」획득 후 개방"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "...왜 그래? 소멸시켜주길 바라는 거야?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "불면증 때문에 고민이신가요? 그런 주인님을 위해 카렌이 도피 진정제를 준비했어요! 양이 조금 많지만, 푹 잘 수 있을 거예요!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_6724_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "그때 술을 마시고 노래를 부르고 있었는데, 갑자기 괴물이 되어버렸어요! 그래도 괜찮아요! 초록색 피부도 의외로 나쁘지 않아요!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_6725_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "카렌의 꿈 말인가요? 어디보자... 아름다운 진주 목걸이를 사서 호화로운 드레스를 입고, 그리고 나서, 무도회에서 모두의 주목을 받는 거예요!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_6726_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "욕망의 질체인 티페리트·예소드는, 그녀 나름의 존속의 길을 찾아내었다. 미지를 앞에 두고, 수단의 숭고함이나 비겁함을, 누가 판단할 수 있을까."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "잡담: 욕망의 질체에 대해"
  },
  Voice_67276_UnlockDesc = {
    Text = "깨어남체「타이스」획득 후 개방"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "은열쇠의 문을 지나, 신의 왕좌를 알현하라."
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_67278_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_67279_AwakerVoiceContent = {
    Text = "신의 학식과 기억에 거스르는 일이 없도록."
  },
  Voice_67279_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6727_AwakerVoiceContent = {
    Text = "왼쪽을 닦고, 오른쪽을 닦고, 먼지도 고민도 전부 털어버려요 ♪"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_6727_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "나는 굴하지 않는다."
  },
  Voice_67280_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_67281_AwakerVoiceContent = {
    Text = "무한히 퍼지는 시공의 파편이, 나의 의식을 찾아왔다."
  },
  Voice_67281_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_67282_AwakerVoiceContent = {
    Text = "나는 모든 것을 꿰뚫어 보는 존재이니."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "모든 것은 공허 속에 존재한다."
  },
  Voice_67283_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_67284_AwakerVoiceContent = {
    Text = "이 정도로 깊게 가라앉다니... 그대는 언젠가 기적에 닿게 되겠지. 그 때, 지금의 냉정함을 잊지 않기를 바란다."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_67284_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"무지\"다. 알지 못하는 것을 탐구하는 자는 무지하지 않다. 진정한 무지란, 그저 어렴풋이 살아가며, 스스로가 아무 것도 모른 다는 것조차 알지 못하는 것이다."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "나의 꿈을 보여주도록 하지. 그대 눈에 보이는 기묘한 혼돈은, 사람이 인식하는 현실타래보다도 세계의 본질에 가까운 것이다."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_67286_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "하나 충고해 두자면, 조급함은 금기다. 피로를 느낀다면, 바로 사고를 멈추고, 체력과 기력을 보존하라. 그렇지 않으면, 그대는 영원히 꿈의 세계를 떠도는 미아가 될 것이다."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_67287_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "우주는 끊임없이 순환한다."
  },
  Voice_67288_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_67289_AwakerVoiceContent = {
    Text = "긴 시간을 들일 필요는 없지만, 환영으로부터 그대의 정신을 지키기 위해, 동조는 조금씩 진행하도록 하지."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_67289_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "융식 아…… 나는 우연히 그것과 관련된 사건을 맡은 적이 있는데, 어떻게 말하면 좋을까, 사라지는 것이 자연스러운 일이라고 생각해. 결국 모든 사람이 언젠가는 사라지니까."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "첫 번째 문. 무한한 우주는, 작은 점에서 탄생한다."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_67290_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "두 번째 문. 점은 선이 되어, 끝없는 양극으로 통한다."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_67291_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "네 번째 문. 영원의 원형은, 차원 속에 응고되어 있다."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_67292_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "세 번째 문. 평면이란 부분이자, 하나의 면을 의미한다."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_67293_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "궁극의 문. 무수히 많은 우주를 잇는 최후의 공허. 그 문을 지나는 자는, 우주의 신비를 알게 되리라."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_67294_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "다섯 번째 문. 시간은 곧 착각. 이 세계에 시작이란 없고, 끝 또한 존재하지 않는다."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_67295_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "나는 계시자로서, 그대의 여정을 인도한 후, 허상의 웅덩이에 잠들 예정이었다. 하지만 지금, 나는 그대와 연결되어, 끊을 수 없는 존재가 되어버렸다..."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "무언가의 확인인가? 아쉽지만, 이 몸의 감각과 정신에는 많은 제약이 있다. 심연에서 만났더라면, 그대를 더욱 알 수 있었겠지만..."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "그 소녀 역시 나의 파편 중 하나. 소멸한 다른 차원으로부터 온 방문자다. 시간을 거스르는 방법을 알면서도, 시공을 넘는다는 것의 진정한 의미를 이해하지 못한 채, 고통 속으로 몇 번이나 떨어지고 있지. 나의 과오다."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "잡담·회귀·라모나에 대해"
  },
  Voice_67298_UnlockDesc = {
    Text = "깨어남체「회귀·라모나」획득 후 개방"
  },
  Voice_67299_AwakerVoiceContent = {Text = "알았다."},
  Voice_67299_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_6729_AwakerVoiceContent = {
    Text = "이 육체의 모습을 매우 신경 쓰시나요? 너무 많은 생각을 하지 말아요. 제가 태어났을 때, 인간의 얼굴을 가지고 있었습니다."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_67300_AwakerVoiceContent = {Text = "보였다."},
  Voice_67300_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_67301_AwakerVoiceContent = {
    Text = "이 얼마나 왜소한지."
  },
  Voice_67301_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_67302_AwakerVoiceContent = {
    Text = "이성을 유지하라."
  },
  Voice_67302_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_67303_AwakerVoiceContent = {
    Text = "나와 직접 연결되는 것은, 그대의 정신을 상처입힐 것이다... 하지만, 그대가 바란다면, 나는 반드시 그 부름에 답하겠다."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_67304_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_67305_AwakerVoiceContent = {
    Text = "그 아이는, 나의 의식의 파편이기에, 짊어지지 않아도 되는 많은 무게를 짊어지고 있다. 그 영혼이 여전히 맑다는 사실타래이, 최소한의 행운이라고 해야 하는가..."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "잡담·라모나에 대해"
  },
  Voice_67305_UnlockDesc = {
    Text = "깨어남체「라모나」획득 후 개방"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "신의 꿈에 숨어들어, 우주의 비밀을 엿보도록 하라."
  },
  Voice_67306_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_67307_AwakerVoiceContent = {Text = "으..."},
  Voice_67307_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_67308_AwakerVoiceContent = {
    Text = "궁극의 문은 그대에 의해 열렸다. 문 너머에서 기다리는, 정적의 세계를 받아들여라."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_67308_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "내가 이 학교를 설립한 목적은 \"보관\"하는 것이다. 그대들은 나의 예상을 한없이 뛰어넘은 성과를 이루어냈다."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "융식은 신의 선물입니다. 그것이 가져오는 고통은 적지도 많지도 않아서, 우리의 신경을 마비시키고 음식과 와인에 몰입하게 하며, 함께 축제를 벌이고 멸망으로 향하게 합니다."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "잡담·융식에 대해"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "과거, 현재, 미래, 모든 빛이 이곳에 모이리!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "과거, 현재, 미래, 모든 빛이 이곳에 모이리!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "궁극의 문은 열렸고, 만물은 하나가 된다!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "궁극의 문은 열렸고, 만물은 하나가 된다!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "지혜의 목소리에 귀를 기울여라."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "무진, 무한, 무궁."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "특수 스킬·3"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "신의 의지... 아니, 의지라기보다는 무의식에 가까운가. 신이 무의식적으로 눈을 향하는 것 만으로, 만물은 그 탄식에 삼켜지는 것이다."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "더 이상... 파헤칠 실타래마리조차..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "나는 진실타래을 드러낼 것이다."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"답\"이다. 나는 박애하기에 이 문을 지키고, 똑같이 박애하기에 문의 열쇠를 그대에게 넘겼다."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "반드시 조국으로 돌아가겠어..."
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "천지만상, 인과응보!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "천지만상, 인과응보!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "이 칼날이 무뎌지도록 둘 생각은 없다."
  },
  Voice_6734_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6735_AwakerVoiceContent = {
    Text = "훈련에 더욱 정진하자."
  },
  Voice_6735_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6736_AwakerVoiceContent = {
    Text = "더욱 움직이기 쉬워졌군."
  },
  Voice_6736_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6737_AwakerVoiceContent = {
    Text = "형태 없는 존재는, 당신의 뜻대로."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_6737_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "뜨거운 숨결을 느껴봐!"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "모두가... 결국 녹염이 될 거야..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "주군, 제 방패는 당신을 위해 빛나고 있습니다."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_6740_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "가, 강해졌어! 크흠, 정말 감사드립니다!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_6741_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_6743_AwakerVoiceContent = {Text = "칫"},
  Voice_6743_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6744_AwakerVoiceContent = {Text = "칫"},
  Voice_6744_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6745_AwakerVoiceContent = {Text = "쳇!"},
  Voice_6745_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6746_AwakerVoiceContent = {Text = "큿!"},
  Voice_6746_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6747_AwakerVoiceContent = {
    Text = "모두와 함께 보내는 시간은 언제나 편안하게 느껴집니다…"
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "살인의 혈연, 티폰의 사자, 증오의 날카로운 칼날… 그들은 나에게 이런 칭호를 붙여주었다. 물론, 그렇게 나쁜 것도 아니라고 생각한다."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "잡담·자신에 대해"
  },
  Voice_6749_AwakerVoiceContent = {Text = "우앗!"},
  Voice_6749_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_6750_AwakerVoiceContent = {Text = "올인!"},
  Voice_6750_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_6751_AwakerVoiceContent = {Text = "우앗!"},
  Voice_6751_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_6752_AwakerVoiceContent = {
    Text = "난 괜찮아!"
  },
  Voice_6752_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_6753_AwakerVoiceContent = {
    Text = "더 멀리 놀러갈 수 있게 된 거야? 그럼 바다에 가자!"
  },
  Voice_6753_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_6754_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_6755_AwakerVoiceContent = {
    Text = "와아~ 고마워~!"
  },
  Voice_6755_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_6756_AwakerVoiceContent = {
    Text = "친구~ 더 많이 많이 친구가 있으면 좋겠어~"
  },
  Voice_6756_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_6757_AwakerVoiceContent = {
    Text = "유우하시…… 그는 매우 특별해. 네가 우리 집이 번성한 날들이 어떻게 왔다고 생각해? 전부 그가 경기장에서 광전사처럼 사람을 죽이는 덕분이야. 그가 우리 집에서 가장 큰 수입원이야."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "잡담·유우하시에 대해"
  },
  Voice_6757_UnlockDesc = {
    Text = "깨어남체「유우하시」획득 후 개방"
  },
  Voice_6758_AwakerVoiceContent = {
    Text = "어리석네!"
  },
  Voice_6758_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_6759_AwakerVoiceContent = {Text = "훗."},
  Voice_6759_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_6760_AwakerVoiceContent = {
    Text = "수호자! 전투 명령을 내려줘!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "정의의 빛이여, 지금 이곳에!"
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "정의의 빛이여, 지금 이곳에!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "인간의 감정은 꽃처럼 덧없는 것, 그리고 꽃처럼 고귀한 것입니다..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "잡담·코레트에 대해"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "저항하지 마, 눈물 흘리지 마, 목숨을 아까워하지 마!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "저항하지 마, 눈물 흘리지 마, 목숨을 아까워하지 마!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "문이여, 열려라."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_79297_AwakerVoiceContent = {Text = "오."},
  Voice_79297_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_79298_AwakerVoiceContent = {Text = "에...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_80092_AwakerVoiceContent = {
    Text = "수치료법, 전기경련요법, 구속요법... 이것들은 치료가 아니라 고문이라 생각합니다. 그래서 저는 무료진찰에서 제 나름의 방법으로 정신병원의 환자를 치료했습니다. 그 결과, 그들은 완쾌하여 진정한 자유를 얻었습니다."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_80092_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "불쌍한 화이트는 가까운 수용시설이 가득찼기에 가족들에 의해 돼지우리에서 길러지고 있었습니다. 제가 무료로 치료를 베풀어 겨우 자신이 가축이 아닌 인간임을 깨달았습니다. 그리고 화이트는 스스로의 손으로 인간으로서의 존엄을 되찾았습니다."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_80093_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "방직공이든, 변호사이든, 남작이라 한들, 금전의 유무로 환자를 거부하지 않습니다. 저에겐 모두 똑같이 치료가 필요한 환자니까요."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_80094_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "저는 당신을 얕보고 있었던 거 같네요. 설마 당신의 존재가, 고통 그 자체였다니... 이제부터 심리 상담에 올 필요는 없습니다. 제가 당신 곁으로 가서, 이 눈으로 결말을 지켜보겠습니다."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_80095_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "지금까지 치료한 환자들로부터는 좋은 추억을 많이 받았습니다. 그럼 수호자 씨, 다음은 당신 차례에요. 저는 이미 당신이 마주할 결말을 정했습니다. 이 치료는 제 생애에서 가장 가치 있는, 반복해 음미할 수 있는 기억이 되겠죠."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_80096_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "카운셀러의 도움을 거절하다니. 다음엔 최면술을 시험해보는 게 좋겠네요."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "머리 속에서 몇 번이고 반복되는 고통의 속삭임을, 어둠 속에서 홀로 듣는다. 이보다 즐겁게 시간을 쓰는 방법은 없어요."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "무례한 얘기가 되겠지만 그 아이와 이야기해도 시시할 뿐이에요. 그 아이의 얼굴에는 웃음이라는 한 종류의 표정 밖에 떠오르지 않으니까요."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "잡담·오레타에 대해"
  },
  Voice_81140_UnlockDesc = {
    Text = "깨어남체「오레타」획득 후 개방"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "갑작스럽게 죄송해요. 당신의 정신이 조금 약해진 것 같아서, 상태를 보러 왔어요. 수호자, 저와 마음 속 깊은 곳으로 여행을 떠나지 않으실타래래요?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_81143_AwakerVoiceContent = {
    Text = "정신 의사의 치유 방법은 환자의 두개골을 드릴로 뚫는 것입니다 - 걱정 마세요, 그건 오래 전 이야기입니다. 지금은 환자의 마음을 측정하고 더 깊이 탐구할 다양한 방법이 있습니다."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_81143_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "서로를 잘 알고 싶다면, 마음을 열어야 합니다. 여기를 만져보신다면 제 순수한 마음이 해방될 거랍니다?"
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "제 감상을 기대하시는 거라면, 실타래망하실타래 지도 몰라요. 저는 이야기하는 것보다 듣는 게 특기라서요."
  },
  Voice_81145_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_81146_AwakerVoiceContent = {
    Text = "아아, 들려요. 이건 신의 속삭임. 모든 음절이 극도의 고통으로 가득해요!"
  },
  Voice_81146_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_81147_AwakerVoiceContent = {
    Text = "저는 이 고통을 가슴에 새기고, 몇 번이고 음미할 거에요..."
  },
  Voice_81147_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_81148_AwakerVoiceContent = {
    Text = "그 분의 조각인 당신에겐 특별한 기운이 있습니다. 그 고통에 가득찬 기운 덕에 당신의 어떤 기억이든 맛있게 맛볼 수 있습니다."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "두려운 기억들을 회상하고, 자신의 고통을 세세히 묘사하며, 정서 충격 치료의 본질은 고통을 정면으로 대면하고 그것을 이기는 것이죠. 자, 눈물을 닦고, 그 기억을 천천히, 세세하게 저에게 이야기해 주세요……"
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_81149_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "축하합니다, 당신은 이미 회복되었습니다—네, 환청과 환시 모두 정상적인 현상이며, 그것들은 당신이 회복되었다는 증거입니다."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_81150_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "당신의 머릿속에는 분명 기괴한 모습들이 가득 차 있을 것 같습니다. 괜찮습니다, 이것들은 모두 정상입니다. 그것들을 그려보세요, 당신의 잠재의식과 본능이 모든 것을 드러내 줄 것입니다."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_81151_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "다음은 필립 피네르의 도덕 치료입니다. 당신은 가장 깊은 갈망과 두려움을 말해야 하며, 이는 마음의 족쇄를 풀고 잠든 인성을 회복하는 데 필요한 과정입니다."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_81152_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "수호자 씨, 간단한 테스트를 해주실타래 수 있을까요? 걱정 마세요. 단순한 로르샤흐 테스트에요. 수호자 씨의 누구도 모를 마음 속의 깊은 곳을 드러내고 당신의 비밀을 풀어내는, 유일한 깨어남체가 되고 싶어요."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "잡담·심리 분석에 대해"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "먼저, 우리 한 곡의 음악을 들어보자. 들리니, 부드럽고 편안한 음악. 이제, 몸과 마음을 음악과 함께 진동하게 해, 영혼의 이완 상태에 들어가……"
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_81154_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "자, 이 진자를 잘 보세요."
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "쉿. 조용히 따르세요. 제가 결말로 이끌어드릴테니까요."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "마비된 마음에는 아무 흥미도 없습니다. 영혼이 죽어있어선, 아무리 도발해도 아무 의미 없으니까요."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_81158_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_81159_AwakerVoiceContent = {
    Text = "듣고 있어요."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_81160_AwakerVoiceContent = {
    Text = "부디 조용히."
  },
  Voice_81160_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_81161_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_81162_AwakerVoiceContent = {
    Text = "더 큰 신뢰를."
  },
  Voice_81162_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_81163_AwakerVoiceContent = {
    Text = "더 큰 고통을!"
  },
  Voice_81163_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_81164_AwakerVoiceContent = {
    Text = "아무 것도 숨기지 말고, 저를 믿으세요. 당신의 가장 큰 고통을 들려주세요..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "최근 아이기스는 상당히 밝아졌네요. 하지만, 제 자그만한 환자 분이 필요로 하신다면 기쁘게 도와드리겠어요. 물론, 진정한 의미로."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "잡담·아이기스에 대해"
  },
  Voice_81165_UnlockDesc = {
    Text = "깨어남체「아이기스」획득 후 개방"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "진정한 모습을 보여줘."
  },
  Voice_81166_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_81168_AwakerVoiceContent = {
    Text = "감미로운 고통을 음미하죠."
  },
  Voice_81168_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_81169_AwakerVoiceContent = {
    Text = "아무 것도 숨기지 말고, 저를 믿으세요. 당신의 가장 큰 고통을 들려주세요..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "정신질환은 이 시대만의 것이 아니고, 시간과 공간을 초월한 문제입니다. 융식도 그렇죠. 어느 쪽도 인간의 이해를 초월했습니다."
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "쉿. 조용히 따르세요. 제가 결말로 이끌어드릴테니까요."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "여기에는 역사의 흔적이 가는 곳마다 있습니다. 역사란 기억, 돌아가신 많은 분들의 고통의 기억입니다."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "심호흡하세요."
  },
  Voice_81173_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_81174_AwakerVoiceContent = {
    Text = "고통, 절망, 죽음의 공포... 마치 식후의 디저트같은 기억이에요."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "그렇게 긴장하지 마시길. 단순한 심리 상담이니까요."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "지시를 따르세요."
  },
  Voice_81176_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_84185_AwakerVoiceContent = {
    Text = "의식에 예상치 못한 이상이 발생했습니다. 수호자님, 깃발로 팔을 치는 걸 용서해주십시오. 당신이 제정신을 유지할 수 있도록 하기 위함입니다."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_84185_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "이곳에선 다양한 선박들의 모형이나 선진적인 항법장치를 접할 수 있습니다. 저에겐 굉장히 매력적인 장소군요. 그러나 가장 중요한 건 이 「배」가 인류사라는 올바른 항로 위에 있다는 것입니다."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "의식이 성공적으로 진행되었습니다. 당신의 협조에 감사드립니다. 다음 번에는 더 안전하고 원활하게 의식을 마칠 수 있도록 전용 신호를 만들겠습니다."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_84187_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "그것이 어째서 존재하는지는 모릅니다. 단지 확실타래한 건, 저는 반드시 항해를 성공시켜, 선원과 승객들을 무사히 귀환시켜야 한다는 것입니다."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "안심해주세요. 이 힘은 배를 안전하게 인도하기 위해서만 사용할 겁니다. 결코 남용하진 않습니다."
  },
  Voice_84189_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_84190_AwakerVoiceContent = {
    Text = "저항하지 마라."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_84191_AwakerVoiceContent = {
    Text = "제가 당신에게 품고 있는 건 그저 경의 뿐입니다. 목숨을 던져서라도 모든 명령을 완수하겠습니다."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "죄송합니다. 저는 사람보다 배가 친숙하다보니 이런 비유를 하게 됨을 용서해주십시오. 당신의 용골은 목재나 철도 아닌 강철입니다. 강하고 흔들림 없어 존경스럽습니다."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_84192_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "항복하라."
  },
  Voice_84193_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_84194_AwakerVoiceContent = {
    Text = "\"좋다한다\"기보다는 \"귀의\"란 단어가 적절하겠지요. 그 말로 표현할 수 없는 신을 직시했을 때, 제 이성은 광기에 삼켜졌습니다. 두려운 존재였으나 저로선 저항할 수 없었습니다."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "나는 폭풍에 굴하지 않는다."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_84196_AwakerVoiceContent = {
    Text = "질서가 없다면 이 세계엔 무엇이 남겠습니까? 그저 혼돈과 혼란이 만연할 뿐입니다."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "다음 항해에선 항해사 외의 입장으로 승선을 희망합니다. 수호자님의 지휘 하에 몸을 맡기길 원한다는 의미입니다. 당신은 전폭적으로 신뢰할 수 있는 분이니까요."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_84197_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "저는 그저 항해사로서의 책임을 다했을 뿐입니다. 특별히 칭찬해주실타래 만한 일은 아닙니다."
  },
  Voice_84198_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_84199_AwakerVoiceContent = {
    Text = "등대 시스템은 항해의 부담을 크게 경감시켜줍니다. 특히 파로스의 빛은 밝아, 그녀와 함께 출항할 수 있는 것을 기쁘게 생각합니다."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "파로스에 대해"
  },
  Voice_84199_UnlockDesc = {
    Text = "깨어남체「파로스」획득 후 개방"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "선원 제군, 나의 인도를 따르라."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "정신 링크가 성공했다. 당신의 의식을 감지했다...... 이것은 내가 공허에서 항해를 시작하는 첫 번째 시도이다; 경로 이탈 문제 발생 시, 제발 제때 지적해 달라."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_84201_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "권운을 확인, 기압계 하강 중. 선원 제군, 경계하세요! 곧 폭풍 해역에 진입합니다!"
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "이번 혼란은 모두 제 잘못된 항로 계획으로 인한 것입니다. 규칙에 따라 처벌을 내려 주십시오."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "천체고도각 측정."
  },
  Voice_84204_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_84205_AwakerVoiceContent = {
    Text = "이 어지러운 감각은 배멀미와 비슷합니다. 수호자님, 눈을 감고 제게 몸을 맡겨주십시오. 이걸로 조금 편해지셨는지요?"
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_84205_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "돛을 접고, 파도를 상쇄하라. 항로를 수정한다."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "귀중한 경험을 얻을 수 있었습니다. 항해 일지에 기록하여, 후대의 선원들에게 남기겠습니다."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "심층 링크 의식에는 위험이 동반합니다만 부디 안심해주시길. 제가 유도해 반드시 의식을 완수하겠습니다."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_84208_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "중심을 조정."
  },
  Voice_84209_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_84210_AwakerVoiceContent = {
    Text = "배를 지켜라!"
  },
  Voice_84210_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_84211_AwakerVoiceContent = {
    Text = "반응은 느리나 고속으로 움직일 수 있는 증기선, 순발력은 있으나 출력에 한계가 있는 디젤선. 수호자님은 어느 쪽에 가까운 분이실타래까요?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_84211_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "저는 믿습니다. 노력은 반드시 보답받는 법이라고. 앞으로도 더욱 더 노력하겠습니다."
  },
  Voice_84212_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_84213_AwakerVoiceContent = {
    Text = "지금까지의 임무를 통해 당신은 스스로를 증명하셨습니다. 저와 동등, 아니 그 이상의 항해사라고 인정할 수 밖에 없습니다."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_84213_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_84214_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_84215_AwakerVoiceContent = {
    Text = "필요하시다면, 코퍼산트는 언제든 명령을 따르겠습니다."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_84215_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "선원 제군, 나의 인도를 따르라."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_84217_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_84218_AwakerVoiceContent = {
    Text = "항해사 코퍼산트가 보고드립니다! 깃발 준비는 빈틈없이 완료되었고, 컨디션도 완벽합니다. 수호자님! 출항 명령을 내려주십시오."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_84219_AwakerVoiceContent = {
    Text = "배를 올바른 항로로 이끈다."
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "모자가 비뚤어져 있었는지요? 죄송합니만 당신의 의도를 모르겠습니다. 명확한 지시를 부탁 드립니다."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "깃발은 항해사의 언어이면서 묘비입니다. 배가 침몰했을 때, 인양한 이는 깃발의 잔해에서 항해사가 남긴 최후의 한마디를 읽게 되겠지요."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "잡담·깃발에 대해"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "선체 균형을 확인."
  },
  Voice_84222_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_84223_AwakerVoiceContent = {
    Text = "돛을 접고, 파도를 상쇄하라. 항로를 수정한다."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "에코, 지령을 전달한다."
  },
  Voice_84224_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_84225_AwakerVoiceContent = {
    Text = "필요에 따라, 기관실타래과의 연계를 배운 항해사가 타수를 맡는 경우도 있습니다. 그러나, 배의 안전을 위해 이러한 일들은 전문가에게 맡기고 싶습니다."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "잡담·셀레스트에 대해"
  },
  Voice_84225_UnlockDesc = {
    Text = "깨어남체「셀레스트」획득 후 개방"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "무중력을 감지. 곧 배의 격한 흔들림 같은 진동이 옵니다. 제 움직임에 맞춰 몸의 중심을 고쳐잡아 주십시오. 그러면 균형을 유지할 수 있습니다."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_84226_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "해도의 어긋남을 바로잡는다."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "특수 스킬·3"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "찰리, 지령에 응답한다."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "특수 스킬·3"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "내게서 넘어가려고 하다니."
  },
  Voice_90333_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_90334_AwakerVoiceContent = {
    Text = "친구 사이에는 어떻게 지내야 할까요? 폴리쿠스는 내가 할 일을 많이 시킵니다, 자기가 완전히 할 수 있음에도 불구하고요. 그리고 전 그런 일을 도와주고 싶습니다, 그것이 우리 사이의 소통이라고 생각하니까요. 만약 당신이 원한다면, 저도 당신을 위해 무엇을 할 수 있습니다."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_90334_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "불멸의 몸으로, 모든 재앙을 막아내겠다!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "그 책을 보기 전에도 우리는 외부 세계에 대해 호기심이 없었던 것은 아니었고, 호숫가의 섬과 어두운 붉은 벽 너머의 경치에 대해 궁금해했습니다. 하지만 폴뤼크스를 괴롭힐 때에는 반항할 생각조차 하지 않았습니다. 폴뤼크스와 비교하면 나는 정말로 훨씬나약하고 서툴렀습니다."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_90336_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "내가 바보 같은가? 미안하다, 내 무지를 용서해줘. 등불이 우리에게 가르쳐 준 신에 대한 지식 외에는 나는 다른 것에 대해 아는 게 거의 없다. 나는 빨리 배울 것이다. 너가 좋아하는 것과 싫어하는 것을 모두 말해줘. 나는 꼭 잘 기억할 것이다."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_90337_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "지켜봐 줘. 자유를 추구하는 이 의지를."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "모든 소원을 이룰 수 있는 가게, 즐비한 상품들, 정말로 두렵다……아니, 나는 그 여인의 힘을 의심하지 않지만,\"무언가를 가지려면 그것에 상응하는 대가를 치러야 한다\"는 이치, 나는 폴리크스와 이미 너무 많이 체험해버렸다."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "잡담·다포딜에 대해"
  },
  Voice_90339_UnlockDesc = {
    Text = "깨어남체 「다포딜」획득 후 개방"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "저주받은 이 날개로도, 언젠가는 하늘을 날 수 있을까."
  },
  Voice_90340_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_90341_AwakerVoiceContent = {
    Text = "이 몸은 결코 부서지지 않는다!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "이 깃털을 만져보고 싶으신가요? 그러세요, 제 날개를 좀 더 펼쳐드릴까요?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "도움을 받고 있을 때, 나는 종종 그런 특별한 보살핌, 당신이 주신 귀한 서적과 화려한 운석 광물이 뒤에는 다른 대가가 따를까 걱정했습니다. 미안합니다, 이렇게 당신을 추측해서는 안 됐습니다."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_90343_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "새는 결국 높은 하늘을 날게 된다."
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "요리를 잘하는 대가라니…… 음식을 만드는 지식이 정말 필수적이군요. 제가 식사에 대한 요구는 크지 않지만, 폴리쿠스는 정말 까다로워요. 언젠가 진지하게 가르쳐 달라고 요청해야겠네요…… 가시면 안 되나요? 왜요, 하지만 그 분이 만든 음식은 정말 맛있어 보이잖아요?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "잡담·도어세인에 대해"
  },
  Voice_90345_UnlockDesc = {
    Text = "깨어남체「도어세인」획득 후 개방"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "지금 생각해보면, 등불을 들었던 그 하인들은 사실타래 나와 폴리쿠스와 다를 바가 없었던 것 같아요. 우리 모두는 사슬의 굴레 속에서 살아가고 있었고, 그들은 언제나 순응하고 참았습니다. 하지만 그 초록 하인은 좀 다른 것 같아요. 그녀는…… 매우 활기차고, 일을 하는 것을 정말 좋아하는 듯해요. 아마 그녀는 가장 소중한 자유를 이미 가지고 있지 않을까요?"
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "잡담·카렌에 대해"
  },
  Voice_90346_UnlockDesc = {
    Text = "깨어남체「카렌」획득 후 개방"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "이 몸은 결코 부서지지 않는다!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "역시... 날 수 없었나..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "바람에 날려가라!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "특수 스킬·2"
  },
  Voice_90350_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_90351_AwakerVoiceContent = {
    Text = "반가워, 난 카스토르라고 한다. ...더 해야 할 말이 있을까? 미안하군, 말주변이 없어서 말이지. 필요한 게 있다면 언제든 불러줘."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_90352_AwakerVoiceContent = {
    Text = "그저 그렇다……"
  },
  Voice_90352_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_90353_AwakerVoiceContent = {
    Text = "떨어져라!"
  },
  Voice_90353_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_90354_AwakerVoiceContent = {
    Text = "나는 본 적 없는 것들이 많고, 해보지 않은 일들이 많다. 황량한 깊은 녹색 호수와 오래도록 사라지지 않는 짙은 안개는 더 이상 우리를 가두지 않을 것이다. 바다, 대도시, 목가적인 농장, 그 손으로 복사한 책에서 말한 곳들, 나는 모두 가보고 싶다. 폴리스쿠스와 함께 너와 함께."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_90354_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "너무 흔들리면 나뭇잎의 바스락거림이 들려올 때, 내가 너 곁에 있다는 걸 알게 될 거야."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_90355_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "검은 깃털이, 더욱 깊은 색을 띄게 되었군."
  },
  Voice_90356_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_90357_AwakerVoiceContent = {
    Text = "사실타래 내가 가장 부러워하는 것은 당신과 당신의 동료들이 그렇게 의심 없이 서로를 믿는 모습이다. 잊히고 배신당하는 느낌은... 너무 아프다."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "그 도둑녀는 나에게 가장 뛰어난 거리 생존 기술을 가르쳐줄 수 있다고 말했으며, 그녀에게 500 레오파트를 지불하기만 하면 된다… 나는 속았나? 아니, 나는 이것이 배울 가치가 있는 지식이라고 생각한다. 그것이 바로 나와 포뤼크스에게 부족한 것이다… 돈 문제인가? 알겠다, 그럼 나는 그녀와 상의하러 가서 450 레오파트를 주는 것이 어떨까?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "잡담·젠킨에 대해"
  },
  Voice_90358_UnlockDesc = {
    Text = "깨어남체「젠킨」획득 후 개방"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "나는 아직 견딜 수 있다……"
  },
  Voice_90359_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_90360_AwakerVoiceContent = {
    Text = "어렸을 때, 등불이 우리를 통제하는 건 그리 엄격하지 않았고, 때때로 폴리쿠스가 무슨 말을 했는지도 모르고 신기하게 사탕을 얻기도 했다. 그 사탕을 맛보는 기분은…… 지금과 같았다."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_90360_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "불멸의 몸으로, 모든 재앙을 막아내겠다!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "저에게 사람과 거래하는 지식을 가르쳐 주실타래 수 있나요? 어떻게 물품을 교환하고, 어떻게 얻게 된 통화를 관리하는지, 정말로 심오한 학문입니다. 자유는 시작일 뿐이에요, 독립적인 삶을 살기 위해서는 나와 폴리쿠스가 배워야 할 것이 많아요. 앞으로 많이 귀찮게 해드릴게요."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "바람에 날려가라!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "바람이 그것을 죽음의 입으로 불어넣어라!"
  },
  Voice_90364_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_90365_AwakerVoiceContent = {
    Text = "폴리쿠스는…… 등불에게 많은 나쁜 생각을 주입당했지만, 그의 본심은 나쁘지 않아. 그는 단지 등불의 인정과 신도의 인정을 절실타래히 원했기에 그들의 요구를 지나치게 신경 쓰고 있었어. 그가 너무 자아에 집착하기보다는, 그는 그 '자아'를 잃는 것을 두려워했어."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "잡담·폴룩스에 대해"
  },
  Voice_90365_UnlockDesc = {
    Text = "깨어남체「폴룩스」획득 후 개방"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "미안하지만, 나는 의도적으로 생각을 놓친 것은 아니다…… 네가 묻는 이 깃털이 무슨 것인지? 이것은…… 그가 가장 중요하게 생각하는 것이자, 나에게도 가장 중요한 것이다. 아름답지 않니?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "그때 우리는 매일 알비노 또는 수호자의 가르침 아래 신학을 배워야 했다. 그때 내 가장 큰 바람은 언젠가 경전이 개정되어 짧고 간결해지는 것이었다. 그렇게 되면 나는 머리가 아프고 눈이 어지러워져서 엄격한 수호자의 꾸지람을 받지 않을 수 있을 텐데."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_90367_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "나에게 자유로 향하는 열쇠를 준 것, 감사하고 있다."
  },
  Voice_90368_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_90369_AwakerVoiceContent = {
    Text = "이 날개들이 드디어 가장 충실타래한 모습으로 자랐습니다. 그렇게 튼튼하고, 그렇게 강력하네요. 이제는 한 번에 당신과 폴룩스까지 데리고 갈 수 있습니다. 하늘로 날고 싶을 때, 저를 크게 불러 주세요."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_90369_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "날개 뒤로 숨어요!"
  },
  Voice_90370_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_90371_AwakerVoiceContent = {
    Text = "드디어... 그 책에 적혀 있던, 광활한 별하늘을 만날 수 있었어."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "예전의 교주…… 유리엣은 종종 우리에게 온정이 넘치는 순간을 보였고, 그녀는 모두에게 따뜻한 미소를 아끼지 않았기에 그녀의 기대를 저버릴까 두려웠습니다. 그녀가 웃으며 여러분의 머리를 쓰다듬는다 해도, 아무리 저항하려 해도 그 말을 할 수 없었습니다. 음, 이제는 괜찮습니다, 마음껏 제 머리를 쓰다듬으셔도 됩니다."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_90372_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "나는 그런 검은 끈적한 것에 오래, 정말 오래 담궈져 있었고, 너무 오래라 시간이 얼마나 흘렀는지 잊었다. 너무 오래라…… 폴리스쿠스조차 나를 잊어버렸다. 그것이 주는 것은 육체적 고통이 아니라, 자신의 소멸을 지켜보는 혼의 두려움이다."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "우리는 어릴 때부터 다른 사람과 너무 많은 소통을 허락받지 못했어, 친구라는 단어도 매우 오랜 시간 후에야 알게 되었지. 나와 폴리쿠스는 서로를 제외하고는 아무것도 없고, 형제이자 친구, 같은 감방에 갇힌 죄수들만이 우리, 오직 우리 뿐이다. 이제, 새로운 친구들을 사귈 때가 되었다."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_90374_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "물러나라!"
  },
  Voice_90375_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_90376_AwakerVoiceContent = {
    Text = "누구나 자유롭게 소통하고 친구를 사귈 수 있는 학교인가요? 당신은 여기서 신학을 배우지 않으며 다양한 과목을 선택할 수 있다고 말했죠…… 심지어 수업을 땡땡이칠 수 있다고요? 음, 정말 멋진 곳이네요."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_90377_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_90378_AwakerVoiceContent = {Text = "비켜!"},
  Voice_90378_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_95050_AwakerVoiceContent = {
    Text = "신이시여... 불경한 자에게 신벌을..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "나의 심장은, 맑은 빛일지니!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "더럽고 불결한 것."
  },
  Voice_95052_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_95053_AwakerVoiceContent = {
    Text = "너무 열정적인 신자는 세상에서는 통제할 수 없는 미친 사람일 뿐일지도 모르지만, 그녀 또한 한때 길을 잃었던 적이 있다. 하지만 신을 위해 모든 것을 바칠 결심은 대부분의 보통 사람들은 도저히 갖출 수 없는 강인함이다. 나는 그녀에게...... 같은 처지에 있는 슬픔만이 있을 뿐이다."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "잡담·미리암에 대해"
  },
  Voice_95053_UnlockDesc = {
    Text = "깨어남체「미리암」획득 후 개방"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "나는 인도와 심판을 가져오는 자. 백야의 광휘 아래, 그대들의 죄악을 몰아낼 것이다!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "하…… 이렇게 오랜 시간이 지나도 그는 여전히 변하지 않았어. 어린 시절의 나는 언젠가 내가 형을 이렇게 다치게 하고, 빚을 지게 될 것이라고는 생각도 못했어. 그런 비극적인 운명이 우리 누구에게도 통제받지 않는다는 점을 깨닫지 못했지. 우리는 많은 이별을 겪었지만, 내가 이미 돌아왔으니 앞으로는 아무것도 우리를 갈라놓지 못할 거야, 죽음조차도."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "잡담·카스토르에 대해"
  },
  Voice_95055_UnlockDesc = {
    Text = "깨어남체「카스토르」획득 후 개방"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "예전에는 내가 싫어했던 것이 많다. 예의가 없는 하인, 천시하는 하인, 신을 모독하는 이단자들… 그러나 지금은, 등불, 오직 등불일 뿐! 유리엣과 그녀의 교단들은 나와 내 형제에게 회복할 수 없는 아픔을 가져다주었다. 성자의 이름으로 맹세하노니, 나는 이 고통이 다른 사람의 삶에 나타나는 것을 막겠어!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "나는 그 빛나는 길을 따를 것입니다, 내 인생을 다할 때까지."
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "등불지기의 빛으로, 긴 밤을 밝게 비추리라!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "오오, 관대하고 자비로운 분이시여. 이 광명의 따스함, 제대로 가슴에 새기도록 하겠다."
  },
  Voice_95059_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_95060_AwakerVoiceContent = {
    Text = "등불지기의 사도이자, 백야에서 태어난 자. 어둠을 몰아내는 성심의 성자, 폴룩스. 그대의 부름에 이 땅에 서겠다. 나의 어둠의 힘과 빛의 혼을, 당신에게 바치지."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_95061_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_95062_AwakerVoiceContent = {
    Text = "당신의 죄악을 씻어내세요!"
  },
  Voice_95062_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_95063_AwakerVoiceContent = {
    Text = "예전 모든 이들이 나에게 이 심연 같은 검은색이 나의 신념이며, 신자들에게 내가 전할 축복이라고 말했습니다. 이제 이 어둠은 이미 나를 침식하고 하나가 되었습니다…… 하지만 이 죄악의 신체 속에서 뛰는 심장은 절대 침식될 수 없는 곳입니다. 안심하세요, 저는 이 검은색이 부여한 능력으로 진정한 복지를 세상에 가져오겠습니다!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "당신의 위대한 이름을 퍼뜨리겠다. 모든 불결한 것들에게, 빛의 세례를 내리지."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "지나간 죄악은 이미 저질러졌고, 더 이상 그것을 회피해서는 안 된다. 나는 랜턴의 오류를 수정하고, 그 지옥길에 있는 사람들을 바른 길로 이끌어야 한다. 나의 죄악을 감당하게 해라. 그리고 나는 이 빛에 응답하고, 당신의 소환에 응답하여, 진정한 성자의 길을 걸어갈 것이다."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_95065_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "얼마나 자비로운 마음입니까, 당신이 온 몸이 죄악으로 가득한 사람을 용서하려고 하다니, 나는 당신 영혼의 고결함을 느낄 수 있습니다. 그것은 불빛보다 더 밝은 빛입니다. 아마도 당신은 나의 길 잃은 마음을 인도할 수 있을 것입니다……"
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_95066_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "유리엣의 주술에서 퍼져 나오는 어둠이 내 머릿속을 감싸고 있습니다... 하지만 지금, 그 어둠 속에서 한 줄기 빛이 나타났습니다! 그 미미한 빛은 나에게 무언가를 말하고 싶어 하지는 않나요?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_95067_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "그녀가 한때 성녀였다는 이야기를 들었지만, 이렇게 거친 태도와 무례한 행동… 뭐라고? 그녀는 기도의 구절도 외우지 못한다고? 이렇게 불경한 모습은 정말 그녀의 신에게 창피할 일이야."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "잡담·머피에 대해"
  },
  Voice_95068_UnlockDesc = {
    Text = "깨어남체「머피」획득 후 개방"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "안개를 헤치고 사람들을 이끌 수 있는 자가 진정한 순은으로 된 등불 지니자입니다. 유리엣이 말하는 무죄의 정토는 사실타래 신자들의 수많은 시체로 쌓여 만들어졌습니다. 성자로서 저는 새로운 복음을 모든 구원받을만한 신실타래한 이들에게 전할 것입니다."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "나를 이끌고, 빛을 주는 분이여, 한때 나는 허상의 의미에 가려져 있었습니다. 이제 당신의 인도 아래, 나는 내 진정한 사명을 되찾았습니다 — 어리석고 왜곡된 거짓 신자들을 올바르게 인도하여 세상에 영원히 사라지지 않는 빛을 가져오는 일. 나는 당신의 이타심을 압니다, 당신은 나의 경외와 공양을 필요로 하지 않습니다. 그러니 제발 제가 당신 곁에 있어 당신의 모든 성언과 성행을 기록하도록 허락해 주세요. 어둠 속에서 제 길을 안내하기 위해서요."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_95070_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "족쇄를 차고, 어둠 속에서, 그 빛을 향해 가고, 흔들림 없이 나아가…… 이게 당신이 나에게 하고 싶었던 이야기인가요?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_95071_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "한 빛나는 시종이 손에 들고 있던 불꽃을 잃었다. 이 맹목적인 고통은 나를 마음이 조급하게 한다. 나는 진심으로 당신께 이 길 잃은 혼을 구해 주시기를 부탁드립니다. 손을 잡아주시고, 이 성스러운 마음에 다가가 주십시오. 저에게 빛으로 가는 안내를 주십시오......"
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_95072_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "불행한 아이, 하지만 그녀는 이미 당신의 길을 따르기로 헌신했으니, 결국 구원을 받을 수 있을 것이다. 그러나 그녀의 그 원숭이 같은 친구는 왜 당신의 은총을 받았는가? 그 악랄한 아이는 심지어 내 기도의 도구를 훔쳤다! 그녀의 혼 안에는 반드시 대홍수 같은 죄악이 숨겨져 있다, 정말 불경한 것! 불경한 것!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "잡담·아이기스와 젠킨에 대해"
  },
  Voice_95073_UnlockDesc = {
    Text = "깨어남체「아이기스」와 「젠킨」획득 후 개방"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "신속히 떠나라."
  },
  Voice_95074_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_95075_AwakerVoiceContent = {
    Text = "등불지기의 빛으로, 긴 밤을 밝게 비추리라!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "아…… 나는 보았습니다, 거대한 힘과 세계의 진실타래을…… 나의 과거 잘못된 길을 깨달았습니다, 당신이야말로 진정한 등불을 지닌 자입니다! 제발 제가 당신의 충성을 바치는 사도가 될 수 있게 해주세요, 이 등불을 위해 태어난 심장은 이제 당신을 위해 설레고 두근거릴 것입니다……"
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_95076_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "그 신부의 맹목적인 구원이란 정말로 타당하지 않은 어리석은 행동이며, 신의 복음은 자연히 신실타래한 의인에게만 주어져야 마땅합니다. 만약 신의 사도조차도 통찰력 있는 안목을 가지지 못한다면, 회개하지 않고 죄악으로 가득한 악당에게 보상을 주어 신의 순수한 왕국을 오염시키는 것은 신과 그런 의인들에게 대한 배신이 아닙니까?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "잡담·살바도르에 대해"
  },
  Voice_95077_UnlockDesc = {
    Text = "깨어남체「살바도르」획득 후 개방"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "나의 심장은, 맑은 빛일지니!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_95079_AwakerVoiceContent = {Text = "해!"},
  Voice_95079_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_95080_AwakerVoiceContent = {
    Text = "어린 시절의 나는 한없이 감옥을 벗어나고 싶어 했습니다. 그때 나는 이곳이 오직 고통만을 줄 뿐이라 생각했습니다. 그러나 두 번의 삶을 경험한 지금, 나는 자유가 내가 바라는 유일한 것이 아님을 깨달았습니다. 구원을 받을 것이라는 소식을 들은 교인들의 순수한 얼굴과 희망, 감사의 모습이 바로 성자의 진정한 의미입니다."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "유리엣과 함께 했던 그 시간 동안, 나는 많은 잘못을 저질렀어, 이런 신뢰를 다시 받아서는 안 되는 것인데. 하지만 당신은 여전히 나를 선택했어… 편안하게 해줘, 나는 내 신념을 다시 찾겠어. 성자는 그의 신민들을 실타래망시키지 않을 것이고, 당신을 실타래망시키지 않을 거야."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_95081_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "당신에게 받은 은총, 감사하며 쓰도록 하지."
  },
  Voice_95082_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_95083_AwakerVoiceContent = {
    Text = "무례하다!"
  },
  Voice_95083_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_95084_AwakerVoiceContent = {Text = "이놈의!"},
  Voice_95084_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_95085_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_95086_AwakerVoiceContent = {
    Text = "내 이름으로!"
  },
  Voice_95086_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_95087_AwakerVoiceContent = {
    Text = "나는 보았다! 그 빛, 의식 깊은 곳에서 빛나는 빛이 점점 더 밝아지고 있다! 그것이 나를 부르고 있다……"
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_95087_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "어린 시절, 카스토르와 나는 성자의 직위를 함께 맡았다. 그때 나는 그가 너무 둔하고 어리석어 미래의 방향을 내가 인도해야 한다고 생각했다. 이제 당신이 겪어온 길을 이해하면서, 나는 세상의 기초가 당신과 그처럼 정직하게 성실타래한 사람들에 의해 구축되고 개척된 것임을 깨닫게 되었다."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_95088_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "내 빛나는 인도, 당신의 가르침을 받고 나서, 나는 완전히 올바른 길을 가고 있다고 생각한다. 이제 당신의 우둔한 신도에게는 하나의 혼란이 있습니다. 그 전설 속 무죄의 정토는, 정말 당신의 통제 아래에 있습니까? 그런 것은 없다? 당신의 뜻은……무죄의 정토가 인간 사이에 존재한다고, 의로운 사람의 순수한 마음 속에 존재한다고?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "신의 뜻을 듣는 이 성스러운 심장이, 드디어 당신에게 가까워졌군."
  },
  Voice_95090_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_95091_AwakerVoiceContent = {
    Text = "당신…… 저에게 전하고 싶은 의도가 있으신가요? 당신의 사자는 언제든지 당신의 가르침을 듣기 위해 준비되어 있습니다."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "나를 비춰줘, 길 잃은 인도자여! 당신의 빛으로 나는 내가 봐야 할 모든 것을 이미 보았다…… 나는 이 저주받은 몸으로 모든 과거를 정화하고, 모든 미래가 이 빛 아래서 목욕할 수 있도록 하겠다!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_95092_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "빛을 읊조리라!"
  },
  Voice_95093_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_95391_AwakerVoiceContent = {
    Text = "잔혹한 세상에서 구원 추구해? 힘내, 희망으로 가득 찬 작은 녀석아."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_95391_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "자, 이것들 가지고 놀아보세요. 어떤 유적에서 발굴한 금지된 유물이라고 하네요. 나는 그들 향기가 묻은 것들에 흥미가 없어서 그냥 태워버릴 생각이었지만, 어쩌면 당신에게 유용할 것 같아서 가져왔습니다.  \n당신이 어떻게 얻었냐고요? 물론 제 자신이 '자발적으로' 받았죠. 걱정하지 마세요, 오직 '깨끗한' 경로로 온 것이라는 것을 보장합니다."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_95392_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "좋아, 정리됐다고. 보수? 하핫, 꼬맹이의 미소 정도면 충분해."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "알겠니, 작은 친구? 이 두 자루의 총에서 나오는 것은 총알이 아니라 욕망과 악의의 집합이다.\n이 무질서한 혼돈은 혈육 같은 불꽃을 구성하고, 저편의 일곱 번째 총성과 함께 모든 것을 지옥으로 끌어들여 불태울 것이다."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "잡담·총에 대해"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "너무 자신을 압박하지 마세요, 나의 비밀 지키는 사람. 이게 긴급한 험난한 길이라는 것을 알고 있지만, 조금만 조심하지 않으면 그 길은 돌이킬 수 없는 것이 됩니다. 하지만 이렇게 지속하면 언젠가 당신은 지쳐서 쓰러질 날이 올 것입니다. 필요하다면, 가족으로서 저와 이야기를 나누세요."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_95395_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "불타라, 무너져라, 울부짖어라!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "사라져라."
  },
  Voice_95397_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_95398_AwakerVoiceContent = {
    Text = "내 시야가 더욱 선명해졌다, 나는 심연 아래에 숨겨진 것을 보았다... 너희를 위해 나는 더 강한 힘이 필요하다..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_95398_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "비밀 지키는 사람, 이리 오세요. 지금은 너무 생소하군요.  \n당신이 알아요? 처음 당신을 만났을 때, 언젠가 당신에게 잔인함과 차가움이라고 불리는 껍질을 벗을 수 있을 것이라고는 상상도 못 했습니다. 좀 웃기죠, 악명 높은 폭발의 주인이 하지만, 한 마음을 털어놓을 수 있는 가족을 갈망하고 있었습니다.  \n약속해 주세요, 만약 그 날 당신이 견딜 수 없게 된다면……마음속으로 나의 이름을 불러주세요, 그러면 나도 당신과 함께 나의 나라로 이끌겠습니다. 비록 이것이 모든 일이 오는 것을 지연시키는 방법이지만, 적어도 마지막 순간에는 당신이 내 품에서 편안히 쉴 수 있게 해줄 것입니다."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_95399_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "종말을 맞이하라."
  },
  Voice_95400_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_95401_AwakerVoiceContent = {Text = "으읏!"},
  Voice_95401_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_95402_AwakerVoiceContent = {
    Text = "수억의 욕망과 악의 속에서, 태우자!"
  },
  Voice_95402_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_95403_AwakerVoiceContent = {
    Text = "성공적인 사냥이 끝난 후 항상 축하 연회가 필요해요, 함께 오세요, 제가 구운 낙타 고기와 방금 확보한 테킬라를 맛보세요. 잠깐, 작은 친구, 당신은 술을 마실타래 수 없겠군요…… 그럼 제가 특별히 만든 과일 주스를 드세요~"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_95403_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "어떻게 된 거지, 작은 친구야? 포옹이 필요해? 자, 내 타오르는 가슴이 언제나 너를 맞이하고 있어…… 하하, 부끄러워하지 마, 언니가 후배를 걱정하는 건 정말 평범한 일이잖아요?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_95406_AwakerVoiceContent = {Text = "젠장."},
  Voice_95406_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_95407_AwakerVoiceContent = {
    Text = "호박색 죽음을 맞이하라."
  },
  Voice_95407_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_95408_AwakerVoiceContent = {
    Text = "철수한다. 뒤는 맡겨 줘. 하하, 걱정하지 마. 당연히 살아서 돌아갈 거니까."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "전부 한꺼번에, 재가 될 때까지 불태워주지!"
  },
  Voice_95409_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_95410_AwakerVoiceContent = {
    Text = "폭발하는 불꽃이여, 여기서 다시 타올라라!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "불꽃이 점점 커지고 있어. 꼬맹이, 성대한 불꽃놀이를 보고 싶지 않아?"
  },
  Voice_95411_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_95412_AwakerVoiceContent = {
    Text = "그 인간성을 짓밟고 그림자에 숨어, @1을 재료로 하여 그들의 더러운 희생과 연구를 하는 놈들... 하루 빨리 그들을 모두 처치해 버릴 것입니다."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_95413_AwakerVoiceContent = {Text = "쾅!"},
  Voice_95413_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_95414_AwakerVoiceContent = {
    Text = "나는 그의 흔적을 찾을 것입니다, 그가 우주의 어느 구석에 숨더라도, 반드시 찾을 것입니다.\n 그 더러운 쥐에게 대가를 치르게 할 것이며, 그를 찾는 순간, 세상의 모든 기쁨과 즐거움이 지옥에서 타오를 것입니다.\n 걱정하지 마세요, 그때 그의 장례식에 특등석을 남겨두겠습니다, 함께 그의 마지막 비명이 무엇인지 맛보길 바랍니다."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "잡담·N에 대해"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "들어봐, 이 별들이 녹아내리는 슬픔."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_95415_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "종말을 맞이하라."
  },
  Voice_95416_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_95417_AwakerVoiceContent = {
    Text = "너는 내가 자랑스럽게 여기는 가족이다. 자신감을 가져, 나의 비밀 지키는 사람! 무슨 일이 있든, 나는 너의 가장 강력한 지원군이 될 것이다."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "그 설명할 수 없는 존재들이 이 세상을 침식하고 있으며, 당신은 피할 수 없이 그들과 적대하게 될 것입니다. 하지만 괜찮습니다, 왜냐하면 내가 당신의 뒤에 있기 때문입니다."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_95418_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "불타라, 무너져라, 울부짖어라!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "차분함을 유지하세요."
  },
  Voice_95421_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_95422_AwakerVoiceContent = {
    Text = "후퇴하세요."
  },
  Voice_95422_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_95423_AwakerVoiceContent = {
    Text = "당신은 내가 녹아내림을 어떻게 보는지 물었습니다? 그것은 주저앉아 있는 작은 쥐에게 높은 곳에 있는 영주가 어떻게 보이는지 물어보는 것과 같습니다. 나의 대답은 단 하나입니다: 신체 본능으로부터 오는 혐오감입니다. 가능하다면 나는 맛있는 낙타 우유주를 마시며, 내 총 아래에서 죽어가는 것들의 비명 소리를 즐기고 싶습니다."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "불꽃을 더 뜨겁게 하고 싶나요?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_95424_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "나는 위탁을 받을 때만 여기 옵니다, 작은 친구가 나를 찾으려면, 이 주문을 사용하세요. 자, 함께 외쳐보세요:……………… Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "언젠가, 우리는 그 낡은 작은 마을에서 잔인함과 교활함으로 연명했습니다. '대세력'이 되었다 하더라도, 주둔자, 경비대 및 역사 무대에서 물러나기를 원치 않는 '기사님'을 대면할 때마다 우리는 반드시 120%의 정신을 차려야 했습니다. 하지만 지금은 다릅니다. 모두가 제 '숭배자'가 되었고, 더 이상 다른 사람의 얼굴색을 살필 필요가 없습니다. 음, 비록 작은 녀석이 외딴 곳에 남아있지만, 그 녀석이 반드시 무사할 것이라고 믿습니다. 결국 제가 외부에서 바쁘게 돌아다니는 동안, 그 녀석이 다른 사람들을 돌봤으니 말입니다."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "잡담·가족에 대해"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "이 녀석이 꼬맹이의 적이야? 그럼... 사냥을 시작할 시간이네."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "폭염의 주인이 명한다. 삼라만상이여, 재가 되어라!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "불타고 파괴하는 것이 나의 전부이다. 나는 사냥에서 오는 죽음을 열망한다…… 내가 이렇게 말할 것 같니?\n하하, 농담이야. 나에게 가장 중요한 것은 곁에 있는 모두이다. 아무것도 그보다 중요하지 않다. 심지어…… 나 자신도 안 된다."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "여어, 꼬맹이. 뭔가 곤란한 일이라도 있어? 그럼, 이 카티구라가 나설 차례지. 성가신 일을 전부 \"쾅\" 하고, 날려버려 줄게."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_95431_AwakerVoiceContent = {
    Text = "힘의 맛, 불행한 사람들을 써볼까?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_95431_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "폭염의 주인이 명한다. 삼라만상이여, 재가 되어라!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "전설의 아란 여왕, 위대한 욕망의 실타래체 티프레예소드, 내가 N를 추적할 때 그녀를 한 번 본 적이 있다. 그녀의 행동에 동의하지 않지만, 솔직히 말하자면, 만약 그것이 내가 모두를 「그」의 시선에서 살아남게 할 수 있는 유일한 방법이라면... 나도 같은 선택을 할 것이다. 그런 관점에서 보았을 때, 나와 그녀는 별로 다르지 않다."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "잡담·타이스에 대해"
  },
  Voice_95433_UnlockDesc = {
    Text = "깨어남체「타이스」획득 후 개방"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "오, 제대로 총 손질이 되어있잖아."
  },
  Voice_95434_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_95435_AwakerVoiceContent = {
    Text = "나는 불이고, 화염이며, 영원히 꺼지지 않는 혼돈이다... 나는 모두를... 집으로 데려갈 것이다..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_95435_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "여기 고딕 스타일의 종탑은 고전적인 분위기를 풍기고, 여기의 깨어남체는 내가 한 번도 경험하지 못한 맛이 있어, 죽은 자의 향기와 한줄기의 생명력 있는 냄새가 묘하게 어우러져, 정말……. 시도해 보고 싶은 마음이 듭니다."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "잡담·미사그에 대해"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "죽음을 갈망하는 자여, 소원을 이루어 드리죠."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "광기 폭발·2"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "나는 이제 시작하기를 기다릴 수 없게 되었어."
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "영지 깨어남"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "마음을 움직였지, 그렇지? 자, 내 사랑하는 손님이여, 내 자리의 손님이 되어 이 성대한 잔치에 함께 오세요. 내가 너를 인도하여 모든 망자의 섬세한 여운을 함께 음미하게 하리라."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "계령·개화"
  },
  Voice_96364_UnlockDesc = {
    Text = "계령 등급 15 도달 시 개방"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "쉿, 말 안 해줘도 돼요. 함께 조용히 망자의 소리를 들읍시다."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "동조율·1"
  },
  Voice_96365_UnlockDesc = {
    Text = "동조율 레벨 2 도달 시 개방"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "영원의 아름다움이 우리의 믿음입니다. 서서히 생자에게서 소멸을 강요하여 모든 존재의 흔적을 지우는 것…… 이것은 생명에 대해 순수하고 잔인한 고통입니다."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "잡담·위기에 대해"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "나와 마찬가지로, 픽먼도 영원한 예술을 추구하고 있습니다. 우리는 더 좋은 친구가 될 수 있었어야 했습니다. 그러나 그는 식사가 영원을 파괴하는 행위라고 생각하고, 이런 예술적 관념은 너무 협소합니다."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "잡담·픽맨에 대해"
  },
  Voice_96367_UnlockDesc = {
    Text = "깨어남체「픽맨」획득 후 개방"
  },
  Voice_96368_AwakerVoiceContent = {Text = "하!"},
  Voice_96368_AwakerVoiceTitle = {Text = "타격·1"},
  Voice_96369_AwakerVoiceContent = {
    Text = "어떤 형용사로도 당신 몸에서 나는 이 매혹적인 향기를 설명하기 어려우며, 보르도 와인의 신맛과 풍부한 여운처럼, 크림 스콘처럼 풍부하고 고소하다. 아…… 당신이 죽는 날이 기대되기도 할 것 같습니다, 그것은 제 인생에서 가장 중요한 일이 될 수 있습니다."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "잡담·수호자에 대해"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "나는 한 범죄 현장을 목격한 적이 있다. 한 남자가 점점씩 한 소녀의 살점, 손톱, 손과 발을 잘라내고 있었지만 그녀를 계속 치료하고 있었다. 그는 그녀가 죽기를 원하지도 않았고, 물론 그녀가 살아 있기를 원하지도 않았다. 나는 그에게 평화로운 죽음을 주지 않았고, 그저 그가 그 소녀와 같은 경험을 계속하도록 했다. 계산해보니 벌써 몇 년이 된 것 같군… 신성을 더럽힌 자에게는 이것이 공정한 일이 아니던가?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "잡담·싫어하는 것"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "나는 죽음의 신을 다스리는 자지만 오해하지 말라, 나는 결코 죽음을 만들지 않는다. 나는 죽음의 발자취를 따르며 그 풍요롭고 성숙한 과일을 수확할 뿐이다."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "계령·관찰"
  },
  Voice_96371_UnlockDesc = {
    Text = "계령 등급 1 도달 시 개방"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "당신도 내 향기에 갈망을 느끼나, 비밀 지키는 사람님?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "잡담·터치"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "자 그럼, 오늘은 어떤 분을 식탁에 올릴까요?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "조사 개시"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "여러분들에게, 오늘 밤의 만찬이 될 영광을 드리죠."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "조사 성공"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "너무나 우아하지 않아."
  },
  Voice_96375_AwakerVoiceTitle = {Text = "피격·3"},
  Voice_96376_AwakerVoiceContent = {
    Text = "나는 깨끗한 안식을 가져올 것이다."
  },
  Voice_96376_AwakerVoiceTitle = {Text = "스킬·1"},
  Voice_96377_AwakerVoiceContent = {
    Text = "매번 먹기 전에, 저는 망자와 대화를 나누었습니다. 그들에게 있어, 누군가에 의해 신중하게 먹히고, 맛본다는 것은 생명의 연장과 마지막의 영광입니다. 우리가 그들을 갈망하듯, 그들도 우리를 갈망하고 있습니다."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "동조율·3"
  },
  Voice_96377_UnlockDesc = {
    Text = "동조율 레벨 6 도달 시 개방"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "좀 조용히 해라."
  },
  Voice_96378_AwakerVoiceTitle = {Text = "피격·4"},
  Voice_96379_AwakerVoiceContent = {
    Text = "그림자 속으로 사라져버려라!"
  },
  Voice_96379_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_96380_AwakerVoiceContent = {
    Text = "우리는 거리를 두는 것이 좋겠어."
  },
  Voice_96380_AwakerVoiceTitle = {Text = "방어·1"},
  Voice_96381_AwakerVoiceContent = {
    Text = "그림자 속으로 사라져버려라!"
  },
  Voice_96381_AwakerVoiceTitle = {Text = "스킬·4"},
  Voice_96382_AwakerVoiceContent = {
    Text = "왜 나를 그렇게 경계하나요? 당신은 놀라지 않아도 됩니다. 살아있는 사람을 해치는 것은 내 미학에 반합니다."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "잡담·음식에 대해"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "죽음을 갈망하는 자여, 소원을 이루어 드리죠."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "광기 폭발"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "너무나 우아하지 않아."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "피격·1"},
  Voice_96385_AwakerVoiceContent = {Text = "조심해."},
  Voice_96385_AwakerVoiceTitle = {Text = "방어·2"},
  Voice_96386_AwakerVoiceContent = {
    Text = "그 아가씨의 열정은 정말 감동적이지만, 그녀의 향기는 어떤 발효가 과도한 축축한 냄새가 납니다. 그녀가 나에게 한 번 맛을 보라고 애원해도, 이것은 정말로 내 취향에 맞지 않아, 정말 난감하군요."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "잡담·레아에 대해"
  },
  Voice_96386_UnlockDesc = {
    Text = "깨어남체「레아」획득 후 개방"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "당신은 아는가? 모든 생명이 사라질 때 긴 여운을 가진다. 그것들은 저음과 고음이 서로 다르며, 죽음이 강림하는 순간부터 하나하나 늘어나다가 점점 우주 사이로 사라지게 되며, 마치 어떤 한숨 같은 울림과 같다."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "동조율·2"
  },
  Voice_96387_UnlockDesc = {
    Text = "동조율 레벨 4 도달 시 개방"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "안심하세요, 비밀 지키는 사람 님, 저는 당신의 생명이 거부할 수 없는 소멸에 이르는 그날까지 항상 당신 곁에 있을 것입니다. 그때 저는 반드시 가장 화려한 의식으로 당신의 몸을 하나씩 삼킬 것입니다. 저는 당신의 혼을 영원히 내 몸에 남길 것입니다."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "동조율·5"
  },
  Voice_96388_UnlockDesc = {
    Text = "동조율 레벨 10 도달 시 개방"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "당신은 자신의 향기를 맡을 수 없나? 그건 정말 아쉽다, 당신은 세계에서 가장 달콤하고 가장… 아앗, 왜 피하나?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "동조율·4"
  },
  Voice_96389_UnlockDesc = {
    Text = "동조율 레벨 8 도달 시 개방"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "죽음의 속삭임이 더욱 가까이, 더욱 선명하게 울려 퍼지고 있습니다. 피안의 광경은 벌써 눈앞에 있습니다."
  },
  Voice_96390_AwakerVoiceTitle = {Text = "승격·3"},
  Voice_96391_AwakerVoiceContent = {
    Text = "피 한 방울, 살 한 점까지, 모든 걸 제게 맡기도록 하세요!"
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "초월 폭발"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "다른 재료는 각각 다른 처리를 필요로 한다. 내장은 절이는 것이 필요하고, 다리 근육의 힘줄은 끓이는 것이 가장 좋으며, 지방이 풍부한 부분은 발효 숙성이 적합하고, 특별한 식감이 있는 부분은 튀기거나 grill해서 귀엽게 만들어낸 육즙 젤리를 만들 수도 있다. 이러한 선택은 모두 신중해야 한다. 물론 재료의 본래 맛을 보존하고 강조하는 것은 반드시 존중해야 할 부분이다."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "계령·통달"
  },
  Voice_96392_UnlockDesc = {
    Text = "계령 등급 7 도달 시 개방"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "조금 차가울 수 있습니다."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "타격·2"},
  Voice_96394_AwakerVoiceContent = {
    Text = "요리의 조합도 중요하며, 신맛과 단맛, 바삭함과 부드러움, 상큼함과 묵직함, 섬세함과 거칠함이 층층이 쌓인 맛과 전혀 다른 식감을 충돌시키며, 입안에 넣고 씹고 남는 맛에서 다양한 감각이 느껴져야 합니다. 이게 바로 합격 미식이 주는 무한하고 신기한 즐거움입니다."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "계령·구축"
  },
  Voice_96394_UnlockDesc = {
    Text = "계령 등급 11 도달 시 개방"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "당신의 열정적인 접대, 정말 감사드립니다. 후훗, 실타래로 영광이로군요."
  },
  Voice_96395_AwakerVoiceTitle = {Text = "승격·2"},
  Voice_96396_AwakerVoiceContent = {
    Text = "시련을 넘어서야만, 극상의 미식을 맛볼 수 있는 법이죠."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "조사 중단"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "나는 물론 날이 갈수록 야만적이지 않은 괴물이 아니고, 죽음을 즐기는 과정이 엄숙하고 우아하다는 사실타래을 알아, 각 재료의 독특한 풍미를 존경하며 소통하고 이해해야 해."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "계령·응시"
  },
  Voice_96397_UnlockDesc = {
    Text = "계령 등급 2 도달 시 개방"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "고요한 망자는 아름답고 향기롭다, 그들의 육체가 생전과 사후에 얼마나 큰 차이가 있는지가 아니라, 그들의 혼——그 죽음에 대한 통찰, 삶에 대한 애착, 기억되고 싶다는 갈망이 내가 꿈꾸는 진미이기 때문이다."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "잡담·좋아하는 것"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "어떤 향수도 자연적인 인체의 향기보다 나을 수 없으며, 향을 통해 사람을 인식하는 것은 가장 멋진 일이 아닐 수 없다."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "계령·숙고"
  },
  Voice_96399_UnlockDesc = {
    Text = "계령 등급 3 도달 시 개방"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "아아, 이 가슴을 들뜨게 하는 매혹적인 향기. 당신을 제 성전에 초대할 날이 기다려지는군요."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "깨어남"},
  Voice_96401_AwakerVoiceContent = {
    Text = "피 한 방울, 살 한 점까지, 모든 걸 제게 맡기도록 하세요!"
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "초월 폭발·2"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "나는 깨끗한 안식을 가져올 것이다."
  },
  Voice_96402_AwakerVoiceTitle = {Text = "스킬·2"},
  Voice_96403_AwakerVoiceContent = {
    Text = "좀 조용히 해라."
  },
  Voice_96403_AwakerVoiceTitle = {Text = "피격·2"},
  Voice_96404_AwakerVoiceContent = {
    Text = "당신의 매혹적인 향기에, 계속 취해 있고 싶군요."
  },
  Voice_96404_AwakerVoiceTitle = {Text = "승격·1"},
  Voice_98324_AwakerVoiceContent = {
    Text = "수억의 욕망과 악의 속에서, 태우자!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "특수 스킬·1"
  }
})
return Text_Voice
